def vex2_retime_ff_drift_ok(ff_before, ff_after) -> bool:
    """Latency audit predicate (DQ protection): True iff BOTH FF counts
    were measured and |after - before| / before <= 1% (inclusive; q07
    measured 1678 -> 1682 = +0.24%).  None / unparseable / non-positive
    'before' -> False: this is a PROTECTION and protections fail ON
    (abort the registration) — GRAYAREAS_SYNTHESIS doctrine."""
    if ff_before is None or ff_after is None:
        return False
    try:
        b = int(ff_before)
        a = int(ff_after)
    except (TypeError, ValueError):
        return False
    if b <= 0 or a < 0:
        return False
    return abs(a - b) / float(b) <= VEX2_RETIME_FF_DRIFT_MAX_FRAC


def v40_flag_env_present(*names) -> bool:
    """True iff ANY of the given env vars is PRESENT (any value, incl. "0").
    Gates ONLY the v4.0 'skipped reason=disabled' audit lines (post-review
    ack): a run with NO v4.0 knobs in the environment must stay log-byte
    identical to v3.3.  Behavior gates keep using the *_enabled() helpers."""
    return any(os.environ.get(n) is not None for n in names)


