    async def _recipe_register_retiming(self, args: dict) -> str:
        """Synthetic tool — apply register retiming via phys_opt_design.

        The contest-promoted technique #5 (register retiming) is
        accessible via `phys_opt_design -directive AlternateFlowWithRetiming`
        or `phys_opt_design -directive AddRetime`.  This recipe runs the
        directive, optionally re-routes, and measures.  Designed for
        LOSS designs (corescore-class) where the standard pblock + phys_opt
        flow has plateaued.

        Returns JSON with status, directive_used, route_errors,
        delta_fmax_mhz (recipe contribution).
        """
        directive = args.get("directive", "AlternateFlowWithRetiming")
        if directive not in ("AlternateFlowWithRetiming", "AddRetime"):
            return json.dumps({
                "status": "error",
                "error": f"directive must be AlternateFlowWithRetiming or AddRetime, got {directive!r}",
            })
        rewrite_dcp = bool(args.get("rewrite_dcp", True))

        result = {
            "status": "error",
            "directive_used": directive,
            "route_errors": None,
            "delta_fmax_mhz": None,
            "initial_fmax_mhz": None,
            "final_fmax_mhz": None,
            "error": None,
        }

        pre_recipe_wns = self.best_wns
        try:
            # Step 1 — run phys_opt_design with the retiming directive.
            phys_str = await self.call_tool("vivado_phys_opt_design", {
                "directive": directive,
            })
            if _looks_like_tool_error(phys_str):
                result["error"] = f"phys_opt_design failed: {phys_str[:200]}"
                return json.dumps(result)

            # Step 2 — re-route.  Retiming inserts/moves FFs, which can
            # invalidate the route on at least the affected paths.
            route_str = await self.call_tool("vivado_route_design", {"directive": "Default"})
            if _looks_like_tool_error(route_str):
                result["error"] = f"route_design after retiming failed: {route_str[:200]}"
                return json.dumps(result)

            # Step 3 — check routing health.
            route_status = await self.call_tool("vivado_report_route_status", {})
            m = re.search(r"# of nets with routing errors.*?:\s+(-?\d+)", route_status)
            route_errors = int(m.group(1)) if m else -1
            result["route_errors"] = route_errors

            if route_errors != 0:
                result["status"] = "route_errors"
                result["error"] = (
                    f"route_design left {route_errors} routing errors after "
                    f"{directive} retiming — revert."
                )
                return json.dumps(result)

            # Step 4 — measure.
            await self.call_tool("vivado_report_timing_summary", {})
            initial_fmax = self.calculate_fmax(self.initial_wns, self.clock_period)
            pre_fmax = (
                self.calculate_fmax(pre_recipe_wns, self.clock_period)
                if pre_recipe_wns is not None and pre_recipe_wns > float("-inf") else None
            )
            final_fmax = (
                self.calculate_fmax(self.best_wns, self.clock_period)
                if self.best_wns > float("-inf") else None
            )
            if initial_fmax is not None and final_fmax is not None:
                result["initial_fmax_mhz"] = round(initial_fmax, 2)
                result["final_fmax_mhz"] = round(final_fmax, 2)
                if pre_fmax is not None:
                    result["delta_fmax_mhz"] = round(final_fmax - pre_fmax, 2)
                else:
                    result["delta_fmax_mhz"] = round(final_fmax - initial_fmax, 2)
            result["status"] = "success"
            return json.dumps(result)

        except Exception as e:  # pragma: no cover — defensive
            logger.exception("recipe_register_retiming raised")
            result["error"] = repr(e)
            return json.dumps(result)

    async def _recipe_lut_optimization(self, args: dict) -> str:
        """Synthetic high-level tool — LUT-input-cone optimisation cycle.

        Extracts LUT input pins (named I0..I5) on the worst critical paths,
        feeds them to optimize_lut_input_cone, then writes / opens / routes /
        measures.  Same gate pattern as recipe_cell_replacement but no
        per-design applicability table (the underlying tool returns a clean
        no_optimization status when the cone isn't reducible, so we can
        let it run on any design and short-circuit cleanly).
        """
        num_paths = _arg_int(args, "num_paths", 10)
        target_max_path = _arg_int(args, "target_max_path", 2)
        max_pins_to_try = _arg_int(args, "max_pins_to_try", 12)

        result = {
            "status": "error",
            "pins_extracted": 0,
            "pins_targeted": [],
            "pins_optimized": [],
            "pins_skipped": [],
            "route_errors": None,
            "delta_fmax_mhz": None,
            "initial_fmax_mhz": None,
            "final_fmax_mhz": None,
            "error": None,
        }

        # Snapshot pre-recipe state for accurate per-recipe delta.
        pre_recipe_wns = self.best_wns

        try:
            # Step 1 — extract critical-path pins.  We use a fresh file so
            # callers running this twice don't read stale data.
            pins_file = Path(self.temp_dir) / "recipe_lut_pins.json"
            await self.call_tool("vivado_extract_critical_path_pins", {
                "num_paths": num_paths,
                "output_file": str(pins_file),
            })

            # Step 2 — filter to LUT-input pins on the worst N paths.
            try:
                critical_paths = json.loads(pins_file.read_text())
            except (OSError, json.JSONDecodeError) as e:
                result["error"] = f"could not read critical-path pins JSON: {e}"
                return json.dumps(result)

            candidate_pins = []
            seen = set()
            for path_idx, path in enumerate(critical_paths):
                if path_idx >= target_max_path:
                    break
                if not isinstance(path, list):
                    continue
                for pin in path:
                    if not isinstance(pin, str) or "/" not in pin:
                        continue
                    # LUT input pins end in /I0..I5.  optimize_lut_input_cone
                    # gracefully reports no_optimization for non-LUT cells,
                    # so we don't need to check cell type here.
                    if not re.search(r"/I[0-5]$", pin):
                        continue
                    if pin in seen:
                        continue
                    seen.add(pin)
                    candidate_pins.append(pin)
            result["pins_extracted"] = len(candidate_pins)
            result["pins_targeted"] = candidate_pins[:max_pins_to_try]

            if not result["pins_targeted"]:
                result["status"] = "no_candidates"
                return json.dumps(result)

            # Step 3 — call optimize_lut_input_cone (single batched call).
            opt_str = await self.call_tool("rapidwright_optimize_lut_input_cone", {
                "hierarchical_input_pins": result["pins_targeted"],
            })
            try:
                opt = json.loads(opt_str) if isinstance(opt_str, str) else opt_str
            except (json.JSONDecodeError, TypeError) as e:
                result["error"] = f"optimize_lut_input_cone returned non-JSON: {e}"
                return json.dumps(result)
            if isinstance(opt, dict) and opt.get("error"):
                result["error"] = f"optimize_lut_input_cone: {opt['error']}"
                return json.dumps(result)

            for r in opt.get("results", []) if isinstance(opt, dict) else []:
                if r.get("status") == "optimized":
                    result["pins_optimized"].append(r.get("pin"))
                else:
                    result["pins_skipped"].append({
                        "pin": r.get("pin"),
                        "status": r.get("status"),
                        "message": r.get("message"),
                    })

            if not result["pins_optimized"]:
                result["status"] = "no_optimization_possible"
                return json.dumps(result)

            # Step 4 — write / open / route / measure (with error gates).
            rw_out = Path(self.temp_dir) / "recipe_lut_optimized.dcp"
            write_str = await self.call_tool("rapidwright_write_checkpoint", {
                "dcp_path": str(rw_out),
                "overwrite": True,
            })
            if _looks_like_tool_error(write_str):
                result["error"] = f"rapidwright_write_checkpoint failed: {write_str[:200]}"
                return json.dumps(result)
            if not rw_out.exists():
                result["error"] = f"write_checkpoint succeeded but {rw_out} is missing"
                return json.dumps(result)

            open_str = await self.call_tool("vivado_open_checkpoint", {
                "dcp_path": str(rw_out),
            })
            if _looks_like_tool_error(open_str):
                result["error"] = f"vivado_open_checkpoint failed: {open_str[:200]}"
                return json.dumps(result)

            route_str = await self.call_tool("vivado_route_design", {"directive": "Default"})
            if _looks_like_tool_error(route_str):
                result["error"] = f"vivado_route_design failed: {route_str[:200]}"
                return json.dumps(result)

            route_status = await self.call_tool("vivado_report_route_status", {})
            m = re.search(r"# of nets with routing errors.*?:\s+(-?\d+)", route_status)
            route_errors = int(m.group(1)) if m else -1
            result["route_errors"] = route_errors

            if route_errors != 0:
                result["status"] = "route_errors"
                result["error"] = (
                    f"route_design left {route_errors} routing errors — "
                    "do NOT accept this DCP."
                )
                return json.dumps(result)

            await self.call_tool("vivado_report_timing_summary", {})
            initial_fmax = self.calculate_fmax(self.initial_wns, self.clock_period)
            pre_fmax = (
                self.calculate_fmax(pre_recipe_wns, self.clock_period)
                if pre_recipe_wns is not None and pre_recipe_wns > float("-inf") else None
            )
            final_fmax = (
                self.calculate_fmax(self.best_wns, self.clock_period)
                if self.best_wns > float("-inf") else None
            )
            if initial_fmax is not None and final_fmax is not None:
                result["initial_fmax_mhz"] = round(initial_fmax, 2)
                result["final_fmax_mhz"] = round(final_fmax, 2)
                # delta_fmax_mhz reflects the recipe's own contribution.
                if pre_fmax is not None:
                    result["delta_fmax_mhz"] = round(final_fmax - pre_fmax, 2)
                else:
                    result["delta_fmax_mhz"] = round(final_fmax - initial_fmax, 2)
            result["status"] = "success"
            return json.dumps(result)

        except Exception as e:  # pragma: no cover — defensive
            logger.exception("recipe_lut_optimization raised")
            result["error"] = repr(e)
            return json.dumps(result)

    async def _recipe_cell_replacement(self, args: dict) -> str:
        """Synthetic high-level tool — runs the contest's published cell-
        replacement recipe via the optimizer's existing MCP sessions.

        Returns a JSON string with the recipe outcome.  Sub-steps go
        through self.call_tool(), so WNS tracking, force-continue logic,
        and tool_call_details all see each underlying call.

        Refuses on designs the recipe-applicability table marks as
        harmful or error.  No-cells-moved and no-candidates branches
        return cleanly without writing a DCP — the LLM can pick a
        different strategy on the next iter.
        """
        num_paths = _arg_int(args, "num_paths", 10)
        detour_threshold = _arg_float(args, "detour_threshold", 2.0)
        target_max_path = _arg_int(args, "target_max_path", 2)
        max_cells_to_try = _arg_int(args, "max_cells_to_try", 8)

        result = {
            "status": "error",
            "candidates_total": 0,
            "candidates_targeted": [],
            "cells_moved": [],
            "cells_unmoved": [],
            "route_errors": None,
            "delta_fmax_mhz": None,
            "initial_fmax_mhz": None,
            "final_fmax_mhz": None,
            "error": None,
        }

        # Applicability gate: skip on known-harmful / error designs.
        # Gated OFF in contest mode: benchmark-name conditional.  On
        # hidden designs the LLM is allowed to attempt the recipe and
        # discover failure via the normal tool-error pathway.
        design = getattr(self, "_design_name_for_memory", None)
        contest_mode = bool(getattr(self, "contest_mode", False))
        if (_recipe_safe_for is not None and design
                and not contest_mode
                and not _recipe_safe_for(design)):
            result["error"] = (
                f"recipe_cell_replacement is BLOCKED for '{design}' — prior sweeps "
                "marked it harmful or error.  Choose a different strategy."
            )
            return json.dumps(result)

        # Snapshot pre-recipe state so delta_fmax_mhz reflects the recipe's
        # own contribution, not the cumulative best since run start.
        pre_recipe_wns = self.best_wns

        try:
            # Step 1 — extract critical-path pins (Vivado already has design open).
            pins_file = Path(self.temp_dir) / "recipe_critical_path_pins.json"
            await self.call_tool("vivado_extract_critical_path_pins", {
                "num_paths": num_paths,
                "output_file": str(pins_file),
            })

            # Step 2 — RapidWright detour analysis.
            analysis_str = await self.call_tool("rapidwright_analyze_net_detour", {
                "input_file": str(pins_file),
                "detour_threshold": detour_threshold,
            })
            try:
                analysis = json.loads(analysis_str) if isinstance(analysis_str, str) else analysis_str
            except (json.JSONDecodeError, TypeError) as e:
                result["error"] = f"analyze_net_detour returned non-JSON: {e}"
                return json.dumps(result)
            if isinstance(analysis, dict) and analysis.get("error"):
                result["error"] = f"analyze_net_detour: {analysis['error']}"
                return json.dumps(result)
            candidates = analysis.get("candidates", []) if isinstance(analysis, dict) else []
            result["candidates_total"] = len(candidates)

            # Filter to unique cells on the worst N paths, preserving detour-
            # ratio descending order.
            seen = set()
            target_cells = []
            for c in candidates:
                if not isinstance(c, dict):
                    continue
                p = c.get("path")
                if p is None or p > target_max_path:
                    continue
                name = str(c.get("cell"))
                if name in seen or name == "None":
                    continue
                seen.add(name)
                target_cells.append(name)
            result["candidates_targeted"] = target_cells[:max_cells_to_try]

            if not result["candidates_targeted"]:
                result["status"] = "no_candidates"
                return json.dumps(result)

            # Step 3 — try cells one at a time so a single bad candidate
            # doesn't kill the whole recipe (RapidWright NPE on certain
            # cell types).
            moved_any = False
            for cell_name in result["candidates_targeted"]:
                try:
                    opt_str = await self.call_tool("rapidwright_optimize_cell_placement", {
                        "cell_names": [cell_name],
                    })
                    opt = json.loads(opt_str) if isinstance(opt_str, str) else opt_str
                except (json.JSONDecodeError, TypeError, RuntimeError) as e:
                    result["cells_unmoved"].append(
                        {"cell": cell_name, "status": "exception", "message": str(e)}
                    )
                    continue
                opt_results = opt.get("results", []) if isinstance(opt, dict) else []
                if not opt_results:
                    result["cells_unmoved"].append(
                        {"cell": cell_name, "status": "internal_error",
                         "message": "RapidWright returned no results (internal exception)"}
                    )
                    continue
                for r in opt_results:
                    if r.get("status") == "success":
                        result["cells_moved"].append(r.get("cell"))
                        moved_any = True
                    else:
                        result["cells_unmoved"].append({
                            "cell": r.get("cell"),
                            "status": r.get("status"),
                            "message": r.get("message"),
                        })

            if not moved_any:
                result["status"] = "no_cells_moved"
                return json.dumps(result)

            # Step 4 — write RapidWright DCP, open in Vivado, route, measure.
            # call_tool returns JSON-error strings on failure (does not raise),
            # so we check each step's output explicitly before proceeding.
            rw_out = Path(self.temp_dir) / "recipe_rw_optimized.dcp"
            write_str = await self.call_tool("rapidwright_write_checkpoint", {
                "dcp_path": str(rw_out),
                "overwrite": True,
            })
            if _looks_like_tool_error(write_str):
                result["error"] = f"rapidwright_write_checkpoint failed: {write_str[:200]}"
                return json.dumps(result)
            if not rw_out.exists():
                result["error"] = f"write_checkpoint succeeded but {rw_out} is missing"
                return json.dumps(result)

            open_str = await self.call_tool("vivado_open_checkpoint", {
                "dcp_path": str(rw_out),
            })
            if _looks_like_tool_error(open_str):
                result["error"] = f"vivado_open_checkpoint failed: {open_str[:200]}"
                return json.dumps(result)

            route_str = await self.call_tool("vivado_route_design", {"directive": "Default"})
            if _looks_like_tool_error(route_str):
                result["error"] = f"vivado_route_design failed: {route_str[:200]}"
                return json.dumps(result)

            route_status = await self.call_tool("vivado_report_route_status", {})
            m = re.search(r"# of nets with routing errors.*?:\s+(-?\d+)", route_status)
            route_errors = int(m.group(1)) if m else -1
            result["route_errors"] = route_errors

            # Hard gate: any routing errors → recipe failed for this design.
            if route_errors != 0:
                result["status"] = "route_errors"
                result["error"] = (
                    f"route_design left {route_errors} routing errors — "
                    "do NOT accept this DCP.  Try a different strategy."
                )
                return json.dumps(result)

            # Measure ΔFmax via the optimizer's existing tracking machinery.
            await self.call_tool("vivado_report_timing_summary", {})
            # Report TWO deltas:
            #   - delta_fmax_mhz: recipe's own contribution (vs pre-recipe state)
            #   - cumulative_final_fmax_mhz: run's best so far (vs initial)
            # The LLM cares about the FIRST to decide whether the recipe helped;
            # the SECOND tells it the run-level state to write_checkpoint or revert.
            initial_fmax = self.calculate_fmax(self.initial_wns, self.clock_period)
            pre_fmax = (
                self.calculate_fmax(pre_recipe_wns, self.clock_period)
                if pre_recipe_wns is not None and pre_recipe_wns > float("-inf") else None
            )
            final_fmax = (
                self.calculate_fmax(self.best_wns, self.clock_period)
                if self.best_wns > float("-inf") else None
            )
            if initial_fmax is not None and final_fmax is not None:
                result["initial_fmax_mhz"] = round(initial_fmax, 2)
                result["final_fmax_mhz"] = round(final_fmax, 2)
                # delta_fmax_mhz: recipe's contribution (post − pre)
                if pre_fmax is not None:
                    result["delta_fmax_mhz"] = round(final_fmax - pre_fmax, 2)
                else:
                    # No pre-recipe baseline → fall back to run-level delta
                    result["delta_fmax_mhz"] = round(final_fmax - initial_fmax, 2)
            result["status"] = "success"
            return json.dumps(result)

        except Exception as e:  # pragma: no cover — defensive
            logger.exception("recipe_cell_replacement raised")
            result["error"] = repr(e)
            return json.dumps(result)

    # Default phys_opt sweep ordering — picked from observed
    # contest-design behaviour: critical_cell_opt and equ_drivers_opt
    # tend to win first on fanout-bound paths; placement_opt and
    # restruct_opt help LUT-dense paths; dsp_register_opt is design-
    # specific; slr_crossing_opt only matters on multi-SLR parts.
    _DEFAULT_PHYS_OPT_SWEEP = (
        "critical_cell_opt",
        "equ_drivers_opt",
        "placement_opt",
        "restruct_opt",
        "dsp_register_opt",
        "slr_crossing_opt",
    )

    # Evidence-backed constants for _physopt_default_fixpoint.  Each is a
    # measurement, not a tuned knob — see PHYSOPT_ARG_DROP_jul31.md §2.
    _PODF_MAX_CALLS = 4       # gains by streak position: 10/11, 8/8, 6/6, 1/4
    _PODF_EPSILON_NS = 0.002  # below this a "gain" is measurement noise
    _PODF_MAX_SHARE = 0.15    # one call may never bet >15% of the window

    async def _physopt_default_fixpoint(self) -> None:
        """Run `phys_opt_design -directive Default` to fixpoint, pre-loop.

        WHY THIS EXISTS.  `VivadoMCP/vivado_mcp_server.py` builds its phys_opt
        command with an if/else: when `directive` is set, every other argument
        is discarded — including `path_groups`.  So the LLM calls that jul29
        recorded as "aimed at the re-grouped critical path" actually ran a plain
        full-design `phys_opt_design -directive Default` with the group thrown
        away.  That inverts FIR_VARIANCE_IS_PHYSOPT_DEPTH_jul29 §4: the variable
        is directive-vs-sub-option, not scope.

        Cut over 833 phys_opt tool calls in 199 agent.logs, replicating
        independently on BOTH boxes:
            directive=Default   26/30  = 86.7%   <- highest-yield action we own
            any directive      146/354 = 41%
            sub-option only     70/479 = 15%
        No recipe or ILS stage has ever called it; only the LLM, ad hoc, which
        is why fir's alpha is a coin-flip.  fir's ILS entry baseline predicts
        alpha 15/15, and `nDefault >= 2` selected the 21.30 mode EIGHT for
        eight, against 9.07 when the LLM emitted at most one.  jul30 emitted 3
        (-0.218 -> 21.30); jul31 emitted 1 (-0.249 -> 9.07).  0.031 ns = 12.23
        MHz of pure scheduling luck.

        SAFETY.  Three independent reasons this cannot cost alpha:
          * never-worse — a call that does not clear epsilon is reverted by
            re-opening best_valid.dcp, the same path
            `_recipe_post_route_phys_opt_sweep` uses, and `best_wns` is restored;
          * it stops on the FIRST non-gain, so the cost of being wrong on a
            design is exactly one call;
          * the wall gate is a MEASUREMENT, not a prediction — call 1 is sized
            from the design-aware place+route model (a conservative ceiling for
            a phys_opt, per `_no_history_risky_estimate_s`) and calls 2+ from the
            OBSERVED duration of the previous call.  ispd16 (est 600 s) and
            boom (est 600 s) are blocked before spending anything; fir (est
            ~70 s) proceeds.

        ⚠️ EXPOSURE, not dismissed: all 30 `directive=Default` observations in
        the corpus are fir's.  n=30 calls but n=1 DESIGN — the same overfitting
        shape as the endhigh density gate.  Hence DEFAULT OFF pending an all-16
        A/B that must show no alpha or wall regression on the other 15.

        v2 (jul31 night) — CALL SITE MOVED, logic unchanged.  v1 ran this
        pre-loop and its own all-16 A/B killed it on the pre-registered
        two-strike rule:

            digit, same design, same -1.025 start:
              ship default : LLM's own phys_opt -> -0.821 (+0.204) => alpha 72.59
              v1 pre-loop  : this stage         -> -0.915 (+0.110), LLM then
                             found NOTHING and exited            => alpha 59.65

        The stage PRE-EMPTED a better call the LLM was about to make.  It is not
        additive; it competes.  fir was the exception only because all 30 Default
        calls in the corpus are fir's — Default is what the LLM already picks
        there, so the stage merely made it reliable.

        v2 therefore runs from `_exit_with_ils_polish`, AFTER the LLM loop is
        done, where there is no call left to pre-empt.  It still lands before the
        ILS entry baseline is read, which is the entire mechanism by which fir
        gains.  Still DEFAULT OFF, still needs its own A/B — and this one must
        include digit, because digit is the design that exposed the defect.
        """
        if os.environ.get(
                "FPL26_PHYSOPT_DEFAULT_FIXPOINT", "0").strip().lower() not in (
                "1", "true", "on", "yes"):
            return
        if self.best_wns is None or self.best_wns == float("-inf"):
            logger.info("[podf] skipped: no baseline WNS established yet.")
            return
        if self.best_wns >= 0:
            logger.info("[podf] skipped: timing already met "
                        f"(best_wns={self.best_wns:.3f} ns).")
            return

        # Call 1 is costed from the design-aware size model; every later call
        # from the measured duration of the one before it.
        est_s = self._estimate_tool_runtime(
            "vivado_phys_opt_design", is_risky=True)
        committed = 0
        for n in range(1, self._PODF_MAX_CALLS + 1):
            remaining = self._budget_remaining()
            budget_cap = self._PODF_MAX_SHARE * remaining
            if est_s * 1.3 > budget_cap:
                logger.info(
                    f"[podf] stop before call {n}: need {est_s * 1.3:.0f}s "
                    f"(basis {'measured' if n > 1 else 'size-model'} "
                    f"{est_s:.0f}s x1.3) > {self._PODF_MAX_SHARE:.0%} of "
                    f"{remaining:.0f}s remaining = {budget_cap:.0f}s.")
                break

            pre_wns = self.best_wns
            t0 = time.time()
            try:
                out = await self.call_tool(
                    "vivado_phys_opt_design",
                    {"directive": "Default", "timeout": 3600.0})
            except Exception as exc:                      # noqa: BLE001
                logger.warning(f"[podf] call {n} raised {type(exc).__name__}: "
                               f"{exc} — stopping (fail open).")
                break
            observed_s = time.time() - t0
            if _looks_like_tool_error(out):
                logger.info(f"[podf] call {n} returned a tool error after "
                            f"{observed_s:.0f}s — stopping (fail open).")
                break

            # call_tool's auto-bank hook has already measured and, if the
            # design improved AND is routed, moved best_wns + mirrored.
            post_wns = self.best_wns
            delta = (post_wns - pre_wns) if (
                post_wns is not None and pre_wns is not None) else 0.0
            if delta >= self._PODF_EPSILON_NS:
                committed += 1
                logger.info(
                    f"[podf] call {n}: {pre_wns:.3f} -> {post_wns:.3f} ns "
                    f"(D={delta:+.3f}) in {observed_s:.0f}s — KEPT.")
                est_s = observed_s          # measured basis for the next call
                continue

            # No gain: revert Vivado's in-memory state to the banked best so
            # the LLM loop does not start from a degraded placement.
            logger.info(
                f"[podf] call {n}: {pre_wns:.3f} -> "
                f"{post_wns if post_wns is not None else float('nan'):.3f} ns "
                f"(D={delta:+.3f}) in {observed_s:.0f}s — no gain, stopping.")
            if (self._best_valid_dcp is not None
                    and Path(self._best_valid_dcp).exists()):
                try:
                    rv = await self.call_tool(
                        "vivado_open_checkpoint",
                        {"dcp_path": str(self._best_valid_dcp.resolve())})
                    if _looks_like_tool_error(rv):
                        logger.warning("[podf] revert: open_checkpoint failed; "
                                       "leaving Vivado state as-is.")
                    else:
                        self.best_wns = pre_wns
                        logger.info("[podf] revert: re-opened best_valid.dcp "
                                    f"(best_wns restored to {pre_wns:.3f} ns).")
                except Exception as exc:                  # noqa: BLE001
                    logger.warning(f"[podf] revert raised "
                                   f"{type(exc).__name__}: {exc}")
            else:
                logger.info("[podf] revert: no best_valid.dcp to re-open.")
            break

        logger.info(f"[podf] done: {committed} call(s) kept, best_wns="
                    f"{self.best_wns:.3f} ns.")

    async def _recipe_post_route_phys_opt_sweep(self, args: dict) -> str:
        """Bounded granular phys_opt_design sweep on a routed design.

        Runs ONE sub-optimization at a time (critical_cell_opt, etc.)
        instead of a full -directive Explore.  Each sub-flag is much
        smaller-scope: ~5-8 min on huge designs vs ~30-50 min for the
        full directive.  Improvements are kept; regressions revert by
        re-opening the best_valid.dcp mirror so the Vivado session
        state matches our tracked best_wns.

        This recipe is designed for budget-tight situations where the
        dispatcher has already refused a Class G / full-directive
        Explore.  See `beta_improvement_roadmap.md` for the design
        rationale.

        Returns JSON with per-flag {status, delta_wns_ns,
        delta_fmax_mhz, elapsed_s} entries plus cumulative deltas.
        """
        flags_arg = args.get("flags")
        flags = list(flags_arg) if flags_arg else list(self._DEFAULT_PHYS_OPT_SWEEP)
        epsilon_ns = _arg_float(args, "epsilon_ns", 0.010)
        skip_route_recheck = bool(args.get("skip_route_recheck", True))
        # Onion-layering options (added per 2026-05-14 critique).
        early_exit_on_first_gain = bool(args.get("early_exit_on_first_gain", True))
        max_successful_subpasses = _arg_int(args, "max_successful_subpasses", 1)
        min_remaining_time_for_next_layer_s = float(
            args.get("min_remaining_time_for_next_layer_s", 600.0)
        )

        # Cap to known sub-flags so a stray entry can't smuggle a
        # full-directive call past the dispatcher gate.
        valid_flags = {
            "critical_cell_opt", "equ_drivers_opt", "placement_opt",
            "dsp_register_opt", "restruct_opt", "slr_crossing_opt",
        }
        flags = [f for f in flags if f in valid_flags]
        if not flags:
            return json.dumps({
                "status": "error",
                "error": "no valid flags after filtering; nothing to sweep",
            })

        result = {
            "status": "running",
            "flags_attempted": [],
            "flags_committed": [],
            "flags_reverted": [],
            "per_flag": [],
            "initial_wns_ns": None,
            "final_wns_ns": None,
            "initial_fmax_mhz": None,
            "final_fmax_mhz": None,
            "delta_wns_ns": 0.0,
            "delta_fmax_mhz": 0.0,
            "elapsed_total_s": 0.0,
            "error": None,
        }

        pre_recipe_wns = self.best_wns
        if pre_recipe_wns is None or pre_recipe_wns == float("-inf"):
            return json.dumps({
                "status": "error",
                "error": "best_wns not yet established; run report_timing_summary first",
            })
        result["initial_wns_ns"] = float(pre_recipe_wns)
        result["initial_fmax_mhz"] = (
            self.calculate_fmax(pre_recipe_wns, self.clock_period)
        )

        sweep_start = time.time()

        for flag in flags:
            # Budget pre-flight at the sweep level — abort gracefully
            # if remaining < a conservative single-flag estimate.
            single_flag_estimate_s = self._estimate_tool_runtime(
                "vivado_phys_opt_design", is_risky=True)
            # Use a smaller estimate for sub-flag calls since they're
            # bounded — but err high: half the full-directive estimate.
            single_flag_estimate_s = max(120.0, single_flag_estimate_s * 0.5)
            if self._budget_deadline is not None:
                if self._budget_remaining() < single_flag_estimate_s:
                    logger.info(
                        f"phys_opt_sweep: skipping {flag} — remaining "
                        f"{self._budget_remaining():.0f}s < est "
                        f"{single_flag_estimate_s:.0f}s"
                    )
                    result["per_flag"].append({
                        "flag": flag,
                        "status": "skipped_budget",
                        "remaining_s": self._budget_remaining(),
                    })
                    break

            flag_start = time.time()
            pre_wns = self.best_wns
            result["flags_attempted"].append(flag)
            try:
                # Call phys_opt_design with ONLY this sub-flag.  We
                # explicitly do NOT pass directive — the MCP server
                # rejects mixing directive with specific options.
                phys_str = await self.call_tool(
                    "vivado_phys_opt_design", {flag: True}
                )
                if _looks_like_tool_error(phys_str):
                    elapsed_s = time.time() - flag_start
                    result["per_flag"].append({
                        "flag": flag,
                        "status": "tool_error",
                        "elapsed_s": round(elapsed_s, 1),
                        "error": str(phys_str)[:200],
                    })
                    # Continue to next flag; one error doesn't poison the sweep.
                    continue

                # Optionally verify routing didn't break.  phys_opt is
                # conservative about legality but we offer a paranoid
                # mode.  Pre-flight check the route call too.
                route_errors = None
                if not skip_route_recheck:
                    rs = await self.call_tool("vivado_report_route_status", {})
                    if not _looks_like_tool_error(rs):
                        m = re.search(r"# of nets with routing errors.*?:\s+(-?\d+)", rs)
                        if m:
                            route_errors = int(m.group(1))

                # Measure WNS using a cheap call (get_wns is faster
                # than full timing_summary).  call_tool's improvement-
                # detection branch updates self.best_wns for us.
                wns_str = await self.call_tool("vivado_get_wns", {})
                if _looks_like_tool_error(wns_str):
                    elapsed_s = time.time() - flag_start
                    result["per_flag"].append({
                        "flag": flag,
                        "status": "measure_failed",
                        "elapsed_s": round(elapsed_s, 1),
                        "error": str(wns_str)[:200],
                    })
                    continue

                try:
                    post_wns = float(wns_str.strip())
                except (ValueError, AttributeError):
                    elapsed_s = time.time() - flag_start
                    result["per_flag"].append({
                        "flag": flag,
                        "status": "measure_parse_failed",
                        "elapsed_s": round(elapsed_s, 1),
                        "wns_str": wns_str[:80],
                    })
                    continue

                elapsed_s = time.time() - flag_start
                delta_wns_ns = post_wns - (
                    pre_wns if pre_wns is not None and pre_wns != float("-inf")
                    else post_wns
                )
                delta_fmax_mhz = 0.0
                if self.clock_period:
                    pre_fmax = self.calculate_fmax(pre_wns, self.clock_period) or 0.0
                    post_fmax = self.calculate_fmax(post_wns, self.clock_period) or 0.0
                    delta_fmax_mhz = post_fmax - pre_fmax

                entry = {
                    "flag": flag,
                    "elapsed_s": round(elapsed_s, 1),
                    "pre_wns_ns": round(pre_wns, 4) if pre_wns is not None else None,
                    "post_wns_ns": round(post_wns, 4),
                    "delta_wns_ns": round(delta_wns_ns, 4),
                    "delta_fmax_mhz": round(delta_fmax_mhz, 3),
                    "route_errors": route_errors,
                }

                # Commit-or-revert decision.  An improvement above
                # epsilon is kept (call_tool's WNS handler already
                # updated self.best_wns and set _pending_best_mirror).
                # A regression triggers a revert via best_valid.dcp.
                if delta_wns_ns >= epsilon_ns:
                    entry["status"] = "committed"
                    result["flags_committed"].append(flag)
                else:
                    entry["status"] = "reverted_no_gain" if delta_wns_ns >= -epsilon_ns else "reverted_regression"
                    result["flags_reverted"].append(flag)
                    # Revert Vivado state to best_valid.dcp so the next
                    # sub-flag starts from the right baseline.
                    if (self._best_valid_dcp is not None
                            and Path(self._best_valid_dcp).exists()):
                        try:
                            revert_str = await self.call_tool(
                                "vivado_open_checkpoint",
                                {"dcp_path": str(self._best_valid_dcp.resolve())},
                            )
                            if _looks_like_tool_error(revert_str):
                                entry["revert_status"] = "open_checkpoint_failed"
                            else:
                                entry["revert_status"] = "reopened_best_valid"
                                # best_wns is a soft tracker; reset it
                                # to pre_wns since Vivado's state matches
                                # the prior best now.
                                self.best_wns = pre_wns if pre_wns is not None else self.best_wns
                        except Exception as e:
                            entry["revert_status"] = f"revert_raised:{type(e).__name__}"
                    else:
                        entry["revert_status"] = "no_best_valid_to_revert_to"

                result["per_flag"].append(entry)
                logger.info(
                    f"phys_opt_sweep[{flag}]: pre_wns={pre_wns:.3f} → "
                    f"post_wns={post_wns:.3f}, Δ={delta_wns_ns:+.3f} ns, "
                    f"status={entry['status']}, elapsed={elapsed_s:.1f}s"
                )

                # Session 23: preempt streak counter — feature-blind,
                # design-name-blind.  Only updates when the opt-in flag
                # is set.  Counts consecutive `reverted_no_gain` /
                # `reverted_regression` per-flag outcomes; any
                # `committed` entry (even Δ<0.05 ns) resets the streak
                # to zero.  Other statuses (raised, etc.) leave the
                # streak unchanged.
                #
                # Session 24: when mode == "mid_sweep", check the
                # preempt trigger immediately after the counter update
                # and break the remaining sweep flags if the helper
                # returns "triggered" or "skipped_budget".  Continuing
                # after we know the heavy rescue is unaffordable wastes
                # wall time.  Default mode "end_sweep" preserves
                # Session-23 behaviour (check only at end of function).
                if self.phys_opt_preempt_after is not None:
                    _entry_status = entry.get("status")
                    if _entry_status == "committed":
                        self._physopt_no_gain_streak = 0
                    elif _entry_status in ("reverted_no_gain",
                                            "reverted_regression"):
                        self._physopt_no_gain_streak += 1
                    if getattr(self, "phys_opt_preempt_mode",
                               "end_sweep") == "mid_sweep":
                        # Index of current flag in the original flags
                        # list; flags_remaining excludes current.
                        try:
                            _idx = flags.index(flag)
                            _remaining = max(0, len(flags) - _idx - 1)
                        except (ValueError, AttributeError):
                            _remaining = None
                        _outcome = self._maybe_emit_phys_opt_preempt(
                            result,
                            current_flag=flag,
                            flags_remaining=_remaining,
                        )
                        if _outcome == "triggered":
                            result["early_exit_reason"] = "phys_opt_preempt"
                            logger.info(
                                "phys_opt_sweep: early-exit — preempt "
                                f"triggered mid-sweep after flag "
                                f"{flag!r}; breaking {_remaining} "
                                "remaining flag(s)."
                            )
                            break
                        if _outcome == "skipped_budget":
                            result["early_exit_reason"] = (
                                "phys_opt_preempt_insufficient_budget"
                            )
                            logger.info(
                                "phys_opt_sweep: early-exit — preempt "
                                f"streak met at flag {flag!r} but "
                                "budget gate failed; breaking remaining "
                                "flags."
                            )
                            break

                # Onion-layering exit conditions (added per 2026-05-14
                # critique).  After a commit, return early so the outer
                # loop / LLM can choose a different transform on top of
                # the new state, peeling the next bottleneck instead of
                # consuming the whole budget here.
                if entry["status"] == "committed":
                    committed_count = len(result["flags_committed"])
                    if (early_exit_on_first_gain
                            and committed_count >= max_successful_subpasses):
                        result["early_exit_reason"] = (
                            f"early_exit_on_first_gain (committed {committed_count}"
                            f"/{max_successful_subpasses})"
                        )
                        logger.info(
                            f"phys_opt_sweep: early-exit after {committed_count} "
                            "commit(s); leaving wall time for next-layer recipe."
                        )
                        break
                    if (self._budget_deadline is not None
                            and self._budget_remaining() < min_remaining_time_for_next_layer_s):
                        result["early_exit_reason"] = (
                            f"remaining {self._budget_remaining():.0f}s < "
                            f"min_remaining_for_next_layer "
                            f"{min_remaining_time_for_next_layer_s:.0f}s"
                        )
                        logger.info(
                            f"phys_opt_sweep: early-exit — "
                            f"remaining {self._budget_remaining():.0f}s "
                            "below next-layer floor; finalize wins so far."
                        )
                        break

            except Exception as e:
                elapsed_s = time.time() - flag_start
                result["per_flag"].append({
                    "flag": flag,
                    "status": "raised",
                    "elapsed_s": round(elapsed_s, 1),
                    "error": f"{type(e).__name__}: {str(e)[:200]}",
                })
                logger.exception(f"phys_opt_sweep[{flag}] raised")
                # Don't break the sweep — try the next flag.

        result["elapsed_total_s"] = round(time.time() - sweep_start, 1)
        # Cumulative deltas relative to the recipe's starting point.
        result["final_wns_ns"] = float(self.best_wns) if self.best_wns is not None else None
        if (self.best_wns is not None and self.best_wns != float("-inf")
                and self.clock_period):
            final_fmax = self.calculate_fmax(self.best_wns, self.clock_period)
            initial_fmax = result["initial_fmax_mhz"]
            if final_fmax is not None and initial_fmax is not None:
                result["final_fmax_mhz"] = round(final_fmax, 2)
                result["delta_fmax_mhz"] = round(final_fmax - initial_fmax, 3)
        if self.best_wns is not None and pre_recipe_wns is not None:
            result["delta_wns_ns"] = round(self.best_wns - pre_recipe_wns, 4)
        result["status"] = (
            "success" if result["flags_committed"] else "no_gain"
        )

        # Session 23: phys_opt preempt trigger check.  Feature-blind,
        # design-name-blind, opt-in via `--phys-opt-preempt-after N`.
        # When the per-flag streak counter has reached N with no
        # intervening committed gain AND there is enough wall budget
        # remaining for the heavy rescue sequence (place_design Auto_1
        # + route_design Default), inject a user message into
        # self.messages directing the LLM to run the heavy rescue
        # next.  Fired at most once per run.
        self._maybe_emit_phys_opt_preempt(result)

        return json.dumps(result)

    def _maybe_emit_phys_opt_preempt(self, sweep_result: dict,
                                     *,
                                     current_flag: Optional[str] = None,
                                     flags_remaining: Optional[int] = None) -> str:
        """Session 23/24: emit preempt directive when the no-gain
        streak condition is met.  Default-OFF; no-op when
        `self.phys_opt_preempt_after is None`.

        Trigger conditions (ALL required):
          - flag is set (`phys_opt_preempt_after is not None`);
          - not already fired (`_phys_opt_preempt_fired is False`);
          - per-flag streak `>= phys_opt_preempt_after`;
          - budget gate: `_budget_remaining() >=
            phys_opt_preempt_budget_floor_s`;
          - no meaningful WNS lift yet (best - initial <= 0 ns).

        On trigger: latch fired; emit decision-trace record; inject
        user-role heavy-rescue message into `self.messages`.

        On gate failure with streak >= N: emit decision-trace event
        with `triggered=False` and a `skipped_reason`.

        Returns one of:
          - "off": flag not set, latched, invalid N, or streak below N.
          - "triggered": preempt fired and message injected.
          - "skipped_budget": streak met but budget gate failed.
          - "skipped_lift": streak met but WNS already lifted.
        The string return enables callers (mid-sweep loop) to decide
        whether to break the sweep loop.
        """
        if self.phys_opt_preempt_after is None:
            return "off"
        if self._phys_opt_preempt_fired:
            return "off"
        try:
            n = int(self.phys_opt_preempt_after)
        except (TypeError, ValueError):
            return "off"
        if n < 1:
            return "off"
        if self._physopt_no_gain_streak < n:
            return "off"

        # Streak has reached the threshold — record what we saw and
        # decide whether to fire or skip.
        statuses_seen = [
            e.get("status") for e in sweep_result.get("per_flag", [])
        ]
        remaining_s = self._budget_remaining()
        if remaining_s is None:
            remaining_s_f = -1.0
        else:
            remaining_s_f = float(remaining_s)
        try:
            budget_floor = float(getattr(
                self, "phys_opt_preempt_budget_floor_s", 1100.0))
        except (TypeError, ValueError):
            budget_floor = 1100.0
        mode = str(getattr(self, "phys_opt_preempt_mode", "end_sweep") or "end_sweep")
        best = self.best_wns if self.best_wns is not None else None
        init = self.initial_wns if self.initial_wns is not None else None
        if best is None or init is None or best == float("-inf"):
            wns_lift_ns = None
        else:
            wns_lift_ns = round(float(best) - float(init), 4)

        gate_budget_ok = remaining_s_f >= budget_floor
        gate_no_lift = (wns_lift_ns is None) or (wns_lift_ns <= 0.0)
        should_fire = gate_budget_ok and gate_no_lift

        base_record = {
            "action_label": "phys_opt_preempt",
            "decision_source": "controller",
            "phase": "phys_opt_preempt",
            "schema_version": 1,
            "extra": {
                "enabled": True,
                "mode": mode,
                "N": n,
                "trigger_count": int(self._physopt_no_gain_streak),
                "statuses_seen": statuses_seen,
                "current_flag": current_flag,
                "flags_remaining": flags_remaining,
                "best_wns_before": (float(best) if best is not None
                                     and best != float("-inf") else None),
                "wns_lift_ns": wns_lift_ns,
                "remaining_wall_seconds": (round(remaining_s_f, 1)
                                            if remaining_s is not None
                                            else None),
                "budget_floor_seconds": budget_floor,
                "preempt_action_family": (
                    "place_design_unplace_then_Auto1_then_route_design_Default"
                ),
                "used_for_decision": bool(should_fire),
            },
        }

        if not should_fire:
            base_record["notes"] = "preempt streak reached threshold but gate failed"
            base_record["extra"]["triggered"] = False
            if not gate_budget_ok:
                base_record["extra"]["skipped_reason"] = "insufficient_budget"
                outcome = "skipped_budget"
            elif not gate_no_lift:
                base_record["extra"]["skipped_reason"] = "wns_already_lifted"
                outcome = "skipped_lift"
            else:
                base_record["extra"]["skipped_reason"] = "unknown"
                outcome = "skipped_budget"
            self._emit_decision(base_record)
            return outcome

        # Trigger.
        self._phys_opt_preempt_fired = True
        base_record["notes"] = "preempt triggered; heavy rescue directive injected"
        base_record["extra"]["triggered"] = True
        self._emit_decision(base_record)

        preempt_message = (
            f"CONTROLLER PREEMPT: phys_opt sweep produced "
            f"{self._physopt_no_gain_streak} consecutive no-gain per-flag "
            f"outcomes (threshold N={n}) with best WNS still at "
            f"{best:.3f} ns and "
            f"{remaining_s_f/60.0:.0f} min of wall budget remaining "
            f"(floor {budget_floor/60.0:.0f} min). "
            "Stop the phys_opt sweep iteration.  Run the deterministic "
            "heavy rescue sequence next, in this order:\n"
            "  1. `vivado_run_tcl` with command `place_design -unplace`\n"
            "  2. `vivado_place_design` with `directive=\"Auto_1\"`\n"
            "  3. `vivado_route_design` with `directive=\"Default\"`\n"
            "Optionally insert one `vivado_phys_opt_design` pass between "
            "steps 2 and 3 if wall budget allows.  Measure WNS after step 3; "
            "if it regresses, revert; otherwise continue.  Do NOT issue "
            "further `phys_opt_design` calls before running the heavy step."
        )
        try:
            self.messages.append({
                "role": "user",
                "content": preempt_message,
            })
        except Exception:  # pragma: no cover — defensive
            logger.exception("phys_opt_preempt: failed to append message")
        logger.info(
            f"[CONTROLLER-PREEMPT] phys_opt preempt TRIGGERED: "
            f"mode={mode} streak={self._physopt_no_gain_streak} N={n} "
            f"remaining={remaining_s_f:.0f}s floor={budget_floor:.0f}s "
            f"best_wns={best} wns_lift_ns={wns_lift_ns} "
            f"current_flag={current_flag} flags_remaining={flags_remaining}"
        )
        return "triggered"

    async def _recipe_high_fanout_timing_replication(self, args: dict) -> str:
        """Bounded high-fanout-driver replication recipe.

        Identify (analyse): get_critical_high_fanout_nets returns the
          parent nets of fanout-pathology critical paths.
        Optimize: phys_opt_design -force_replication_on_nets surgically
          replicates the chosen drivers — no full directive, no full
          re-place.
        Measure: get_wns; commit on improvement, revert on regression.

        Designed for boom_soc / corescore_500_mod patterns where critical
        paths share a small number of fanout pathologies.  Cheaper than
        recipe_post_route_phys_opt_sweep when the pathology is concentrated
        on a few nets — typically completes in 5-15 min instead of 30-40.
        """
        num_paths = _arg_int(args, "num_paths", 20)
        min_fanout = _arg_int(args, "min_fanout", 100)
        max_nets = _arg_int(args, "max_nets_to_replicate", 10)
        epsilon_ns = _arg_float(args, "epsilon_ns", 0.010)

        result = {
            "status": "error",
            "candidates_total": 0,
            "nets_replicated": [],
            "pre_wns_ns": None,
            "post_wns_ns": None,
            "delta_wns_ns": 0.0,
            "delta_fmax_mhz": 0.0,
            "elapsed_total_s": 0.0,
            "revert_status": None,
            "error": None,
        }

        pre_wns = self.best_wns
        if pre_wns is None or pre_wns == float("-inf"):
            result["error"] = "best_wns not yet established; run report_timing_summary first"
            return json.dumps(result)
        result["pre_wns_ns"] = float(pre_wns)

        sweep_start = time.time()
        try:
            # Step 1 — IDENTIFY: get high-fanout nets on critical paths.
            hf_str = await self.call_tool("vivado_get_critical_high_fanout_nets", {
                "num_paths": num_paths,
                "min_fanout": min_fanout,
                "exclude_clocks": True,
            })
            if _looks_like_tool_error(hf_str):
                result["error"] = f"get_critical_high_fanout_nets failed: {hf_str[:200]}"
                return json.dumps(result)

            # Parse the response.  The Vivado MCP returns one net name per
            # line, optionally with a fanout suffix.  We deliberately tolerate
            # both formats since the server has shipped both over time.
            nets = []
            for raw in hf_str.splitlines():
                raw = raw.strip()
                if not raw or raw.startswith("#") or raw.startswith("(") or raw.startswith("✓"):
                    continue
                # Drop any trailing "  fanout=NNN" annotation if present.
                name = raw.split()[0]
                if name and "/" in name or "." in name or "[" in name:
                    nets.append(name)
            result["candidates_total"] = len(nets)
            if not nets:
                result["status"] = "no_candidates"
                result["error"] = "no high-fanout nets found on critical paths"
                return json.dumps(result)

            # Filter to the top N — too many nets makes the
            # force_replication_on_nets argument huge and slow.
            nets = nets[:max_nets]
            result["nets_replicated"] = nets

            # Step 2 — OPTIMIZE: phys_opt with force_replication_on_nets.
            # The MCP expects a single string; we wrap the net list as a
            # Tcl get_nets call so Vivado resolves any wildcards safely.
            tcl_nets = " ".join(nets)
            force_arg = f"[get_nets {{{tcl_nets}}}]"
            phys_str = await self.call_tool("vivado_phys_opt_design", {
                "force_replication_on_nets": force_arg,
            })
            if _looks_like_tool_error(phys_str):
                result["error"] = f"phys_opt_design (replication) failed: {phys_str[:200]}"
                return json.dumps(result)

            # Step 3 — verify route still legal (cheap).
            rs = await self.call_tool("vivado_report_route_status", {})
            if not _looks_like_tool_error(rs):
                m = re.search(r"# of nets with routing errors.*?:\s+(-?\d+)", rs)
                if m:
                    route_errors = int(m.group(1))
                    result["route_errors"] = route_errors
                    if route_errors != 0:
                        # Replication broke routing — revert.
                        result["status"] = "route_errors_revert"
                        result["error"] = f"replication left {route_errors} routing errors"
                        await self._revert_to_best_valid(result)
                        return json.dumps(result)

            # Step 4 — MEASURE.
            wns_str = await self.call_tool("vivado_get_wns", {})
            if _looks_like_tool_error(wns_str):
                result["status"] = "measure_failed_tool_error"
                result["error"] = f"get_wns after replication failed: {wns_str[:200]}"
                # Vivado state may be inconsistent (phys_opt + replication
                # can leave partial routing).  Revert to best_valid so the
                # LLM's next move starts from a known-good state.
                await self._revert_to_best_valid(result)
                return json.dumps(result)
            try:
                post_wns = float(wns_str.strip())
            except (ValueError, AttributeError):
                result["status"] = "measure_failed_parse"
                result["error"] = f"could not parse WNS: {wns_str[:120]!r}"
                await self._revert_to_best_valid(result)
                return json.dumps(result)
            result["post_wns_ns"] = post_wns

            delta_wns_ns = post_wns - pre_wns
            result["delta_wns_ns"] = round(delta_wns_ns, 4)
            if self.clock_period:
                pre_fmax = self.calculate_fmax(pre_wns, self.clock_period) or 0.0
                post_fmax = self.calculate_fmax(post_wns, self.clock_period) or 0.0
                result["delta_fmax_mhz"] = round(post_fmax - pre_fmax, 3)

            # Step 5 — COMMIT or REVERT.
            if delta_wns_ns >= epsilon_ns:
                result["status"] = "committed"
            else:
                result["status"] = "reverted_no_gain" if delta_wns_ns >= -epsilon_ns else "reverted_regression"
                await self._revert_to_best_valid(result)

        except Exception as e:
            logger.exception("recipe_high_fanout_timing_replication raised")
            result["status"] = "raised"
            result["error"] = repr(e)
        finally:
            result["elapsed_total_s"] = round(time.time() - sweep_start, 1)
            # Make sure we never leak status="error" with a populated
            # nets_replicated — if we got to step 2 successfully and a
            # later step failed silently, mark it so the LLM can tell
            # the difference between "didn't run" and "ran, no signal".
            if result["status"] == "error" and result["nets_replicated"]:
                result["status"] = "no_status_recorded_check_logs"
                if not result["error"]:
                    result["error"] = (
                        "phys_opt ran but no terminal status fired — "
                        "likely fell through after route-status check"
                    )

        return json.dumps(result)

    async def _recipe_critical_path_focused_phys_opt(self, args: dict) -> str:
        """Bounded scoped phys_opt_design on top-N critical paths.

        Identify (analyse): get_timing_paths returns the worst N paths;
          their ENDPOINT_PIN values are the targets for a custom path
          group.
        Optimize: group_path -name pg_critical_focus -to <endpoints>
          defines a Vivado path group containing only those paths.
          phys_opt_design -<sub_flag> -path_groups pg_critical_focus
          then runs the chosen sub-optimization on JUST those paths.
        Measure: report_route_status (cheap) + get_wns.
        Decision: commit on >= epsilon improvement; revert otherwise
          via best_valid.dcp.

        Designed to break boom_soc's 35-min critical_cell_opt
        bottleneck.  By restricting scope to ~20 paths, the same
        sub-flag completes in a fraction of the time, leaving room
        for layer-2 transforms.

        See `.planning/beta/boom_soc_pathology_diagnosis.md` and
        the recipe card in `.planning/beta/recipe_cards/`.
        """
        num_paths = _arg_int(args, "num_paths", 20)
        sub_flag = str(args.get("sub_flag", "critical_cell_opt"))
        epsilon_ns = _arg_float(args, "epsilon_ns", 0.010)

        # Guard: only allow known sub-flags so a stray name can't
        # smuggle a full-directive call past the dispatcher.
        valid_sub_flags = {
            "critical_cell_opt", "equ_drivers_opt", "placement_opt",
            "restruct_opt", "dsp_register_opt", "critical_pin_opt",
        }
        if sub_flag not in valid_sub_flags:
            return json.dumps({
                "status": "error",
                "error": f"invalid sub_flag {sub_flag!r}; must be in {sorted(valid_sub_flags)}",
            })

        pg_name = "pg_critical_focus"
        result = {
            "status": "error",
            "num_paths": num_paths,
            "sub_flag": sub_flag,
            "path_group_name": pg_name,
            "endpoints_captured": 0,
            "pre_wns_ns": None,
            "post_wns_ns": None,
            "delta_wns_ns": 0.0,
            "delta_fmax_mhz": 0.0,
            "elapsed_total_s": 0.0,
            "scoped_phys_opt_elapsed_s": 0.0,
            "revert_status": None,
            "error": None,
        }

        pre_wns = self.best_wns
        if pre_wns is None or pre_wns == float("-inf"):
            result["error"] = "best_wns not yet established; run report_timing_summary first"
            return json.dumps(result)
        result["pre_wns_ns"] = float(pre_wns)

        sweep_start = time.time()
        try:
            # Step 1 — IDENTIFY: extract top-N critical path endpoints
            # via a single Tcl round-trip so we get a clean list.
            # Vivado 12-608 rejects -delay_type with -setup/-hold;
            # -setup already implies max-delay analysis.  Bug surfaced
            # in the 2026-05-14 boom_soc scoped run.
            tcl_extract = (
                f"set tps [get_timing_paths -max_paths {num_paths} "
                f"-setup -sort_by slack]; "
                f"set ends [list]; "
                f"foreach tp $tps {{ "
                f"  set ep [get_property ENDPOINT_PIN $tp]; "
                f"  if {{$ep ne {{}}}} {{lappend ends $ep}} "
                f"}}; "
                f"puts \"ENDPOINTS:[llength $ends]\"; "
                f"foreach e $ends {{ puts \"EP:$e\" }}"
            )
            extract_str = await self.call_tool(
                "vivado_run_tcl", {"command": tcl_extract}
            )
            if _looks_like_tool_error(extract_str):
                result["error"] = f"endpoint extraction failed: {str(extract_str)[:200]}"
                return json.dumps(result)
            endpoints: list[str] = []
            for line in str(extract_str).splitlines():
                line = line.strip()
                if line.startswith("EP:"):
                    ep = line[3:].strip()
                    if ep:
                        endpoints.append(ep)
            result["endpoints_captured"] = len(endpoints)
            if not endpoints:
                result["status"] = "no_endpoints"
                result["error"] = "no critical path endpoints captured (get_timing_paths returned empty)"
                return json.dumps(result)

            # Step 2 — DEFINE path group with those endpoints.
            # Use `catch {group_path -default}` first to clear any
            # prior group of the same name from a previous recipe
            # invocation in the same session.
            endpoints_tcl = " ".join("{" + e + "}" for e in endpoints)
            tcl_pg = (
                f"catch {{group_path -name {pg_name} -default}}; "
                f"group_path -name {pg_name} -to [get_pins {{{' '.join(endpoints)}}}]; "
                f"puts \"PATH_GROUP:{pg_name}\""
            )
            pg_str = await self.call_tool(
                "vivado_run_tcl", {"command": tcl_pg}
            )
            if _looks_like_tool_error(pg_str):
                result["error"] = f"group_path setup failed: {str(pg_str)[:200]}"
                return json.dumps(result)

            # Step 3 — OPTIMIZE: scoped phys_opt with the chosen
            # sub-flag and our custom path group.
            phys_start = time.time()
            phys_str = await self.call_tool("vivado_phys_opt_design", {
                sub_flag: True,
                "path_groups": pg_name,
            })
            result["scoped_phys_opt_elapsed_s"] = round(time.time() - phys_start, 1)
            if _looks_like_tool_error(phys_str):
                result["error"] = f"scoped phys_opt failed: {str(phys_str)[:200]}"
                await self._revert_to_best_valid(result)
                return json.dumps(result)

            # Step 4 — MEASURE.  Use the cheap get_wns call.
            wns_str = await self.call_tool("vivado_get_wns", {})
            if _looks_like_tool_error(wns_str):
                result["status"] = "measure_failed_tool_error"
                result["error"] = f"get_wns after scoped phys_opt failed: {str(wns_str)[:200]}"
                await self._revert_to_best_valid(result)
                return json.dumps(result)
            try:
                post_wns = float(str(wns_str).strip())
            except (ValueError, AttributeError):
                result["status"] = "measure_failed_parse"
                result["error"] = f"could not parse WNS: {str(wns_str)[:120]!r}"
                await self._revert_to_best_valid(result)
                return json.dumps(result)
            result["post_wns_ns"] = post_wns

            delta_wns_ns = post_wns - pre_wns
            result["delta_wns_ns"] = round(delta_wns_ns, 4)
            if self.clock_period:
                pre_fmax = self.calculate_fmax(pre_wns, self.clock_period) or 0.0
                post_fmax = self.calculate_fmax(post_wns, self.clock_period) or 0.0
                result["delta_fmax_mhz"] = round(post_fmax - pre_fmax, 3)

            # Step 5 — COMMIT or REVERT.
            if delta_wns_ns >= epsilon_ns:
                result["status"] = "committed"
            else:
                result["status"] = "reverted_no_gain" if delta_wns_ns >= -epsilon_ns else "reverted_regression"
                await self._revert_to_best_valid(result)

        except Exception as e:
            logger.exception("recipe_critical_path_focused_phys_opt raised")
            result["status"] = "raised"
            result["error"] = repr(e)
        finally:
            result["elapsed_total_s"] = round(time.time() - sweep_start, 1)

        return json.dumps(result)

    async def _revert_to_best_valid(self, result: dict) -> None:
        """Restore Vivado state from best_valid.dcp.  Recipe helper.

        Updates result['revert_status'] with the outcome of the revert.
        Idempotent — safe to call when best_valid mirror doesn't exist
        (records the absence instead of erroring out).
        """
        if (self._best_valid_dcp is None
                or not Path(self._best_valid_dcp).exists()):
            result["revert_status"] = "no_best_valid_to_revert_to"
            return
        try:
            revert_str = await self.call_tool(
                "vivado_open_checkpoint",
                {"dcp_path": str(self._best_valid_dcp.resolve())},
            )
            if _looks_like_tool_error(revert_str):
                result["revert_status"] = "open_checkpoint_failed"
            else:
                result["revert_status"] = "reopened_best_valid"
        except Exception as e:
            result["revert_status"] = f"revert_raised:{type(e).__name__}"

    def _phase1_wall_allowance_remaining_s(self) -> Optional[float]:
        """C1-T4a: seconds left of the cumulative Phase-1 wall allowance.

        Allowance = phase1_wall_frac × max_wall_seconds, measured from the
        top of perform_initial_analysis.  Returns None when uncapped
        (no wall budget set, Phase 1 not started, or frac non-positive) —
        callers treat None as "no cap" for legacy/dev-mode compatibility.
        """
        if (self.max_wall_seconds is None
                or self._phase1_start_ts is None
                or self.phase1_wall_frac <= 0.0):
            return None
        allowance = float(self.phase1_wall_frac) * float(self.max_wall_seconds)
        return allowance - (time.time() - self._phase1_start_ts)

    def _phase1_skipped_display(self) -> list[str]:
        """Render phase1_skipped labels with their skip reason when known
        (C1-T4a: wall-capped skips carry reason "phase1_wall_cap")."""
        return [
            f"{label} ({self.phase1_skip_reasons[label]})"
            if label in self.phase1_skip_reasons else label
            for label in self.phase1_skipped
        ]

    async def _phase1_call(
        self,
        tool_name: str,
        arguments: dict,
        timeout_seconds: float,
        *,
        mandatory: bool = False,
        label: Optional[str] = None,
    ) -> Optional[str]:
        """
        Phase-1 tool-call wrapper with timeout + graceful degradation.

        Why this exists: large designs (boom_soc, ispd16_example2) can blow
        through the default server-side timeouts (300 s open_checkpoint,
        600 s high-fanout, etc.) on Phase 1 analysis steps that aren't
        strictly required to drive the LLM.  Hard-failing on those steps
        prevents the optimizer from ever reaching its iteration loop on
        those designs.  This wrapper:

        - Multiplies `timeout_seconds` by `self.phase1_timeout_scale`.
        - Injects `timeout` into the MCP tool arguments (Vivado tools we
          call from Phase 1 all expose this field; other servers safely
          ignore unknown kwargs).
        - Belt-and-braces with an asyncio wait_for at the client side
          (timeout + 30 s headroom) so a non-cooperative server can't hang
          the optimizer.
        - On any failure (Python timeout, MCP error, or tool-error envelope):
            * mandatory=True  → re-raise RuntimeError to halt Phase 1.
            * mandatory=False → log a warning, append `label` to
              self.phase1_skipped, return None.  Callers degrade gracefully.

        Returns the raw tool response string on success, or None on a
        non-mandatory failure.
        """
        label = label or tool_name
        effective = float(timeout_seconds) * float(self.phase1_timeout_scale)
        # C1-T4a (jul20 phase-1 red-team audit): cumulative Phase-1 wall
        # cap.  OPTIONAL steps stop launching once Phase 1 has consumed
        # phase1_wall_frac of the wall budget, and their scaled timeout
        # never exceeds the allowance still remaining (scale 3.0 ×
        # uncapped optional steps was the one remaining alpha=0 mechanism
        # on a >>boom hidden design).  Mandatory steps are never capped.
        if not mandatory:
            remaining = self._phase1_wall_allowance_remaining_s()
            if remaining is not None:
                if remaining <= 0.0:
                    msg = (
                        f"Phase 1 step '{label}' skipped: cumulative Phase-1 "
                        f"wall cap reached ({self.phase1_wall_frac:.0%} of "
                        f"{self.max_wall_seconds:.0f}s wall budget)."
                    )
                    logger.warning(msg)
                    self.phase1_skipped.append(label)
                    self.phase1_skip_reasons[label] = "phase1_wall_cap"
                    return None
                if effective > remaining:
                    logger.info(
                        f"Phase 1 step '{label}': scaled timeout "
                        f"{effective:.0f}s clamped to remaining Phase-1 "
                        f"allowance {remaining:.0f}s (C1-T4a wall cap)."
                    )
                    effective = remaining
        args = dict(arguments)
        args.setdefault("timeout", effective)
        try:
            result = await asyncio.wait_for(
                self.call_tool(tool_name, args),
                timeout=effective + 30.0,
            )
        except asyncio.TimeoutError:
            msg = (
                f"Phase 1 step '{label}' timed out client-side after "
                f"{effective + 30.0:.0f}s."
            )
            logger.warning(msg)
            self.phase1_skipped.append(label)
            if mandatory:
                raise RuntimeError(msg)
            return None
        except Exception as e:
            msg = f"Phase 1 step '{label}' raised {type(e).__name__}: {e}"
            logger.warning(msg)
            self.phase1_skipped.append(label)
            if mandatory:
                raise RuntimeError(msg)
            return None

        if _looks_like_tool_error(result):
            msg = f"Phase 1 step '{label}' tool-error envelope: {str(result)[:200]}"
            logger.warning(msg)
            self.phase1_skipped.append(label)
            if mandatory:
                raise RuntimeError(msg)
            return None
        return result

    async def call_tool(self, tool_name: str, arguments: dict) -> str:
        """Execute a tool call on the appropriate MCP server."""
        # Synthetic high-level recipe tools — see _collect_tools.
        if tool_name == "recipe_cell_replacement":
            return await self._recipe_cell_replacement(arguments)
        if tool_name == "recipe_lut_optimization":
            return await self._recipe_lut_optimization(arguments)
        if tool_name == "recipe_register_retiming":
            return await self._recipe_register_retiming(arguments)
        if tool_name == "recipe_post_route_phys_opt_sweep":
            return await self._recipe_post_route_phys_opt_sweep(arguments)
        if tool_name == "recipe_high_fanout_timing_replication":
            return await self._recipe_high_fanout_timing_replication(arguments)
        if tool_name == "recipe_critical_path_focused_phys_opt":
            return await self._recipe_critical_path_focused_phys_opt(arguments)

        # Finalize bypass: when _in_finalize=True the call comes from
        # _finalize_output_dcp (or one of its inner writes) AFTER the iter
        # loop has already paid for whatever gain Vivado holds in memory.
        # Refusing these writes loses the gain (digit-recognition 2026-05-18:
        # +22.89 MHz lost). Bypass the budget gate entirely; the per-call
        # asyncio timeout below still applies as a hung-Vivado guard.
        if self._in_finalize or self._in_ils_stage:
            skip, skip_reason = (False, "")
        else:
            # Deadline-aware skip — pre-flight check.  Three escape hatches:
            #   1. budget already exhausted → skip + mark _budget_killed
            #   2. remaining < finalize_reserve + MIN_USEFUL_TOOL_SECONDS → skip
            #   3. tool is risky and estimated runtime exceeds usable window
            # See _should_skip_for_budget for the policy.  We return an error
            # envelope so the LLM sees the skip in the next round and can pick
            # a cheaper move; we also flip _budget_killed so the iteration loop
            # finalizes cleanly at its next budget check.
            skip, skip_reason = self._should_skip_for_budget(tool_name, arguments)
        # jul25 panel (gemini seat, 5/5 — rated above every MHz on the board):
        # XDC / timing-constraint edits are DISQUALIFYING. Refuse them at the
        # boundary and tell the model why, so it picks a legal physical move.
        # This is PREVENTION; the fingerprint diff at ship time is DETECTION,
        # and detection is the load-bearing layer (string matching is
        # defeatable, a fingerprint diff is not).
        if tool_name == "vivado_run_tcl" and arguments:
            try:
                from optimizer.constraint_guard import (deny_reason,
                                                        is_constraint_mutating)
                _cmd = (arguments.get("command")
                        or arguments.get("tcl_command") or "")
                _hit, _which = is_constraint_mutating(_cmd)
                if _hit:
                    logger.warning(
                        f"[constraint-guard] REFUSED {_which}: timing "
                        f"constraint edits are disqualifying. Payload: "
                        f"{str(_cmd)[:200]}")
                    self.tool_call_details.append({
                        "tool_name": tool_name,
                        "status": "refused_constraint_edit",
                        "detail": _which,
                        # Every consumer of tool_call_details sums this key;
                        # a guard entry without it crashed a completed run.
                        "elapsed_time": 0.0,
                    })
                    return deny_reason(_which)
            except Exception as e:  # never let the guard break a run
                logger.warning(f"[constraint-guard] check raised (ignored): {e!r}")
        # jul25 panel (4/5 seats converged): cheap pre-flight second opinion
        # before a heavy Vivado move. ADVISORY ONLY — it cannot skip, cancel or
        # rewrite this call; it only appends a note the planner may ignore on
        # the next round. Runs AFTER the budget skip decision so it can never
        # influence it, and is a strict no-op with the flag off (default).
        if not skip:
            try:
                await self._maybe_plan_critique(tool_name, arguments)
            except Exception as e:
                logger.warning(f"plan-critic raised (ignored): {e!r}")
        if skip:
            self._strategies_skipped_budget.append(f"{tool_name} ({skip_reason})")
            self._budget_killed = True
            # D3 signal (c): "nothing schedulable within the remaining
            # wall" — the sanctioned budget-kill saturation signal.
            self._maybe_arm_wall_handback(f"budget_skip:{skip_reason}")
            mw = self.max_wall_seconds
            mw_str = f"{mw:.0f}s" if mw is not None else "n/a"
            logger.warning(
                f"Budget skip: {tool_name} not started ({skip_reason}); "
                f"remaining={self._budget_remaining():.0f}s of {mw_str}."
            )
            self.tool_call_details.append({
                "tool_name": tool_name,
                "iteration": self.iteration,
                "elapsed_time": 0.0,
                "wns": None,
                "error": True,
                "error_message": f"budget_skip:{skip_reason}",
            })
            skip_payload = json.dumps({
                "error": "tool_skipped_budget",
                "reason": skip_reason,
                "remaining_seconds": self._budget_remaining(),
            })
            # P1/P2 (2026-05-20 s2): classify skip + emit trace event.
            # Skip path is the BUDGET_SKIP code in the taxonomy.
            tool_err = self._classify_tool_payload(
                skip_payload, context="call_tool_skip"
            )
            self._emit_decision({
                "decision_source": "executor",
                "phase": "call_tool",
                "tool_name": tool_name,
                "action_label": "budget_skip",
                "runtime_s": 0.0,
                "tool_error_code": tool_err.code if tool_err is not None else "BUDGET_SKIP",
                "notes": skip_reason,
            })
            return skip_payload

        # ---- R-D1-2 unbankable-sequence gate (2026-07-19) ----
        # A routed-state-DESTROYING op (route_design -unroute,
        # place_design on a routed design, or a full re-route while
        # unrouted) forces a MANDATORY full re-route before anything can
        # be banked again.  The budget skip above cannot see that:
        # -unroute itself is ~16s, and a first-ever route_design falls
        # back to the flat 600s estimate (boom_soc_2025.1_v2 eval
        # 2026-07-14: real need >1633s on 379,380 cells → budget-killed
        # → unrouted → alpha=0).  Gate the destroying op on the predicted
        # cost of that follow-up re-route (optimizer/route_gate.py,
        # size-scaled), refusing BEFORE it starts with a steering
        # envelope toward the bankable incremental phys_opt ladder.
        # Placed AFTER the finalize/ILS bypass above so it shares that
        # discipline: finalize writes and ILS's own self-capped
        # unroute/reroute cycles (ils_polish _heavy_to) are never gated.
        # Assessment is pure (no Vivado calls) — nothing here can hang.
        # jul25 (#8): router BLOCK veto. Both jul25 panels asked 5/5 for
        # plan.blocks to stop being advisory prompt text. Same bypass
        # discipline as the unroute-gate below: finalize and ILS are never
        # vetoed, and the check is pure (no Vivado calls, cannot hang).
        # Fails OPEN on anything unexpected — a router problem must never
        # freeze the optimizer.
        if (not self._in_finalize and not self._in_ils_stage
                and _router_blocked_reason is not None):
            _blk = _router_blocked_reason(
                getattr(self, "recipe_router_plan", None), tool_name, arguments)
            if _blk:
                logger.warning(f"[router-block] REFUSED {tool_name}: {_blk}")
                self.tool_call_details.append({
                    "tool_name": tool_name,
                    "iteration": self.iteration,
                    "elapsed_time": 0.0,
                    "wns": None,
                    "error": True,
                    "error_message": f"router_block_refused:{_blk[:160]}",
                })
                return (f"REFUSE: {_blk}. This move is forbidden for this "
                        f"design's feature profile — choose a step from the "
                        f"recipe plan's action list instead.")

        if (self._unroute_gate_enabled
                and not self._in_finalize
                and not self._in_ils_stage
                and self.is_routed_state_destroying(tool_name, arguments)):
            from optimizer.route_gate import assess_destructive_reroute
            assessment = assess_destructive_reroute(
                self._budget_remaining(),
                self.tool_call_details,
                self._input_cell_count,
            )
            if not assessment.feasible:
                # Observable in harness logs — the Plan-04 DEBUG-WALL
                # run greps for this line (same discipline as the
                # "Budget skip:" log above).
                logger.warning(
                    f"[unroute-gate] REFUSED {tool_name}: "
                    f"{assessment.reason}"
                )
                self.tool_call_details.append({
                    "tool_name": tool_name,
                    "iteration": self.iteration,
                    "elapsed_time": 0.0,
                    "wns": None,
                    "error": True,
                    "error_message":
                        f"unroute_gate_refused:{assessment.reason[:160]}",
                })
                # Same {"error": ...} envelope shape as the budget skip
                # so _looks_like_tool_error classifies the refusal
                # correctly (RESEARCH Landmine 8).  NOTE: unlike the
                # budget skip, _budget_killed is NOT flipped — the run
                # must continue with bankable incremental work.
                refusal_payload = json.dumps({
                    "error": "unroute_gate_refused",
                    "reason": assessment.reason,
                    "predicted_reroute_s": assessment.predicted_reroute_s,
                    "remaining_seconds": assessment.remaining_wall_s,
                    "steering": (
                        "Do NOT destroy the current routed state — the "
                        "mandatory full re-route cannot finish in the "
                        "remaining wall budget. Run a bankable "
                        "incremental step instead: phys_opt_design on "
                        "the routed design (e.g. -directive "
                        "AggressiveExplore or AlternateFlowWithRetiming) "
                        "or an incremental route_design that preserves "
                        "routed state, then measure WNS so the "
                        "improvement is banked."
                    ),
                })
                tool_err = self._classify_tool_payload(
                    refusal_payload, context="call_tool_unroute_gate"
                )
                self._emit_decision({
                    "decision_source": "executor",
                    "phase": "call_tool",
                    "tool_name": tool_name,
                    "action_label": "unroute_gate_refused",
                    "runtime_s": 0.0,
                    "tool_error_code": (tool_err.code
                                        if tool_err is not None
                                        else "UNROUTE_GATE_REFUSED"),
                    "notes": assessment.reason,
                })
                return refusal_payload

        # ---- C1-T3 post-route polish reserve gate (2026-07-20) ----
        # boom_soc_v2 official beta: the final post-route phys_opt polish
        # was refused at est 600s > 443s remaining because speculative
        # heavy ops had already burned the tail.  While the reserve is
        # ARMED (routed banked best + polish stages pending, see
        # _polish_reserve_armed_s) a speculative routed-state-DESTROYING
        # op must fit (remaining − reserve): the reserved window belongs
        # to the polish stages.  State-PRESERVING heavy ops (phys_opt on
        # the routed design, incremental route) are polish-flavored and
        # keep seeing the full remaining window — that is exactly the op
        # boom needed at the end of the wall.  Like the unroute gate
        # (and UNLIKE the budget skip above) this does NOT flip
        # _budget_killed: the run must continue with bankable
        # state-preserving work inside the reserved window.
        if (not self._in_finalize
                and not self._in_ils_stage
                and self._is_risky(tool_name, arguments)
                and self.is_routed_state_destroying(tool_name, arguments)):
            _reserve = self._polish_reserve_armed_s()
            if _reserve > 0.0:
                _remaining = self._budget_remaining()
                _est = self._estimate_tool_runtime(tool_name, is_risky=True)
                _window = _remaining - _reserve
                if _est > _window:
                    _reason = (
                        f"estimated_{_est:.0f}s_exceeds_speculative_window_"
                        f"{max(0.0, _window):.0f}s_(polish_reserve_"
                        f"{_reserve:.0f}s_of_{_remaining:.0f}s_remaining)")
                    logger.warning(
                        f"[polish-reserve] REFUSED speculative {tool_name}: "
                        f"{_reason}")
                    self.tool_call_details.append({
                        "tool_name": tool_name,
                        "iteration": self.iteration,
                        "elapsed_time": 0.0,
                        "wns": None,
                        "error": True,
                        "error_message": f"polish_reserve_refused:{_reason}",
                    })
                    reserve_payload = json.dumps({
                        "error": "polish_reserve_refused",
                        "reason": _reason,
                        "polish_reserve_s": _reserve,
                        "remaining_seconds": _remaining,
                        "steering": (
                            "The last "
                            f"{_reserve:.0f}s of the wall are reserved for "
                            "the final post-route polish of the banked "
                            "best. Do not start another full place/route "
                            "gamble now. Run a state-preserving step "
                            "instead: phys_opt_design on the routed design "
                            "(e.g. -directive AggressiveExplore) or an "
                            "incremental route_design, then measure WNS so "
                            "the improvement is banked."
                        ),
                    })
                    tool_err = self._classify_tool_payload(
                        reserve_payload, context="call_tool_polish_reserve")
                    self._emit_decision({
                        "decision_source": "executor",
                        "phase": "call_tool",
                        "tool_name": tool_name,
                        "action_label": "polish_reserve_refused",
                        "runtime_s": 0.0,
                        "tool_error_code": (tool_err.code
                                            if tool_err is not None
                                            else "POLISH_RESERVE_REFUSED"),
                        "notes": _reason,
                    })
                    return reserve_payload

        # Parse server prefix from tool name
        if tool_name.startswith("rapidwright_"):
            session = self.rapidwright_session
            actual_name = tool_name[len("rapidwright_"):]
        elif tool_name.startswith("vivado_"):
            session = self.vivado_session
            actual_name = tool_name[len("vivado_"):]
        else:
            return json.dumps({"error": f"Unknown tool prefix in: {tool_name}"})

        # Track timing for this tool call
        start_time = time.time()
        wns_measured = None
        error_occurred = False
        # P1 (2026-05-20 s2): snapshot best_wns before the call so the
        # trace record can report wns_before → wns_after deltas without
        # extra Vivado round-trips.  None when no measurement exists.
        wns_before_call = (
            float(self.best_wns)
            if (self.best_wns is not None and self.best_wns != float("-inf"))
            else None
        )

        try:
            logger.info(f"Calling {tool_name} with args: {json.dumps(arguments)[:200]}...")
            # In finalize mode, use a fixed per-call timeout (120s) instead
            # of the deadline-derived one. The deadline-derived timeout
            # would be 0 here (budget exhausted) and asyncio.wait_for(0)
            # cancels immediately. write_checkpoint and write_edif take a
            # few seconds on most designs and up to ~60s on the largest;
            # 120s catches a hung Vivado without artificially capping a
            # legitimate finalize write.
            if self._in_finalize:
                timeout = FINALIZE_PER_CALL_TIMEOUT_S
            else:
                # C1-T3: tool identity lets the timeout cap speculative
                # destroying ops at (remaining − polish reserve) — the
                # runtime enforcement of the reserve fence.  ILS-stage
                # calls pass tool_name=None so they are NEVER capped
                # here: the polish sub-stages must see the full window,
                # and ILS-internal ruin cycles are fenced by the reduced
                # deadline_ts in _ils_polish_body instead.
                timeout = self._deadline_aware_timeout(
                    None if self._in_ils_stage else tool_name, arguments)
            if timeout is None:
                # No budget set (legacy dev mode) — call without a timeout.
                result = await session.call_tool(actual_name, arguments)
            else:
                # Wrap in asyncio.wait_for so a runaway Vivado call cannot
                # silently consume the whole budget the way uncapped runs
                # did pre-fix (see boom_soc 2026-05-13: phys_opt took 48 min
                # while budget was nominally 55 min, but iteration-boundary
                # check could not interrupt).  TimeoutError → record skip,
                # flip _budget_killed, return error envelope.
                try:
                    result = await asyncio.wait_for(
                        session.call_tool(actual_name, arguments),
                        timeout=timeout,
                    )
                except asyncio.TimeoutError:
                    elapsed_time = time.time() - start_time
                    self._budget_killed = True
                    # FIX 5 (S3, observability only): the kill came from the
                    # C1-T3 polish-reserve FENCE cap (timeout = remaining −
                    # reserve, fires `reserve` seconds BEFORE the genuine
                    # deadline), not from budget exhaustion — label it so
                    # forensics can tell the two apart.  First cause wins.
                    if (self._last_timeout_fence_capped
                            and self._budget_kill_cause is None):
                        self._budget_kill_cause = "polish_reserve_fence"
                    self._strategies_skipped_budget.append(
                        f"{tool_name} (timed_out after {elapsed_time:.0f}s of "
                        f"{timeout:.0f}s allowance)"
                    )
                    logger.warning(
                        f"Budget timeout: {tool_name} cancelled after "
                        f"{elapsed_time:.0f}s (allowance={timeout:.0f}s); "
                        f"remaining={self._budget_remaining():.0f}s. Session "
                        "may be compromised — finalizing soon."
                    )
                    self.tool_call_details.append({
                        "tool_name": tool_name,
                        "iteration": self.iteration,
                        "elapsed_time": elapsed_time,
                        "wns": None,
                        "error": True,
                        "error_message": f"budget_timeout_after_{elapsed_time:.0f}s",
                    })
                    # P1/P2 (2026-05-20 s2): classify + trace timeout.
                    self._emit_decision({
                        "decision_source": "executor",
                        "phase": "call_tool",
                        "tool_name": tool_name,
                        "action_label": "budget_timeout",
                        "runtime_s": elapsed_time,
                        "tool_error_code": "TIMEOUT_BUDGET",
                        "notes": (
                            f"allowance_s={timeout:.0f} elapsed_s={elapsed_time:.0f}"
                        ),
                    })
                    return json.dumps({
                        "error": "tool_timed_out_budget",
                        "elapsed_seconds": elapsed_time,
                        "allowance_seconds": timeout,
                    })
            
            # Extract text content from result
            if result.content:
                text_parts = [c.text for c in result.content if hasattr(c, 'text')]
                result_text = "\n".join(text_parts)
            else:
                result_text = "(no output)"
            
            # Track WNS from timing reports and get_wns calls
            if tool_name == "vivado_report_timing_summary":
                # If target clock is set, get clock-specific WNS instead of overall
                if self.target_clock:
                    clock_wns = None
                    try:
                        clock_wns = await super().get_wns_for_target_clock(self._call_vivado_tool)
                    except Exception as e:
                        # aug08: only a PROBE failure falls back to overall
                        # WNS. This except used to wrap the entire tracking
                        # block below, so a raise from the mirror/guard
                        # machinery nulled target_clock for the REST OF THE
                        # RUN — and on a multi-clock design later genuine
                        # improvements on the scored clock became invisible
                        # (overall WNS masks them).
                        logger.warning(f"Failed to get clock-specific WNS, falling back to overall: {e}")
                        self.target_clock = None  # Fall through to overall WNS parsing
                    if clock_wns is not None:
                        try:
                            current_wns = clock_wns
                            wns_measured = current_wns
                            current_fmax = self.calculate_fmax(current_wns, self.clock_period)
                            fmax_str = f", fmax: {current_fmax:.2f} MHz" if current_fmax is not None else ""
                            if current_wns > self.best_wns and not await self._routed_ok_for_best():
                                logger.warning(f"WNS {current_wns:.3f} beats best but design is NOT fully routed (estimated timing) — REJECTED as best (phantom-best guard, jul05 preview #10).")
                            elif current_wns > self.best_wns:
                                old_best_wns = self.best_wns
                                logger.info(f"New best WNS (clock: {self.target_clock}): {current_wns:.3f} ns{fmax_str} (improved from {old_best_wns:.3f} ns)")
                                self.best_wns = current_wns
                                self.last_improvement_iter = self.iteration  # [BETA-CTRL-V0]
                                self.last_improvement_time = time.time()  # ILS stagnation clock
                                self.regression_warning_sent = False  # [BETA-CTRL-V0.1] re-arm
                                self._pending_best_mirror = True  # mirror best_valid.{dcp,edf} next iter top
                                self._pending_best_mirror_epoch = self._mutation_epoch
                                # [POST-2026-05-19 mirror-fix] Eager-capture the
                                # best-valid disk mirror RIGHT NOW, before the LLM
                                # can issue a degrading intra-iteration tool call.
                                # See _mirror_best_valid_now docstring for the
                                # vexriscv_v2 incident this guards against.
                                await self._mirror_best_valid_now(eager=True)
                            else:
                                logger.info(f"Current WNS (clock: {self.target_clock}): {current_wns:.3f} ns{fmax_str} (best is still {self.best_wns:.3f} ns)")
                                # [BETA-CTRL-V0.2] regression-detection removed; v0.1 logicnets
                                # test showed mid-iteration injection cut off productive
                                # in-iteration exploration.  Track only.
                                pass
                        except Exception as e:
                            # Best-tracking machinery failed AFTER a good
                            # measurement — swallow (as before) but KEEP the
                            # clock; the next report re-measures normally.
                            logger.warning(
                                f"clock-WNS best-tracking raised (ignored; "
                                f"target_clock kept): {e!r}")

                if not self.target_clock or wns_measured is None:
                    timing_info = parse_timing_summary_static(result_text)
                    if timing_info["wns"] is not None:
                        current_wns = timing_info["wns"]
                        wns_measured = current_wns
                        current_fmax = self.calculate_fmax(current_wns, self.clock_period)
                        fmax_str = f", fmax: {current_fmax:.2f} MHz" if current_fmax is not None else ""
                        if current_wns > self.best_wns and not await self._routed_ok_for_best():
                            logger.warning(f"WNS {current_wns:.3f} beats best but design is NOT fully routed (estimated timing) — REJECTED as best (phantom-best guard, jul05 preview #10).")
                        elif current_wns > self.best_wns:
                            old_best_wns = self.best_wns
                            logger.info(f"New best WNS: {current_wns:.3f} ns{fmax_str} (improved from {old_best_wns:.3f} ns)")
                            self.best_wns = current_wns
                            self.last_improvement_iter = self.iteration  # [BETA-CTRL-V0]
                            self.last_improvement_time = time.time()  # ILS stagnation clock
                            self.regression_warning_sent = False  # [BETA-CTRL-V0.1] re-arm
                            self._pending_best_mirror = True  # mirror best_valid.{dcp,edf} next iter top
                            self._pending_best_mirror_epoch = self._mutation_epoch
                            # [POST-2026-05-19 mirror-fix] Eager-capture (see
                            # docstring of _mirror_best_valid_now).
                            await self._mirror_best_valid_now(eager=True)
                        else:
                            logger.info(f"Current WNS: {current_wns:.3f} ns{fmax_str} (best is still {self.best_wns:.3f} ns)")
                            # [BETA-CTRL-V0.2] regression-detection removed (see commit msg).
            
            # Also track WNS from get_wns tool (returns just the numeric WNS value)
            elif tool_name == "vivado_get_wns":
                try:
                    current_wns = float(result_text.strip())
                    wns_measured = current_wns
                    current_fmax = self.calculate_fmax(current_wns, self.clock_period)
                    fmax_str = f", fmax: {current_fmax:.2f} MHz" if current_fmax is not None else ""
                    if current_wns > self.best_wns and not await self._routed_ok_for_best():
                        logger.warning(f"WNS {current_wns:.3f} beats best but design is NOT fully routed (estimated timing) — REJECTED as best (phantom-best guard, jul05 preview #10).")
                    elif current_wns > self.best_wns:
                        old_best_wns = self.best_wns
                        logger.info(f"New best WNS (from get_wns): {current_wns:.3f} ns{fmax_str} (improved from {old_best_wns:.3f} ns)")
                        self.best_wns = current_wns
                        self.last_improvement_iter = self.iteration  # [BETA-CTRL-V0]
                        self.last_improvement_time = time.time()  # ILS stagnation clock
                        self.regression_warning_sent = False  # [BETA-CTRL-V0.1] re-arm
                        self._pending_best_mirror = True  # mirror best_valid.{dcp,edf} next iter top
                        self._pending_best_mirror_epoch = self._mutation_epoch
                        # [POST-2026-05-19 mirror-fix] Eager-capture (see
                        # docstring of _mirror_best_valid_now).
                        await self._mirror_best_valid_now(eager=True)
                    else:
                        logger.info(f"Current WNS (from get_wns): {current_wns:.3f} ns{fmax_str} (best is still {self.best_wns:.3f} ns)")
                        # [BETA-CTRL-V0.2] regression-detection removed (see commit msg).
                except (ValueError, AttributeError):
                    logger.warning(f"Could not parse WNS from get_wns output: {result_text[:100]}")
            
            elapsed_time = time.time() - start_time
            # Feed runtime history → _estimate_tool_runtime for future
            # deadline-aware gating decisions.
            self._record_tool_runtime(tool_name, elapsed_time)
            # Wall economics: size the observation window from COMPLETED
            # heavy moves only (see _heavy_move_seconds).
            if elapsed_time >= 1.0 and self._is_risky(tool_name, arguments):
                self._heavy_move_seconds.append(elapsed_time)
                if len(self._heavy_move_seconds) > 20:
                    del self._heavy_move_seconds[:len(self._heavy_move_seconds) - 20]

            # Piggyback best-valid mirror on the LLM's own checkpoint
            # writes.  When _pending_best_mirror is set (WNS just improved
            # since the last mirror) and the LLM has just successfully
            # written a checkpoint, shutil-copy that file to best_valid.dcp.
            # This captures the improved state at the exact moment the LLM
            # saves it — no race with subsequent in-memory mutations and
            # no extra Vivado round-trip cost.
            if tool_name == "vivado_write_checkpoint" and self._pending_best_mirror:
                self._piggyback_mirror_checkpoint(arguments)
            # Same piggyback for write_edif so the EDIF mirror tracks the
            # DCP mirror.  Cheap: just a shutil.copy when the EDIF target
            # path matches conventional naming.
            if tool_name == "vivado_write_edif" and self._best_valid_dcp is not None:
                self._piggyback_mirror_edif(arguments)

            # R-D1-2 routed-state tracking: keep _design_routed_state in
            # sync after every SUCCESSFUL mutating op so the destroying-op
            # classifier sees the true harness state.  Always runs (even
            # during finalize/ILS and with the gate kill switch OFF) —
            # only the refusal itself is gated on _unroute_gate_enabled.
            if not _looks_like_tool_error(result_text):
                _new_routed = _routed_state_transition(tool_name, arguments)
                # jul20 review S2: any successful design-mutating op
                # (place/route/open transition, or a phys_opt/opt_design
                # netlist mutation) invalidates the "written checkpoint ==
                # measured best" assumption the piggyback mirror stamps on.
                _cmd_low_mut = _tool_cmd_text(tool_name, arguments)
                if (_new_routed is not None
                        or tool_name in ("vivado_phys_opt_design",
                                         "vivado_opt_design")
                        or re.search(r"\b(phys_opt_design|opt_design)\b",
                                     _cmd_low_mut)):
                    self._mutation_epoch += 1
                if _new_routed is not None:
                    if _new_routed != self._design_routed_state:
                        logger.info(
                            f"[unroute-gate] routed-state "
                            f"{self._design_routed_state} -> {_new_routed} "
                            f"after {tool_name}")
                    self._design_routed_state = _new_routed

            # Record tool call details. cmd_head lets post-hoc consumers
            # (ILS cold-start anchor) classify vivado_run_tcl calls whose
            # heavy work (place_design/route_design) is embedded in Tcl —
            # the dominant path for R7-routed recipes (jun12 drill2: zero
            # granular place/route calls, all via run_tcl).
            self.tool_call_details.append({
                "tool_name": tool_name,
                "iteration": self.iteration,
                "elapsed_time": elapsed_time,
                "wns": wns_measured,
                "error": False,
                "cmd_head": str(arguments.get("command", ""))[:200]
                            if isinstance(arguments, dict) else "",
            })

            # Router-step coverage tracking for the BETA-CTRL-V0 stop
            # handler.  Captures (tool_name, directive) so the controller
            # can detect when the LLM has not yet attempted a heavy step
            # recommended by the active router plan (e.g., place_design
            # directive=Auto_1 on R4 designs).
            try:
                directive = ""
                if isinstance(arguments, dict):
                    d = arguments.get("directive")
                    if d is not None:
                        directive = str(d)
                self._tool_calls_seen.append((tool_name, directive))
            except Exception:
                pass

            # ---- R-D1-1 auto-bank after heavy op (2026-07-19) ----
            # A heavy mutating op (place/route/phys_opt, incl. run_tcl-
            # embedded) that returns OK is measured HERE, deterministically,
            # without waiting for the LLM to call a measurement tool —
            # closing the boom_soc_2025.1_v2 alpha=0 hole (see
            # _auto_bank_enabled in __init__ for the full evidence).
            # Improved AND routed → bank via the exact existing
            # eager-mirror path (lineage tag: eager_mirror — reused, not
            # extended; _mirror_best_valid_now(eager=True) bumps it
            # internally, so finalize's membership check cannot raise).
            # The two measurement tool names are excluded because the
            # side-channel above already handled them (no double-measure).
            # Recursion is safe by classification: the measurement
            # (get_timing_paths), route-status check, and the mirror's
            # write_checkpoint/write_edif are all non-risky, so none of
            # them re-trigger this hook.
            if (self._auto_bank_enabled
                    and not self._in_finalize
                    and not self._in_ils_stage
                    # Tail-controller phys_opt bracket: the hook has no
                    # hold gate; those moves bank via the controller's
                    # own hold-gated accept (see __init__ comment).
                    and not self._tail_ctrl_suppress_autobank
                    and tool_name not in ("vivado_report_timing_summary",
                                          "vivado_get_wns")
                    and self._is_risky(tool_name, arguments)
                    and not _looks_like_tool_error(result_text)):
                try:
                    if (self._budget_deadline is not None
                            and self._budget_remaining()
                            < MIN_USEFUL_TOOL_SECONDS):
                        logger.info(
                            "[auto-bank] skip: %.0fs remaining below %.0fs "
                            "measurement floor after %s — not measuring.",
                            self._budget_remaining(),
                            MIN_USEFUL_TOOL_SECONDS, tool_name)
                    else:
                        # Explicit outer cap on the measurement — never rely
                        # on the MCP server's 300s default (jun08 heavy-cmd
                        # timeout incident).  600s matches the
                        # _routed_ok_for_best safety cap for the largest
                        # designs; the recursive call_tool dispatch below
                        # additionally applies its own deadline-aware cap.
                        auto_wns = await asyncio.wait_for(
                            self.get_wns_for_target_clock(
                                self._call_vivado_tool),
                            timeout=600.0)
                        if auto_wns is not None and auto_wns > self.best_wns:
                            if not await self._routed_ok_for_best():
                                logger.warning(
                                    f"[auto-bank] WNS {auto_wns:.3f} after "
                                    f"{tool_name} beats best but design is "
                                    "NOT fully routed — REJECTED as best "
                                    "(phantom-best guard, jul05 preview #10).")
                                _bank_ok = False
                            else:
                                _bank_ok = True
                                # jul22 OOD stress fix (finding 1): the hook
                                # was HOLD-BLIND — banking a hold-dirty
                                # state ships a validator hold_passed
                                # failure (α=0).  Check WHS on improvement
                                # events only (rare, one cheap SLACK query)
                                # and FAIL OPEN: unmeasurable hold banks
                                # exactly as before — a measurement gap can
                                # never re-open the boom α=0 hole this hook
                                # exists to close.  Contest inputs enter
                                # hold-clean (whs >= 0; ispd16-class at
                                # exactly 0.000 PASSES the official gate,
                                # jul02 preview), so refusing whs < 0 never
                                # strands a design below its baseline.
                                try:
                                    from optimizer.ils_polish import (
                                        _measure_hold as _ab_measure_hold)
                                    # jul23 FIX (wave-4 Q4 forensics +
                                    # panel SHIP-BLOCKING verdict): the
                                    # jul22 version passed
                                    # _call_vivado_tool, which PREFIXES
                                    # tool names -> the probe dispatched
                                    # as "vivado_vivado_run_tcl" and the
                                    # guard silently failed OPEN on
                                    # EVERY call.  _measure_hold already
                                    # passes the full tool name — use
                                    # call_tool directly (same as the
                                    # tail controller's working hold
                                    # gates; measurement commands are
                                    # non-risky so the hook cannot
                                    # recurse).
                                    _bank_whs = await asyncio.wait_for(
                                        _ab_measure_hold(
                                            self.call_tool,
                                            timeout_s=120.0),
                                        timeout=180.0)
                                except Exception:
                                    _bank_whs = None
                                if _bank_whs is None:
                                    # Fail-open stays (a measurement gap
                                    # must never re-open the boom α=0
                                    # hole) but LOUD (panel jul23):
                                    # repeated unmeasurable-hold banks
                                    # are a zero-risk signal for the
                                    # rehearsal log miner.
                                    self._autobank_hold_failopen_count = (
                                        getattr(self,
                                                "_autobank_hold_failopen_count",
                                                0) + 1)
                                    logger.warning(
                                        "[auto-bank] HOLD UNMEASURABLE on "
                                        "improvement event #%d — banking "
                                        "FAIL-OPEN (whs unknown; validator "
                                        "gates hold_passed).",
                                        self._autobank_hold_failopen_count)
                                if (_bank_whs is not None
                                        and _bank_whs < 0.0):
                                    _bank_ok = False
                                    logger.warning(
                                        f"[auto-bank] WNS {auto_wns:.3f} "
                                        f"after {tool_name} beats best but "
                                        f"HOLD is dirty (whs={_bank_whs:.3f}"
                                        " < 0 — validator gates hold_passed)"
                                        " — REJECTED as best (hold guard, "
                                        "jul22 OOD stress finding 1).")
                            if _bank_ok and self._input_cell_count:
                                # jul23 panel Q2 (5/5 tracker-first NOT
                                # sufficient): logic DELETION (remove_cell
                                # / disconnect_net) is invisible to the
                                # routed-state tracker AND can improve WNS
                                # while failing the equivalence validator
                                # (score 0).  Cheap sanity band on every
                                # improvement event vs the Phase-1 entry
                                # count — [0.5x, 3x] mirrors the LASTMILE
                                # band (legit opts move counts by far
                                # less).  Fail-open on unmeasurable count
                                # (never re-open the boom α=0 hole).
                                try:
                                    _cc_r = await asyncio.wait_for(
                                        self.call_tool(
                                            "vivado_run_tcl",
                                            {"command":
                                             "llength [get_cells -quiet "
                                             "-hierarchical -filter "
                                             "{IS_PRIMITIVE}]",
                                             "timeout": 120.0}),
                                        timeout=180.0)
                                    # Same guard as :7307 (jul20 red-team F3):
                                    # an error/budget envelope carries digits
                                    # ("only_23s_remain", elapsed_seconds 45),
                                    # and a bare re.search turns one into a
                                    # tiny cell count that fails the band and
                                    # silently REJECTS a good candidate. Fail
                                    # OPEN (None) like every other failure.
                                    if _looks_like_tool_error(_cc_r):
                                        raise RuntimeError(
                                            f"cell-count query returned error "
                                            f"envelope: {str(_cc_r)[:120]}")
                                    _cc_m = re.search(r"(\d+)",
                                                      str(_cc_r) or "")
                                    _cc = (int(_cc_m.group(1))
                                           if _cc_m else None)
                                except Exception:
                                    _cc = None
                                if (_cc is not None
                                        and not (0.5 * self._input_cell_count
                                                 <= _cc
                                                 <= 3.0 * self._input_cell_count)):
                                    _bank_ok = False
                                    logger.warning(
                                        f"[auto-bank] WNS {auto_wns:.3f} "
                                        f"after {tool_name} beats best but "
                                        f"cell count {_cc:,} is outside "
                                        f"[0.5x, 3x] of entry "
                                        f"{self._input_cell_count:,} — "
                                        "REJECTED as best (logic-deletion "
                                        "guard, jul23 panel Q2).")
                            if _bank_ok:
                                old_best_wns = self.best_wns
                                logger.info(
                                    f"[auto-bank] New best WNS after "
                                    f"{tool_name}: {auto_wns:.3f} ns "
                                    f"(improved from {old_best_wns:.3f} ns) "
                                    "— banking best_valid now.")
                                self.best_wns = auto_wns
                                self.last_improvement_iter = self.iteration
                                self.last_improvement_time = time.time()
                                self.regression_warning_sent = False
                                self._pending_best_mirror = True
                                self._pending_best_mirror_epoch = self._mutation_epoch
                                await self._mirror_best_valid_now(eager=True)
                        elif auto_wns is not None:
                            logger.info(
                                f"[auto-bank] WNS after {tool_name}: "
                                f"{auto_wns:.3f} ns (best is still "
                                f"{self.best_wns:.3f} ns) — no bank.")
                except Exception as e:
                    # Banking must never crash the run; fail toward
                    # not-banking.
                    logger.warning(
                        f"[auto-bank] hook failed after {tool_name} "
                        f"(non-fatal, not banking): {e}")

            # P1/P2 (2026-05-20 s2/s3): emit a single per-call trace record.
            # Classify the result_text — call_tool returns JSON-error
            # strings on dispatcher failures (does not raise) so we
            # MUST run the classifier here, not just on exceptions.
            #
            # Gate the action_label on _looks_like_tool_error so the
            # trace distinguishes:
            #   - tool_call_success: no real error AND no classifier match
            #   - tool_call_warning: classifier matched a warning pattern,
            #     but the gate says the call still succeeded
            #     (e.g. "WARNING: integrity check ... missing" on
            #     open_checkpoint that still completes — observed in
            #     2026-05-20 multi-design smoke)
            #   - tool_call_classified_error: real error + classifier match
            #   - tool_call_error: real error but classifier didn't match
            tool_err = self._classify_tool_payload(
                result_text, context="call_tool"
            )
            is_real_error = _looks_like_tool_error(result_text)
            if is_real_error and tool_err is not None:
                action_label = "tool_call_classified_error"
            elif is_real_error:
                action_label = "tool_call_error"
            elif tool_err is not None:
                action_label = "tool_call_warning"
            else:
                action_label = "tool_call_success"
            wns_after_call = (
                float(self.best_wns)
                if (self.best_wns is not None and self.best_wns != float("-inf"))
                else None
            )
            delta_wns = (
                (wns_after_call - wns_before_call)
                if (wns_after_call is not None and wns_before_call is not None)
                else None
            )
            self._emit_decision({
                "decision_source": "executor",
                "phase": "call_tool",
                "tool_name": tool_name,
                "action_label": action_label,
                "wns_before": wns_before_call,
                "wns_after": wns_after_call,
                "delta_wns": delta_wns,
                "runtime_s": elapsed_time,
                "tool_error_code": tool_err.code if tool_err is not None else None,
                "notes": (
                    f"args_keys={list(arguments.keys()) if isinstance(arguments, dict) else []} "
                    f"directive={directive if 'directive' in locals() else ''}"
                ),
            })

            return result_text

        except Exception as e:
            error_occurred = True
            elapsed_time = time.time() - start_time

            # Record failed tool call
            self.tool_call_details.append({
                "tool_name": tool_name,
                "iteration": self.iteration,
                "elapsed_time": elapsed_time,
                "wns": None,
                "error": True,
                "error_message": str(e)
            })

            # P1/P2 (2026-05-20 s2): classify the exception message +
            # emit trace event for raised-exception path.
            err_payload = json.dumps({"error": str(e)})
            tool_err = self._classify_tool_payload(
                err_payload, context="call_tool_exception"
            )
            self._emit_decision({
                "decision_source": "executor",
                "phase": "call_tool",
                "tool_name": tool_name,
                "action_label": "tool_call_exception",
                "wns_before": wns_before_call,
                "runtime_s": elapsed_time,
                "tool_error_code": tool_err.code if tool_err is not None else "UNKNOWN_TOOL_ERROR",
                "notes": f"exception={str(e)[:160]}",
            })

            logger.error(f"Tool call failed: {e}")
            return err_payload
    
    async def _call_vivado_tool(self, tool_name: str, arguments: dict) -> str:
        """Helper to call Vivado tools (for use with base class methods)."""
        return await self.call_tool(f"vivado_{tool_name}", arguments)

    # [BETA-CTRL-V0.1] Auto-revert injection ----------------------------------
    # Threshold: WNS regression > REGRESSION_THRESHOLD_NS triggers a revert
    # warning.  v0 logicnets test showed the LLM accepted a -0.488 ns
    # regression (-0.912 -> -1.400) and built on the worse state for 11
    # iterations without recovering.  This injects a user-visible message
    # the next time the LLM is invoked, telling it to revert before any
    # new strategy.  We track regression_warning_sent to avoid spam — it
    # is re-armed whenever best_wns improves.
    REGRESSION_THRESHOLD_NS = 0.05

    def _maybe_inject_revert_warning(self, current_wns: float) -> None:
        """Inject a 'revert before new strategy' user message when WNS
        regresses materially below best_wns.  No-op once per regression-
        episode (re-armed on next improvement)."""
        if self.regression_warning_sent:
            return
        if current_wns >= self.best_wns - self.REGRESSION_THRESHOLD_NS:
            return
        if self.best_wns == float('-inf'):
            return  # no baseline yet; first reading
        self.regression_warning_sent = True
        self.regression_warning_count += 1
        delta = self.best_wns - current_wns
        logger.info(
            f"[BETA-CTRL-V0.1] Regression detected: best={self.best_wns:.3f} ns -> "
            f"current={current_wns:.3f} ns (delta={delta:.3f} ns). "
            f"Injecting revert instruction (#{self.regression_warning_count})."
        )
        self.messages.append({
            "role": "user",
            "content": (
                f"WNS regressed from best={self.best_wns:.3f} ns to current={current_wns:.3f} ns "
                f"(degradation of {delta:.3f} ns).  "
                f"DO NOT propose a new strategy on this degraded state. "
                f"FIRST revert: open the DCP checkpoint that was saved when WNS was {self.best_wns:.3f} ns or better. "
                f"Look back at your earlier `vivado_write_checkpoint` / `rapidwright_write_checkpoint` calls — "
                f"identify the most recent checkpoint at or above the best WNS and `vivado_open_checkpoint` it. "
                f"After you've reverted, then choose a DIFFERENT strategy class than the one that just regressed."
            )
        })
    # ------------------------------------------------------------------------

    async def process_response(self, response) -> tuple[str, bool]:
        """Process LLM response, execute tool calls, return final text and done flag."""
        # Validate response structure with detailed logging
        try:
            if not response:
                raise ValueError("Response is None")
            if not hasattr(response, 'choices'):
                raise ValueError(f"Response has no 'choices' attribute. Response type: {type(response)}, Response: {response}")
            if response.choices is None:
                raise ValueError("Response.choices is None")
            if len(response.choices) == 0:
                raise ValueError("Response choices list is empty")
            
            message = response.choices[0].message
            if not message:
                raise ValueError("Message is None")
        except Exception as e:
            logger.error(f"Failed to parse response structure: {e}")
            logger.error(f"Response object: {response}")
            raise
        
        # Convert message to dict, excluding None values which can cause issues
        message_dict = message.model_dump(exclude_none=True)
        self.messages.append(message_dict)
        
        if self.debug:
            logger.debug(f"Added message to conversation: {json.dumps(message_dict, indent=2)[:500]}...")
        
        # Check for tool calls
        if message.tool_calls:
            tool_results = []
            
            for tool_call in message.tool_calls:
                # Validate tool_call structure
                if not tool_call or not hasattr(tool_call, 'function') or not tool_call.function:
                    logger.warning(f"Invalid tool_call structure: {tool_call}")
                    continue
                
                tool_name = tool_call.function.name
                try:
                    tool_args = json.loads(tool_call.function.arguments) if tool_call.function.arguments else {}
                except json.JSONDecodeError:
                    tool_args = {}
                
                result = await self.call_tool(tool_name, tool_args)
                
                # Truncate very long results to avoid API issues
                MAX_RESULT_LENGTH = 50000  # characters
                if len(result) > MAX_RESULT_LENGTH:
                    logger.warning(f"Tool result from {tool_name} is {len(result)} chars, truncating to {MAX_RESULT_LENGTH}")
                    result = result[:MAX_RESULT_LENGTH] + f"\n...[truncated {len(result) - MAX_RESULT_LENGTH} characters]"
                
                tool_results.append({
                    "role": "tool",
                    "tool_call_id": tool_call.id,
                    "name": tool_name,
                    "content": result
                })
                
                # Debug logging
                if self.debug:
                    logger.debug(f"Tool {tool_name} result: {result[:500]}...")
            
            # Add tool results to messages
            self.messages.extend(tool_results)
            
            # Continue conversation
            return await self.get_completion()
        
        # No tool calls - check if we're done
        content = message.content or ""
        
        # Check for completion indicators
        is_done = any(phrase in content.lower() for phrase in [
            "optimization complete",
            "timing is met",
            "wns >= 0",
            "no more optimizations",
            "design meets timing",
            "successfully saved",
            "final design saved"
        ])
        
        return content, is_done
    
    # ------------------------------------------------------------------
    # FRESH-STATE ROUTE-LOTTERY PRE-SWEEP (jul23 panel Q3 fantasy #1)
    # ------------------------------------------------------------------

    def _presweep_now(self) -> float:
        """Clock seam for the pre-sweep budget accounting (tests script
        it; production is time.time)."""
        return time.time()

    def _presweep_budget_shape(self) -> tuple[float, float]:
        """(budget_total_s, first_draw_timeout_s) for this run.

        With a wall cap: 0.2 x wall total (panel spec) and 0.12 x wall
        for the first-draw-measures timeout.  Without one (local
        drills): conservative fixed fallbacks."""
        if self.max_wall_seconds:
            wall = float(self.max_wall_seconds)
            return (FRESH_PRESWEEP_BUDGET_FRAC * wall,
                    FRESH_PRESWEEP_FIRST_DRAW_FRAC * wall)
        return (FRESH_PRESWEEP_FALLBACK_BUDGET_S,
                FRESH_PRESWEEP_FALLBACK_FIRST_TIMEOUT_S)

    async def _presweep_reopen(self, dcp_path: Path) -> bool:
        """Re-open a checkpoint from disk (the pristine input DCP after
        a worse/failed draw — the never-worse insurance — or the banked
        best_valid mirror at hand-off).  Returns True on success;
        open_checkpoint flips the routed-state tracker back to True via
        _routed_state_transition."""
        try:
            scale = float(getattr(self, "phase1_timeout_scale", 1.0) or 1.0)
            res = await asyncio.wait_for(
                self.call_tool("vivado_open_checkpoint", {
                    "dcp_path": str(Path(dcp_path).resolve())}),
                timeout=600.0 * max(1.0, scale))
            if _looks_like_tool_error(res):
                logger.warning(
                    f"[pre-sweep] pristine re-open FAILED: {str(res)[:160]}")
                return False
            return True
        except Exception as e:
            logger.warning(
                f"[pre-sweep] pristine re-open raised {type(e).__name__}: {e}")
            return False

    async def _presweep_execute_draw(
            self, op: str, timeout_s: float
    ) -> tuple[Optional[float], Optional[float], bool, Optional[str]]:
        """Run ONE pre-sweep draw op and measure it.

        op:
          "unroute_ae" — `route_design -unroute` then `route_design
              -directive AggressiveExplore` (the two-op form the wave-1
              probe measured: fir +0.070 / vtr +0.306 / optical +0.075
              from fresh states).  Destructive mid-op, which is why it
              is ONLY legal here at step 0 where the pristine input DCP
              is trivially re-openable.
          "bare" — plain `route_design` (incremental re-bite; the
              "also observed" form).  Used for chained draws so K > 1
              is not a deterministic duplicate of draw 1 (route_design
              is deterministic given identical netlist+placement).

        Returns (wns, whs, routed_ok, error):
          wns    — post-op WNS for the target clock (None = ERROR draw)
          whs    — worst hold slack (None = unmeasurable; caller
                   fails OPEN like the auto-bank hook)
          routed — tracker-first _routed_ok_for_best verdict
          error  — short string when the op itself failed

        Caller brackets this with _tail_ctrl_suppress_autobank: the
        R-D1-1 auto-bank hook is hold-blind and would double-measure;
        the pre-sweep banks through its own gated accept instead (same
        pattern as the tail controller's phys_opt bracket)."""
        if op == "unroute_ae":
            cmd = ("route_design -unroute; "
                   "route_design -directive AggressiveExplore")
        else:
            cmd = "route_design"
        try:
            res = await asyncio.wait_for(
                self.call_tool("vivado_run_tcl",
                               {"command": cmd, "timeout": float(timeout_s)}),
                timeout=float(timeout_s) + 60.0)
        except Exception as e:
            return (None, None, False, f"op_raised:{type(e).__name__}")
        if _looks_like_tool_error(res):
            return (None, None, False, f"op_failed:{str(res)[:120]}")
        # Measure WNS the same way the auto-bank hook does (outer cap —
        # never rely on the server's 300 s default, jun08 incident).
        try:
            wns = await asyncio.wait_for(
                self.get_wns_for_target_clock(self._call_vivado_tool),
                timeout=600.0)
        except Exception:
            wns = None
        if wns is None:
            return (None, None, False, "wns_unmeasurable")
        # Tracker-first routed gate (phantom-best guard; fails CLOSED).
        routed = await self._routed_ok_for_best()
        # Hold probe via self.call_tool — NOT _call_vivado_tool, which
        # prefixes tool names and would dispatch the probe to the
        # nonexistent "vivado_vivado_run_tcl" (the silent fail-open
        # bug fixed in 94e53bd; _measure_hold passes full tool names).
        try:
            from optimizer.ils_polish import _measure_hold
            whs = await asyncio.wait_for(
                _measure_hold(self.call_tool, timeout_s=120.0),
                timeout=180.0)
        except Exception:
            whs = None
        return (wns, whs, routed, None)

    async def _run_fresh_presweep(self, input_dcp: Path) -> None:
        """FRESH-STATE ROUTE-LOTTERY PRE-SWEEP — take K banked route
        re-rolls on the pristine input state; keep the best draw
        (never-worse vs entry) as the pipeline entry state.

        Insertion contract (see call site in perform_initial_analysis):
        runs AFTER initial_wns/best_wns are measured on the PRISTINE
        state (never-worse baseline + improvement accounting) and
        BEFORE every remaining Phase-1 feature capture, so high-fanout
        nets / spread / RQA / pathology / recipe-router all see the
        post-sweep state.  A route re-roll is placement-invariant, so
        the only features that can drift are the timing ones — WNS is
        taken from the adopted draw's own measurement and TNS/failing
        endpoints are re-parsed below on adoption.

        Never-hand-off-worse: an ADOPTED draw is the in-memory state
        (banked via the normal eager-mirror machinery); a worse/failed
        draw re-opens the pristine input DCP.  If a later draw was
        rejected after an earlier adoption, hand-off re-opens the
        banked best_valid mirror so the pipeline enters at the best
        draw, falling back to pristine (the mirror on disk still
        protects the gain through finalize)."""
        K = int(self._fresh_presweep_draws)
        if K <= 0:
            return  # OFF — zero tool calls, zero diff.
        if self.initial_wns is None:
            logger.info("[pre-sweep] skip: entry WNS unmeasured — cannot "
                        "gate never-worse.")
            return
        if self.initial_wns >= 0.0:
            logger.info("[pre-sweep] skip: timing already met at entry "
                        f"(wns={self.initial_wns:.3f}).")
            return
        # INSURED-COMPARE cost gate (jul23 panel #2 caveat): in candidate
        # mode the pristine pipeline runs the FULL wall unchanged, so the
        # 0.2x sweep is PURE overhead.  Arm it only when the wall is large
        # enough that the pipeline still keeps a full eval-equivalent
        # budget AFTER the 0.2x overhead (max_wall >= 4500s).  On the
        # 3600s eval box this is OFF regardless of the flag — the sweep
        # would steal ~720s from a pipeline that needs the whole hour
        # (wave-5 stolen-wall lesson).  Adopt-entry mode (kill-switch,
        # panel-DEAD) keeps the legacy no-gate behaviour.
        if not self._presweep_adopt_entry:
            if (not self.max_wall_seconds
                    or float(self.max_wall_seconds)
                    < FRESH_PRESWEEP_MIN_WALL_S):
                logger.info(
                    "[pre-sweep] skip (candidate mode): max_wall="
                    f"{self.max_wall_seconds} < "
                    f"{FRESH_PRESWEEP_MIN_WALL_S:.0f}s cost gate — the 0.2x "
                    "candidate-producer sweep would steal wall from the "
                    "full-wall pristine pipeline (needs a DEBUG-WALL / farm "
                    "run with headroom).")
                return
        budget_total, first_timeout = self._presweep_budget_shape()
        if not self.max_wall_seconds:
            logger.info(
                "[pre-sweep] no wall cap configured — fallback budget "
                f"{budget_total:.0f}s / first-draw timeout {first_timeout:.0f}s.")
        entry_wns = float(self.initial_wns)
        sweep_t0 = self._presweep_now()
        logger.info(
            f"[pre-sweep] START: K={K} draws, entry wns={entry_wns:.3f}, "
            f"budget={budget_total:.0f}s "
            f"({FRESH_PRESWEEP_BUDGET_FRAC:.0%} of wall), first-draw "
            f"timeout={first_timeout:.0f}s (first-draw-measures).")
        spent = 0.0
        max_observed: Optional[float] = None
        state_tag = "pristine"
        tried: set[tuple[str, str]] = set()
        adopted_any = False
        in_memory_is_best = False
        for k in range(1, K + 1):
            # Op selection + deterministic-duplicate stop: route_design
            # is deterministic given identical netlist+placement, so a
            # (state, op) pair already drawn cannot yield a new result.
            if state_tag == "pristine" and ("pristine", "unroute_ae") not in tried:
                op = "unroute_ae"
            else:
                op = "bare"
            key = (state_tag, op)
            if key in tried:
                logger.info(
                    f"[pre-sweep] draw={k}/{K} skipped: deterministic "
                    f"duplicate (op={op} already drawn from state="
                    f"{state_tag}); stopping sweep.")
                break
            allowed, timeout_k, reason = _presweep_draw_allowance(
                k, spent, max_observed, budget_total, first_timeout)
            if not allowed:
                logger.info(
                    f"[pre-sweep] draw={k}/{K} skipped: {reason}; "
                    f"stopping sweep (spent={spent:.0f}s of "
                    f"{budget_total:.0f}s).")
                break
            # Wall-floor sanity on top of the pre-sweep budget: never
            # start a draw the global deadline cannot absorb.
            if (self._budget_deadline is not None
                    and self._budget_remaining() < timeout_k + 120.0):
                logger.info(
                    f"[pre-sweep] draw={k}/{K} skipped: global wall floor "
                    f"(remaining {self._budget_remaining():.0f}s < "
                    f"draw timeout {timeout_k:.0f}s + 120s margin).")
                break
            pre_wns = (float(self.best_wns)
                       if (self.best_wns is not None
                           and self.best_wns != float("-inf"))
                       else entry_wns)
            t0 = self._presweep_now()
            prev_suppress = self._tail_ctrl_suppress_autobank
            self._tail_ctrl_suppress_autobank = True
            try:
                wns, whs, routed, err = await self._presweep_execute_draw(
                    op, timeout_k)
            finally:
                self._tail_ctrl_suppress_autobank = prev_suppress
            cost = max(0.0, self._presweep_now() - t0)
            spent += cost
            max_observed = max(max_observed or 0.0, cost)
            tried.add(key)
            # Verdict (requirement-3 banking discipline).
            reject_why = ""
            if err is not None or wns is None:
                verdict = "ERROR"
                reject_why = err or "wns_unmeasurable"
            elif not routed:
                verdict = "REJECTED"
                reject_why = "not_routed (tracker-first guard)"
            elif whs is not None and whs < 0.0:
                verdict = "REJECTED"
                reject_why = f"hold_dirty whs={whs:.3f}"
            elif wns > pre_wns:
                verdict = "ADOPTED"
                if whs is None:
                    # Fail-open like the auto-bank hook (a measurement
                    # gap must never strand a real gain) but LOUD.
                    self._presweep_hold_failopen_count += 1
                    logger.warning(
                        "[pre-sweep] HOLD UNMEASURABLE on adopted draw "
                        f"#{self._presweep_hold_failopen_count} — banking "
                        "FAIL-OPEN (whs unknown; validator gates "
                        "hold_passed).")
            else:
                verdict = "REJECTED"
                reject_why = "no strict improvement"
            if verdict == "ADOPTED":
                old_best = self.best_wns
                self.best_wns = wns
                self.last_improvement_iter = self.iteration
                self.last_improvement_time = time.time()
                self.regression_warning_sent = False
                self._pending_best_mirror = True
                self._pending_best_mirror_epoch = self._mutation_epoch
                await self._mirror_best_valid_now(eager=True)
                adopted_any = True
                in_memory_is_best = True
                self._presweep_adopted = True
                self._presweep_post_wns = float(wns)
                state_tag = f"best@{wns:.6f}"
                logger.info(
                    f"[pre-sweep] draw {k} BANKED via eager mirror "
                    f"(best {old_best if old_best is not None else 'None'} "
                    f"-> {wns:.3f}).")
            else:
                # Worse/failed draw: re-open the pristine input DCP
                # before the next draw / hand-off (never hand the
                # pipeline a worse-than-entry state).
                in_memory_is_best = False
                reopened = await self._presweep_reopen(input_dcp)
                if not reopened:
                    logger.warning(
                        f"[pre-sweep] draw={k}/{K}: pristine re-open "
                        "FAILED after a non-adopted draw — aborting sweep "
                        "(hand-off will retry the re-open).")
                    state_tag = "unknown"
                    self._log_presweep_draw(k, K, pre_wns, wns, whs,
                                            verdict, reject_why, cost,
                                            budget_total - spent, op)
                    break
                state_tag = "pristine"
            self._log_presweep_draw(k, K, pre_wns, wns, whs, verdict,
                                    reject_why, cost,
                                    budget_total - spent, op)
        # ---- INSURED-COMPARE candidate mode (jul23 panel #2, DEFAULT) ----
        # The adopt-entry hand-off below is DEAD (5/5): a better POINT is
        # a worse BASIN for the pristine-calibrated pipeline (net -27 MHz).
        # Instead: REGISTER the banked best draw as a separate never-worse
        # FINAL candidate and hand the pipeline a PRISTINE entry — the
        # perturbed DCP only competes at finalize, where the MUX ships
        # max(pipeline, presweep).  The pipeline never sees the re-roll.
        if not self._presweep_adopt_entry:
            registered = False
            if (adopted_any and self._presweep_post_wns is not None
                    and self._best_valid_dcp is not None
                    and Path(self._best_valid_dcp).exists()):
                try:
                    # In-memory := the banked best draw, so register's
                    # verify=True re-runs the exact routed/hold/cell gates
                    # against the candidate state (the mirror on disk).
                    reopened = await self._presweep_reopen(
                        Path(self._best_valid_dcp))
                    if reopened:
                        store_dir = self.run_dir / "final_candidates"
                        store_dir.mkdir(parents=True, exist_ok=True)
                        store = store_dir / "presweep.dcp"
                        _atomic_copy(str(self._best_valid_dcp), str(store))
                        src_edif = Path(self._best_valid_dcp).with_suffix(".edf")
                        if src_edif.exists() and src_edif.stat().st_size > 0:
                            try:
                                _atomic_copy(str(src_edif),
                                             str(store.with_suffix(".edf")))
                            except Exception:
                                pass
                        registered = await self.register_final_candidate(
                            store, self._presweep_post_wns, "presweep",
                            verify=True)
                    else:
                        logger.warning(
                            "[pre-sweep] candidate mode: could not re-open "
                            "the banked best draw to verify — SKIPPING "
                            "registration (pipeline still runs pristine).")
                except Exception as e:
                    logger.warning(
                        "[pre-sweep] candidate registration raised "
                        f"{type(e).__name__} (non-fatal): {e}")
            # Hand the pipeline a PRISTINE entry and reset the pipeline
            # lineage so its improvement accounting starts clean (the
            # perturbed best draw is now insured in the candidate store,
            # NOT the pipeline's best_valid mirror).
            await self._presweep_reopen(input_dcp)
            self.best_wns = entry_wns
            self._best_valid_dcp = None
            self._best_valid_dcp_wns = None
            self._best_valid_edif = None
            self._best_valid_edif_wns = None
            self._best_valid_lineage = None
            self._pending_best_mirror = False
            self.last_improvement_iter = self.iteration
            self.last_improvement_time = time.time()
            self.regression_warning_sent = False
            self._presweep_adopted = False
            self._presweep_post_wns = None
            sweep_elapsed = max(0.0, self._presweep_now() - sweep_t0)
            if self._phase1_start_ts is not None:
                self._phase1_start_ts += sweep_elapsed
            logger.info(
                f"[pre-sweep] COMPLETE (candidate mode): adopted={adopted_any} "
                f"registered={registered} entry {entry_wns:.3f}; pipeline "
                f"enters PRISTINE, presweep draw insured as a FINAL candidate "
                f"({len(self._final_candidates)} enrolled). spent={spent:.0f}s "
                f"of {budget_total:.0f}s (phase-1 allowance shifted by "
                f"{sweep_elapsed:.0f}s).")
            return
        # ---- hand-off (never-worse) ----  [adopt-entry kill-switch only]
        if adopted_any and not in_memory_is_best:
            handed_best = False
            if (self._best_valid_dcp is not None
                    and Path(self._best_valid_dcp).exists()):
                handed_best = await self._presweep_reopen(
                    Path(self._best_valid_dcp))
            if handed_best:
                logger.info(
                    "[pre-sweep] hand-off: re-opened banked best draw "
                    f"({self._presweep_post_wns:.3f} ns) as the pipeline "
                    "entry state.")
                in_memory_is_best = True
            else:
                logger.warning(
                    "[pre-sweep] hand-off: could not re-open the banked "
                    "best mirror — pipeline enters at PRISTINE (the "
                    "on-disk mirror still protects the banked gain "
                    "through finalize).")
                # The LLM/router will be working the pristine state, so
                # the feature view must describe pristine, not the
                # mirror (best_wns keeps the banked value — that is the
                # mirror's contract, not the in-memory state's).
                self._presweep_adopted = False
                self._presweep_post_wns = None
                if state_tag == "unknown":
                    await self._presweep_reopen(input_dcp)
        elif not adopted_any and state_tag == "unknown":
            # Last resort: one more attempt to leave a sane state.
            await self._presweep_reopen(input_dcp)
        # ---- requirement-4 feature refresh (adopted state only) ----
        if adopted_any and in_memory_is_best:
            try:
                scale = float(getattr(self, "phase1_timeout_scale", 1.0) or 1.0)
                rpt = await asyncio.wait_for(
                    self.call_tool("vivado_report_timing_summary", {}),
                    timeout=300.0 * max(1.0, scale) + 60.0)
                if not _looks_like_tool_error(rpt):
                    ti = parse_timing_summary_static(rpt)
                    self._presweep_post_tns = ti.get("tns")
                    self._presweep_post_failing_endpoints = ti.get(
                        "failing_endpoints")
                    logger.info(
                        "[pre-sweep] post-sweep feature refresh: tns="
                        f"{self._presweep_post_tns} failing_endpoints="
                        f"{self._presweep_post_failing_endpoints}.")
            except Exception as e:
                logger.warning(
                    f"[pre-sweep] post-sweep timing re-parse failed "
                    f"(router falls back to entry TNS/endpoints; WNS "
                    f"feature is already post-sweep): {e}")
        # ---- Phase-1 wall-allowance exclusion ----
        # The pre-sweep has its OWN 0.2 x wall budget; without this
        # shift it would also consume the C1-T4a Phase-1 allowance and
        # spuriously skip the optional analyses (fanout/spread/RQA)
        # that run after the insertion point.
        sweep_elapsed = max(0.0, self._presweep_now() - sweep_t0)
        if self._phase1_start_ts is not None:
            self._phase1_start_ts += sweep_elapsed
        logger.info(
            f"[pre-sweep] COMPLETE: adopted={adopted_any} entry "
            f"{entry_wns:.3f} -> best "
            f"{self.best_wns if self.best_wns != float('-inf') else 'None'} "
            f"spent={spent:.0f}s of {budget_total:.0f}s "
            f"(phase-1 allowance shifted by {sweep_elapsed:.0f}s).")

    def _log_presweep_draw(self, k: int, K: int, pre_wns: float,
                           post_wns: Optional[float], whs: Optional[float],
                           verdict: str, reject_why: str, cost: float,
                           remaining: float, op: str) -> None:
        """Requirement-5 structured per-draw log line + decision-trace
        record + in-memory record for post-mortems."""
        post_str = f"{post_wns:.3f}" if post_wns is not None else "None"
        whs_str = f"{whs:.3f}" if whs is not None else "None"
        line = (f"[pre-sweep] draw={k}/{K} wns {pre_wns:.3f} -> {post_str} "
                f"whs={whs_str} verdict={verdict} cost={cost:.0f}s "
                f"remaining={remaining:.0f}s")
        if reject_why:
            line += f" ({reject_why})"
        logger.info(line)
        rec = {
            "draw": k, "draws_total": K, "op": op,
            "wns_before": pre_wns, "wns_after": post_wns, "whs": whs,
            "verdict": verdict, "reject_why": reject_why or None,
            "cost_s": round(cost, 1), "budget_remaining_s": round(remaining, 1),
        }
        self._presweep_draw_records.append(rec)
        try:
            self._emit_decision({
                "decision_source": "presweep",
                "phase": "phase_1",
                "action_label": f"presweep_draw_{verdict.lower()}",
                "tool_name": "vivado_run_tcl",
                "wns_before": pre_wns,
                "wns_after": post_wns,
                "runtime_s": cost,
                "notes": (f"op={op} draw={k}/{K} whs={whs_str} "
                          f"remaining={remaining:.0f}s"
                          + (f" reject_why={reject_why}" if reject_why else "")),
            })
        except Exception:  # pragma: no cover — trace must never break a run
            pass

    def _phase1_wns_for_features(self) -> Optional[float]:
        """WNS the Phase-1 feature consumers (recipe router, pathology
        classifier) should route on: the post-sweep value when a
        pre-sweep draw was adopted, else the pristine entry WNS.
        initial_wns itself stays PRISTINE (accounting — see __init__)."""
        if (getattr(self, "_presweep_adopted", False)
                and self._presweep_post_wns is not None):
            return self._presweep_post_wns
        return self.initial_wns

    def _phase1_failing_endpoints_for_features(self) -> Optional[int]:
        """Failing-endpoint count for the Phase-1 feature consumers
        (post-sweep re-parse when adopted, else entry value)."""
        if (getattr(self, "_presweep_adopted", False)
                and self._presweep_post_failing_endpoints is not None):
            return self._presweep_post_failing_endpoints
        return self.initial_failing_endpoints

    async def perform_initial_analysis(self, input_dcp: Path) -> str:
        """
        Perform initial analysis without LLM:
        1. Initialize RapidWright
        2. Open checkpoint in Vivado
        3. Report timing summary
        4. Get critical high fanout nets
        
        Returns a formatted summary of the analysis.
        """
        logger.info("Performing initial design analysis...")
        print("\n=== Initial Design Analysis ===\n")

        # C1-T4a: anchor the cumulative Phase-1 wall clock.  Every call in
        # this method (wrapped or not) counts against the Phase-1 allowance
        # checked by _phase1_wall_allowance_remaining_s.
        self._phase1_start_ts = time.time()

        # Step 1: Initialize RapidWright
        logger.info("Initializing RapidWright...")
        print("Initializing RapidWright...")
        result = await self.call_tool("rapidwright_initialize_rapidwright", {})
        if "error" in result.lower() and "success" not in result.lower():
            raise RuntimeError(f"Failed to initialize RapidWright: {result}")
        print("✓ RapidWright initialized\n")
        
        # Step 2: Open checkpoint in Vivado (MANDATORY).  Base 600 s — large
        # designs (boom_soc, ispd16_example2) need longer than the server-
        # side 300 s default.  Scale via --phase1-timeout-scale on the CLI.
        logger.info(f"Opening checkpoint: {input_dcp}")
        print(f"Opening checkpoint: {input_dcp.name}")
        result = await self._phase1_call(
            "vivado_open_checkpoint",
            {"dcp_path": str(input_dcp.resolve())},
            timeout_seconds=600.0,
            mandatory=True,
            label="open_checkpoint",
        )
        if "error" in result.lower() and "opened successfully" not in result.lower():
            raise RuntimeError(f"Failed to open checkpoint: {result}")
        print("✓ Checkpoint opened in Vivado\n")

        # GOLDEN cell count (jul03, GitHub #36; relaxed jul13, upstream PR
        # #41): the validator's Phase-1 hard gate on cell count was REMOVED
        # upstream jul07 (counts are info-only now; eval box confirmed on the
        # post-removal validator, attempt #16 scorecard b2aafb7). Measure the
        # input once here so netlist-transforming accepts (LASTMILE's
        # -lut_opt) can still be checked against a WIDE sanity band (cfg
        # cell_floor/ceil_ratio) that only catches wholesale netlist
        # mangling. Non-mandatory: on failure the check fails OPEN.
        try:
            _cc = await self.call_tool("vivado_run_tcl", {
                "command": "llength [get_cells -quiet -hierarchical "
                           "-filter {IS_PRIMITIVE}]",
                # 300 -> 600 (aug05 gray-areas k3 F3-lite, capped per review
                # m1): the flat cap was never scaled by phase1_timeout_scale
                # and ONE timeout on a slow cold box flips THREE gates at
                # once for a giant (ILS fail-open, tail reserve NOT armed,
                # RFD fail-closed).  600 not 900: this is plain call_tool,
                # unclamped by the phase-1 allowance (525 s) — a hung query
                # at 900 s would exhaust the allowance and skip the spread
                # analysis, which (with the new spread fail-closed) would be
                # a behavioral delta on a measurement-degraded known.
                "timeout": 600})
            # jul20 phase-1 red-team F3: an error/budget-skip envelope
            # contains digits ("ERROR: [Common 17-69]", remaining_seconds)
            # — a bare re.search would poison golden_cell_count AND the
            # unroute-gate predictor with a garbage tiny count. Error
            # envelopes must fail OPEN (None), like every other failure.
            if _looks_like_tool_error(_cc):
                raise RuntimeError(
                    f"cell-count query returned error envelope: "
                    f"{str(_cc)[:120]}")
            _ccm = re.search(r"(\d+)", _cc or "")
            self._input_cell_count = int(_ccm.group(1)) if _ccm else None
            if self._input_cell_count:
                self._ils_polish_cfg.golden_cell_count = self._input_cell_count
                _fl = self._ils_polish_cfg.cell_floor_ratio
                _cl = self._ils_polish_cfg.cell_ceil_ratio
                logger.info(f"Input primitive cell count: {self._input_cell_count:,} "
                            f"(sanity band: {int(self._input_cell_count*_fl):,}"
                            f"..{int(self._input_cell_count*_cl):,})")
        except Exception as e:
            self._input_cell_count = None
            logger.warning(f"input cell-count measurement failed ({e!r}); "
                           "cell guard disabled (fail-open)")

        # Step 3: Report timing summary (MANDATORY).  Base 300 s — large
        # designs may need longer; scaled by phase1_timeout_scale.
        logger.info("Analyzing timing...")
        print("Analyzing timing...")
        timing_report = await self._phase1_call(
            "vivado_report_timing_summary",
            {},
            timeout_seconds=300.0,
            mandatory=True,
            label="report_timing_summary",
        )
        
        # Parse timing
        timing_info = parse_timing_summary_static(timing_report)
        self.initial_tns = timing_info["tns"]
        self.initial_failing_endpoints = timing_info["failing_endpoints"]
        
        # Get clock period for fmax calculation (also detects target clock)
        self.clock_period = await super().get_clock_period(self._call_vivado_tool)
        
        # Get WNS for the target clock domain
        target_wns = await super().get_wns_for_target_clock(self._call_vivado_tool)
        if target_wns is not None:
            self.initial_wns = target_wns
        else:
            self.initial_wns = timing_info["wns"]
        self.best_wns = self.initial_wns if self.initial_wns is not None else float('-inf')
        # jul25 constraint-guard DETECTION layer: fingerprint the timing
        # constraints at the baseline, so finalize can prove they were not
        # altered. Detection is the load-bearing half of the guard — the
        # deny-list at the run_tcl boundary is string matching and string
        # matching is defeatable (alias, source, eval); a fingerprint diff
        # is not. Best-effort: never blocks Phase 1.
        try:
            self._constraint_fp_baseline = \
                await self._capture_constraint_fingerprint("baseline")
        except Exception as e:
            logger.warning(f"[constraint-guard] baseline capture failed "
                           f"(ignored): {e!r}")

        clock_info = f" (clock: {self.target_clock})" if self.target_clock else ""
        print(f"✓ Timing analyzed:")
        if self.clock_period is not None:
            target_fmax = 1000.0 / self.clock_period
            print(f"  - Clock period: {self.clock_period:.3f} ns (target fmax: {target_fmax:.2f} MHz)")
        if self.target_clock:
            print(f"  - Target clock: {self.target_clock}")
        if self.initial_wns is not None:
            print(f"  - WNS{clock_info}: {self.initial_wns:.3f} ns")
            initial_fmax = self.calculate_fmax(self.initial_wns, self.clock_period)
            if initial_fmax is not None:
                print(f"  - Achievable fmax: {initial_fmax:.2f} MHz")
        if self.initial_tns is not None:
            print(f"  - TNS: {self.initial_tns:.3f} ns")
        if self.initial_failing_endpoints is not None:
            print(f"  - Failing endpoints: {self.initial_failing_endpoints}")
        print()

        # FRESH-STATE ROUTE-LOTTERY PRE-SWEEP (jul23 panel Q3 fantasy #1;
        # DEFAULT OFF = no-op).  Insertion contract: AFTER the entry
        # WNS/best_wns are measured on the PRISTINE state (never-worse
        # baseline; initial_wns must stay pristine so the banked pre-sweep
        # gain counts as improvement and survives finalize's
        # no-improvement guard) and BEFORE every remaining Phase-1
        # feature capture (high-fanout nets, spread, RQA, pathology +
        # recipe-router blocks), so those see the post-sweep state.
        if self._fresh_presweep_draws > 0:
            try:
                await self._run_fresh_presweep(input_dcp)
            except Exception as e:
                logger.warning(
                    f"[pre-sweep] raised {type(e).__name__} (non-fatal): {e}")
                if not self._presweep_adopted:
                    # Leave the pipeline a sane pristine state; an adopted
                    # draw is already the in-memory state + banked mirror.
                    try:
                        await self._presweep_reopen(input_dcp)
                    except Exception:
                        pass

        # Step 4: Get critical high fanout nets (OPTIONAL).  Base 600 s.
        # Used by the LLM to gauge Class D applicability; on failure we set
        # an empty list and the LLM picks a different strategy class.
        logger.info("Identifying critical high fanout nets...")
        print("Identifying critical high fanout nets...")
        nets_report = await self._phase1_call(
            "vivado_get_critical_high_fanout_nets",
            {"num_paths": 50, "min_fanout": 100},
            timeout_seconds=600.0,
            mandatory=False,
            label="get_critical_high_fanout_nets",
        )
        if nets_report is None:
            self.high_fanout_nets = []
            print("⚠ Skipped high-fanout-net analysis; LLM will not see Class D candidates.\n")
        else:
            self.high_fanout_nets = self.parse_high_fanout_nets(nets_report)
            print(f"✓ Found {len(self.high_fanout_nets)} high fanout nets (>100 fanout)\n")

        # Step 5: Load design in RapidWright for spread analysis (OPTIONAL).
        # If this fails (RapidWright OOM, parse error, JNI crash on huge
        # netlists), skip steps 6+7 too — they depend on it.
        critical_path_spread_info = None
        self.lut_count = None

        logger.info("Loading design in RapidWright...")
        print("Loading design in RapidWright for spread analysis...")
        result = await self._phase1_call(
            "rapidwright_read_checkpoint",
            {"dcp_path": str(input_dcp.resolve())},
            timeout_seconds=900.0,
            mandatory=False,
            label="rapidwright_read_checkpoint",
        )
        if result is None or ("error" in result.lower() and "success" not in result.lower()):
            if result is not None:
                logger.warning(f"RapidWright load returned non-success: {result[:200]}")
                if "rapidwright_read_checkpoint" not in self.phase1_skipped:
                    self.phase1_skipped.append("rapidwright_read_checkpoint")
            print("⚠ Skipped spread analysis (RapidWright load unavailable).\n")
        else:
            print("✓ Design loaded in RapidWright\n")

            # Capture cell-count fingerprint (used by strategy_memory's
            # fingerprint_match for unknown designs).  Best-effort.
            info_str = await self._phase1_call(
                "rapidwright_get_design_info",
                {},
                timeout_seconds=120.0,
                mandatory=False,
                label="rapidwright_get_design_info",
            )
            if info_str is not None:
                try:
                    info = json.loads(info_str) if isinstance(info_str, str) else info_str
                    top_types = info.get("top_cell_types", {}) if isinstance(info, dict) else {}
                    self.lut_count = sum(
                        cnt for typ, cnt in top_types.items()
                        if isinstance(typ, str) and typ.upper().startswith("LUT")
                    )
                    if self.lut_count:
                        print(f"  - LUT count (fingerprint): {self.lut_count:,}\n")
                except Exception as e:
                    logger.debug(f"lut_count fingerprint capture failed: {e}")

            # Step 6: Extract critical path cells from Vivado (OPTIONAL).
            logger.info("Extracting critical path cells for spread analysis...")
            temp_path = Path(self.temp_dir) / "initial_critical_paths.json"
            cells_json = await self._phase1_call(
                "vivado_extract_critical_path_cells",
                {"num_paths": 50, "output_file": str(temp_path)},
                timeout_seconds=600.0,
                mandatory=False,
                label="extract_critical_path_cells",
            )

            # Step 7: Analyze spread in RapidWright (OPTIONAL, depends on 6).
            spread_result = None
            if cells_json is not None and temp_path.exists():
                spread_result = await self._phase1_call(
                    "rapidwright_analyze_critical_path_spread",
                    {"input_file": str(temp_path)},
                    timeout_seconds=300.0,
                    mandatory=False,
                    label="analyze_critical_path_spread",
                )
            else:
                if "extract_critical_path_cells" not in self.phase1_skipped:
                    self.phase1_skipped.append("extract_critical_path_cells")

            if spread_result is not None:
                try:
                    spread_data = json.loads(spread_result)
                    critical_path_spread_info = {
                        "max_distance": spread_data.get("max_distance_found", 0),
                        "avg_distance": spread_data.get("avg_max_distance", 0),
                        "paths_analyzed": spread_data.get("paths_analyzed", 0)
                    }
                    print(f"✓ Critical path spread analyzed:")
                    print(f"  - Max distance: {critical_path_spread_info['max_distance']} tiles")
                    print(f"  - Avg distance: {critical_path_spread_info['avg_distance']:.1f} tiles")
                    print(f"  - Paths analyzed: {critical_path_spread_info['paths_analyzed']}")
                    print()
                except (json.JSONDecodeError, KeyError, TypeError) as e:
                    logger.warning(f"Could not parse spread results: {e}")
                    if "analyze_critical_path_spread" not in self.phase1_skipped:
                        self.phase1_skipped.append("analyze_critical_path_spread")

        # Stash for downstream consumers (RAG strategy memory uses spread
        # for fingerprint-matching when the design name is unknown).
        self.critical_path_spread_info = critical_path_spread_info
        # K3 spread-gate plumbing (jul20 mining): hand the measured avg
        # critical-path spread to the ILS config so the PARTIAL_RUIN
        # skip-gate can fire (optimizer/ils_polish.py, held-out rule 2:
        # spread~0 cell surgery is 26/26 negative). A missing/failed
        # measurement leaves it None -> gate stays open (behavior unchanged).
        try:
            if (isinstance(critical_path_spread_info, dict)
                    and critical_path_spread_info.get("avg_distance") is not None):
                self._ils_polish_cfg.critical_path_avg_spread_tiles = float(
                    critical_path_spread_info["avg_distance"])
                logger.info(
                    f"ILS spread-gate feature: critical_path_avg_spread_tiles="
                    f"{self._ils_polish_cfg.critical_path_avg_spread_tiles:.1f}")
        except (TypeError, ValueError) as e:
            logger.warning(f"ILS spread-gate plumbing skipped ({e!r}); "
                           "PARTIAL_RUIN gate stays open (fail-open).")
        # jul31: pair the spread above with the Phase-1 failing-endpoint count so
        # the ILS can compute failing-endpoint DENSITY, the ExtraNetDelay_high
        # gate feature (optimizer/ils_polish.py). Uses the SAME accessor the
        # recipe router consumes, so the two can never disagree about what
        # Phase 1 measured. Missing -> stays None -> that gate fails OPEN.
        try:
            _fe = self._phase1_failing_endpoints_for_features()
            # Assign UNCONDITIONALLY, including the None case. Setting the field
            # only on success lets a stale value from an earlier Phase 1 on the
            # same optimizer instance masquerade as a fresh measurement, so the
            # gate would decide from the previous design instead of failing open.
            # (Raised by gpt-5.6-sol, panel_endhigh_jul31.md.)
            self._ils_polish_cfg.phase1_failing_endpoints = (
                int(_fe) if _fe is not None else None)
            if _fe is not None:
                _sp = self._ils_polish_cfg.critical_path_avg_spread_tiles
                if _sp:
                    logger.info(
                        f"ILS endhigh-density feature: failing={int(_fe)} / "
                        f"spread={float(_sp):.1f} = "
                        f"{int(_fe) / float(_sp):.0f}")
        except (TypeError, ValueError, ZeroDivisionError) as e:
            logger.warning(f"ILS endhigh-density plumbing skipped ({e!r}); "
                           "ExtraNetDelay_high gate stays open (fail-open).")

        # Step 8: Report QoR Assessment (OPTIONAL, post-2026-05-20).  Cheap
        # diagnosis signal (Vivado predicts likelihood of meeting timing
        # on a 1-5 scale and flags methodology issues).  We exclude
        # methodology checks to keep the call short (~30-60s vs 2-5 min)
        # and cap max_paths to 100 (default).  Output goes through the
        # tolerant parser; on any failure the whole feature set stays
        # None and Phase 1 still completes.
        # jul25 (B4): report_qor_assessment REMOVED and replaced by
        # report_utilization.  Rationale, both measured:
        #   - cost: RQA ran up to 48 s (~25% of Phase 1 on the largest designs;
        #     see final_round/PHASE1_AUDIT_jul25.md) and is the step that pushed
        #     corescore over the 15% Phase-1 wall cap;
        #   - value: its downstream signal was A/B'd to NEUTRAL and CLOSED
        #     (episode_qor_join / --capture-qor, sessions S13-S17).
        # Removal is behaviourally identical to "always skipped" — the step was
        # already mandatory=False and was observed skipping on corescore with the
        # run completing normally, so every consumer already handles absence.
        # report_utilization is the uncovered-bands panel's UNANIMOUS (5/5) ask:
        # it yields util% AND the BRAM/URAM/DSP mix in ONE call, making the
        # panel's bands 2 and 4 detectable at all (they were previously invisible
        # to the router). Net Phase-1 wall change is approximately zero.
        logger.info("Running Vivado report_utilization for Phase-1 resource features...")
        print("Running utilization report...")
        util_text = await self._phase1_call(
            "vivado_run_tcl",
            {"command": ("set _u [report_utilization -return_string]; "
                         "set _r \"\"; "
                         "catch {set _r [report_route_status -return_string]}; "
                         "puts $_u; puts \"===FPL26_ROUTE_STATUS===\"; puts $_r")},
            timeout_seconds=180.0,
            mandatory=False,
            label="report_utilization",
        )
        if isinstance(util_text, str) and util_text and not _looks_like_tool_error(util_text):
            try:
                _util_txt, _route_txt = split_reports(util_text)
                self.utilization = parse_utilization(_util_txt)
                self.route_pct = parse_route_status(_route_txt)
                _lu = self.utilization.get("lut_pct")
                _br = self.utilization.get("bram_pct")
                _ur = self.utilization.get("uram_pct")
                _ds = self.utilization.get("dsp_pct")
                self.memory_dominated = memory_dominated(self.utilization)
                _fmt = lambda v: "?" if v is None else f"{v:.1f}%"
                logger.info(
                    "Utilization: LUT %s  BRAM %s  URAM %s  DSP %s  "
                    "memory_dominated=%s",
                    _fmt(_lu), _fmt(_br), _fmt(_ur), _fmt(_ds),
                    self.memory_dominated,
                )
                print(f"✓ Utilization: LUT {_fmt(_lu)} | BRAM {_fmt(_br)} | "
                      f"URAM {_fmt(_ur)} | DSP {_fmt(_ds)} | "
                      f"routed {_fmt(self.route_pct)}")
            except Exception as e:
                logger.warning(f"utilization parse failed: {e}; "
                               "continuing without resource features.")
        else:
            print("⚠ Skipped report_utilization (Vivado returned no usable output).\n")

        if self.phase1_skipped:
            print(f"⚠ Phase 1 degraded: skipped {len(self.phase1_skipped)} optional step(s): "
                  f"{', '.join(self._phase1_skipped_display())}.")
            print("  Optimization continues — LLM will operate without these analyses.\n")

        # Create concise summary for LLM
        summary = []
        summary.append("=== Initial Design Analysis ===\n")

        # Phase-1 degradation banner.  Tell the LLM which optional analyses
        # weren't available so it can pick a strategy without the missing
        # signals (e.g., skip Class D if high-fanout list is empty, skip
        # PBLOCK heuristic if spread analysis was skipped).
        if self.phase1_skipped:
            summary.append("PHASE-1 NOTICE: the following analyses were unavailable")
            summary.append(f"(skipped on this design): {', '.join(self._phase1_skipped_display())}.")
            summary.append("Choose strategy without these signals — proceed with timing data alone.")
            summary.append("")

        # Timing status
        summary.append("TIMING STATUS:")
        if self.clock_period is not None:
            target_fmax = 1000.0 / self.clock_period
            summary.append(f"  Clock period: {self.clock_period:.3f} ns (target fmax: {target_fmax:.2f} MHz)")
        if self.initial_wns is not None:
            if self.initial_wns >= 0:
                summary.append(f"  WNS: {self.initial_wns:.3f} ns - TIMING MET ✓")
            else:
                summary.append(f"  WNS: {self.initial_wns:.3f} ns - TIMING VIOLATED")
            # Add fmax information
            initial_fmax = self.calculate_fmax(self.initial_wns, self.clock_period)
            if initial_fmax is not None:
                summary.append(f"  Achievable fmax: {initial_fmax:.2f} MHz")
        if (getattr(self, "_presweep_adopted", False)
                and self._presweep_post_wns is not None
                and self.initial_wns is not None):
            summary.append(
                f"  PRE-SWEEP: a fresh-state route re-roll was BANKED before "
                f"this analysis — WNS {self.initial_wns:.3f} -> "
                f"{self._presweep_post_wns:.3f} ns. You are optimizing from "
                f"this improved (already banked) state; do not repeat a bare "
                f"re-route expecting the same gain.")
        if self.initial_tns is not None:
            summary.append(f"  TNS: {self.initial_tns:.3f} ns")
        if self.initial_failing_endpoints is not None:
            summary.append(f"  Failing endpoints: {self.initial_failing_endpoints}")
        summary.append("")
        
        # Critical path spread analysis
        if critical_path_spread_info:
            summary.append("CRITICAL PATH SPREAD ANALYSIS:")
            summary.append(f"  Max cell distance: {critical_path_spread_info['max_distance']} tiles")
            summary.append(f"  Avg cell distance: {critical_path_spread_info['avg_distance']:.1f} tiles")
            summary.append(f"  Paths analyzed: {critical_path_spread_info['paths_analyzed']}")
            
            # Recommendation based on spread
            if critical_path_spread_info['avg_distance'] > 70 and critical_path_spread_info['paths_analyzed'] >= 5:
                summary.append(f"  ⚠ RECOMMENDATION: Use PBLOCK strategy (high spread detected)")
            summary.append("")
        
        # High fanout nets (show top 10)
        if self.high_fanout_nets:
            summary.append("CRITICAL HIGH FANOUT NETS (top 10):")
            for i, (net_name, fanout, path_count) in enumerate(self.high_fanout_nets[:10]):
                summary.append(f"  {i+1}. {net_name}")
                summary.append(f"     Fanout: {fanout}, Critical paths: {path_count}")
            if len(self.high_fanout_nets) > 10:
                summary.append(f"  ... and {len(self.high_fanout_nets) - 10} more nets")
        else:
            summary.append("CRITICAL HIGH FANOUT NETS: None found")
        
        summary.append("")
        summary.append(f"Total nets available for optimization: {len(self.high_fanout_nets)}")

        # Vivado QoR Assessment feature block (post-2026-05-20).  Compact:
        # score + flow guidance only; no raw RQA text bloating the prompt.
        # The LLM treats this as advisory diagnosis, not a command source.
        rqa_score = self.qor_assessment.get("score") if isinstance(self.qor_assessment, dict) else None
        if rqa_score is not None:
            summary.append("")
            summary.append("VIVADO QoR ASSESSMENT (advisory):")
            score_label = {
                1: "design unlikely to complete implementation",
                2: "implementation completes but timing will not close",
                3: "small chance of success — try directives or report_qor_suggestions",
                4: "should close with a few directives or ML strategies",
                5: "design will easily meet timing",
            }.get(rqa_score, "")
            summary.append(f"  RQA Score: {rqa_score}/5"
                            + (f" — {score_label}" if score_label else ""))
            if self.qor_assessment.get("flow_guidance"):
                summary.append(f"  Recommended next action: "
                                f"{self.qor_assessment['flow_guidance']}")
            if self.qor_assessment.get("ml_strategy_available") is True:
                summary.append("  ML Strategies available for this design.")
            if isinstance(self.qor_assessment.get("methodology_violations"), int):
                summary.append(
                    f"  Methodology violations flagged: "
                    f"{self.qor_assessment['methodology_violations']}"
                )

        # Deterministic pathology classifier — feeds the LLM a structured
        # recipe-priority list derived from the Phase 1 data, BEFORE the
        # LLM makes its first strategy decision.  Closes the integration
        # gap flagged in the 2026-05-14 critique: the classifier was
        # built + tested but never reached the runtime decision loop.
        # Also drops recipes the per-design applicability table says
        # are harmful (corescore_500_mod blocks recipe_cell_replacement)
        # — surfaced in the 2026-05-14 corescore reproducibility run
        # where the classifier recommended a blocked recipe at #1.
        design_name_for_classifier = None
        if _design_name_from_dcp is not None:
            try:
                design_name_for_classifier = _design_name_from_dcp(input_dcp)
            except Exception:
                pass
        pathology_block = self._build_pathology_block(design_name_for_classifier)
        if pathology_block:
            summary.append("")
            summary.extend(pathology_block)

        # Feature-based recipe router — deterministic second-stage routing
        # on top of the pathology classifier. On the 4 known designs the
        # pathology label is the same (CELL_SPREAD) for four DIFFERENT
        # winning recipes; the router uses |WNS|, fmax_ratio, failing-
        # endpoint count, spread, and remaining budget to select among
        # them. Always on (no env gate); silent when features missing.
        router_block = self._build_recipe_router_block()
        if router_block:
            summary.append("")
            summary.extend(router_block)

        # Cross-model steering (post-grok-4.3-migration): when enabled AND
        # the design matches a known historical winner, append a compact
        # hint describing what the prior model did. No-op when the env flag
        # is unset, so default behavior is unchanged.
        steering_hint = _steering_iter1_hint(design_name_for_classifier)
        if steering_hint:
            summary.append("")
            summary.append(steering_hint)

        summary_text = "\n".join(summary)
        print(summary_text)
        print()

        return summary_text

    def _build_pathology_block(self, design_name: Optional[str] = None) -> list[str]:
        """Return a list of strings to append to the Phase 1 summary that
        describes the deterministic pathology diagnosis.

        Builds synthetic "paths" from the Phase 1 data we have:
          - one design-level path carrying global cell_spread + slack
          - per-top-high-fanout-net path entries carrying the fanout
            number (so HIGH_FANOUT_DRIVER fires when warranted)

        When `design_name` is provided AND the recipe-applicability
        table marks `recipe_cell_replacement` as harmful/error for this
        design (e.g., corescore_500_mod), the recommended-recipe list
        drops that recipe and surfaces a BLOCKED warning so the LLM
        doesn't waste a round trying it.

        Returns [] when the classifier is unavailable (soft-import
        failed) or when no signal data exists.
        """
        if _classify_design is None:
            return []
        paths: list[dict] = []
        # Global design-level "path" so cell_spread + slack can fire
        # at design-level even when no per-path enrichment is available.
        design_level_path: dict = {}
        # Pre-sweep feature view (jul23): classify on the post-sweep
        # timing state when a step-0 route re-roll was adopted.
        _slack_for_features = self._phase1_wns_for_features()
        if _slack_for_features is not None:
            design_level_path["slack_ns"] = _slack_for_features
        if (isinstance(self.critical_path_spread_info, dict)
                and self.critical_path_spread_info.get("avg_distance") is not None):
            design_level_path["cell_spread"] = float(
                self.critical_path_spread_info["avg_distance"]
            )
        # Roll up top fanouts as "nets on this path" so HIGH_FANOUT_DRIVER
        # can fire from a single design-level path.
        if self.high_fanout_nets:
            top_nets = [(name, fanout) for name, fanout, _ in self.high_fanout_nets[:5]]
            design_level_path["high_fanout_nets"] = top_nets
        if design_level_path:
            paths.append(design_level_path)

        # One synthetic path per top-3 high-fanout net so the count-based
        # primary-label tie-breaking surfaces HIGH_FANOUT_DRIVER when
        # fanouts are the dominant signal.  Each path also inherits the
        # design-level cell_spread (it's a global property — every
        # critical path is in the same fabric) so designs with HUGE
        # spread (boom_soc: 302 tiles avg) don't get out-voted by
        # moderate fanout signals (boom_soc: 111-173 fanout, well below
        # the 500 VERY_HIGH_FANOUT threshold).
        cell_spread_global = None
        if (isinstance(self.critical_path_spread_info, dict)
                and self.critical_path_spread_info.get("avg_distance") is not None):
            cell_spread_global = float(
                self.critical_path_spread_info["avg_distance"]
            )
        for name, fanout, _path_count in (self.high_fanout_nets or [])[:3]:
            p = {
                "high_fanout_nets": [(name, fanout)],
                "slack_ns": _slack_for_features,
            }
            if cell_spread_global is not None:
                p["cell_spread"] = cell_spread_global
            paths.append(p)

        if not paths:
            return []

        try:
            diagnosis = _classify_design(
                paths,
                design_context={
                    "initial_wns": self.initial_wns,
                    "high_fanout_nets": [
                        (n, f) for n, f, _ in (self.high_fanout_nets or [])
                    ],
                    "critical_path_spread_info": self.critical_path_spread_info,
                },
            )
        except Exception as e:
            logger.warning(f"pathology classifier failed: {e}")
            return []

        out: list[str] = []
        out.append("PATHOLOGY DIAGNOSIS (deterministic, from Phase 1 data):")
        out.append(f"  Primary: {diagnosis.primary_label}")
        if diagnosis.counts:
            non_primary = [
                f"{k}={v}" for k, v in sorted(
                    diagnosis.counts.items(), key=lambda kv: -kv[1])
                if k != diagnosis.primary_label
            ]
            if non_primary:
                out.append(f"  Secondary: {', '.join(non_primary)}")
        # Filter blocked recipes out of the recommendation list using
        # the per-design applicability table (scheduler.dispatch.
        # recipe_safe_for).  Currently only recipe_cell_replacement is
        # gated this way; if other recipes get per-design blocks in the
        # future, extend the mapping here.
        # Gated OFF in contest mode: this is a benchmark-name
        # conditional and violates the hidden-design hard rule.
        blocked_recipes: set = set()
        contest_mode = bool(getattr(self, "contest_mode", False))
        if (design_name and _recipe_safe_for is not None
                and not contest_mode
                and not _recipe_safe_for(design_name)):
            blocked_recipes.add("recipe_cell_replacement")
        recommended = [
            r for r in diagnosis.suggested_recipes_ordered
            if r not in blocked_recipes
        ]
        if recommended:
            out.append("  RECOMMENDED RECIPE ORDER (try in this order; "
                       "each is bounded and reverts on regression):")
            for i, r in enumerate(recommended, 1):
                out.append(f"    {i}. {r}")
        if blocked_recipes:
            out.append("  BLOCKED RECIPES (per-design applicability table; "
                       "DO NOT call):")
            for r in sorted(blocked_recipes):
                out.append(f"    - {r}")
        if diagnosis.notes:
            for n in diagnosis.notes:
                out.append(f"  Note: {n}")
        out.append(
            "  This diagnosis is DETERMINISTIC — derived from measured "
            "Phase 1 data, not LLM guesswork.  Strongly prefer recipes "
            "in the order shown unless live evidence contradicts."
        )
        # Store the diagnosis for downstream consumers (RAG records,
        # post-run analysis, optional prompt-injection in later iters).
        self.design_pathology = diagnosis
        return out

    def _router_unattempted_heavy_step(self) -> Optional[str]:
        """Return a one-liner describing the next unattempted heavy step
        from the active router plan, or None if all heavy steps have been
        attempted (or no plan is active).

        "Heavy step" = a vivado_place_design call (any directive) — this
        is the empirically-observed compliance gap in the 2026-05-18 R4
        reruns: digit-recognition stopped at 16 min with 34 min budget
        remaining without ever invoking place_design Auto_1, the R4
        plan's step 3. Feature-based, not name-based: any router plan
        that has `vivado_place_design` in its `actions` triggers this
        check whenever the LLM signals stop.

        Returns the action's name + note string so the force-continue
        prompt can name the exact tool + directive to try next.
        """
        plan = getattr(self, "recipe_router_plan", None)
        if plan is None or not getattr(plan, "actions", None):
            return None
        # Have any place_design calls happened?
        seen_place_design = any(t == "vivado_place_design"
                                for t, _ in self._tool_calls_seen)
        if seen_place_design:
            return None
        # Find the first action.name == "vivado_place_design" in the plan.
        for action in plan.actions:
            if action.name == "vivado_place_design":
                return f"{action.name} ({action.note})"
        return None

    def should_inject_v05_router_nudge(self,
                                       current_gain_mhz: float,
                                       remaining_s: float
                                       ) -> tuple[bool, Optional[str]]:
        """V0.5 gate — pure decision function for the router-step-aware nudge.

        Returns (should_fire, unattempted_step_description). Both halves
        are computed from self.* state + the two passed measurables.

        Gates (all must hold for `should_fire = True`):
          - active router plan has an unattempted heavy step
          - `current_gain_mhz >= 0.0` (V0.5 relaxation — was `> 0.0`
            in V0.4; relaxed to also cover the "no improvement yet but
            heavy step unattempted" case observed on spam-filter)
          - `remaining_s >= V05_MIN_REMAINING_S` (5 min default)
          - NOT `self._budget_killed` (valid session/checkpoint exists)

        Exposed as a method so unit tests can drive the gate without
        running the full optimize() loop.
        """
        unattempted = self._router_unattempted_heavy_step()
        if unattempted is None:
            return (False, None)
        if current_gain_mhz < 0.0:                # clear regression
            return (False, unattempted)
        if remaining_s < V05_MIN_REMAINING_S:     # budget too low
            return (False, unattempted)
        if self._budget_killed:                   # session compromised
            return (False, unattempted)
        return (True, unattempted)

    def _build_recipe_router_block(self) -> list[str]:
        """Return prompt-block lines from the feature-based recipe router.

        Constructs a PhaseOneFeatures snapshot from already-collected
        Phase-1 state (self.initial_wns, self.clock_period,
        self.initial_failing_endpoints, self.critical_path_spread_info,
        and the live wall-budget deadline) and asks the router for a
        recipe plan. Returns formatted lines, or [] when the router is
        unavailable or only emits the low-confidence FALLBACK plan
        (which adds no signal beyond the pathology classifier).
        """
        if _decide_recipe_path is None or _RouterFeatures is None:
            return []

        spread: Optional[float] = None
        if (isinstance(self.critical_path_spread_info, dict)
                and self.critical_path_spread_info.get("avg_distance") is not None):
            spread = float(self.critical_path_spread_info["avg_distance"])

        remaining_budget: Optional[float] = None
        if self._budget_deadline is not None:
            remaining_budget = max(0.0, self._budget_deadline - time.time())

        try:
            # Pre-sweep feature view (jul23): when a step-0 route re-roll
            # was adopted, route on the POST-SWEEP timing state — the
            # pipeline starts there, not at the pristine entry.
            _u = self.utilization if isinstance(self.utilization, dict) else {}
            features = _RouterFeatures(
                # jul25 (B4) resource/size features. cell_count was ALREADY
                # measured every run (0.0-0.3 s) but the router could not see
                # it — that is jul22 risk #6, the reason R3/R4 carried a
                # static Explore estimate across a 158x cell-count range.
                cell_count=self._input_cell_count,
                lut_util_pct=_u.get("lut_pct"),
                bram_util_pct=_u.get("bram_pct"),
                uram_util_pct=_u.get("uram_pct"),
                dsp_util_pct=_u.get("dsp_pct"),
                memory_dominated=self.memory_dominated,
                route_pct=self.route_pct,
                wns_ns=self._phase1_wns_for_features(),
                clock_period_ns=self.clock_period,
                failing_endpoint_count=self._phase1_failing_endpoints_for_features(),
                critical_path_avg_spread_tiles=spread,
                remaining_wall_budget_s=remaining_budget,
                class_g_attempted=False,  # iter-1 — no Class G yet
            )
            plan = _decide_recipe_path(features)
        except Exception as e:
            logger.warning(f"recipe_router failed: {e}")
            return []

        # Suppress FALLBACK with no blocks — it adds no signal beyond
        # the pathology classifier. Emit when we have a positive rule
        # match OR when block rules (R5/R6) produced applicability info.
        if plan.rule_id == "FALLBACK" and not plan.blocks:
            return []

        # Store the plan on self so downstream consumers (RAG, audit logs,
        # later-iter prompts) can reference which rule fired.
        self.recipe_router_plan = plan

        text = plan.format_for_prompt()
        # format_for_prompt returns a multi-line string; split into the
        # list[str] shape expected by the summary builder. Drop a leading
        # blank line so it doesn't double-space with the previous block.
        lines = text.split("\n")
        if lines and lines[0] == "":
            lines = lines[1:]
        return lines

    @staticmethod
    def _is_model_unavailable_error(e: Exception) -> bool:
        """True iff the error indicates the MODEL is unavailable (not a transient
        rate-limit/timeout/5xx).  Only these warrant a model fallback.

        R-D2-4 reclassification (2026-07-20): the auth signatures
        ("unauthorized", "401", "403", "permission") were REMOVED from this
        classifier — they are KEY-level outages (see
        _is_key_level_auth_error), not model outages.  The eval-day defect:
        a key-level 401 ("User not found") matched here and spuriously
        pinned the fallback model, which shares the same dead key.
        Delegates to optimizer.api_resilience.classify_api_error, whose
        key_auth check precedes the model check so "user not found" can
        never match the bare "not found" model signature."""
        s = f"{type(e).__name__}: {e}"
        if _classify_api_error is not None:
            return _classify_api_error(s) == "model_unavailable"
        s = s.lower()
        sigs = ("not found", "404", "model_not_found", "no endpoints",
                "no allowed providers", "is not a valid model", "does not exist",
                "deprecat")
        return any(x in s for x in sigs)

    @staticmethod
    def _is_key_level_auth_error(e: Exception) -> bool:
        """True iff the error is a KEY-level auth outage (the eval-day 401
        'User not found' storm class, mini-isp 18:09:02 + boom_debugwall
        18:53:02).  These must backoff-retry the SAME primary model —
        switching models cannot fix a dead key (R-D2-4)."""
        s = f"{type(e).__name__}: {e}"
        if _classify_api_error is not None:
            return _classify_api_error(s) == "key_auth"
        s = s.lower()
        sigs = ("user not found", "401", "403", "unauthorized",
                "invalid api key", "no auth credentials", "permission")
        return any(x in s for x in sigs)

    @staticmethod
    def _is_transient_api_error(e: Exception) -> bool:
        """True for retryable provider/API conditions (rate-limit, 5xx, network
        timeouts).  Disjoint from _is_model_unavailable_error: that one means
        the MODEL is gone (fall back immediately); this one means the provider
        is having a moment (retry, then fall back if it persists)."""
        s = f"{type(e).__name__}: {e}".lower()
        sigs = ("429", "rate limit", "rate_limit", "500", "502", "503", "504",
                "timeout", "timed out", "overloaded", "connection error",
                "connection reset", "temporarily", "service unavailable",
                "apiconnectionerror", "internal server error")
        return any(x in s for x in sigs)

    @staticmethod
    def _is_prompt_limit_error(e: Exception) -> bool:
        """True for the provider's per-request prompt-size rejection (the
        contest key's 402 'Prompt tokens limit exceeded', observed jul03)."""
        s = f"{type(e).__name__}: {e}".lower()
        return ("prompt tokens limit exceeded" in s
                or ("402" in s and "prompt token" in s))

    def _log_prompt_limit_exhaustion(self, e: Exception) -> None:
        """A 402 prompt-limit that SURVIVES pruning to the 8k floor means the
        key's allowance sits below any viable prompt — OpenRouter shrinks the
        per-request prompt allowance as remaining credit approaches zero
        (aug04: allowance 13779 and falling killed all 50 fir iterations in
        30 s; the run completed VALID_OPTIMIZED at the LLM-free scaffold
        floor and the 13.38 was misread as a real regression for a day).
        Loud + greppable so no harness or human mistakes an LLM-dead run for
        a measured result again.  Observability only — the run continues
        LLM-free (never-worse: the scaffold floor still beats an abort)."""
        self._key_exhaustion_suspect_count = getattr(
            self, "_key_exhaustion_suspect_count", 0) + 1
        logger.error(
            f"KEY-EXHAUSTION-SUSPECT #{self._key_exhaustion_suspect_count}: "
            f"402 prompt-limit persists after pruning to the 8k floor "
            f"({str(e)[:160]}) — provider key allowance is below any viable "
            f"prompt (credit likely exhausted). LLM is DEAD for this run; "
            f"any result from here is the LLM-free scaffold floor, NOT a "
            f"measured optimization outcome.")
        print("🚨 KEY-EXHAUSTION-SUSPECT: LLM calls failing 402 below the "
              "prune floor — treat this run's result as LLM-free.")

    @staticmethod
    def _estimate_message_tokens(m) -> int:
        """Conservative token estimate (chars/3 — JSON-heavy tool output runs
        denser than prose's chars/4; overestimating is the safe direction)."""
        try:
            return max(1, len(json.dumps(m, default=str)) // 3)
        except Exception:
            return max(1, len(str(m)) // 3)

    def _estimate_messages_tokens(self) -> int:
        return sum(self._estimate_message_tokens(m) for m in self.messages)

    def _prune_conversation(self, target_tokens: int) -> int:
        """Drop middle messages so the conversation fits ~target_tokens.

        Keeps the head (system prompt + initial analysis/recipe message,
        PROMPT_PRUNE_HEAD_KEEP) and a contiguous SUFFIX of recent messages,
        replacing the dropped middle with one marker message carrying the
        essential state (best WNS). A contiguous suffix can never orphan a
        tool response from a LATER parent, but it may START with tool
        messages whose assistant parent was dropped — those are popped so
        the API never sees an orphaned tool_call_id. Returns #dropped."""
        head = self.messages[:PROMPT_PRUNE_HEAD_KEEP]
        rest = self.messages[PROMPT_PRUNE_HEAD_KEEP:]
        if not rest:
            return 0
        head_tokens = sum(self._estimate_message_tokens(m) for m in head)
        tail_budget = max(2_000, target_tokens - head_tokens - 200)
        kept: list = []
        used = 0
        for m in reversed(rest):
            t = self._estimate_message_tokens(m)
            if used + t > tail_budget and kept:
                break
            kept.append(m)
            used += t
        kept.reverse()
        while kept and isinstance(kept[0], dict) and kept[0].get("role") == "tool":
            kept.pop(0)
        dropped = len(rest) - len(kept)
        if dropped <= 0:
            return 0
        best = getattr(self, "best_wns", None)
        best_txt = (f"{best:.3f} ns" if isinstance(best, (int, float))
                    and best != float("-inf") else "unknown")
        marker = {
            "role": "user",
            "content": (
                f"[CONTEXT PRUNED: {dropped} earlier conversation messages were "
                f"removed to fit the provider's per-request prompt-token limit. "
                f"State: current best WNS on the scored clock is {best_txt}; the "
                f"best checkpoint is preserved on disk by the keep-best mirror. "
                f"Continue optimizing from the most recent messages below.]"
            ),
        }
        self.messages = head + [marker] + kept
        return dropped

    def _chat_create(self, model: str):
        return self.openai.chat.completions.create(
            model=model,
            messages=self.messages,
            tools=self.tools,
            tool_choice="auto",
            max_tokens=4096,
            extra_body={"usage": {"include": True}},
        )

    def _create_completion_with_fallback(self):
        """Call the primary model with eval-day resilience (R-D2-1/R-D2-4,
        2026-07-20; kill switch _api_resilience_enabled, default ON):
          - KEY-level auth outage (401 'User not found' class) -> backoff and
            retry the SAME primary model on a deadline-aware exponential
            schedule.  NEVER switch models: the fallback shares the same dead
            key (both repro logs: mini-isp 18:09:02, boom_debugwall 18:53:02);
          - model-UNAVAILABLE error (404/model_not_found/...) -> fall back
            once to FALLBACK_MODEL and pin it for the rest of the run
            (existing behavior preserved);
          - TRANSIENT error (429/5xx/timeout) -> backoff-retry the SAME model
            on the schedule; if it persists across
            TRANSIENT_FALLBACK_THRESHOLD consecutive failures, pin
            FALLBACK_MODEL (existing escape preserved — transient only,
            never for key_auth);
          - 402 prompt-limit -> existing prune-and-retry path (prompt guard,
            jul03), untouched, never enters backoff;
          - anything else propagates (the iteration loop logs and continues).

        Backoff sleeps go through self._backoff_sleep (injectable) and are
        computed by optimizer.api_resilience.compute_backoff_sleep, which is
        deadline-aware (never sleeps past remaining-wall-minus-guard; the
        finalize path always survives) and capped per episode
        (API_BACKOFF_EPISODE_CAP_S) — after the cap the error propagates to
        the existing 'LLM dead' path.  The loop is synchronous so a storm is
        absorbed HERE without returning to optimize() (no iteration burn, no
        conversation pollution — the loop-side hygiene is Plan 02-02)."""
        if not self._api_resilience_enabled or _classify_api_error is None:
            return self._create_completion_legacy()
        attempt = 0
        in_episode = False
        while True:
            try:
                resp = self._chat_create(self.model)
                self._consecutive_transient_failures = 0
                if in_episode:
                    # R-D2-4 single-line episode-resolution forensic log
                    # (Plan 02-02): one greppable line per episode so eval
                    # forensics can reconstruct a storm from the log alone.
                    self._api_last_episode_failures = attempt
                    logger.warning(
                        f"[api-resilience] episode "
                        f"#{self._api_error_episodes} resolved: recovered "
                        f"after {attempt} failure(s), "
                        f"{self._api_backoff_used_s:.0f}s backoff."
                    )
                self._api_backoff_used_s = 0.0   # episode resolved
                return resp
            except Exception as e:
                kind = _classify_api_error(f"{type(e).__name__}: {e}")
                # Prompt too large for the provider key (402 doom loop,
                # jul03): prune and retry — appending the error to the
                # conversation (the old path) only GROWS the prompt and
                # makes every later call fail.  UNCHANGED from legacy.
                if kind == "prompt_limit":
                    for _target in (PROMPT_PRUNE_TARGET // 2, 8_000):
                        _dropped = self._prune_conversation(_target)
                        logger.warning(
                            f"[prompt-guard] provider prompt-limit hit "
                            f"({str(e)[:120]}); pruned {_dropped} messages to "
                            f"~{_target} est. tokens and retrying.")
                        try:
                            resp = self._chat_create(self.model)
                            self._consecutive_transient_failures = 0
                            self._api_backoff_used_s = 0.0
                            return resp
                        except Exception as e2:
                            if not self._is_prompt_limit_error(e2):
                                raise
                            e = e2
                    self._log_prompt_limit_exhaustion(e)
                    raise
                if (kind == "model_unavailable"
                        and self.model != FALLBACK_MODEL):
                    logger.warning(
                        f"Primary model {self.model!r} unavailable ({e!r}); "
                        f"falling back to {FALLBACK_MODEL!r} for the rest of "
                        f"the run."
                    )
                    self.model = FALLBACK_MODEL
                    return self._chat_create(self.model)
                if kind in ("key_auth", "transient"):
                    if not in_episode:
                        in_episode = True
                        self._api_error_episodes += 1
                        self._api_backoff_used_s = 0.0
                    if kind == "transient":
                        self._consecutive_transient_failures += 1
                        if (self.model != FALLBACK_MODEL
                                and self._consecutive_transient_failures
                                >= TRANSIENT_FALLBACK_THRESHOLD):
                            logger.warning(
                                f"{self._consecutive_transient_failures} "
                                f"consecutive transient failures on "
                                f"{self.model!r} ({e!r}); pinning "
                                f"{FALLBACK_MODEL!r} for the rest of the run."
                            )
                            self.model = FALLBACK_MODEL
                            continue   # immediate retry on the fallback
                    dur = _compute_backoff_sleep(
                        attempt=attempt,
                        remaining_budget_s=self._budget_remaining(),
                        finalize_guard_s=self._api_backoff_finalize_guard_s,
                        backoff_used_s=self._api_backoff_used_s,
                    )
                    if dur is None:
                        # Episode cap reached or no room before the
                        # finalize reserve -> give up, propagate to the
                        # existing LLM-dead path (T-02-01/T-02-03).
                        # Plan 02-02: record the episode's failure count
                        # for the loop-side forensic line (R-D2-4).
                        self._api_last_episode_failures = attempt + 1
                        logger.warning(
                            f"[api-resilience] giving up after "
                            f"{self._api_backoff_used_s:.0f}s backoff "
                            f"(episode #{self._api_error_episodes}, "
                            f"attempt {attempt + 1}, {kind}) on "
                            f"{self.model!r}: {e!r}"
                        )
                        raise
                    logger.warning(
                        f"[api-resilience] {kind} API error on "
                        f"{self.model!r} (attempt {attempt + 1}, episode "
                        f"#{self._api_error_episodes}): {e!r}; backing off "
                        f"{dur:.1f}s and retrying the SAME model."
                    )
                    self._backoff_sleep(dur)
                    self._api_backoff_used_s += dur
                    self._total_backoff_s += dur
                    attempt += 1
                    continue
                raise

    def _create_completion_legacy(self):
        """Pre-R-D2 call path, preserved byte-for-behavior under the
        _api_resilience_enabled kill switch (OFF):
          - model-unavailable OR auth error -> one-shot fallback-model pin
            (legacy lumped key-level 401/403 into model-unavailable — the
            exact eval-day misclassification R-D2-4 fixes);
          - transient -> single flat TRANSIENT_RETRY_BACKOFF_S retry, pin
            fallback after TRANSIENT_FALLBACK_THRESHOLD consecutive
            failures;
          - anything else propagates.
        Only change vs the pre-change code: the sleep goes through the
        injectable self._backoff_sleep (default time.sleep — identical
        behavior, testable without real sleeps)."""
        try:
            resp = self._chat_create(self.model)
            self._consecutive_transient_failures = 0
            return resp
        except Exception as e:
            # Prompt too large for the provider key (402 doom loop, jul03):
            # prune and retry — appending the error to the conversation (the
            # old path) only GROWS the prompt and makes every later call fail.
            if self._is_prompt_limit_error(e):
                for _target in (PROMPT_PRUNE_TARGET // 2, 8_000):
                    _dropped = self._prune_conversation(_target)
                    logger.warning(
                        f"[prompt-guard] provider prompt-limit hit "
                        f"({str(e)[:120]}); pruned {_dropped} messages to "
                        f"~{_target} est. tokens and retrying.")
                    try:
                        resp = self._chat_create(self.model)
                        self._consecutive_transient_failures = 0
                        return resp
                    except Exception as e2:
                        if not self._is_prompt_limit_error(e2):
                            raise
                        e = e2
                self._log_prompt_limit_exhaustion(e)
                raise
            if self.model != FALLBACK_MODEL and (
                    self._is_model_unavailable_error(e)
                    or self._is_key_level_auth_error(e)):
                logger.warning(
                    f"Primary model {self.model!r} unavailable ({e!r}); "
                    f"falling back to {FALLBACK_MODEL!r} for the rest of the run."
                )
                self.model = FALLBACK_MODEL
                return self._chat_create(self.model)
            if self._is_transient_api_error(e):
                self._consecutive_transient_failures += 1
                logger.warning(
                    f"Transient API error #{self._consecutive_transient_failures} "
                    f"on {self.model!r} ({e!r}); retrying once after backoff."
                )
                self._backoff_sleep(TRANSIENT_RETRY_BACKOFF_S)
                try:
                    resp = self._chat_create(self.model)
                    self._consecutive_transient_failures = 0
                    return resp
                except Exception as e2:
                    if (self.model != FALLBACK_MODEL
                            and self._consecutive_transient_failures
                            >= TRANSIENT_FALLBACK_THRESHOLD):
                        logger.warning(
                            f"{self._consecutive_transient_failures} consecutive "
                            f"transient failures on {self.model!r} ({e2!r}); "
                            f"pinning {FALLBACK_MODEL!r} for the rest of the run."
                        )
                        self.model = FALLBACK_MODEL
                        return self._chat_create(self.model)
                    raise
            raise

    def _llm_cost_breached(self) -> bool:
        """C1-T1 β circuit-breaker: has this attempt's LLM spend crossed the
        effective in-attempt exit?  Threshold <= 0 disables (never breached)."""
        return (self.llm_cost_exit_usd > 0
                and self.total_cost >= self.llm_cost_exit_usd)

    def _write_cost_ledger(self) -> None:
        """FIX 1a (C1/S7 breaker bypass, jul20 adversarial review):
        incremental crash-safe LLM spend ledger.

        token_usage.json is written ONLY by _print_optimization_summary on
        the normal-exit path — any crash after real LLM spend loses the
        ledger, the multi-restart wrapper reads cost=None, charges $0, and
        the cumulative β circuit-breaker is silently bypassed.  Rewrite a
        tiny cost_ledger.json after EVERY API-call cost accrual (plus a $0
        seed at construction, so a benign no-LLM crash leaves an explicit
        $0 record): atomic tmp+os.replace, same discipline as _atomic_copy,
        so a kill mid-write can never expose a truncated ledger.  ANY
        failure is logged and swallowed — the ledger must never crash the
        run it is auditing.
        """
        try:
            payload = json.dumps({
                "total_cost": round(
                    float(getattr(self, "total_cost", 0.0) or 0.0), 6),
                "calls": int(getattr(self, "llm_call_count", 0) or 0),
            })
            path = Path(self.run_dir) / "cost_ledger.json"
            fd, tmp = tempfile.mkstemp(
                prefix="cost_ledger.", suffix=".tmp", dir=str(path.parent))
            try:
                with os.fdopen(fd, "w") as fh:
                    fh.write(payload)
                os.replace(tmp, str(path))
            except Exception:
                try:
                    os.unlink(tmp)
                except OSError:
                    pass
                raise
        except Exception as e:
            try:
                logger.warning(f"cost-ledger write failed (non-fatal): {e}")
            except Exception:
                pass

    async def get_completion(self) -> tuple[str, bool]:
        """Get LLM completion and process it."""
        try:
            # C1-T1 β circuit-breaker (jul20): pre-call spend gate.  The
            # iteration loop's cost exit only runs BETWEEN outer iterations,
            # but process_message recurses back here after EVERY tool round —
            # a single iteration can chain many LLM calls with no cost check
            # in between.  At eval iteration speed (~12x local) that is how
            # preview #15 crossed the $1.00 zero-cap (grok-4.5 vexriscv_v2
            # ZEROED "no_improvement") and how reh-1 fir reached cum $0.76.
            # Refuse to issue another call once spend crosses the effective
            # exit; the loop's breach checks (v0_3 + anchor) then finalize
            # with the banked best — never mid-op abandonment.
            if self._llm_cost_breached():
                logger.info(
                    f"[cost-exit] refusing LLM call: spend "
                    f"${self.total_cost:.4f} >= exit "
                    f"${self.llm_cost_exit_usd:.2f}")
                return (f"[cost-exit] LLM spend ${self.total_cost:.2f} reached "
                        f"the in-attempt exit ${self.llm_cost_exit_usd:.2f}; "
                        f"no further LLM calls this attempt.", False)

            self.llm_call_count += 1
            logger.info(f"LLM API call #{self.llm_call_count}")

            # Prompt-size guard (jul03): keep every request under the eval
            # key's per-request prompt-token limit so the LLM stays available
            # for the whole run instead of 402-ing out mid-budget.
            _est = self._estimate_messages_tokens()
            if _est > PROMPT_TOKEN_SOFT_LIMIT:
                _dropped = self._prune_conversation(PROMPT_PRUNE_TARGET)
                logger.info(
                    f"[prompt-guard] conversation ~{_est} est. tokens > soft "
                    f"limit {PROMPT_TOKEN_SOFT_LIMIT}; pruned {_dropped} middle "
                    f"messages -> ~{self._estimate_messages_tokens()} est. tokens")

            # Request usage accounting from OpenRouter (with model fallback)
            response = self._create_completion_with_fallback()
            
            # Validate response immediately
            if response is None:
                raise ValueError("API returned None response")
            
            # Extract token usage information from OpenRouter
            if hasattr(response, 'usage') and response.usage:
                prompt_tokens = response.usage.prompt_tokens
                completion_tokens = response.usage.completion_tokens
                total_tokens = response.usage.total_tokens
                
                # Update cumulative totals
                self.total_prompt_tokens += prompt_tokens
                self.total_completion_tokens += completion_tokens
                self.total_tokens += total_tokens
                
                # Get actual cost from OpenRouter (in credits/dollars)
                call_cost = 0.0
                if hasattr(response.usage, 'cost') and response.usage.cost is not None:
                    call_cost = float(response.usage.cost)
                    self.total_cost += call_cost
                else:
                    logger.warning("OpenRouter did not provide cost information")
                
                # Extract additional usage details if available
                cached_tokens = 0
                reasoning_tokens = 0
                if hasattr(response.usage, 'prompt_tokens_details') and response.usage.prompt_tokens_details:
                    if hasattr(response.usage.prompt_tokens_details, 'cached_tokens'):
                        cached_tokens = response.usage.prompt_tokens_details.cached_tokens or 0
                if hasattr(response.usage, 'completion_tokens_details') and response.usage.completion_tokens_details:
                    if hasattr(response.usage.completion_tokens_details, 'reasoning_tokens'):
                        reasoning_tokens = response.usage.completion_tokens_details.reasoning_tokens or 0
                
                # Store details for this call
                call_detail = {
                    "call_number": self.llm_call_count,
                    "iteration": self.iteration,
                    "prompt_tokens": prompt_tokens,
                    "completion_tokens": completion_tokens,
                    "total_tokens": total_tokens,
                    "cost": call_cost,
                    "cached_tokens": cached_tokens,
                    "reasoning_tokens": reasoning_tokens
                }
                self.api_call_details.append(call_detail)
                
                # Log token usage
                cache_info = f", Cached: {cached_tokens:,}" if cached_tokens > 0 else ""
                reasoning_info = f", Reasoning: {reasoning_tokens:,}" if reasoning_tokens > 0 else ""
                cost_info = f" | Cost: ${call_cost:.4f}" if call_cost > 0 else ""
                
                logger.info(f"API call #{self.llm_call_count} - Tokens: {prompt_tokens} prompt + {completion_tokens} completion = {total_tokens} total{cost_info}{cache_info}{reasoning_info}")
                print(f"[API Call #{self.llm_call_count}] Tokens: {total_tokens:,} (Prompt: {prompt_tokens:,}, Completion: {completion_tokens:,}{cache_info}{reasoning_info}){cost_info}")
            else:
                logger.warning("No usage information in API response")

            # FIX 1a (C1/S7): persist the incremental spend ledger after
            # every API call so a later crash cannot lose the accrued cost
            # (never raises — see _write_cost_ledger).
            self._write_cost_ledger()

            # Debug logging
            if self.debug:
                logger.debug(f"Response type: {type(response)}")
                logger.debug(f"Response: {response}")
            
            # Check if response has error
            if hasattr(response, 'error') and response.error:
                raise ValueError(f"API returned error: {response.error}")
            
            return await self.process_response(response)
            
        except Exception as e:
            logger.error(f"Error in get_completion: {e}")
            logger.error(f"Number of messages in conversation: {len(self.messages)}")
            if self.messages:
                logger.error(f"Last message: {self.messages[-1]}")
            raise
    
    # ------- wall-time budget helpers -------
    def _budget_remaining(self) -> float:
        """Seconds left before the wall-time deadline. inf when no cap set."""
        if self._budget_deadline is None:
            return float("inf")
        return max(0.0, self._budget_deadline - time.time())

    def _budget_exhausted(self) -> bool:
        """True iff we're past the wall-time deadline (no margin)."""
        return self._budget_remaining() <= 0.0

    def _strategy_fits_in_budget(self, estimated_seconds: float,
                                  label: str = "<unknown>") -> bool:
        """Whether `estimated_seconds` of work is likely to finish before the
        budget deadline.  Logs + records the skip when False so we can surface
        it in the run summary.  Always returns True when no budget set.
        """
        if self._budget_deadline is None:
            return True
        remaining = self._budget_remaining()
        if estimated_seconds > remaining:
            self._strategies_skipped_budget.append(
                f"{label} (need ~{estimated_seconds:.0f}s, have {remaining:.0f}s)"
            )
            logger.info(
                f"Budget guard: skipping {label} (need ~{estimated_seconds:.0f}s, "
                f"only {remaining:.0f}s remaining of {self.max_wall_seconds:.0f}s)"
            )
            return False
        return True

    def _estimate_tool_runtime(self, tool_name: str,
                                is_risky: Optional[bool] = None) -> float:
        """Best-effort estimate of how long a tool call will take (seconds).

        Uses the max of the last 5 observed runs for `tool_name` if any have
        been recorded; otherwise falls back to a conservative constant.  We
        intentionally err high so the dispatcher skips a call rather than
        starting one that won't finish under the budget.

        `is_risky` lets the caller signal that this specific invocation is
        risky (e.g., vivado_run_tcl wrapping place_design).  When None we
        consult RISKY_VIVADO_TOOLS membership.
        """
        history = self._tool_runtime_history.get(tool_name, [])
        if history:
            self._last_estimate_provenance = _gl.PROV_HISTORY
            return max(history[-5:])
        self._last_estimate_provenance = _gl.PROV_UNKNOWN
        if is_risky is None:
            is_risky = tool_name in RISKY_VIVADO_TOOLS
        if is_risky:
            return self._no_history_risky_estimate_s()
        return DEFAULT_CHEAP_RUNTIME_S

    def _no_history_risky_estimate_s(self) -> float:
        """Size-aware fallback for a risky tool with NO runtime history yet.

        THE DEFECT THIS FIXES (measured, chain40 jul26).  This used to return the
        flat `DEFAULT_RISKY_RUNTIME_S` (600 s) regardless of design size, so on
        mini-ISP — 8,414 primitive cells, whose size-model place+route is 37 s —
        `_should_skip_for_budget` REFUSED `vivado_phys_opt_design` three times with
        277/275/265 s remaining and the run shipped `VALID_FALLBACK_BASELINE` at
        +0.00 MHz.  The same log line that recorded the refusal also printed the
        real anchor: "place+route anchor 37s".  A 16x over-estimate refused work
        that would have finished in well under a tenth of the window.

        That is precisely the family this session has been clearing: *a prediction
        may SCHEDULE work; it may never REFUSE it.  Refusal is legitimate only
        against a hard bound — wall clock, legality, a measured cost.*  The wall IS
        a hard bound, but 600 s was not a measurement of anything; it is blind to
        the design.

        THE FIX, and why it cannot regress a big design: bound the blind constant
        by the DESIGN-AWARE size model (`predict_place_route_s`, the same basis
        deep-replace sizes from, published jul26 in d054bde).  Because this is a
        `min`, the estimate can only ever get SMALLER — never more conservative
        than today:
            mini-ISP    8,414 cells -> min(600, max(37x1.3, 30))  =  48 s   (was 600)
            ispd16    532,160 cells -> min(600, max(2315x1.3, 30)) = 600 s  (unchanged)
        A place+route anchor is also a conservative ceiling for a phys_opt, which is
        the tool the refusal actually blocked.

        Floors and fallbacks, all failing to CURRENT behaviour:
          * cell count unknown (Phase 1 not done) -> the constant, unchanged;
          * size model unmeasurable (returns 0)   -> the constant, unchanged;
          * never below `MIN_USEFUL_TOOL_SECONDS` so a tiny design cannot produce
            an absurd sub-30 s estimate;
          * any exception -> the constant, unchanged.
        Kill switch: `FPL26_SIZE_AWARE_TOOL_EST=0`.
        """
        _flag = os.environ.get("FPL26_SIZE_AWARE_TOOL_EST", "").strip().lower()
        if _flag in ("0", "false", "no", "off"):
            self._last_estimate_provenance = _gl.PROV_CONSTANT
            return DEFAULT_RISKY_RUNTIME_S
        cells = getattr(self, "_input_cell_count", None)
        if not cells or cells <= 0:
            self._last_estimate_provenance = _gl.PROV_CONSTANT
            return DEFAULT_RISKY_RUNTIME_S
        try:
            from optimizer.deep_replace_sibling import predict_place_route_s
            est, why = predict_place_route_s(primitive_cells=int(cells))
            if not est or est <= 0:
                self._last_estimate_provenance = _gl.PROV_CONSTANT
                return DEFAULT_RISKY_RUNTIME_S
            sized = min(DEFAULT_RISKY_RUNTIME_S,
                        max(est * 1.3, MIN_USEFUL_TOOL_SECONDS))
            if sized < DEFAULT_RISKY_RUNTIME_S:
                logger.info(
                    f"[tool-est] no history for a risky tool; sizing from the "
                    f"design instead of the blind {DEFAULT_RISKY_RUNTIME_S:.0f}s "
                    f"constant: {sized:.0f}s ({why}). A prediction may schedule "
                    f"work, never refuse it.")
            self._last_estimate_provenance = (
                _gl.PROV_MODEL if sized < DEFAULT_RISKY_RUNTIME_S else _gl.PROV_CONSTANT)
            return sized
        except Exception as e:  # pragma: no cover — defensive
            logger.warning(f"[tool-est] size-aware estimate unavailable "
                           f"({type(e).__name__}); using the constant.")
            self._last_estimate_provenance = _gl.PROV_CONSTANT
            return DEFAULT_RISKY_RUNTIME_S

    def _record_tool_runtime(self, tool_name: str, elapsed: float) -> None:
        """Record a completed tool-call elapsed time for future estimation.

        Only meaningful elapsed times (>= 1 s) are kept — sub-second returns
        usually mean the call short-circuited and would skew estimates low.
        """
        if elapsed < 1.0:
            return
        # Observed leg of the predicted-vs-observed calibration pair. Joining these
        # against the budget_skip rows is what lets a blind constant be replaced by a
        # 2-4 param cost model under leave-one-design-out (fitting a COST model, which
        # the methodology invariant permits).
        _gl.emit("tool_runtime", _gl.VERDICT_OBSERVE,
                 design=getattr(self, "_design_label", None),
                 run_id=getattr(self, "run_id", None),
                 iteration=getattr(self, "iteration", None),
                 tool=tool_name, observed_s=elapsed,
                 site="dcp_optimizer._record_tool_runtime")
        bucket = self._tool_runtime_history.setdefault(tool_name, [])
        bucket.append(elapsed)
        if len(bucket) > 20:
            del bucket[: len(bucket) - 20]

    def _deadline_aware_timeout(self, tool_name: Optional[str] = None,
                                arguments: Optional[dict] = None
                                ) -> Optional[float]:
        """asyncio.wait_for timeout for the next tool call.

        Returns None when no budget is set (legacy/dev mode — no wrapping).
        Returns 0.0 when the remaining budget is too small to be useful;
        the caller must skip the call.  Returns the positive number of
        seconds the call is allowed to run otherwise.

        Note: `self._budget_deadline` is already set to
        `start_time + max_wall_seconds - _finalize_reserve_seconds` in
        optimize(), so `_budget_remaining()` IS the reserve-protected
        window for tool calls.  We do not subtract reserve again here.

        C1-T3: when `tool_name` is given AND the polish reserve is armed
        AND the call is a speculative routed-state-DESTROYING op, the
        timeout is capped at (remaining − reserve).  The pre-flight gate
        refuses such ops when their ESTIMATE exceeds that window; this
        cap is the runtime enforcement — an op whose estimate fit but
        that runs long is cancelled at the fence instead of silently
        spending into the reserved polish window (boom_soc_v2 beta:
        polish arrived at 443s remaining because earlier ops had already
        eaten the tail).  Polish stages/finalize/banking are unaffected
        (ILS/finalize bypass this path; banking ops are non-destroying).
        """
        # FIX 5 (S3): remember whether THIS computation fence-capped the
        # window, so the TimeoutError handler can label the kill cause.
        self._last_timeout_fence_capped = False
        if self._budget_deadline is None:
            return None
        remaining = self._budget_remaining()
        if remaining < MIN_USEFUL_TOOL_SECONDS:
            return 0.0
        if tool_name is not None:
            reserve = self._polish_reserve_armed_s()
            if (reserve > 0.0
                    and self._is_risky(tool_name, arguments)
                    and self.is_routed_state_destroying(tool_name, arguments)):
                self._last_timeout_fence_capped = True
                return max(0.0, remaining - reserve)
        return remaining

    def _is_risky(self, tool_name: str, arguments: Optional[dict] = None) -> bool:
        """Classify a tool call as risky (subject to estimate gating).

        - All tools in RISKY_VIVADO_TOOLS are always risky.
        - vivado_run_tcl is risky only when its tcl payload mentions one of
          RISKY_TCL_SUBSTRINGS (place_design, route_design, etc).
        """
        if tool_name in RISKY_VIVADO_TOOLS:
            return True
        if tool_name == "vivado_run_tcl" and arguments:
            cmd = arguments.get("command") or arguments.get("tcl_command") or ""
            cmd_low = str(cmd).lower()
            return any(s in cmd_low for s in RISKY_TCL_SUBSTRINGS)
        return False

    def is_routed_state_destroying(self, tool_name: str,
                                   arguments: Optional[dict] = None) -> bool:
        """R-D1-2: instance view of the module-level pure classifier,
        bound to the harness-tracked _design_routed_state.  See the
        module-level is_routed_state_destroying for the three-case scope
        and the incremental-route exclusion."""
        return is_routed_state_destroying(tool_name, arguments,
                                          self._design_routed_state)

    async def _capture_constraint_fingerprint(self, label: str):
        """Snapshot the design's timing constraints (jul25 constraint guard).

        Runs two read-only reports and digests them. Returns a
        ConstraintFingerprint; ``captured=False`` when either report could not
        be obtained, which the comparison surfaces as UNVERIFIED rather than
        silently claiming 'unchanged'.

        Read-only and best-effort by design: this must never be able to break
        or slow a run. Both reports are cheap (no timing update forced)."""
        from optimizer.constraint_guard import build_fingerprint
        clocks = excs = None
        try:
            clocks = await self.call_tool(
                "vivado_run_tcl",
                {"command": "report_clocks -return_string", "timeout": 120.0})
            if _looks_like_tool_error(clocks):
                clocks = None
        except Exception:
            clocks = None
        try:
            excs = await self.call_tool(
                "vivado_run_tcl",
                {"command": "report_exceptions -return_string", "timeout": 120.0})
            if _looks_like_tool_error(excs):
                excs = None
        except Exception:
            excs = None
        fp = build_fingerprint(clocks, excs)
        logger.info(f"[constraint-guard] {label} fingerprint: "
                    f"captured={fp.captured} clocks={fp.clock_count} "
                    f"exceptions={fp.exception_count}")
        return fp

    async def _verify_constraints_unchanged(self) -> bool:
        """Compare the ship-time constraints against the baseline.

        Returns True when constraints are unchanged OR unverifiable.

        DOES NOT BLOCK THE SHIP. This is deliberate: XDC edits have never been
        observed in any historical run (a grep over every log found zero), so
        the realistic failure mode here is a FALSE alarm, and blocking a ship
        on a false alarm would convert a monitoring gap into a lost
        submission. A real edit is loud in the log and in the decision record,
        which is what we need to catch it. Revisit only if a true positive
        ever fires."""
        base = getattr(self, "_constraint_fp_baseline", None)
        if base is None:
            logger.info("[constraint-guard] no baseline fingerprint; "
                        "constraint integrity UNVERIFIED for this run.")
            return True
        try:
            now = await self._capture_constraint_fingerprint("ship")
        except Exception as e:
            logger.warning(f"[constraint-guard] ship capture failed: {e!r}")
            return True
        changed, why = base.differs_from(now)
        if changed:
            logger.error(
                f"[constraint-guard] *** TIMING CONSTRAINTS CHANGED *** {why}. "
                f"XDC/timing-constraint edits are DISQUALIFYING under the "
                f"contest rules — this DCP must be reviewed before submission.")
            try:
                self.tool_call_details.append({
                    "tool_name": "constraint_guard",
                    "status": "CONSTRAINTS_CHANGED",
                    "detail": why,
                    # See the note at the refused_constraint_edit append: the
                    # summary printer sums this key unconditionally.
                    "elapsed_time": 0.0,
                })
            except Exception:
                pass
            return False
        logger.info(f"[constraint-guard] ship check: {why}")
        return True

    async def _maybe_plan_critique(self, tool_name: str,
                                   arguments: Optional[dict]) -> None:
        """Cheap second opinion before a heavy Vivado move (jul25 panel, 4/5).

        ADVISORY ONLY. Appends a note to self.messages that the planner may
        ignore; it never skips, cancels or rewrites the pending call. A
        malformed reply produces an empty note and is dropped entirely.

        Fires only while there is genuine beta headroom — the panel's finding
        was that our worst design (boom_soc, -22.15) made the fewest LLM calls
        and spent 36% of its ~$1 budget. Unspent beta is unused deliberation,
        not saved money.

        Strict no-op with the flag off (default)."""
        from optimizer.plan_critic import (CRITIC_MAX_TOKENS, CRITIC_SYSTEM,
                                           build_critic_prompt,
                                           parse_critic_verdict,
                                           should_critique)
        if not getattr(self, "plan_critic_enabled", False):
            return
        remaining = (self._budget_remaining()
                     if self._budget_deadline is not None else float("inf"))
        run, why = should_critique(
            enabled=True,
            tool_name=tool_name,
            arguments=arguments,
            calls_made=getattr(self, "_plan_critic_calls", 0),
            max_calls=getattr(self, "plan_critic_max_calls", 4),
            spent_usd=float(self.total_cost or 0.0),
            # The live per-attempt LLM budget is llm_cost_exit_usd (the spend
            # at which the attempt bails). 0/None means "no budget known" and
            # should_critique fails CLOSED on it — deliberate: firing without
            # a known budget could push beta past its 10%-of-alpha cap.
            budget_usd=(self.llm_cost_exit_usd
                        if getattr(self, "llm_cost_exit_usd", 0) else None),
            beta_headroom_frac=getattr(self, "plan_critic_beta_headroom_frac",
                                       0.7),
            remaining_s=remaining,
            min_remaining_s=600.0,
        )
        if not run:
            logger.debug(f"plan-critic: skipped ({why})")
            return
        prompt = build_critic_prompt(
            tool_name=tool_name,
            arguments=arguments,
            initial_wns=getattr(self, "initial_wns", None),
            current_wns=self.best_wns,
            failing_endpoints=getattr(self, "initial_failing_endpoints", None),
            router_rule=getattr(self, "_router_rule_label", None),
            router_why=getattr(self, "_router_rule_why", None),
            # LLM-INVISIBILITY (aug04 exposure investigation): exclude
            # recipe-pass machinery from the critic's model-visible
            # window — the pass is log-only by contract, and its
            # vivado_run_tcl/open/restart entries would otherwise leak
            # what the pass did into a model prompt on fired runs.
            tried=[d.get("tool_name", "")
                   for d in self.tool_call_details
                   if not d.get("recipe_pass_internal")][-8:],
            remaining_s=(None if remaining == float("inf") else remaining),
        )
        model = getattr(self, "plan_critic_model", PLAN_CRITIC_DEFAULT_MODEL)
        try:
            resp = await asyncio.to_thread(
                self.openai.chat.completions.create,
                model=model,
                messages=[{"role": "system", "content": CRITIC_SYSTEM},
                          {"role": "user", "content": prompt}],
                max_tokens=CRITIC_MAX_TOKENS,
                extra_body={"usage": {"include": True}},
            )
        except Exception as e:
            logger.info(f"plan-critic: call failed ({e!r}); continuing.")
            return
        self._plan_critic_calls = getattr(self, "_plan_critic_calls", 0) + 1
        try:
            text = resp.choices[0].message.content
        except Exception:
            text = None
        # Best-effort beta accounting: the critic's spend is real and must be
        # charged, or the headroom gate above would be measuring a lie.
        try:
            usage = getattr(resp, "usage", None)
            cost = float(getattr(usage, "cost", 0.0) or 0.0)
            if cost:
                self.total_cost += cost
        except Exception:
            pass
        v = parse_critic_verdict(text)
        note = v.advisory_note()
        if not note:
            logger.info("plan-critic: reply unparseable; note dropped.")
            return
        logger.info(f"plan-critic [{model}] {v.verdict}: {v.why[:160]}")
        self.messages.append({"role": "user", "content": note})

    def _should_skip_for_budget(self, tool_name: str,
                                 arguments: Optional[dict] = None
                                 ) -> tuple[bool, str]:
        """Pre-flight: should we skip this tool call due to budget pressure?

        Three skip conditions:
          1. deadline already passed (remaining == 0; deadline IS the
             reserve-protected soft deadline, not the real wall)
          2. remaining < MIN_USEFUL_TOOL_SECONDS — too little time for
             any tool call to produce useful work
          3. tool is risky (RISKY_VIVADO_TOOLS or vivado_run_tcl with a
             risky tcl payload) AND its estimated runtime exceeds the
             remaining window
        """
        if self._budget_deadline is None:
            return (False, "")
        remaining = self._budget_remaining()
        if remaining <= 0.0:
            return (True, "deadline_passed")
        if remaining < MIN_USEFUL_TOOL_SECONDS:
            return (True,
                    f"only_{remaining:.0f}s_remain_below_min_useful_"
                    f"{MIN_USEFUL_TOOL_SECONDS:.0f}s")
        if self._is_risky(tool_name, arguments):
            est = self._estimate_tool_runtime(tool_name, is_risky=True)
            # Typed ledger (jul26 panel #1). Records the OPERANDS and, crucially, the
            # PROVENANCE of the estimate: a refusal bounded by HISTORY (measured on this
            # design, this run) is legitimate; one bounded by a CONSTANT or a MODEL is
            # the defect family that cost this project ~+55 points. Default OFF and
            # cannot raise — see optimizer/gate_log.py.
            _gl.emit(
                "budget_skip",
                _gl.VERDICT_REFUSE if est > remaining else _gl.VERDICT_ALLOW,
                design=getattr(self, "_design_label", None),
                run_id=getattr(self, "run_id", None),
                iteration=getattr(self, "iteration", None),
                tool=tool_name,
                predicted_s=est,
                threshold_s=remaining,
                remaining_wall_s=remaining,
                provenance=getattr(self, "_last_estimate_provenance", None),
                best_wns_ns=(self.best_wns if self.best_wns != float("-inf") else None),
                reason_code=("estimated_exceeds_remaining" if est > remaining
                             else "fits"),
                site="dcp_optimizer._should_skip_for_budget",
            )
            if est > remaining:
                return (True,
                        f"estimated_{est:.0f}s_exceeds_remaining_{remaining:.0f}s")
        return (False, "")

    def _polish_reserve_armed_s(self) -> float:
        """C1-T3: active post-route polish reserve in seconds (0.0 = not
        armed).  The reserve arms ONLY when reserving can pay off, so an
        unarmed run behaves byte-identically to today (never-worse):

          1. reserve enabled (_polish_reserve_s > 0; 0 = kill switch),
          2. a wall budget is set (contest mode — dev runs unaffected),
          3. not yet released (release is one-way, see
             _release_polish_reserve),
          4. a routed banked best EXISTS (_best_valid_dcp; the bank only
             ever holds validated routed states) — before the first bank
             there is nothing to polish and speculative work must not be
             blocked ("a trimmed zero is worse than a slow zero"),
          5. the polish machinery is not disabled: the ILS/polish stage
             is enabled AND at least one of its polish sub-stages
             (LASTMILE / fanout) is flag-enabled — the existing
             eligibility flags, reused, not re-derived.  Dynamic
             per-design gates (LASTMILE wns entry gate, fanout cheap-
             design anchor gate) are evaluated at ILS-stage time and
             release the reserve when NEITHER stage can fire
             (_ils_polish_body precheck) so a polish-ineligible design
             class never has speculative work fenced for a polish that
             cannot happen.
        """
        if self._polish_reserve_s <= 0.0:
            return 0.0
        if self._budget_deadline is None:
            return 0.0
        if self._polish_reserve_release_reason is not None:
            return 0.0
        if self._best_valid_dcp is None:
            return 0.0
        cfg = self._ils_polish_cfg
        if not getattr(cfg, "enabled", False):
            return 0.0
        if not (getattr(cfg, "lastmile_polish_enabled", True)
                or getattr(cfg, "fanout_polish_enabled", True)):
            return 0.0
        return self._polish_reserve_s

    def _release_polish_reserve(self, reason: str) -> None:
        """C1-T3: one-way release of the polish reserve.  Called when the
        polish stages have run or been correctly skipped (ILS-stage tail,
        dynamic-ineligibility precheck) and unconditionally at finalize —
        the reserve must never strand wall time.  First reason wins."""
        if self._polish_reserve_release_reason is not None:
            return
        self._polish_reserve_release_reason = reason
        if self._polish_reserve_s > 0.0:
            logger.info(f"polish-reserve: released ({reason}); speculative "
                        f"dispatch sees the full remaining window again.")

    def _maybe_arm_wall_handback(self, reason: str) -> None:
        """D3 (04-01): arm the saturation early-exit reason — guarded.

        Called ONLY from the three sanctioned EXISTING signal sites:
          (a) ILS no-improve stop (run_ils_polish's futility break, detected
              post-hoc via the result notes in _ils_polish_body),
          (b) LASTMILE reject verdict (_lastmile_polish_after_ils),
          (c) _should_skip_for_budget budget-kill (call_tool skip path).
        GUARD (locked): never arm before a banked accept exists
        (_best_valid_dcp) — a trimmed zero is worse than a slow zero.
        First reason wins (the earliest saturation verdict is the one that
        matters for gamma attribution).  Arming is observational when the
        --wall-handback kill switch is OFF: only _wall_handback_break_due()
        acts on it, and that predicate requires _wall_handback_enabled.
        """
        if self._exit_early_reason is not None:
            return
        if self._best_valid_dcp is None:
            logger.debug(f"wall-handback: signal '{reason}' NOT armed "
                         f"(no banked accept yet — never trim before a "
                         f"banked accept).")
            return
        self._exit_early_reason = reason
        logger.info(
            f"wall-handback: saturation signal armed ({reason}); "
            + ("acting at the next loop check (kill switch ON)."
               if self._wall_handback_enabled
               else "observe-only (kill switch OFF).")
        )

    def _wall_economics_window_s(self) -> Optional[float]:
        """Observation window = the CHEAPEST completed heavy move this run.

        A measurement, not a constant: if a full heavy move's worth of wall
        has passed with no gain, the maximum-likelihood forward rate is 0.
        Returns None when no heavy move has completed yet (fail open — the
        rule then cannot fire).
        """
        return min(self._heavy_move_seconds) if self._heavy_move_seconds else None

    def _maybe_arm_wall_economics_stop(self) -> None:
        """Fourth sanctioned wall-handback signal (jul26): DERIVED gamma stop.

        The other three signals (ILS futility, LASTMILE reject, budget-kill)
        are saturation VERDICTS from a sub-mechanism.  This one is arithmetic
        on the contest's own scoring function: continuing is only worth it
        while marginal alpha beats the marginal gamma penalty.  See
        optimizer/wall_economics.py for the derivation — there is no fitted
        threshold anywhere in it.

        Reuses _maybe_arm_wall_handback, so it inherits the locked guards:
        never arm before a banked accept, first-reason-wins, and OBSERVE-ONLY
        while the --wall-handback kill switch is off (the ship path does not
        pass it, so this is zero behavior change by default).  Acting on it
        exits the LLM loop to the SHARED finalize tail, which still runs the
        polish stages once — so stopping LLM iterations never forfeits the
        deterministic tail's gradient.
        """
        if self._exit_early_reason is not None:      # first reason wins
            return
        if self.best_wns == float("-inf") or self.initial_wns is None:
            return
        best_fmax = self.calculate_fmax(self.best_wns, self.clock_period)
        init_fmax = self.calculate_fmax(self.initial_wns, self.clock_period)
        if best_fmax is None or init_fmax is None:
            return
        try:
            from optimizer.wall_economics import should_stop_for_wall
        except Exception:
            return
        # Time since the last banked improvement; by construction the
        # realized gain across that window is zero (banking paths are what
        # update last_improvement_time), so gain_in_window_mhz stays 0.0.
        since = time.time() - (self.last_improvement_time or self.start_time)
        stop, reason = should_stop_for_wall(
            alpha_mhz=best_fmax - init_fmax,
            remaining_s=self._budget_remaining(),
            since_last_gain_s=since,
            observation_window_s=self._wall_economics_window_s(),
        )
        if stop:
            logger.info(f"[wall-economics] {reason}")
            self._maybe_arm_wall_handback(f"wall_economics:{reason[:160]}")

    def _wall_handback_break_due(self) -> bool:
        """D3 (04-01): True iff the LLM iteration loop should exit early to
        the finalize tail and hand the remaining wall back to the wrapper.
        Requires BOTH the --wall-handback kill switch AND an armed
        saturation reason; with the switch OFF (default) this is always
        False — behavior byte-identical to today."""
        return bool(self._wall_handback_enabled and self._exit_early_reason)

    def _deep_wns_tail_reserve_effective_s(self) -> float:
        """Effective deep-WNS tail reserve window in seconds (0.0 = OFF).

        A configured value in (0, 1) is a FRACTION of --max-wall-seconds
        (OFF when no wall cap is set — without a deadline there is no
        boundary to reserve against); >= 1 is absolute seconds.

        V2 WALL CLAMP (jul23 panel Q1b): when max_wall_seconds is known,
        the effective reserve is clamped to TAIL_RESERVE_WALL_CLAMP_FRAC
        x wall (2400/3500 ≈ 0.686 — the wave-2 proven arm on the eval
        wall).  Wave-3 refutation: reserve >= wall truncated the recipe
        BEFORE its big move (ispd16 pre-R1-route-lever, boom_v2 @3600
        pre-route-first → BOTH regressed to baseline).  When max_wall is
        unknown an absolute reserve is left as-is (already inert without
        a deadline)."""
        v = self._deep_wns_tail_reserve_s
        if v <= 0.0:
            return 0.0
        if v < 1.0:
            if self.max_wall_seconds is None:
                return 0.0
            base = v * float(self.max_wall_seconds)
        else:
            base = v
        if self.max_wall_seconds is not None:
            cap = TAIL_RESERVE_WALL_CLAMP_FRAC * float(self.max_wall_seconds)
            if base > cap:
                if not self._tail_reserve_clamp_logged:
                    logger.warning(
                        f"[tail-reserve] WALL CLAMP: requested reserve "
                        f"{base:.0f}s exceeds "
                        f"{TAIL_RESERVE_WALL_CLAMP_FRAC:.3f} x wall "
                        f"({float(self.max_wall_seconds):.0f}s) = "
                        f"{cap:.0f}s — clamping to {cap:.0f}s "
                        f"(wave-3 refutation: reserve >= wall truncates "
                        f"the recipe before its big move; proven arm = "
                        f"2400s on the 3500s eval wall).")
                    self._tail_reserve_clamp_logged = True
                base = cap
        # FPL26_RECIPE_FIRST_DEEP reduced-tail cap (aug04): set ONLY by
        # _recipe_first_deep_apply_reduced_tail after a flag-gated fire
        # that BANKED a candidate; None (the default, and the only value
        # flag-off runs can ever see) leaves every path above byte-
        # identical.  Only ever REDUCES — the min() cannot raise the
        # reserve.
        rfd_cap = self._recipe_first_deep_tail_reserve_cap_s
        if rfd_cap is not None and rfd_cap < base:
            return rfd_cap
        return base

    def _tail_reserve_break_due(self) -> bool:
        """DEEP-WNS TAIL RESERVE V2 (jul22 PLAN item 5 + jul23 panel Q1b
        V2_BOOM_ONLY; DEFAULT OFF): True iff the main LLM iteration loop
        should exit early NOW and hand the remaining wall to the
        deterministic exit tail (_exit_with_ils_polish -> bare-reroute
        loop / tail controller).

        Requires ALL of:
          * reserve armed (effective seconds > 0; default 0 = OFF —
            behavior byte-identical to today).  V2: effective is
            wall-clamped to 0.686 x wall (see
            _deep_wns_tail_reserve_effective_s),
          * a wall deadline set (_budget_deadline; dev/no-cap runs have
            nothing to reserve against),
          * V2 SIZE GATE: the design is ILS-size-gated — measured
            primitive cell count (_input_cell_count, Phase 1) > the LIVE
            ILS max_cells gate (self._ils_polish_cfg.max_cells,
            DEFAULT_MAX_CELLS 300k).  Wave-2 L3-vs-L5: on ILS-path
            (size-viable) designs the normal flow converts tail time at
            least as well (vtr no-reserve control beat the reserve by
            +0.29); the reserve only ever helped the size-gated class
            (boom @2400: +0.020).  Unknown cell count -> NOT armed
            (fail-safe),
          * a measured banked WNS (best_wns finite): with nothing
            measured the deterministic tail has nothing to iterate on —
            its own gates would no-op and the early exit would WASTE the
            window,
          * the design STILL deep-WNS at the boundary: CURRENT best_wns
            <= _tail_ctrl_deep_wns_ns (tail-controller arming threshold,
            default −1.0).  Deliberately the LIVE value, not entry WNS —
            a design that started deep but was recipe-fixed to near-met
            must NOT early-exit (near-met states are owned by ILS/LLM;
            plateau probe: the tail move menu decays to no-op there),
          * remaining wall <= effective reserve (the boundary),
          * V2 STAGNATION GUARD: no best_wns improvement in the last
            _tail_reserve_stagnant_s seconds (default 240; env
            FPL26_TAIL_RESERVE_STAGNANT_S; 0 = guard off).  Wave-3
            failure mode was exiting MID-recipe-improvement; boom's
            healthy wave-2 exits happened while the loop was grinding
            micro-gains.  Banking paths update last_improvement_time;
            no reference clock at all -> NOT stagnant (fail-safe)."""
        reserve = self._deep_wns_tail_reserve_effective_s()
        if reserve <= 0.0:
            return False
        if self._budget_deadline is None:
            return False
        # V2 SIZE GATE (ILS-size-gated class only; unknown -> not armed).
        max_cells = getattr(self._ils_polish_cfg, "max_cells", None)
        if not self._input_cell_count or not max_cells:
            return False
        if self._input_cell_count <= max_cells:
            return False
        if self.best_wns is None or self.best_wns == float("-inf"):
            return False
        if self.best_wns > self._tail_ctrl_deep_wns_ns:
            return False
        if self._budget_remaining() > reserve:
            return False
        # V2 STAGNATION GUARD (only fire on a stagnant loop).
        stagnant_s = self._tail_reserve_stagnant_s
        if stagnant_s > 0.0:
            ref = self.last_improvement_time or getattr(
                self, "start_time", None)
            if ref is None:
                return False  # no clock yet — cannot prove stagnation
            if (time.time() - ref) < stagnant_s:
                return False  # loop improved recently — mid-recipe
        return True

    def _ensure_decision_tracer(self) -> None:
        """Lazy-init the decision tracer once run_dir exists.

        Safe to call any number of times.  Failures are swallowed —
        telemetry must NEVER block the optimizer.
        """
        if self._decision_tracer is not None:
            return
        if _DecisionTracer is None:
            return
        try:
            run_dir = getattr(self, "run_dir", None)
            if not run_dir:
                return
            self._decision_tracer = _DecisionTracer(run_dir)
        except Exception as exc:  # pragma: no cover — defensive
            logger.debug(f"decision_tracer init failed: {exc}")
            self._decision_tracer = None

    def _emit_decision(self, record: dict) -> None:
        """Best-effort decision-record emitter.  Auto-fills design,
        iteration, model from instance state when not provided.
        Never raises.
        """
        self._ensure_decision_tracer()
        if self._decision_tracer is None:
            return
        try:
            record.setdefault("design",
                              getattr(self, "_design_name_for_memory", None))
            record.setdefault("iteration", getattr(self, "iteration", None))
            record.setdefault("model", getattr(self, "model", None))
            record.setdefault(
                "best_valid_token",
                getattr(self, "_best_valid_token", None),
            )
            self._decision_tracer.emit(record)
        except Exception as exc:  # pragma: no cover — defensive
            logger.debug(f"decision_tracer emit failed: {exc}")

    def _classify_tool_payload(self, payload, *, context: str = "call_tool"):
        """Wrap optimizer.tool_errors.classify_tool_error so callers
        can use it without importing the module.  Returns None when
        the module is unavailable or the payload is not an error."""
        if _classify_tool_error is None:
            return None
        try:
            return _classify_tool_error(payload, context=context)
        except Exception as exc:  # pragma: no cover — defensive
            logger.debug(f"classify_tool_error raised: {exc}")
            return None

    def _ensure_path_guard(self, output_dcp: Optional[Path] = None) -> None:
        """Lazy-init the DCP write-path PathGuard.

        Safe to call any number of times; only the first call wires the
        guard.  Roots:
          - self.run_dir (best_valid mirror + intermediates)
          - output_dcp.parent (ship target)
          - submission/dcps (final packaging tree), best-effort
        Mode comes from self._path_guard_mode (default "audit").  All
        failures are swallowed — the guard is defense-in-depth, never
        a critical-path dependency.
        """
        if self._path_guard is not None:
            return
        if _PathGuard is None:
            return
        try:
            roots: list[Path] = []
            run_dir = getattr(self, "run_dir", None)
            if run_dir is not None:
                roots.append(Path(run_dir))
            if output_dcp is not None:
                roots.append(Path(output_dcp).parent)
            # Submission/dcps tree — resolve relative to repo root if
            # discoverable; otherwise skip.  This is the packaged-DCP
            # destination tree; non-existence is fine, allow_root works
            # on un-created paths.
            try:
                script_dir = Path(__file__).resolve().parent
                subm = script_dir / "submission" / "dcps"
                roots.append(subm)
            except Exception:
                pass
            mode = self._path_guard_mode if self._path_guard_mode in (
                "audit", "enforce"
            ) else "audit"
            self._path_guard = _PathGuard(roots, mode=mode)
        except Exception as exc:  # pragma: no cover — defensive
            logger.debug(f"path_guard init failed: {exc}")
            self._path_guard = None

    def _path_guard_check(self, path, *, context: str = "") -> bool:
        """Run PathGuard.check() and emit a decision trace event.

        Returns True when the path is under an allowed root (or when
        the guard isn't initialised — defaults to permissive so the
        guard never blocks production code).  In audit mode an
        out-of-root path returns False and is recorded in
        self._path_guard_violations.  Never raises in audit mode.

        Emits a decision-trace event with the audit outcome regardless
        of mode so we have full visibility into every DCP write target
        in the production run.
        """
        # If the guard isn't ready, treat as permissive but trace.
        guard = self._path_guard
        allowed = True
        try:
            if guard is not None:
                allowed = bool(guard.check(path, context=context))
                if not allowed:
                    # Record violation locally so summary printers can
                    # report aggregate audit findings without grepping
                    # decisions.jsonl.
                    self._path_guard_violations.append({
                        "path": str(path),
                        "context": context,
                        "ts": time.time(),
                    })
        except Exception as exc:  # pragma: no cover — defensive
            # PathGuardError in enforce mode bubbles up; everything else
            # is swallowed.  We re-raise only when the configured mode
            # is "enforce" so we don't silently swallow blocked writes.
            if guard is not None and getattr(guard, "mode", "audit") == "enforce":
                raise
            logger.debug(f"path_guard.check raised: {exc}")
        # Emit a trace event regardless of mode.  Decision tracer is
        # best-effort, so this never blocks the caller.
        try:
            self._emit_decision({
                "decision_source": "executor",
                "phase": "path_guard",
                "action_label": "path_guard_check",
                "tool_name": None,
                "notes": context,
                "output_dcp_path": str(path),
                "path_guard_allowed": allowed,
                "path_guard_mode": (
                    getattr(guard, "mode", None) if guard is not None
                    else None
                ),
            })
        except Exception as exc:  # pragma: no cover — defensive
            logger.debug(f"path_guard trace emit failed: {exc}")
        return allowed

    def _record_ship_lineage(
        self,
        *,
        dcp_path: Path,
        edif_ok: bool,
        inherit_best_valid: bool = False,
        fallback_source: Optional[str] = None,
        baseline: bool = False,
        no_improvement: bool = False,
        hard_fail: bool = False,
        branch: str = "",
    ) -> dict:
        """Tag self._ship_lineage with the lineage of the final shipped DCP.

        Exactly one of the following must be passed truthy:
          - inherit_best_valid (fast path / stale-mirror) — copies current
            best-valid lineage and bumps role to "ship"
          - baseline — explicit baseline fallback after a failed optimized
            ship
          - no_improvement — baseline ship when best_wns ≤ initial_wns
          - hard_fail — neither baseline nor mirror is usable
          - fallback_source given explicitly (used for stale_mirror_file or
            external_write_validated)

        Returns the recorded entry.
        """
        size = None
        try:
            p = Path(dcp_path)
            if p.exists():
                size = p.stat().st_size
        except Exception:
            pass
        if hard_fail:
            entry = _make_lineage_entry(
                "hard_fail_no_ship",
                token=None,
                dcp_path=str(dcp_path),
                dcp_size=size,
                extra={"branch": branch, "edif_ok": edif_ok},
            )
        elif no_improvement:
            entry = _make_lineage_entry(
                "no_improvement_baseline",
                token=None,
                wns=self.initial_wns,
                fmax=self.calculate_fmax(self.initial_wns, self.clock_period)
                if self.initial_wns is not None and self.clock_period else None,
                dcp_path=str(dcp_path),
                dcp_size=size,
                extra={"branch": branch, "edif_ok": edif_ok},
            )
        elif baseline:
            entry = _make_lineage_entry(
                "baseline",
                token=None,
                wns=self.initial_wns,
                fmax=self.calculate_fmax(self.initial_wns, self.clock_period)
                if self.initial_wns is not None and self.clock_period else None,
                dcp_path=str(dcp_path),
                dcp_size=size,
                extra={"branch": branch, "edif_ok": edif_ok},
            )
        elif inherit_best_valid and self._best_valid_lineage is not None:
            # Copy the current best-valid lineage, override path/size to
            # reflect the SHIPPED file (not the mirror file), preserve
            # the original token so downstream audits can trace.
            bv = dict(self._best_valid_lineage)
            entry = _make_lineage_entry(
                bv.get("source", "eager_mirror"),
                token=bv.get("token"),
                wns=bv.get("wns"),
                fmax=bv.get("fmax"),
                iteration=bv.get("iteration"),
                tool_name=bv.get("tool_name"),
                dcp_path=str(dcp_path),
                dcp_size=size,
                extra={
                    "branch": branch,
                    "edif_ok": edif_ok,
                    "best_valid_token": bv.get("token"),
                    "best_valid_source": bv.get("source"),
                },
            )
        else:
            # Either inherit_best_valid was requested but no lineage exists,
            # OR caller passed fallback_source explicitly.
            src = fallback_source or "external_write_validated"
            entry = _make_lineage_entry(
                src,
                token=None,
                wns=self.best_wns if self.best_wns != float("-inf") else None,
                fmax=self.calculate_fmax(self.best_wns, self.clock_period)
                if self.best_wns is not None and self.best_wns != float("-inf")
                and self.clock_period else None,
                dcp_path=str(dcp_path),
                dcp_size=size,
                extra={
                    "branch": branch,
                    "edif_ok": edif_ok,
                    "reason": "no best_valid lineage available at finalize",
                },
            )
        self._ship_lineage = entry
        try:
            self.lifecycle_log.append({
                "event": "ship_lineage_recorded",
                **{k: v for k, v in entry.items() if k != "extra"},
            })
        except Exception:
            pass
        return entry

    def _bump_lineage(
        self,
        source: str,
        *,
        wns: Optional[float] = None,
        fmax: Optional[float] = None,
        tool_name: Optional[str] = None,
        dcp_path: Optional[Path] = None,
        extra: Optional[dict] = None,
    ) -> dict:
        """Increment the monotonic best-valid token and record a lineage
        entry.  Returns the entry for the caller to log if needed.

        Side effects:
          - self._best_valid_token += 1
          - self._best_valid_lineage = <new entry>
          - lifecycle_log gets a "best_valid_lineage_update" event
        """
        self._best_valid_token += 1
        size = None
        path_str = None
        if dcp_path is not None:
            try:
                p = Path(dcp_path)
                path_str = str(p)
                if p.exists():
                    size = p.stat().st_size
            except Exception:
                pass
        if fmax is None and wns is not None and self.clock_period:
            fmax = self.calculate_fmax(wns, self.clock_period)
        entry = _make_lineage_entry(
            source,
            token=self._best_valid_token,
            wns=wns,
            fmax=fmax,
            iteration=getattr(self, "iteration", None),
            tool_name=tool_name,
            dcp_path=path_str,
            dcp_size=size,
            extra=extra,
        )
        self._best_valid_lineage = entry
        try:
            self.lifecycle_log.append({
                "event": "best_valid_lineage_update",
                **{k: v for k, v in entry.items() if k != "extra"},
            })
        except Exception:
            pass
        # P1 (2026-05-20 s2): emit a decision-trace event whenever the
        # best-valid lineage bumps.  Covers eager_mirror / piggyback /
        # backstop / explicit caller-supplied sources in one place
        # (instead of three separate emits at the call sites).
        try:
            self._emit_decision({
                "decision_source": "executor",
                "phase": "best_valid_update",
                "tool_name": tool_name,
                "action_label": f"best_valid_{source}",
                "wns_after": wns,
                "fmax_after": fmax,
                "best_valid_checkpoint_path": path_str,
                "ship_lineage_source": source,
                "notes": f"token={self._best_valid_token} extra={extra}",
            })
        except Exception as exc:  # pragma: no cover — defensive
            logger.debug(f"best_valid trace emit failed: {exc}")
        return entry

    def _piggyback_mirror_checkpoint(self, arguments: dict) -> None:
        """Fast best_valid mirror via shutil.copy of the LLM's checkpoint.

        Called from call_tool() after a successful vivado_write_checkpoint
        when _pending_best_mirror is set (i.e., WNS just improved since
        the last mirror).  Mirroring the file the LLM just wrote captures
        the improved Vivado state without an extra round-trip.

        On success: sets self._best_valid_dcp, clears _pending_best_mirror.
        On failure: leaves both intact — the iter-top fallback path then
        runs a full vivado_write_checkpoint mirror.

        Special case: when the LLM (or our iter-top mirror) wrote directly
        TO best_valid.dcp, src == dst.  Don't copy; just record the path
        and clear the flag — the file is already in the right place.
        """
        try:
            # jul20 review S2: if any design-mutating op ran between the
            # best-WNS measurement and this write, the checkpoint does NOT
            # represent best_wns — stamping it would let a regressed state
            # ship via the finalize fast path.  Skip AND disarm: every
            # later write in this window is post-mutation too; a real new
            # best re-arms the flag at its own measurement.
            if self._mutation_epoch != self._pending_best_mirror_epoch:
                logger.warning(
                    "[piggyback] design mutated since best-WNS measurement "
                    f"(epoch {self._pending_best_mirror_epoch} -> "
                    f"{self._mutation_epoch}) — skipping best_valid stamp")
                self._pending_best_mirror = False
                return
            target = arguments.get("dcp_path")
            if not target:
                return
            src = Path(target).resolve()
            if not src.exists() or src.stat().st_size == 0:
                return
            dst = (self.run_dir / "best_valid.dcp").resolve()
            # P3 (2026-05-20 s2): audit dst path before writing.
            self._path_guard_check(dst, context="piggyback_mirror_checkpoint")
            if src == dst:
                self._best_valid_dcp = dst
                # Piggyback fires only when _pending_best_mirror was True,
                # which means self.best_wns was just bumped.  The on-disk
                # file represents that exact best_wns.  Closes Finding F2
                # from output_write_path_audit.md.
                self._best_valid_dcp_wns = self.best_wns
                # C1-T5: bank-time size = mirror integrity reference.
                try:
                    self._best_valid_mirror_size = dst.stat().st_size
                except OSError:
                    pass
                self._pending_best_mirror = False
                self._bump_lineage(
                    "piggyback",
                    wns=self.best_wns,
                    tool_name="vivado_write_checkpoint",
                    dcp_path=dst,
                    extra={"src_eq_dst": True},
                )
                return
            _atomic_copy(str(src), str(dst))
            self._best_valid_dcp = dst
            # See above — piggyback success implies the LLM-written
            # checkpoint we copied represents the current best_wns.
            self._best_valid_dcp_wns = self.best_wns
            # C1-T5: bank-time size = mirror integrity reference.
            try:
                self._best_valid_mirror_size = dst.stat().st_size
            except OSError:
                pass
            self._pending_best_mirror = False
            self._bump_lineage(
                "piggyback",
                wns=self.best_wns,
                tool_name="vivado_write_checkpoint",
                dcp_path=dst,
                extra={"src": str(src)},
            )
            logger.info(
                f"Piggyback best_valid mirror (wns={self.best_wns:.3f} ns, "
                f"token={self._best_valid_token}): "
                f"{src.name} → {dst.name} ({dst.stat().st_size//1024} KiB)"
            )
        except Exception as e:
            logger.warning(f"Piggyback DCP mirror failed: {e}")

    def _piggyback_mirror_edif(self, arguments: dict) -> None:
        """Fast best_valid.edf mirror via shutil.copy of the LLM's EDIF.

        Called from call_tool() after a successful vivado_write_edif when
        we already have a best_valid.dcp on disk.  Keeps the EDIF mirror
        co-current with the DCP mirror so RapidWright-based validators
        have everything they need.

        Same src==dst handling as the DCP piggyback above.
        """
        try:
            target = arguments.get("edif_path")
            if not target:
                return
            src = Path(target).resolve()
            if not src.exists() or src.stat().st_size == 0:
                return
            dst = (self.run_dir / "best_valid.edf").resolve()
            # P3 (2026-05-20 s2): audit dst path before writing.
            self._path_guard_check(dst, context="piggyback_mirror_edif")
            if src == dst:
                self._best_valid_edif = dst
                self._best_valid_edif_wns = self.best_wns
                return
            _atomic_copy(str(src), str(dst))
            self._best_valid_edif = dst
            # EDIF freshness marker mirrors the DCP one — same rationale.
            self._best_valid_edif_wns = self.best_wns
            logger.info(f"Piggyback best_valid EDIF mirror: {src.name} → {dst.name}")
        except Exception as e:
            logger.warning(f"Piggyback EDIF mirror failed: {e}")

    async def _routed_ok_for_best(self) -> bool:
        """PHANTOM-BEST GUARD (jul05, preview #10 v2 score-0 incident): a WNS
        measured on an UNROUTED design is Vivado's ESTIMATE, and it can beat
        every real routed result (v2: estimated -0.824 right after
        place_design vs real routed -0.84-class). If such a measurement is
        accepted as best, the eager mirror publishes an unrouted checkpoint,
        never-worse then protects the phantom, and the harness scores 0
        ("vivado_measurement_failed", 3488/3488 nets unrouted).

        Returns True only when the CURRENT in-memory design is fully routed
        (no unrouted nets, no routing errors). 2025.1 quirk handled: a fully
        routed report omits the "# of unrouted nets" line entirely. Fails
        CLOSED on measurement failure (jul20 whole-file review S1): a
        new-best REJECTED on a probe hiccup recurs at the next
        measurement, but a phantom ACCEPTED is protected forever by
        never-worse and scores 0 (the jul05 preview #10 v2 incident this
        guard exists for) — the old fail-open re-opened that exact hole
        in the tail-of-wall regime where the probe times out."""
        # jul23 wave-4 Q1/Q4 forensics (anomaly_q1_q4_wave4.md): an
        # UNPLACED design (raw `place_design -unplace`) reports NEITHER
        # regex line below — the probe returned True and the auto-bank
        # hook banked/shipped an unplaced DCP (phantom near-MET wns
        # -0.003 logicnets / -0.171 spam; mirror size halved; reproduced
        # deterministically in every restart; would score 0 on eval).
        # The harness's own routed-state tracker flipped to False
        # correctly in BOTH legs — consult it FIRST (authoritative,
        # zero-cost; tracking runs unconditionally, only the
        # unroute-gate REFUSAL is flag-gated).
        if not getattr(self, "_design_routed_state", True):
            logger.warning(
                "phantom-best guard: in-process routed-state tracker says "
                "NOT ROUTED — REJECTING best-accept (unplaced/unrouted "
                "phantom, jul23 wave-4 Q1/Q4).")
            return False
        try:
            res = await self.call_tool(
                "vivado_run_tcl",
                {"command": "report_route_status -return_string",
                 "timeout": 600.0})
            txt = str(res or "")
            if _looks_like_tool_error(txt):
                logger.warning("phantom-best guard: route-status probe "
                               "unavailable — REJECTING best-accept "
                               f"(fail closed): {txt[:120]}")
                return False
            m_err = re.search(r"# of nets with routing errors.*?:\s+(-?\d+)", txt)
            if m_err and int(m_err.group(1)) != 0:
                return False
            m_unr = re.search(r"# of unrouted nets.*?:\s+(-?\d+)", txt)
            if m_unr and int(m_unr.group(1)) != 0:
                return False
            return True
        except Exception as e:
            logger.warning("phantom-best guard: route-status probe raised "
                           f"{type(e).__name__} — REJECTING best-accept "
                           "(fail closed)")
            return False

    async def _mirror_best_valid_now(self, eager: bool = False) -> None:
        """Write a stable best_valid.{dcp,edf} pair to the run directory.

        Called from:
          (a) inline at the moment of WNS improvement detection
              (`eager=True`) — captures Vivado's in-memory state while
              that state is PROVABLY the best (we just measured it).
              This is the load-bearing path for shipping gain.
          (b) iteration loop top (`eager=False`) as a backstop, in case
              the eager path was skipped (e.g., session not ready yet).

        Eager mode (POST-2026-05-19 fix for the upstream mirror bug):
          - bypasses the budget-floor check
          - runs even when budget is tight — capturing an improvement
            is always worth ~30-90s of Vivado time
          - the alternative is shipping baseline at finalize (the
            2026-05-19 incident pattern)

        Backstop mode (legacy):
          - applies the budget-floor check (skip if budget too tight)

        No-op when:
          - no improvement is pending (the flag is the only trigger)
          - the write/edif tool calls themselves fail
        """
        if not self._pending_best_mirror:
            return
        # In backstop (non-eager) mode, refuse the mirror if remaining
        # budget is below reserve + mirror cost. In eager mode, we ALWAYS
        # try to capture an improvement — it's always worth the time.
        mirror_budget_floor = self._finalize_reserve_seconds + 120.0
        budget_remaining = (
            self._budget_remaining() if self._budget_deadline is not None else None
        )
        prior_mirror_wns = getattr(self, "_best_valid_dcp_wns", None)
        current_best_wns = float(self.best_wns) if self.best_wns is not None else None
        improvement_delta = (
            (current_best_wns - prior_mirror_wns)
            if (current_best_wns is not None and prior_mirror_wns is not None)
            else None
        )
        iteration_for_log = getattr(self, "iteration", None)
        budget_bypassed = False
        # Entry log — proves the eager path fired, and snapshots the state
        # so post-mortem debugging can show exactly when on-disk capture
        # happened relative to the WNS-improvement measurement.
        logger.info(
            "[mirror] enter: eager=%s iter=%s best_wns=%s prior_mirror_wns=%s "
            "delta=%s budget_remaining=%s floor=%.0f",
            eager,
            iteration_for_log,
            f"{current_best_wns:.3f}" if current_best_wns is not None else "None",
            f"{prior_mirror_wns:.3f}" if prior_mirror_wns is not None else "None",
            f"{improvement_delta:+.3f}" if improvement_delta is not None else "None",
            f"{budget_remaining:.0f}" if budget_remaining is not None else "None",
            mirror_budget_floor,
        )
        if (not eager
                and self._budget_deadline is not None
                and self._budget_remaining() < mirror_budget_floor):
            logger.info(
                "[mirror] skip: backstop budget-tight — remaining "
                f"{self._budget_remaining():.0f}s < {mirror_budget_floor:.0f}s "
                "floor; keeping pending_best_mirror=True. Eager mirror should "
                "have captured this already; if not, finalize will fall back "
                "to baseline (safe)."
            )
            return
        if eager and budget_remaining is not None and budget_remaining < mirror_budget_floor:
            budget_bypassed = True
            logger.info(
                "[mirror] eager-bypass: budget_remaining=%.0fs < floor=%.0fs, "
                "writing anyway to capture measured improvement.",
                budget_remaining, mirror_budget_floor,
            )
        dcp_target = self.run_dir / "best_valid.dcp"
        edf_target = self.run_dir / "best_valid.edf"
        # P3 (2026-05-20 s2): audit both write targets before dispatch.
        self._path_guard_check(
            dcp_target.resolve(),
            context=f"mirror_best_valid_now_dcp_{'eager' if eager else 'backstop'}",
        )
        self._path_guard_check(
            edf_target.resolve(),
            context=f"mirror_best_valid_now_edif_{'eager' if eager else 'backstop'}",
        )
        # Snapshot mtime+size BEFORE the write so we can detect whether the
        # call actually rewrote the file (the dispatcher may refuse the call
        # via tool_skipped_budget and leave a stale baseline file on disk —
        # the previous code mistook "file exists" for "file is fresh", which
        # was the root cause of the 2026-05-16 ispd16 artifact mismatch).
        pre_dcp_mtime = dcp_target.stat().st_mtime if dcp_target.exists() else 0.0
        pre_dcp_size = dcp_target.stat().st_size if dcp_target.exists() else 0
        pre_edf_mtime = edf_target.stat().st_mtime if edf_target.exists() else 0.0
        pre_edf_size = edf_target.stat().st_size if edf_target.exists() else 0

        snapshot_wns = float(self.best_wns) if self.best_wns is not None else None

        # ---- DCP write attempt ----
        dcp_fresh = False
        try:
            dcp_result = await self.call_tool("vivado_write_checkpoint", {
                "dcp_path": str(dcp_target.resolve()),
                "force": True,
            })
            if _looks_like_tool_error(dcp_result):
                logger.warning(
                    f"best_valid DCP mirror skipped by dispatcher: "
                    f"{str(dcp_result)[:200]}"
                )
            elif dcp_target.exists() and dcp_target.stat().st_size > 0:
                # mtime advancement is the canonical "the write landed" signal.
                # On WSL2/NTFS some writes back-date to the original mtime if
                # nothing changed; tolerate that by also accepting a size change.
                post_dcp_mtime = dcp_target.stat().st_mtime
                post_dcp_size = dcp_target.stat().st_size
                if (post_dcp_mtime > pre_dcp_mtime
                        or post_dcp_size != pre_dcp_size):
                    dcp_fresh = True
                else:
                    logger.warning(
                        f"best_valid DCP mirror: file unchanged after "
                        f"write_checkpoint (mtime/size identical to pre-call); "
                        f"treating as stale to be safe."
                    )
            else:
                logger.warning(
                    f"best_valid DCP mirror returned but file missing/empty: {dcp_target}"
                )
        except Exception as e:
            logger.warning(f"best_valid DCP mirror raised: {e}")

        if dcp_fresh:
            self._best_valid_dcp = dcp_target
            self._best_valid_dcp_wns = snapshot_wns
            # C1-T5: bank-time size = mirror integrity reference (the
            # bank_mirror-truncation fault variant zeroes this file; a
            # size mismatch at emergency time means the mirror is NOT
            # the state we banked and must not be shipped).
            try:
                self._best_valid_mirror_size = dcp_target.stat().st_size
            except OSError:
                pass
            self._bump_lineage(
                "eager_mirror" if eager else "backstop",
                wns=snapshot_wns,
                tool_name="vivado_write_checkpoint",
                dcp_path=dcp_target,
                extra={"budget_bypassed": budget_bypassed},
            )
            logger.info(
                f"Mirrored best_valid DCP (wns={snapshot_wns:.3f} ns, "
                f"token={self._best_valid_token}) → "
                f"{dcp_target.name} ({dcp_target.stat().st_size//1024} KiB)"
            )
        else:
            # The on-disk best_valid.dcp does NOT reflect the current best_wns
            # — clear the tracked-WNS so finalize knows the fast path is unsafe.
            self._best_valid_dcp_wns = None

        # ---- EDIF write attempt (only worth trying if DCP is fresh) ----
        edif_fresh = False
        if dcp_fresh:
            try:
                edif_result = await self.call_tool("vivado_write_edif", {
                    "edif_path": str(edf_target.resolve()),
                    "force": True,
                })
                if _looks_like_tool_error(edif_result):
                    logger.warning(
                        f"best_valid EDIF mirror skipped by dispatcher: "
                        f"{str(edif_result)[:200]}"
                    )
                elif edf_target.exists() and edf_target.stat().st_size > 0:
                    post_edf_mtime = edf_target.stat().st_mtime
                    post_edf_size = edf_target.stat().st_size
                    if (post_edf_mtime > pre_edf_mtime
                            or post_edf_size != pre_edf_size):
                        edif_fresh = True
                    else:
                        logger.warning(
                            "best_valid EDIF mirror: file unchanged after "
                            "write_edif; treating as stale."
                        )
                else:
                    logger.warning(f"best_valid EDIF write returned but file missing: {edf_target}")
            except Exception as e:
                logger.warning(f"best_valid EDIF write raised: {e}")

        if edif_fresh:
            self._best_valid_edif = edf_target
            self._best_valid_edif_wns = snapshot_wns
            logger.info(f"Mirrored best_valid EDIF → {edf_target.name}")
        else:
            # EDIF is stale relative to current best_wns.  Finalize will
            # know to refresh it from the optimized DCP rather than ship
            # whatever the previous mirror left on disk (which may be the
            # baseline EDIF for a netlist-changing transform like retiming).
            self._best_valid_edif_wns = None

        # Only clear the pending flag when the DCP refresh actually landed.
        # If the dispatcher refused us, leave the flag armed so the next
        # iteration with more budget retries the mirror.  This trades a
        # small extra mirror attempt for correctness when budget is tight.
        if dcp_fresh:
            self._pending_best_mirror = False

        # Exit log — pairs with the entry log so post-mortems can see the
        # full eager-mirror lifecycle: snapshot vs. outcome.
        dcp_exists_post = dcp_target.exists()
        dcp_size_post = dcp_target.stat().st_size if dcp_exists_post else 0
        logger.info(
            "[mirror] exit:  eager=%s iter=%s dcp_fresh=%s edif_fresh=%s "
            "dcp_exists=%s dcp_size=%d wns_snapshot=%s budget_bypassed=%s "
            "pending_after=%s",
            eager,
            iteration_for_log,
            dcp_fresh,
            edif_fresh,
            dcp_exists_post,
            dcp_size_post,
            f"{snapshot_wns:.3f}" if snapshot_wns is not None else "None",
            budget_bypassed,
            self._pending_best_mirror,
        )

    async def _run_ils_polish_stage(self) -> None:
        """ILS ruin-and-recreate, keep-best (never-worse).

        Runs the global re-place in a FRESHLY-RESTARTED Vivado seeded from the RAW
        input DCP. PROVEN on vexriscv_re-place_v2 (A/B/C controlled test 2026-06-07,
        ils_runs_20260605/RESULTS.md): the recipe phase leaves persistent state in
        the Vivado PROCESS that degrades every subsequent place_design (worse WNS
        AND ~2x slower) and open_checkpoint does NOT clear it. In the recipe-polluted
        session ILS stalls at -0.942; after a fresh `restart_vivado` it reaches -0.84
        (+17 MHz) — identical to a clean standalone run. keep-best vs the recipe-best
        => never-worse even if the from-scratch re-place underperforms the recipe."""
        from optimizer.ils_polish import run_ils_polish
        # Enter ILS stage NOW (before the restart): call_tool bypasses the budget-
        # skip gate only while this flag is set. If we restart AFTER setting it the
        # restart_vivado call gets budget-skipped near end-of-run and silently no-ops
        # (observed 2026-06-07: agent logged "restarted" but the MCP server never
        # re-launched Vivado, so ILS ran in the still-polluted session at -0.942).
        self._in_ils_stage = True
        try:
            await self._ils_polish_body(run_ils_polish)
        finally:
            self._in_ils_stage = False

    async def _ils_polish_body(self, run_ils_polish) -> None:
        # Recipe-best artifact: the bar to beat AND the never-worse fallback.
        # Snapshot it to disk BEFORE restarting Vivado (the restart wipes the live
        # design); the DCP carries the design, not the polluted session state.
        recipe_best = self._best_valid_dcp
        if recipe_best is None or not Path(recipe_best).exists():
            recipe_best = (self.run_dir or Path(".")) / "ils_recipe_best.dcp"
            await self.call_tool("vivado_run_tcl",
                                 {"command": f"write_checkpoint -force {{{recipe_best}}}"})
        recipe_best = str(recipe_best)
        # FRESH Vivado: clear the recipe session pollution before the re-place.
        # NOTE: the MCP tool is "restart_vivado" but call_tool routes Vivado tools
        # by the "vivado_" prefix (else -> "Unknown tool prefix" error envelope, a
        # silent no-op). Must call "vivado_restart_vivado" AND check the returned
        # envelope — call_tool returns an error STRING (not an exception) on failure.
        # Cold-start cycle-cost anchor (jun12 corundum drill: ILS burned its
        # whole window on a full-ruin cycle that could not complete). Derive
        # one Explore-cycle's expected wall from the recipe phase's observed
        # heavy-tool durations on THIS design/box; the combo picker scales
        # per-combo priors from it and falls through to affordable combos
        # (partial-ruin 0.7x) when full ruin does not fit the window.
        # PRISTINE baseline for the jul28 retry baseline gate. run_ils_polish is
        # handed the RECIPE-BEST as its baseline_wns, so the ILS cannot otherwise
        # distinguish "worse than the untouched input" from "behind an already
        # polished incumbent" — the distinction that separates spam/3d/optical from
        # vexriscv/mini-ISP/finn. self.initial_wns is kept pristine for improvement
        # accounting, so it is the right source.
        try:
            if self.initial_wns is not None:
                self._ils_polish_cfg.design_baseline_wns = float(self.initial_wns)
        except Exception as e:                                    # pragma: no cover
            logger.warning(f"ILS: could not publish design baseline wns "
                           f"({type(e).__name__}: {e}); retry baseline gate inert")
        # FPL26_MINIISP_RETRY_HOLD (aug05, DEFAULT OFF): band-scoped arming
        # of the retry baseline gate — MID band only (1.05 < |wns_in| <
        # 8.0), the GLOBAL env flag untouched.  Evidence + scope rationale
        # at the FPL26_MINIISP_RETRY_HOLD constants comment (mini-ISP h2
        # +106.10 vs h1 +102.71; the jul29 global-HOLD harm was shallow).
        # Same feature key as the recipe pass (recipe_pass_band on the
        # PRISTINE initial_wns); unmeasured wns -> no band -> not armed
        # (treatments fail OFF).  The skip line makes reached-but-
        # disabled/out-of-band distinguishable from never-called.
        try:
            if miniisp_retry_hold_enabled():
                _mrh_band = recipe_pass_band(self.initial_wns)
                if (_mrh_band == "mid"
                        and abs(self.initial_wns)
                        < MINIISP_RETRY_HOLD_WNS_MAG_MIN_NS):
                    # aug05 re-scope (pre-registered fallback): optical-class
                    # [1.05, 1.20) reverts to exact v3.3 behavior.
                    logger.info(
                        f"MINIISP-RETRY-HOLD: skipped reason=subband_floor "
                        f"wns_in={self.initial_wns} (|wns| < "
                        f"{MINIISP_RETRY_HOLD_WNS_MAG_MIN_NS}; parity-measured "
                        f"optical harm; treatments fail OFF)")
                elif (_mrh_band == "mid"
                        and self._ils_polish_cfg.design_baseline_wns
                        is not None):
                    self._ils_polish_cfg.retry_baseline_gate_scoped = True
                    logger.info(
                        f"MINIISP-RETRY-HOLD: ARMED band=mid "
                        f"wns_in={self.initial_wns} (retry baseline gate "
                        f"scoped in; global FPL26_ILS_RETRY_BASELINE_GATE "
                        f"untouched)")
                else:
                    logger.info(
                        f"MINIISP-RETRY-HOLD: skipped reason=band "
                        f"band={_mrh_band} wns_in={self.initial_wns} "
                        f"(mid-band-only scope; treatments fail OFF)")
            else:
                if v40_flag_env_present("FPL26_MINIISP_RETRY_HOLD",
                                        "FPL26_NO_MINIISP_RETRY_HOLD"):
                    logger.info("MINIISP-RETRY-HOLD: skipped reason=disabled "
                                "(FPL26_MINIISP_RETRY_HOLD off or "
                                "FPL26_NO_MINIISP_RETRY_HOLD set)")
        except Exception as e:                                    # pragma: no cover
            logger.warning(f"MINIISP-RETRY-HOLD: skipped reason=exception "
                           f"{type(e).__name__}: {e!r} (non-fatal; gate "
                           f"stays unscoped)")
        try:
            from optimizer.ils_polish import derive_cost_anchors
            _est, _fan, _maxes = derive_cost_anchors(self.tool_call_details)
            if _est > 0:
                self._ils_polish_cfg.expected_heavy_cycle_s = _est + 60.0
                logger.info(
                    f"ILS cold-start anchor: expected_heavy_cycle_s="
                    f"{self._ils_polish_cfg.expected_heavy_cycle_s:.0f} "
                    f"(singles={_maxes})")
            if _fan > 0:
                # Dedicated fanout-polish anchor (jul04 genericity audit):
                # no-place recipe paths (R7 phys_opt ladder, R1 route lever)
                # leave _est at 0, so the polish's cheap-design gate had no
                # cost sample on exactly the OOD designs it should serve.
                self._ils_polish_cfg.fanout_cost_anchor_s = _fan + 60.0
                self._ils_polish_cfg.fanout_anchor_has_route = (
                    "route_design" in _maxes)
                logger.info(
                    f"ILS cold-start anchor: fanout_cost_anchor_s="
                    f"{self._ils_polish_cfg.fanout_cost_anchor_s:.0f} "
                    f"has_route={self._ils_polish_cfg.fanout_anchor_has_route} "
                    f"(singles={_maxes})")
            _route_single = _maxes.get("route_design", 0.0)
            if _route_single > 0:
                # Dedicated route-reroll anchor (jul21): the __ROUTE_REROLL__
                # combo's affordability basis is THIS design's observed
                # route_design single-stage wall x1.3 (see
                # optimizer.ils_polish.route_reroll_cost_basis). Same +60s
                # margin convention as the anchors above.
                self._ils_polish_cfg.route_cost_anchor_s = _route_single + 60.0
                logger.info(
                    f"ILS cold-start anchor: route_cost_anchor_s="
                    f"{self._ils_polish_cfg.route_cost_anchor_s:.0f} "
                    f"(route-reroll basis; singles={_maxes})")
        except Exception as e:
            logger.warning(f"ILS cold-start anchor derivation failed ({e!r}); "
                           "legacy optimistic cold-start.")
        if self._ils_polish_cfg.restart_vivado_before_ils:
            try:
                _r = await self.call_tool("vivado_restart_vivado", {})
                if isinstance(_r, str) and '"error"' in _r:
                    logger.warning(f"ILS: restart_vivado returned error "
                                   f"({_r[:140]}); staying in current session.")
                else:
                    logger.info("ILS: restarted Vivado fresh (clears recipe session "
                                "pollution that degrades + slows place_design).")
            except Exception as e:
                logger.warning(f"ILS: restart_vivado failed ({e!r}); current session.")
        # ---- Dual-seed ruin-and-recreate (full-13 2026-06-08 STABLE fix) ----
        # recipe_gain~0 cannot tell v2 (raw-seed wins, recipe stuck) from
        # spam/3d/optical (recipe-best-seed wins, recipe already near ceiling) —
        # both read gain~0. The single-gate version mis-routed the latter to raw
        # and gave back their ILS gains. Fix: ONLY for the gate's STUCK verdict
        # (-> raw) run BOTH seeds — raw FIRST (priority budget; preserves the v2
        # capture) with a no-improve early-stop so a mis-classified raw yields the
        # rest to the recipe-best corrective probe SECOND. Non-stuck designs are
        # unchanged (recipe-best only). keep-best => never-worse and strictly >=
        # the single-seed gate on every design.
        from optimizer.ils_polish import choose_ils_seed, stuck_gain_threshold
        _seed_kind, _gain = choose_ils_seed(
            initial_wns=self.initial_wns, recipe_wns=self.best_wns,
            cfg=self._ils_polish_cfg)
        _g = None if _gain is None else round(_gain, 3)
        _cfg = self._ils_polish_cfg
        # Raw seed copy (only needed for the STUCK path). recipe_best stays pristine.
        raw_seed = None
        if (_seed_kind == "raw" and self.input_dcp_path
                and self.input_dcp_path.exists()):
            try:
                _rs = (self.run_dir or Path(".")) / "ils_ruin_seed.dcp"
                shutil.copy(str(self.input_dcp_path), str(_rs))
                raw_seed = str(_rs)
            except Exception as e:
                logger.warning(f"ILS raw-seed copy failed ({e!r}); recipe-best only.")
                raw_seed = None
        # recipe-best working copy. ALWAYS a copy -- see below.
        #
        # C1-T5 / jul30: the comment here used to read "mutated by its ILS run;
        # recipe_best is the floor", and on the DUAL-SEED path that was true. On
        # the SINGLE-SEED path (the common one) it was not: `recipe_best` is
        # `self._best_valid_dcp` itself (see the top of this method), so the ILS's
        # accept path -- `write_checkpoint -force {best_dcp_path}` -- rewrote the
        # BANKED MIRROR in place. `self._best_valid_mirror_size` is only re-stamped
        # after the whole ILS stage (see the `global_improved` block below), so
        # from the first accept until the stage ends the on-disk size no longer
        # matched the banked size, and the emergency SIGTERM path
        #   [LIFECYCLE] SHIP INTEGRITY FAIL: best_valid mirror size N != banked M
        # distrusted the mirror and fell through to the BASELINE copy -- alpha 0
        # on that design, with the ILS's gain sitting on disk unused.
        #
        # The window is ~20-40 min on a 3500s wall, and it is CORRELATED with the
        # thing that makes a hard kill likely: an ILS that overruns its fenced
        # deadline is both later and more exposed. A jul30 5-seat panel ranked this
        # first of three known defects, unanimously.
        #
        # Fix is the invariant the emergency gate already assumes: the banked
        # mirror is immutable for the lifetime of the stage. Copy unconditionally
        # (the dual-seed path already did) and let the `global_improved` block
        # re-point `_best_valid_dcp` at the end. Costs one ~14 MB copy; changes no
        # optimization decision, only which file the ILS writes into.
        # Kill switch: FPL26_ILS_SEED_COPY=0 restores the in-place behaviour.
        recipe_seed = recipe_best
        if os.environ.get("FPL26_ILS_SEED_COPY", "1").strip().lower() in (
                "1", "true", "on", "yes"):
            try:
                _cs = (self.run_dir or Path(".")) / "ils_recipe_seed.dcp"
                shutil.copy(recipe_best, str(_cs))
                recipe_seed = str(_cs)
            except Exception as e:
                # Never fatal: the in-place path is what shipped before today.
                logger.warning(f"ILS recipe-seed copy failed ({e!r}); recipe-best in place.")
                recipe_seed = recipe_best
        # Ordered (kind, path, no_improve_stop) seeds. The FINAL/sole seed uses
        # the futility stop (final_seed_no_improve_stop, default 2): the score's
        # -0.1*alpha*gamma wall penalty makes non-accepting tail cycles a net
        # loss (jun12 replay: +9.65 score over 10 AWS runs, zero forfeited
        # accepts). 0 restores legacy run-to-budget.
        _K = _cfg.no_improve_stop_cycles
        _KF = _cfg.final_seed_no_improve_stop
        if _seed_kind == "raw" and raw_seed and _cfg.dual_seed:
            seeds = [("raw", raw_seed, _K), ("recipe_best", recipe_seed, _KF)]
            # Print the EFFECTIVE threshold, not the cfg default: FPL26_ILS_STUCK_GAIN_NS
            # overrides it, and logging the raw field made this line state something
            # false — jul28 it read "0.154ns < 0.15" while the decision (correctly) used
            # 0.20. The decision was right and the log was not, which is the worst way
            # for a line like this to be wrong.
            logger.info(f"ILS STUCK design (recipe_gain={_g}ns < "
                        f"{stuck_gain_threshold(_cfg)}); "
                        f"DUAL-SEED raw->recipe-best (keep-best, never-worse).")
        elif _seed_kind == "raw" and raw_seed:
            seeds = [("raw", raw_seed, _KF)]    # dual-seed disabled -> legacy single raw
            logger.info(f"ILS STUCK design (recipe_gain={_g}ns); single RAW seed "
                        f"(dual_seed off); keep-best.")
        else:
            seeds = [("recipe_best", recipe_seed, _KF)]
            logger.info(f"ILS seeding from recipe-best (recipe_gain={_g}ns; recipe "
                        f"helped or unknown -> preserve it); keep-best.")
        # Target-clock-aware WNS query (mirrors get_wns_for_target_clock).
        if self.target_clock:
            wns_tcl = (
                f"set clk_obj [get_clocks -quiet {{{self.target_clock}}}]; "
                f"if {{$clk_obj ne {{}}}} {{ set tp [get_timing_paths -max_paths 1 "
                f"-setup -to $clk_obj]; if {{[llength $tp] > 0}} {{get_property SLACK $tp}} "
                f"else {{puts 0.0}} }} else {{ set tp [get_timing_paths -max_paths 1 "
                f"-slack_lesser_than 999]; if {{[llength $tp] > 0}} {{get_property SLACK $tp}} "
                f"else {{puts 0.0}} }}"
            )
        else:
            wns_tcl = ("set tp [get_timing_paths -max_paths 1 -slack_lesser_than 999]; "
                       "if {[llength $tp] > 0} {get_property SLACK $tp} else {puts 0.0}")
        deadline = self._budget_deadline or (time.time() + 1200.0)
        # ---- C1-T3 polish reserve inside the ILS stage ----
        # New ILS ruin cycles are SPECULATIVE: they may not spend into the
        # reserved polish window (boom_soc_v2 beta: polish refused at est
        # 600s > 443s remaining because the tail was already burned).  The
        # seed loop below therefore runs against (deadline − reserve)
        # while the LASTMILE/fanout polish stages keep the full deadline.
        # Dynamic ineligibility precheck (never strand wall time): when
        # NEITHER polish stage can fire on this design — LASTMILE's wns
        # entry gate and the fanout cheap-design anchor gate, the same
        # gates the stages themselves apply — release the reserve NOW so
        # the ruin cycles get the full window, exactly today's behavior.
        _pr = self._polish_reserve_armed_s()
        if _pr > 0.0:
            _w_known = (self.best_wns if self.best_wns > float("-inf")
                        else self._best_valid_dcp_wns)
            _lm_ok = (getattr(_cfg, "lastmile_polish_enabled", True)
                      and _w_known is not None
                      and _w_known >= _cfg.lastmile_min_wns_ns)
            _fan_est, _ = _fanout_polish_cost_basis(_cfg)
            _fan_ok = (getattr(_cfg, "fanout_polish_enabled", True)
                       and 0.0 < _fan_est <= _cfg.fanout_max_cycle_s)
            if not (_lm_ok or _fan_ok):
                self._release_polish_reserve(
                    f"ils_polish_ineligible(lastmile_ok={_lm_ok},"
                    f"fanout_ok={_fan_ok},wns={_w_known})")
                _pr = 0.0
            else:
                logger.info(
                    f"polish-reserve: ILS ruin cycles fenced to "
                    f"deadline−{_pr:.0f}s (lastmile_ok={_lm_ok}, "
                    f"fanout_ok={_fan_ok}); polish stages keep the full "
                    f"window.")
        _ils_spec_deadline = deadline - _pr
        # Hand the ILS the UNFENCED wrapper deadline too. Its own deadline_ts is
        # short by _pr, and comparing a wrapper-level re-draw reserve against
        # that fenced value is what made FPL26_ILS_REDRAW_RESERVE stop digit one
        # cycle before its +38 MHz win (see the defect note in ils_polish.py).
        try:
            _cfg.wrapper_deadline_ts = float(deadline)
        except (TypeError, ValueError):
            _cfg.wrapper_deadline_ts = None
        recipe_baseline = self.best_wns if self.best_wns > float("-inf") else None
        # _in_ils_stage already set by the caller (_run_ils_polish_stage) so every
        # call here — restart, re-place, ship — bypasses the budget-skip gate.
        # Run each seed in order, keep-best ACROSS seeds: pass the running global
        # best as each seed's baseline so a later seed only accepts if it beats the
        # earlier one. The winning DCP lives at that seed's path.
        global_best_wns = recipe_baseline
        global_best_path = recipe_best       # pristine floor if nothing improves
        global_improved = False
        _cycles_done = 0   # corrective probe CONTINUES the combo rotation
        _seed0_res = None
        for _i, (_kind, _path, _nis) in enumerate(seeds):
            # Don't start a later seed without budget for >=1 real cycle.
            # C1-T3: measured against the reserve-fenced deadline — a
            # corrective seed is speculative work too.
            if _i > 0 and (_ils_spec_deadline - time.time()) < _cfg.exit_min_remaining_s:
                logger.info("ILS: insufficient budget for the corrective seed; stopping.")
                break
            _base = global_best_wns
            _off = _cycles_done
            if _i > 0 and getattr(_cfg, "corrective_local_climb", False):
                # jul04 preview #5-vs-#6 forensics (see cfg comment): let the
                # corrective seed climb against its OWN floor (stepping-stone
                # accepts re-enable the ExtraTimingOpt->PARTIAL_RUIN chain
                # that produced v2's best preview draw) and start its
                # rotation where the raw seed's PRISTINE state ended (skip
                # only genuine replays). Global keep-best below still decides
                # what ships — never-worse unchanged.
                _base = recipe_baseline
                if _seed0_res is not None:
                    _off = _seed0_res.pristine_rot
            logger.info(f"ILS seed[{_i}]={_kind} ({Path(_path).name}); "
                        f"baseline={_base} no_improve_stop={_nis} "
                        f"combo_offset={_off}.")
            # HURDLE CONTINUATION (jul26): populate the banked alpha the rule
            # needs. Declared in ILSPolishConfig and read by run_ils_polish, but
            # nothing SET it — so the mechanism was unreachable, not merely
            # default-off. Exactly the defect class this session has been
            # clearing (present in code, no path reaches it), shipped by me in
            # 8d3f23c and caught before it could mislead a null result.
            # Enable with --ils-hurdle-continue / FPL26_ILS_HURDLE_CONTINUE=1.
            try:
                if getattr(self, "_ils_hurdle_continue", False):
                    _a_now = self.calculate_fmax(self.best_wns, self.clock_period)
                    _a_0 = self.calculate_fmax(self.initial_wns, self.clock_period)
                    _alpha = (_a_now - _a_0) if (_a_now and _a_0) else 0.0
                    self._ils_polish_cfg.hurdle_continue_alpha_mhz = max(0.0, _alpha)
                    logger.info(
                        f"ILS: hurdle-continuation ARMED with banked alpha "
                        f"{_alpha:.2f} MHz — the scoring function, not the K "
                        f"counter, decides whether one more cycle pays.")
                else:
                    self._ils_polish_cfg.hurdle_continue_alpha_mhz = 0.0
            except Exception as _e:                          # pragma: no cover
                self._ils_polish_cfg.hurdle_continue_alpha_mhz = 0.0
                logger.warning(f"ILS: could not arm hurdle continuation "
                               f"({type(_e).__name__}); K-counter only.")
            res = await run_ils_polish(
                self.call_tool, best_dcp_path=_path, baseline_wns=_base,
                deadline_ts=_ils_spec_deadline, wns_tcl=wns_tcl,
                cfg=self._ils_polish_cfg,
                log=lambda m: logger.info(m), no_improve_stop=_nis,
                combo_offset=_off,
                combo_cost_seed=(_seed0_res.combo_cost if _seed0_res else None),
            )
            if _i == 0:
                _seed0_res = res
            self._ils_observed_costs = dict(res.combo_cost or {})
            _cycles_done += res.cycles
            logger.info(f"ILS seed[{_i}]={_kind}: {res.summary()}")
            # D3 signal (a): the ILS futility break ("no [meaningful]
            # improvement in N cycles; stopped" — ils_polish.py's
            # no_improve_stop notes).  Detected post-hoc from the result
            # notes: run_ils_polish is a free function and ILSPolishResult
            # carries no structured stopped-early flag (04-01 plan-checker
            # Warning 1 resolution — keep its API untouched).
            try:
                if any("cycles; stopped" in str(n) for n in (res.notes or [])):
                    self._maybe_arm_wall_handback(
                        f"ils_no_improve_stop(seed={_kind})")
            except Exception:
                pass
            if (res.improved and res.best_wns is not None
                    and (global_best_wns is None
                         or res.best_wns > global_best_wns)):
                global_best_wns = res.best_wns
                global_best_path = _path
                global_improved = True
        # Ship the global best: re-open it so finalize never ships a worse seed
        # (never-worse — recipe_best is the floor if nothing improved).
        try:
            await self.call_tool("vivado_run_tcl",
                                 {"command": f"open_checkpoint {{{global_best_path}}}"})
        except Exception:
            pass
        if global_improved:
            self.best_wns = global_best_wns
            self._best_valid_dcp = Path(global_best_path)
            self._best_valid_dcp_wns = global_best_wns
            # C1-T5: keep the banked-size reference in sync with the
            # re-pointed banked best (emergency integrity gate).
            try:
                self._best_valid_mirror_size = (
                    Path(global_best_path).stat().st_size)
            except OSError:
                self._best_valid_mirror_size = None
            logger.info(f"ILS shipped {Path(global_best_path).name} "
                        f"wns={global_best_wns} (improved over recipe-best).")
        else:
            logger.info("ILS: no seed beat recipe-best; shipping recipe-best (never-worse).")
        # C1-T3: the polish stages are now consuming the window the reserve
        # protected — release it (one-way; also covers the case where both
        # stages' own gates then skip: that IS the "correctly skipped"
        # outcome and nothing else may hold the reserve afterwards).
        self._release_polish_reserve("ils_polish_stages_reached")
        # jun14 DRILL D: dedicated AggressiveFanoutOpt polish on the FINAL best,
        # OUTSIDE the futility-gated combo rotation by design (a late-indexed
        # combo would be unreachable on plateaued ship states — exactly where
        # this helps). Cheap-designs-only + budget + strict-hold + never-worse.
        try:
            await self._lastmile_polish_after_ils(
                global_best_path, self.best_wns, deadline, wns_tcl)
        except Exception as e:
            logger.warning(f"lastmile-polish stage failed (ignored, best intact): {e!r}")
        # fanout polish runs on whatever best now stands (LASTMILE accept
        # updates _best_valid_dcp); it never places, so LastMile session
        # poisoning cannot affect it.
        _fp_path = str(self._best_valid_dcp) if self._best_valid_dcp else global_best_path
        try:
            await self._fanout_polish_after_ils(
                _fp_path, self.best_wns, deadline, wns_tcl)
        except Exception as e:
            logger.warning(f"fanout-polish stage failed (ignored, best intact): {e!r}")
        # jul22 placement flagship: INSURED TERMINAL RE-PLACE GAMBLE on the
        # final banked best (default OFF — replace_gamble_enabled; the
        # all-in window flips it on). Runs LAST: it is the only stage that
        # discards the chain's polish, so everything cheaper goes first.
        _rg_path = str(self._best_valid_dcp) if self._best_valid_dcp else global_best_path
        try:
            await self._replace_gamble_after_polish(
                _rg_path, self.best_wns, deadline, wns_tcl)
        except Exception as e:
            logger.warning(f"replace-gamble stage failed (ignored, best intact): {e!r}")
        # jul25 panel (grok-4.5 seat, the only Scale-1 killer): DEEP-WNS full
        # re-place from the PRISTINE input. boom_soc's +35.47 record reopened
        # the original DCP and re-placed; R1-DEEP never does that ("retiming is
        # the slow step"), which is our -22.15 gap. Runs dead last: like the
        # gamble it discards chain polish, and it seeds from pristine so it
        # depends on nothing above it. Never-worse — it only ever adds a MUX
        # candidate.

    def _polish_gate_reserve_s(self, cfg) -> "tuple[float, str]":
        """Bound shim over the module-level pure function (refactor policy
        jul26: keep patch targets module-global).  A caller without
        `_budget_deadline` — every stage stub in the suite — resolves to None
        and therefore keeps the reserve, which is the fail-safe direction."""
        return polish_gate_reserve_s(
            cfg, getattr(self, "_budget_deadline", None))

    async def _lastmile_polish_after_ils(self, best_path: str,
                                         best_wns: "Optional[float]",
                                         deadline: float, wns_tcl: str) -> None:
        """LASTMILE on the PLATEAUED global best (jul06; jun12 probe: v2
        -0.799 -> -0.647 +29MHz, logicnets +15MHz, both 10k-vector PASSED —
        the rotation never applies LASTMILE to the final state). Never-worse:
        a reject keeps the prior best. Runs BEFORE the fanout polish (which
        never places, so LastMile session poisoning cannot affect it)."""
        from optimizer.ils_polish import (_measure, _measure_hold,
                                          lastmile_polish_accept)
        cfg = self._ils_polish_cfg
        if not getattr(cfg, "lastmile_polish_enabled", True):
            return
        if best_wns is None or not best_path:
            return
        if best_wns < cfg.lastmile_min_wns_ns:
            logger.info(f"lastmile-polish: skipped (wns {best_wns} below UG906 "
                        f"entry gate {cfg.lastmile_min_wns_ns}).")
            return
        # Cost: observed LASTMILE cycle from this run's ILS seeds if any,
        # else a conservative default (probe 607s; eval observed 144-636s).
        est = 700.0
        try:
            from optimizer.ils_polish import ILS_COMBOS, LASTMILE_PD
            _lm = [c[0] for c in ILS_COMBOS].index(LASTMILE_PD)
            _obs = (getattr(self, "_ils_observed_costs", None) or {}).get(_lm)
            if _obs:
                est = float(_obs)
        except Exception:
            pass
        remaining = deadline - time.time()
        _rsv, _rsv_tag = polish_gate_reserve_s(
            cfg, getattr(self, "_budget_deadline", None))
        need = est * 1.3 + _rsv
        if remaining < need:
            logger.info(f"lastmile-polish: insufficient budget (remaining "
                        f"{remaining:.0f}s < need {need:.0f}s = est "
                        f"{est:.0f}s x1.3 + {_rsv_tag}); skipped.")
            return

        def _to() -> float:
            return max(300.0, min(cfg.heavy_cmd_timeout_s, deadline - time.time()))
        out_dcp = str((self.run_dir or Path(".")) / "ils_lastmile_polish.dcp")
        for _cmd in (f"open_checkpoint {{{best_path}}}",
                     "phys_opt_design -clock_opt -retime -lut_opt",
                     "place_design -directive LastMile",
                     "phys_opt_design -directive Explore",
                     "route_design -directive Explore",
                     "phys_opt_design -directive Explore"):
            _r = await self.call_tool("vivado_run_tcl",
                                      {"command": _cmd, "timeout": _to()})
            if isinstance(_r, str) and ('"error"' in _r or "TCL ERROR:" in _r):
                logger.info(f"lastmile-polish: step failed ({_cmd.split()[0]}); "
                            f"keeping best (never-worse).")
                return
        w, ur = await _measure(self.call_tool, wns_tcl,
                               timeout_s=cfg.measure_cmd_timeout_s)
        if ur and ur > 0:
            # LastMile draws sometimes leave a few dozen nets unrouted (jun12
            # spam; jul06 v2 validation: ur=39) — one incremental completion
            # pass usually finishes them. Still never-worse: a second failure
            # just rejects below.
            await self.call_tool("vivado_run_tcl",
                                 {"command": "route_design",
                                  "timeout": _to()})
            w, ur = await _measure(self.call_tool, wns_tcl,
                                   timeout_s=cfg.measure_cmd_timeout_s)
        whs = await _measure_hold(self.call_tool,
                                  timeout_s=cfg.measure_cmd_timeout_s)
        cells = None
        try:
            _cr = await self.call_tool("vivado_run_tcl", {
                "command": "llength [get_cells -quiet -hierarchical "
                           "-filter {IS_PRIMITIVE}]",
                "timeout": cfg.measure_cmd_timeout_s})
            # Guard as at :7307 — an error envelope's first integer would
            # become a bogus cell count.
            # ⚠ CORRECTION (review aug06): unlike the other two cell-count
            # sites, this one does NOT end in "no band opinion" —
            # lastmile_polish_accept fails CLOSED on an unknown count when a
            # golden set exists ("cell-count unmeasurable with golden set",
            # optimizer/ils_polish.py), and golden_cell_count IS set on the
            # ship path. So None rejects the accept, exactly as the bogus tiny
            # count did. The guard is therefore outcome-neutral HERE and earns
            # its place only by making the log honest ("error envelope" rather
            # than a fabricated cell count) and by not depending on the
            # accident that every envelope's first integer happens to be small.
            if _looks_like_tool_error(_cr):
                raise RuntimeError(
                    f"cell-count query returned error envelope: "
                    f"{str(_cr)[:120]}")
            _cm = re.search(r"(\d+)", str(_cr) or "")
            cells = int(_cm.group(1)) if _cm else None
        except Exception:
            pass
        ok, why = lastmile_polish_accept(new_wns=w, best_wns=best_wns,
                                         unrouted=ur, whs=whs,
                                         cell_count=cells, cfg=cfg)
        if ok:
            _wr = await self.call_tool(
                "vivado_run_tcl",
                {"command": f"write_checkpoint -force {{{out_dcp}}}",
                 "timeout": _to()})
            if isinstance(_wr, str) and ('"error"' in _wr or "TCL ERROR:" in _wr):
                logger.info("lastmile-polish: write_checkpoint failed; "
                            "keeping best (never-worse).")
                return
            self.best_wns = w
            self._best_valid_dcp = Path(out_dcp)
            self._best_valid_dcp_wns = w
            # C1-T5: keep the banked-size reference in sync.
            try:
                self._best_valid_mirror_size = Path(out_dcp).stat().st_size
            except OSError:
                self._best_valid_mirror_size = None
            logger.info(f"lastmile-polish ACCEPT: {why}; shipped LASTMILE "
                        f"final polish.")
        else:
            logger.info(f"lastmile-polish: rejected ({why}); keeping best "
                        f"(never-worse).")
            # D3 signal (b): the LASTMILE reject verdict — the plateaued
            # best could not be improved by the last dedicated polish.
            self._maybe_arm_wall_handback(f"lastmile_reject:{why[:120]}")

    async def _fanout_polish_after_ils(self, best_path: str,
                                       best_wns: Optional[float],
                                       deadline: float, wns_tcl: str) -> None:
        """One `phys_opt_design -directive AggressiveFanoutOpt` pass on the final
        ILS/recipe best (jun14 DRILL D finding: lifts hold-SAFE designs, e.g.
        logicnets +0.029ns ~+6MHz, GT-confirmed). Gated cheap-designs-only (the
        cold-start anchor must be known AND < fanout_max_cycle_s — paying
        ispd16's ~24min for a hold-marginal candidate the strict gate rejects
        would be a SCORE loss) + comfortable budget. Accept is STRICT-hold +
        never-worse (fanout_polish_accept); a reject keeps the prior best."""
        from optimizer.ils_polish import (_measure, _measure_hold,
                                          fanout_polish_accept)
        cfg = self._ils_polish_cfg
        if not getattr(cfg, "fanout_polish_enabled", True):
            return
        if best_wns is None or not best_path:
            return
        est, anchor_src = _fanout_polish_cost_basis(cfg)
        if est <= 0 or est > cfg.fanout_max_cycle_s:
            logger.info(f"fanout-polish: skipped ({anchor_src} cost anchor "
                        f"{est:.0f}s vs gate {cfg.fanout_max_cycle_s:.0f}s — "
                        f"fast designs only).")
            return
        remaining = deadline - time.time()
        _rsv, _rsv_tag = polish_gate_reserve_s(
            cfg, getattr(self, "_budget_deadline", None))
        need = est * 1.3 + _rsv
        if remaining < need:
            logger.info(f"fanout-polish: insufficient budget (remaining "
                        f"{remaining:.0f}s < need {need:.0f}s = est "
                        f"{est:.0f}s x1.3 + {_rsv_tag}); skipped.")
            return

        def _to() -> float:
            return max(300.0, min(cfg.heavy_cmd_timeout_s, deadline - time.time()))
        fanout_dcp = str((self.run_dir or Path(".")) / "ils_fanout_polish.dcp")
        await self.call_tool("vivado_run_tcl",
                             {"command": f"open_checkpoint {{{best_path}}}",
                              "timeout": cfg.measure_cmd_timeout_s})
        base_whs = await _measure_hold(self.call_tool,
                                       timeout_s=cfg.measure_cmd_timeout_s)
        _r = await self.call_tool(
            "vivado_run_tcl",
            {"command": "phys_opt_design -directive AggressiveFanoutOpt",
             "timeout": _to()})
        if isinstance(_r, str) and '"error"' in _r:
            logger.info("fanout-polish: phys_opt errored; keeping best (never-worse).")
            return
        w, ur = await _measure(self.call_tool, wns_tcl,
                               timeout_s=cfg.measure_cmd_timeout_s)
        if ur != 0:
            # replication can unroute affected nets — reroute once before measuring
            await self.call_tool("vivado_run_tcl",
                                 {"command": "route_design -directive Explore",
                                  "timeout": _to()})
            w, ur = await _measure(self.call_tool, wns_tcl,
                                   timeout_s=cfg.measure_cmd_timeout_s)
        whs = await _measure_hold(self.call_tool,
                                  timeout_s=cfg.measure_cmd_timeout_s)
        ok, why = fanout_polish_accept(new_wns=w, best_wns=best_wns, unrouted=ur,
                                       whs=whs, base_whs=base_whs, cfg=cfg)
        if ok:
            await self.call_tool(
                "vivado_run_tcl",
                {"command": f"write_checkpoint -force {{{fanout_dcp}}}",
                 "timeout": cfg.measure_cmd_timeout_s})
            self.best_wns = w
            self._best_valid_dcp = Path(fanout_dcp)
            self._best_valid_dcp_wns = w
            # C1-T5: keep the banked-size reference in sync.
            try:
                self._best_valid_mirror_size = Path(fanout_dcp).stat().st_size
            except OSError:
                self._best_valid_mirror_size = None
            logger.info(f"fanout-polish ACCEPT: {why} (hold {base_whs}->{whs}); "
                        f"shipped AggressiveFanoutOpt polish.")
        else:
            logger.info(f"fanout-polish: rejected ({why}); keeping best (never-worse).")

    async def _replace_gamble_after_polish(self, best_path: str,
                                           best_wns: Optional[float],
                                           deadline: float,
                                           wns_tcl: str) -> None:
        """INSURED TERMINAL RE-PLACE GAMBLE (jul22 placement flagship,
        P3+P2 merged; optimizer/replace_gamble.py has the full design +
        2025.1 doc evidence). From the banked best, gamble on full
        re-place draws with the untried -net_delay_weight knob, then
        route + measure. The banked best DCP on disk is NEVER written;
        adoption (>= +0.15ns over chain-best, routed, hold clean, verified
        write) banks to a dedicated draw-indexed file and repoints the
        mirror. Fail-closed budget: skipped without a measured full-cycle
        cost anchor or without reserve headroom. Default OFF
        (cfg.replace_gamble_enabled) — zero diff with the flag off."""
        cfg = self._ils_polish_cfg
        if not getattr(cfg, "replace_gamble_enabled", False):
            return
        from optimizer.replace_gamble import run_replace_gamble
        out_base = str((self.run_dir or Path(".")) / "ils_replace_gamble")
        res = await run_replace_gamble(
            self.call_tool, best_dcp_path=best_path, best_wns=best_wns,
            deadline_ts=deadline, wns_tcl=wns_tcl, cfg=cfg,
            log=lambda m: logger.info(m), out_dcp_base=out_base,
            observed_costs=getattr(self, "_ils_observed_costs", None))
        if res.adopted and res.best_path and res.best_wns is not None:
            self.best_wns = res.best_wns
            self._best_valid_dcp = Path(res.best_path)
            self._best_valid_dcp_wns = res.best_wns
            # C1-T5: keep the banked-size reference in sync.
            try:
                self._best_valid_mirror_size = (
                    Path(res.best_path).stat().st_size)
            except OSError:
                self._best_valid_mirror_size = None
            logger.info(f"replace-gamble ADOPTED: shipped "
                        f"{Path(res.best_path).name} wns={res.best_wns} "
                        f"(insured re-place beat chain-best by >= "
                        f"{cfg.replace_gamble_adopt_margin_ns}ns).")
        # jul23 INSURED-COMPARE wiring (FLAGSHIP -> final-candidate MUX):
        # enroll the best VERIFIED gamble draw as a FINAL candidate
        # REGARDLESS of the +0.15 adopt gate. run_replace_gamble already
        # persisted it to disk (best_draw_path) and measured it fully routed
        # (unrouted==0) and hold-clean (best_draw_whs) under the SAME gate
        # LOGIC register_final_candidate applies -> verify=False (the
        # "caller already measured under identical gates" contract), so NO
        # session re-open is needed and the shipping state is undisturbed. A
        # full re-place never deletes cells, so the cell-band guard is moot
        # (cell_count None -> fail-open). NET EFFECT: a +0.10 draw that the
        # in-run ratchet discards today now competes at finalize via the
        # MUX's 0.005 argmax. Strict no-op when the flag is OFF (run returns
        # before any draw, best_draw_path stays None). The +0.15
        # adopt->mirror-repoint above is untouched — this is purely additive.
        if (res.best_draw_path and res.best_draw_wns is not None
                and Path(res.best_draw_path).exists()
                and Path(res.best_draw_path).stat().st_size > 0):
            try:
                await self.register_final_candidate(
                    res.best_draw_path, res.best_draw_wns, "replace_gamble",
                    whs=res.best_draw_whs, verify=False)
            except Exception as e:
                logger.warning(
                    f"[mux] replace_gamble registration raised "
                    f"{type(e).__name__} (non-fatal): {e}")

    async def _maybe_run_recipe_first(self) -> None:
        """Run the forced DEEP-extreme recipe BEFORE the LLM loop (task #13).

        THE ARITHMETIC THAT FORCES THIS: on boom_soc the recipe costs 2750 s of
        a 3500 s wall (79%). A stage needing 79% of the budget cannot be a tail
        supplement — chain8 measured 72 s remaining at exit and logged
        deep_replace=0. Correct wiring alone does not fix that; only ordering
        does.

        WHAT IT IS WORTH (both post-route gated, 8-vCPU eval parity, jul25):
          boom_soc     agent +16.25  vs forced recipe +41.43   (+25.18)
          boom_soc_v2  best-ever +6.41 vs forced recipe +14.06 (+7.66)

        NEVER-WORSE still holds on fmax without new machinery: a losing recipe
        leaves best_wns <= initial_wns, so _finalize_no_improvement() is True
        and finalize ships the baseline byte-identically. The real exposure is
        OPPORTUNITY cost — the LLM loop only gets the remainder. The jul25
        panel upheld that trade 4/5 for the published band specifically, and
        3 seats made it conditional on exactly the baseline insurance above.

        SIZING AT t=0: no heavy step has run, so there is no measured anchor
        (replace_gamble_cost_basis would return 0 and fail closed forever).
        The size model supplies the basis from Phase-1's primitive cell count.

        Strict no-op unless BOTH deep_replace_enabled and
        deep_replace_first_enabled are set. Both default OFF.
        """
        cfg = self._ils_polish_cfg
        _en = bool(getattr(cfg, "deep_replace_enabled", False))
        _first = bool(getattr(cfg, "deep_replace_first_enabled", False))
        # REACHED before the enable check, for the same reason as the tail
        # stage: "never called" and "called but disabled" must be
        # distinguishable in the log.
        logger.info(f"deep-replace[first]: hook REACHED "
                    f"(enabled={_en} first={_first})")
        if not (_en and _first):
            return
        try:
            from optimizer.deep_replace_sibling import predict_place_route_s
            basis, why = predict_place_route_s(
                primitive_cells=getattr(self, "_input_cell_count", None))
            if basis <= 0:
                logger.info(f"deep-replace[first]: skipped ({why})")
                return
            await self._deep_replace_sibling_after_polish(
                time.time() + self._budget_remaining(),
                self._wns_tcl_for_stages(),
                stage_label="first",
                cost_basis_override=basis,
                basis_note=why,
            )
        except Exception as e:
            # Must never sink the run: the LLM loop still has the whole wall.
            logger.warning(f"deep-replace[first] raised "
                           f"{type(e).__name__} (non-fatal): {e!r}")

    async def _maybe_run_fir_subband_floor(self) -> None:
        """FPL26_FIR_SUBBAND_FLOOR (aug05, DEFAULT OFF): scripted in-session
        phys_opt floor for the fir-class sub-band.  See the constant block
        (FIR_FLOOR_*) for the mechanism evidence and design rationale.

        Ordering contract: MUST run after _maybe_run_recipe_first (the
        floor's gains are conditional on deep-replace[first]'s in-memory
        place state — box5 v30a aug05: the same floor on a pristine session
        gained 0.01 ns vs 0.095) and BEFORE _maybe_run_recipe_pass (whose
        reset would rebuild a pristine session; the shallow gate carves this
        sub-band out entirely).

        Banks in-session THROUGH call_tool: phys_opt steps are risky ->
        R-D1-1 auto-bank; the explicit vivado_get_wns after each step hits
        the unconditional bank branch, so best_wns / best-valid mirror /
        recipe_gain / hurdle alpha all see the floor exactly as if the LLM
        had issued the calls (that is what happened in every 21.30 trace).
        Never-worse: phys_opt only refines the routed state; a losing floor
        leaves best_wns untouched and costs wall the gate below prices in.
        Fail-open on any exception — the LLM loop still has the wall."""
        if not fir_subband_floor_enabled():
            logger.info("FIR-FLOOR: skipped reason=disabled "
                        "(FPL26_FIR_SUBBAND_FLOOR off or "
                        "FPL26_NO_FIR_SUBBAND_FLOOR set)")
            return
        wns_in = self.initial_wns  # same key the recipe-pass gate uses
        if not fir_subband_match(wns_in):
            logger.info(f"FIR-FLOOR: skipped reason=out_of_band "
                        f"wns_in={wns_in}")
            return
        # fir-likeness secondary key (aug05 panel, k3 F2): the floor is a
        # monoculture fitted to fir's physics (failing=252); a MEASURABLY
        # congested in-band unknown gets normal shallow treatment instead.
        # None-direction (panel-claims adversarial pass, aug05): an
        # UNMEASURED count does NOT skip — v3.2's validated fir 21.30 path
        # keyed on wns alone, and adding a second measured dependency would
        # let a failing-parse flake at eval degrade fir's deterministic
        # 21.30 to the LLM lottery.  The key may only EXCLUDE on positive
        # evidence, never gate the validated path on measurement success.
        _failing = self._phase1_failing_endpoints_for_features()
        if _failing is not None and not fir_like_failing_ok(_failing):
            logger.info(f"FIR-FLOOR: skipped reason=not_fir_like "
                        f"(measured failing_endpoints={_failing} > "
                        f"{FIR_FLOOR_MAX_FAILING_ENDPOINTS})")
            return
        cap_s = FIR_FLOOR_EXPECTED_S * RECIPE_PASS_TIMEOUT_FACTOR
        need = cap_s + FIR_FLOOR_RESERVE_S
        remaining = self._budget_remaining()
        if remaining < need:
            logger.info(f"FIR-FLOOR: skipped reason=insufficient_wall "
                        f"(remaining {remaining:.0f}s < need {need:.0f}s = "
                        f"cap {cap_s:.0f}s + reserve "
                        f"{FIR_FLOOR_RESERVE_S:.0f}s)")
            return
        logger.info(f"FIR-FLOOR: ARMED wns_in={wns_in:.3f} "
                    f"(scripted floor, in-session bank, cap {cap_s:.0f}s)")
        deadline = time.time() + cap_s
        steps = (
            ("vivado_run_tcl", {"command": FIR_FLOOR_GROUP_TCL}),
            # Arg-drop EFFECTIVE forms of the traced floor (:100/:121/:137):
            ("vivado_phys_opt_design", {"directive": "Default"}),
            ("vivado_get_wns", {}),
            ("vivado_phys_opt_design", {"directive": "Default"}),
            ("vivado_get_wns", {}),
            ("vivado_phys_opt_design", {"critical_pin_opt": True,
                                        "path_groups": "critical_endpoints"}),
            ("vivado_get_wns", {}),
        )
        try:
            for i, (tool, args) in enumerate(steps, 1):
                left = deadline - time.time()
                if left <= 0:
                    self._fir_floor_failed = True
                    logger.warning(f"FIR-FLOOR: aborted at step {i}/7 "
                                   f"(wall cap reached) — partial floor "
                                   f"stays banked; the shallow pass will "
                                   f"run as fallback (floor marked FAILED)")
                    return
                call_args = dict(args)
                if tool != "vivado_get_wns":
                    call_args.setdefault("timeout", float(max(60.0, left)))
                _res = await asyncio.wait_for(
                    self.call_tool(tool, call_args),
                    timeout=float(left) + 60.0)
                # Review M3 (aug05): call_tool reports failures as STRINGS
                # (JSON error envelope incl. budget skips, or Vivado "TCL
                # ERROR" text), never exceptions — without this check a
                # failed step would fall through and the "done" line would
                # lie.  Abort on the first bad payload; whatever the earlier
                # steps banked stays banked (strict-improvement machinery).
                if isinstance(_res, str) and _looks_like_tool_error(_res):
                    self._fir_floor_failed = True
                    logger.warning(
                        f"FIR-FLOOR: aborted at step {i}/7 — {tool} "
                        f"returned a tool error ({_res[:160]}); partial "
                        f"floor stays banked; the shallow pass will run "
                        f"as fallback (floor marked FAILED)")
                    return
            logger.info(f"FIR-FLOOR: done best_wns={self.best_wns} "
                        f"(banked in-session; ILS seeding/hurdle see it as "
                        f"recipe gain)")
        except Exception as e:
            self._fir_floor_failed = True
            logger.warning(f"FIR-FLOOR: aborted ({type(e).__name__}: {e!r}) "
                           f"— non-fatal; the shallow pass will run as "
                           f"fallback (floor marked FAILED)")

    async def _maybe_run_recipe_pass(self, input_dcp: Path) -> None:
        """FPL26_RECIPE_PASS (aug03, DEFAULT OFF): frozen-Tcl candidate pass.

        Runs at the post-Phase-1/pre-LLM slot and clones the presweep
        INSURED-COMPARE candidate-mode contract (see _run_fresh_presweep's
        candidate branch): run the frozen recipe FROM THE PRISTINE INPUT,
        copy the result to the private final_candidates store, enroll via
        register_final_candidate (routed/hold/cell gates), restart Vivado
        (session-pollution mitigation — open_checkpoint does NOT clear it),
        reopen the pristine input and hand the LLM loop an untouched run.
        The result competes ONLY at the finalize MUX (never-worse enforced
        there); it never touches best_valid.  A failed/timed-out recipe
        costs wall only — nothing else.

        Stable log keys (firing audit): "RECIPE-PASS: ARMED band=...",
        "RECIPE-PASS: fired recipe=... wns_in=...",
        "RECIPE-PASS: skipped reason=...".
        """
        if not recipe_pass_enabled():
            # Reached-but-disabled must be distinguishable from never-called
            # (feedback_firing_check_must_key_on_treatment).
            logger.info("RECIPE-PASS: skipped reason=disabled "
                        "(FPL26_RECIPE_PASS off or FPL26_NO_RECIPE_PASS set)")
            # FPL26_RECIPE_FIRST_DEEP misconfiguration guard (aug04): the
            # variant REQUIRES the master flag, so a run with only the
            # variant flag set must say so explicitly instead of silently
            # never arming (same treatment-keyed-log rule as above).  This
            # extra line appears ONLY when FPL26_RECIPE_FIRST_DEEP is set
            # truthy — runs without it stay byte-identical to 12005bd.
            if (os.environ.get("FPL26_RECIPE_FIRST_DEEP", "")
                    .strip().lower() in ("1", "true", "on", "yes")):
                logger.info(
                    "RECIPE-FIRST-DEEP: skipped reason=flag_off "
                    "(FPL26_RECIPE_FIRST_DEEP is set but the master "
                    "FPL26_RECIPE_PASS is off or FPL26_NO_RECIPE_PASS is "
                    "set — BOTH flags must be truthy; the kill switch "
                    "kills both)")
            return
        fired = False
        t_pass0 = time.time()
        # LLM-INVISIBILITY tag (aug04 exposure investigation, box2
        # x1a/x0a): every tool call the pass issues (recipe steps,
        # roundtrip, reset/reopen) lands in self.tool_call_details via
        # call_tool, and that list feeds the plan-critic prompt's
        # `tried` window (_maybe_plan_critique) — a model-visible
        # channel.  The pass is log-only by contract: tag its entries so
        # every prompt-side consumer can exclude them.  Behavioral
        # consumers (derive_cost_anchors etc.) still see the entries —
        # the measured Vivado costs are real.
        _tc0 = len(self.tool_call_details)
        try:
            try:
                fired = await self._run_recipe_pass_inner(input_dcp)
            except Exception as e:
                logger.warning(f"RECIPE-PASS: skipped reason=exception "
                               f"{type(e).__name__}: {e!r} (non-fatal)")
            if fired:
                # Contract steps 4-5 run UNCONDITIONALLY once the recipe
                # touched the session: fresh Vivado + pristine reopen +
                # lineage/allowance handling — success and failure paths
                # both end pristine.
                await self._recipe_pass_reset_session(input_dcp)
                # Phase-1 allowance shift (presweep contract 5993-5994
                # parity): the pass's elapsed wall must not squeeze
                # allowance-keyed gates.
                if self._phase1_start_ts is not None:
                    self._phase1_start_ts += max(0.0,
                                                 time.time() - t_pass0)
                # FPL26_RECIPE_FIRST_DEEP reduced-tail step (aug04): runs
                # ONLY when the size-anchored deep gate fired (flag-on
                # path); the method itself keys the reduction on a BANKED
                # candidate and is explicit-and-logged either way — never
                # silent.  MERGE NOTE (staging/v30-rfd): sits INSIDE the
                # LLM-invisibility tag bracket — the reduction emits log
                # lines only, no tool calls, no messages.
                if self._recipe_first_deep_fired:
                    self._recipe_first_deep_apply_reduced_tail()
        finally:
            for _d in self.tool_call_details[_tc0:]:
                try:
                    _d["recipe_pass_internal"] = True
                except Exception:
                    pass

    async def _run_recipe_pass_inner(self, input_dcp: Path) -> bool:
        """Key/wall gates + recipe execution + candidate registration.

        Returns True iff the recipe MUTATED the Vivado session (caller must
        then reset to pristine).  Never banks into best_valid: the R-D1-1
        auto-bank hook is suppressed for the whole pass (same bracket as the
        presweep draws) and banking happens only via register_final_candidate.
        """
        wns_in = self.initial_wns  # measured once at open; NOT re-measured
        band = recipe_pass_band(wns_in)
        if band is None:
            logger.info("RECIPE-PASS: skipped reason=wns_unmeasured "
                        "(initial_wns is None; no honest band key)")
            return False
        # k3 F7 drift audit (log-only): live banked wns beside the band key,
        # so a deep-replace[first] adopt that moved the design across a band
        # edge is visible in every log without changing any decision.
        logger.info(f"RECIPE-PASS: ARMED band={band} wns_in={wns_in:.3f} "
                    f"live_best_wns={self.best_wns}")
        # FIR sub-band carve-out (aug05; WIDENED by the gray-areas panel —
        # GRAYAREAS_SYNTHESIS_aug05.md): the shallow WLD pass's pristine
        # reset is the one mechanism by which a hidden design can score
        # BELOW v2.2 (proven −7.92 α on fir: box5 v30a recipe_gain 0.01 vs
        # 0.095; "shallow-benign" was a key-dead-era artifact).  Skip the
        # pass for every fir-like design with |wns_in| < 0.50 — no known
        # winner exists below spam's measured-stable 0.686.  Conditions:
        #   (a) fir-like: failing_endpoints ≤ 1,000 (k3 F2 — a congested
        #       in-band unknown keeps normal shallow treatment);
        #   (b) the floor did not FAIL (k3 F6 / qwen H1 — on a floor abort
        #       the pass runs as fallback: 13.38-class beats the 9.07
        #       failure mode on fir's own evidence).
        # Returning False = "session not mutated" → caller skips the reset.
        if (band == "shallow" and fir_subband_floor_enabled()
                and fir_carveout_match(
                    wns_in, self._phase1_failing_endpoints_for_features())
                and not getattr(self, "_fir_floor_failed", False)):
            logger.info("RECIPE-PASS: skipped reason=fir_subband_carveout "
                        "(fir-like |wns_in| < "
                        f"{FIR_CARVEOUT_WNS_MAG_MAX_NS}, failing ≤ "
                        f"{FIR_FLOOR_MAX_FAILING_ENDPOINTS}, floor ok)")
            return False
        if not (input_dcp and Path(input_dcp).exists()):
            logger.info("RECIPE-PASS: skipped reason=no_pristine_input "
                        "(input DCP missing on disk — cannot honor the "
                        "pristine-reopen contract)")
            return False
        steps = {"shallow": RECIPE_PASS_SHALLOW_TCL,
                 "deep": RECIPE_PASS_DEEP_TCL,
                 "mid": RECIPE_PASS_MID_TCL}[band]
        expected_s = {"shallow": RECIPE_PASS_SHALLOW_EXPECTED_S,
                      "deep": RECIPE_PASS_DEEP_EXPECTED_S,
                      "mid": RECIPE_PASS_MID_EXPECTED_S}[band]
        remaining = self._budget_remaining()
        # MAJOR-2 fix (REVIEW_V30_DIFF_aug03.md): the gate reserves what the
        # pass actually spends — the FULL pass budget (1.5x the verified
        # recipe cost) PLUS the four out-of-deadline overheads (measure /
        # store / register / reset; see RECIPE_PASS_*_RESERVE_S).
        pass_budget_cap = RECIPE_PASS_TIMEOUT_FACTOR * expected_s
        overhead = RECIPE_PASS_OVERHEAD_RESERVE_S
        _overhead_terms = (
            f"[measure {RECIPE_PASS_MEASURE_RESERVE_S:.0f} + store "
            f"{RECIPE_PASS_STORE_RESERVE_S:.0f} + register "
            f"{RECIPE_PASS_REGISTER_RESERVE_S:.0f} + reset "
            f"{RECIPE_PASS_RESET_RESERVE_S:.0f}]")
        # FPL26_RECIPE_FIRST_DEEP fire context: (anchor, predicted, need,
        # remaining) when the size-anchored deep gate armed this pass;
        # None on every other path (including ALL flag-off runs).
        _rfd_ctx = None

        # MINOR-2 fix (adversarial review aug04): unwalled runs must
        # print "unbounded", never "infs" — remaining/slack are the only
        # inf-able terms in the RECIPE-FIRST-DEEP lines; finite values
        # format exactly as before ("2726s"), so the prereg'd bins are
        # unchanged.  Function-level def: used by the gate branch AND
        # the fired-site line below.
        def _rfd_s(v) -> str:
            try:
                fv = float(v)
            except (TypeError, ValueError):
                return "unbounded"
            return "unbounded" if fv == float("inf") else f"{fv:.0f}s"

        if band == "deep" and recipe_first_deep_enabled():
            # ---- FPL26_RECIPE_FIRST_DEEP gate (aug04, opt-in) ----------
            # Size-anchored replacement for the band-constant arithmetic
            # below (which is UNARMABLE at ship wall — REVIEW_V30 MAJOR-1;
            # the flag-off branch below stays byte-identical 12005bd).
            # Full cost-model derivation, overhead audit, margin
            # justification and the vtr/boom worked examples live at the
            # RECIPE_FIRST_DEEP_* constants.  Shape:
            #   need = 1.2 x (2.5 x size_anchor) + reset 360s + LLM floor
            # where size_anchor is the SAME per-run size-model figure
            # deep-replace[first] trusts (predict_place_route_s, cells x
            # 0.00435), the 540s measure/store/register reserves are
            # DELIBERATELY ABSENT (inside the 852s calibration span —
            # charging them again is the double-reserve defect class),
            # and the deep-WNS tail reserve term is REPLACED by the
            # 1100s LLM floor, NOT added — that replacement is the whole
            # measured reduced-tail bet (constants block).
            try:
                llm_floor = float(getattr(
                    self, "phys_opt_preempt_budget_floor_s", 1100.0))
            except (TypeError, ValueError):
                llm_floor = 1100.0
            # SCALED LLM FLOOR (hardening (2), review Q2b): protect
            # unknown designs with large remaining; vtr unchanged
            # (0.35 x 2726 = 954 < 1100).  Finite-remaining only — an
            # unwalled run has no boundary to scale against.
            if remaining != float("inf"):
                llm_floor = max(
                    llm_floor,
                    RECIPE_FIRST_DEEP_LLM_FLOOR_FRAC * remaining)
            try:
                from optimizer.deep_replace_sibling import predict_place_route_s
                anchor, anchor_why = predict_place_route_s(
                    primitive_cells=getattr(
                        self, "_input_cell_count", None))
            except Exception as e:
                anchor, anchor_why = 0.0, (
                    f"size model raised {type(e).__name__}")
            anchor = float(anchor)
            # ANCHOR FLOOR (hardening (3), review Q2c): a pathological
            # small-cell design can route 3-5x worse than the size model
            # predicts; the floor keeps the gate honest below ~23k cells.
            # Unmeasurable (<= 0) stays unmeasurable — still fail-closed.
            if 0.0 < anchor < RECIPE_FIRST_DEEP_ANCHOR_FLOOR_S:
                anchor_why += (
                    f" [clamped {anchor:.0f}s->"
                    f"{RECIPE_FIRST_DEEP_ANCHOR_FLOOR_S:.0f}s anchor "
                    f"floor — small-cell honesty guard]")
                anchor = RECIPE_FIRST_DEEP_ANCHOR_FLOOR_S
            predicted = RECIPE_FIRST_DEEP_COST_RATIO * anchor
            need = (RECIPE_FIRST_DEEP_MARGIN * predicted
                    + RECIPE_PASS_RESET_RESERVE_S + llm_floor)
            # MAJOR-1 fix (adversarial review of 956556f+8cee732, aug04):
            # the pass runs under the BAND-CONSTANT hard deadline
            # (pass_budget = RECIPE_PASS_TIMEOUT_FACTOR x
            # RECIPE_PASS_DEEP_EXPECTED_S = 1350s, set below) — a
            # margined prediction ABOVE that deadline means the gate
            # would admit a recipe the deadline cannot finish: the
            # wall-fit check passes, the pass fires, and the per-step
            # fence kills it mid-flight having spent ~1350s for nothing
            # (the anchor ~450-573s window is wall-armable yet
            # deadline-doomed).  Fail closed instead.  vtr-invariant:
            # margined predicted 1029s < 1350s.
            _deadline_funds_s = (RECIPE_PASS_TIMEOUT_FACTOR
                                 * RECIPE_PASS_DEEP_EXPECTED_S)  # 1350
            _deadline_unfundable = (
                RECIPE_FIRST_DEEP_MARGIN * predicted > _deadline_funds_s)
            # GREPPABLE GATE TELEMETRY (hardening (4)): one line per gate
            # evaluation, ADDITIVE — the prereg'd ARMED/skipped bins
            # below are unchanged.  slack = remaining - need (negative on
            # NOFIRE-by-wall).
            _gate_decision = ("FIRE" if (anchor > 0.0
                                         and not _deadline_unfundable
                                         and remaining >= need)
                              else "NOFIRE")
            logger.info(
                f"RECIPE-FIRST-DEEP: GATE decision={_gate_decision} "
                f"anchor={anchor:.0f}s predicted={predicted:.0f}s "
                f"need={need:.0f}s remaining={_rfd_s(remaining)} "
                f"slack={_rfd_s(remaining - need)}")
            if anchor <= 0.0:
                # Unmeasured size must not arm a full place+route recipe
                # (same fail-closed rule predict_place_route_s documents).
                logger.info(
                    f"RECIPE-FIRST-DEEP: skipped reason=cost_model "
                    f"(anchor=0s predicted=0s need={need:.0f}s "
                    f"remaining={_rfd_s(remaining)} — size anchor "
                    f"unmeasurable ({anchor_why}); fail closed)")
                return False
            if _deadline_unfundable:
                logger.info(
                    f"RECIPE-FIRST-DEEP: skipped reason=cost_model "
                    f"(anchor={anchor:.0f}s predicted={predicted:.0f}s "
                    f"need={need:.0f}s remaining={_rfd_s(remaining)}; "
                    f"margined predicted "
                    f"{RECIPE_FIRST_DEEP_MARGIN * predicted:.0f}s > pass "
                    f"deadline {_deadline_funds_s:.0f}s (1.5x900 band "
                    f"constant) — predicted exceeds the pass deadline the "
                    f"band constant funds — deadline-unfundable, fail "
                    f"closed)")
                return False
            if remaining < need:
                logger.info(
                    f"RECIPE-FIRST-DEEP: skipped reason=cost_model "
                    f"(anchor={anchor:.0f}s predicted={predicted:.0f}s "
                    f"need={need:.0f}s remaining={_rfd_s(remaining)}; "
                    f"need = "
                    f"{RECIPE_FIRST_DEEP_MARGIN}x predicted + reset "
                    f"{RECIPE_PASS_RESET_RESERVE_S:.0f}s + LLM floor "
                    f"{llm_floor:.0f}s — fail closed; the post-loop slot "
                    f"may still arm)")
                return False
            _rfd_ctx = (anchor, predicted, need, remaining)
            # Gate-time LLM floor for the reduced-tail step (hardening
            # (2)): the loop must keep what THIS gate promised, not the
            # smaller base floor.
            self._recipe_first_deep_gate_llm_floor_s = llm_floor
            logger.info(
                f"RECIPE-FIRST-DEEP: ARMED band=deep wns_in={wns_in:.3f} "
                f"(anchor={anchor:.0f}s predicted={predicted:.0f}s "
                f"need={need:.0f}s remaining={_rfd_s(remaining)}; "
                f"{anchor_why})")
        elif band == "deep":
            # Fail-closed wall gate: pass budget + overheads AND the deep-WNS
            # tail reserve (2400 s at ship) must all still be fundable, else
            # the deep pipeline downstream is starved.
            #
            # MAJOR-1 (REVIEW_V30_DIFF_aug03.md): with this honest
            # arithmetic the deep gate needs ~1350 + 900 + 2400 = 4650 s,
            # but _budget_deadline = start + MAX_WALL - 300 caps remaining
            # at 3200 s on the ship wall (MAX_WALL 3500) — the deep band is
            # UNARMABLE AS BUILT under `make run_optimizer`.  Deliberate:
            # fail-closed OFF at THIS slot.  The MAJOR-1 redesign is BUILT
            # (aug03): candidate (a), the POST-LOOP slot consuming stranded
            # winner-polish wall — _maybe_run_recipe_pass_postloop at the
            # exit tail, gate 1350 + 540 = 1890 s (tail reserve and reset
            # reserve honestly vanish there).  Candidate (b) reduced-tail
            # bet stays REJECTED: a recipe miss eats the deep tail on the
            # way down = the fence failure mode.
            tail_reserve = self._deep_wns_tail_reserve_effective_s()
            need = pass_budget_cap + overhead + tail_reserve
            if remaining < need:
                logger.info(
                    f"RECIPE-PASS: skipped reason=wall band=deep "
                    f"(remaining {remaining:.0f}s < pass budget "
                    f"{pass_budget_cap:.0f}s (1.5x{expected_s:.0f}) + "
                    f"overheads {overhead:.0f}s {_overhead_terms} + deep-WNS "
                    f"tail reserve {tail_reserve:.0f}s = {need:.0f}s. Deep "
                    f"recipe requires remaining >= {need:.0f}s; the ship "
                    f"wall (MAX_WALL 3500, deadline-300) provides at most "
                    f"3200s — UNARMABLE AS BUILT, fail-closed by design, "
                    f"slot redesign pending (REVIEW_V30 MAJOR-1). "
                    f"(postloop slot may still arm)")
                return False
        elif band == "mid":
            # Corescore recipe gate (aug04).  Uses the MEASURED cross-box
            # probe cost (2800 s) rather than the 1.5x-margined figure —
            # 1.5x2800 = 4200 s alone exceeds the wall, and even the
            # un-margined measured cost fails: 2800 + 900 overheads + 1100
            # LLM floor = 4800 s > the 3200 s ship-wall maximum remaining.
            # So the mid band ships DORMANT-BY-ARITHMETIC, exactly like
            # deep: present, fail-closed, honest skip log.  Intended home =
            # the post-loop slot consuming stranded winner-polish wall
            # (750-1300 s measured stranded per run — still short of
            # 2800 s, so the redesign may also need a segment-A-only
            # variant or a DEBUG-WALL-only arming; decide at the slot
            # redesign, not here).
            try:
                llm_floor = float(getattr(
                    self, "phys_opt_preempt_budget_floor_s", 1100.0))
            except (TypeError, ValueError):
                llm_floor = 1100.0
            need = expected_s + overhead + llm_floor
            if remaining < need:
                logger.info(
                    f"RECIPE-PASS: skipped reason=wall band=mid "
                    f"(remaining {remaining:.0f}s < measured recipe cost "
                    f"{expected_s:.0f}s (cross-box probe, boxes 4/5) + "
                    f"overheads {overhead:.0f}s {_overhead_terms} + "
                    f"LLM-loop floor {llm_floor:.0f}s = {need:.0f}s. Mid "
                    f"recipe requires remaining >= {need:.0f}s; the ship "
                    f"wall (MAX_WALL 3500, deadline-300) provides at most "
                    f"3200s — UNARMABLE AS BUILT, fail-closed by design, "
                    f"slot redesign pending (post-loop stranded-wall slot "
                    f"is the intended home). (postloop slot may still arm)")
                return False
        else:
            # Shallow gate: pass budget + overheads + the LLM-loop floor
            # (review M2(b)'s missing term): do not fire when the pipeline
            # behind the pass would start under the existing minimum-useful-
            # budget for a heavy step (phys_opt_preempt_budget_floor_s,
            # Session-23 value 1100 s — reused, not invented).
            try:
                llm_floor = float(getattr(
                    self, "phys_opt_preempt_budget_floor_s", 1100.0))
            except (TypeError, ValueError):
                llm_floor = 1100.0
            need = pass_budget_cap + overhead + llm_floor
            if remaining < need:
                logger.info(
                    f"RECIPE-PASS: skipped reason=wall band=shallow "
                    f"(remaining {remaining:.0f}s < pass budget "
                    f"{pass_budget_cap:.0f}s (1.5x{expected_s:.0f}) + "
                    f"overheads {overhead:.0f}s {_overhead_terms} + "
                    f"LLM-loop floor {llm_floor:.0f}s = {need:.0f}s — "
                    f"fail closed)")
                return False
        # Hard per-pass deadline: 1.5x the verified cost, additionally capped
        # so the finalize reserve is never spendable by a runaway step.
        pass_budget = RECIPE_PASS_TIMEOUT_FACTOR * expected_s
        if remaining != float("inf"):
            pass_budget = min(pass_budget,
                              remaining - RECIPE_PASS_FINALIZE_RESERVE_S)
        if pass_budget < 60.0:
            logger.info(f"RECIPE-PASS: skipped reason=wall "
                        f"(pass budget {pass_budget:.0f}s < 60s floor)")
            return False
        # Double-fire guard for the post-loop slot (aug03): mark BEFORE the
        # first session mutation so a pre-LLM pass that fired but raised
        # mid-flight still blocks a second run at the exit tail.
        self._recipe_pass_preloop_fired = True
        if _rfd_ctx is not None:
            # Marker AFTER _recipe_pass_preloop_fired (same race-free
            # marker-at-fired-log ordering) and BEFORE the first session
            # mutation, so the caller's reduced-tail step and the postloop
            # already_fired guard agree on what happened.
            self._recipe_first_deep_fired = True
            _a, _p, _n, _r = _rfd_ctx
            logger.info(
                f"RECIPE-FIRST-DEEP: fired recipe=deep "
                f"wns_in={wns_in:.3f} (anchor={_a:.0f}s "
                f"predicted={_p:.0f}s need={_n:.0f}s "
                f"remaining={_rfd_s(_r)}; "
                f"tail reserve reduced after the pass iff a candidate "
                f"banks)")
        logger.info(f"RECIPE-PASS: fired recipe={band} wns_in={wns_in:.3f} "
                    f"(pass_budget={pass_budget:.0f}s, "
                    f"steps={len(steps)})")
        t0 = time.time()
        pass_deadline = t0 + pass_budget
        # The recipes are verified RELATIVE TO THE INPUT STATE (aug03 FIND #2
        # closure); deep-replace[first] may have left a different in-memory
        # state, so the pass starts from an explicit pristine reopen.  From
        # here on the session is considered mutated -> caller resets.
        prev_suppress = self._tail_ctrl_suppress_autobank
        self._tail_ctrl_suppress_autobank = True
        try:
            if not await self._presweep_reopen(input_dcp):
                logger.warning("RECIPE-PASS: failed step=pristine_preopen "
                               "(recipe not run; wall lost, nothing banked)")
                return True
            for i, step in enumerate(steps, 1):
                # DYNAMIC ABORT (hardening (1), review Q2a/Q3): between
                # steps only — rides the existing deadline fencing, no
                # new async machinery.  Cap = 0.75 x the fire-time need
                # budget; with the 1.2 gate margin this is effective
                # 1.6x overrun protection for unknown designs.  Ordering
                # guarantee: _recipe_first_deep_banked is still False
                # here (it is set ONLY at registration, after all
                # steps), so the caller's reduced-tail step logs
                # UNCHANGED and the full deterministic tail is kept —
                # the miss path, by construction.
                if _rfd_ctx is not None:
                    _elapsed = time.time() - t0
                    # MAJOR-3 fix (adversarial review aug04): the cap
                    # must ALSO protect the budget the gate promised the
                    # rest of the run — with 0.75 x need alone, a
                    # low-slack fire could legally burn wall the LLM
                    # floor + reset reserve were counting on.  Cap =
                    # min(0.75 x need, remaining_at_fire - gate LLM
                    # floor - reset reserve).  vtr: min(0.75 x 2489 =
                    # 1867, 2726 - 1100 - 360 = 1266) = 1266s — the
                    # abort, not the 1350s per-step fence, is now the
                    # tighter bound on vtr; measured recipe 852s (+-5%)
                    # stays ~414s clear, so the zero-abort ship
                    # criterion still holds.  Unwalled runs: remaining
                    # is inf -> the 0.75 x need term governs.
                    _gate_floor_s = float(
                        self._recipe_first_deep_gate_llm_floor_s or 0.0)
                    _abort_cap = min(
                        RECIPE_FIRST_DEEP_DYNAMIC_ABORT_FRAC
                        * _rfd_ctx[2],
                        _rfd_ctx[3] - _gate_floor_s
                        - RECIPE_PASS_RESET_RESERVE_S)
                    if _elapsed > _abort_cap:
                        logger.warning(
                            f"RECIPE-FIRST-DEEP: ABORTED "
                            f"reason=dynamic_overrun "
                            f"elapsed={_elapsed:.0f}s "
                            f"cap={_abort_cap:.0f}s (reverted pristine; "
                            f"tail reserve UNTOUCHED — a miss keeps the "
                            f"full tail)")
                        logger.info(
                            f"RECIPE-FIRST-DEEP: RESULT "
                            f"recipe_wall={_elapsed:.0f}s wns_out=NA "
                            f"registered=F abort=dynamic_overrun")
                        # Session is mutated -> True: the caller runs the
                        # existing failure path (_recipe_pass_reset_
                        # session: restart + pristine reopen).
                        return True
                step_left = pass_deadline - time.time()
                if step_left < 30.0:
                    logger.warning(
                        f"RECIPE-PASS: failed step={i}/{len(steps)} "
                        f"reason=pass_timeout ({pass_budget:.0f}s budget "
                        f"exhausted before '{step}'; aborting — wall lost, "
                        f"nothing banked)")
                    if _rfd_ctx is not None:
                        # MAJOR-2 (partial, code side — adversarial
                        # review aug04): the TIMEOUT bin must exist in
                        # the RESULT telemetry, not only the dynamic-
                        # overrun one; an RFD fire killed by the
                        # per-step fence was previously invisible to
                        # the RESULT grep.
                        logger.info(
                            f"RECIPE-FIRST-DEEP: RESULT "
                            f"recipe_wall={time.time() - t0:.0f}s "
                            f"wns_out=NA registered=F "
                            f"abort=pass_timeout")
                    return True
                if step == RECIPE_PASS_SESSION_ROUNDTRIP:
                    ok = await self._recipe_pass_roundtrip(step_left)
                    if not ok:
                        logger.warning(
                            f"RECIPE-PASS: failed step={i}/{len(steps)} "
                            f"reason=session_roundtrip (aborting)")
                        return True
                    continue
                try:
                    res = await asyncio.wait_for(
                        self.call_tool("vivado_run_tcl",
                                       {"command": step,
                                        "timeout": float(step_left)}),
                        timeout=float(step_left) + 60.0)
                except Exception as e:
                    logger.warning(
                        f"RECIPE-PASS: failed step={i}/{len(steps)} "
                        f"reason=step_raised:{type(e).__name__} "
                        f"cmd='{step}' (aborting)")
                    return True
                if _looks_like_tool_error(res):
                    logger.warning(
                        f"RECIPE-PASS: failed step={i}/{len(steps)} "
                        f"reason=step_error cmd='{step}' "
                        f"detail={str(res)[:120]} (aborting)")
                    return True
            # ---- measure + private store + register (contract 1-3) ----
            try:
                wns_out = await asyncio.wait_for(
                    self.get_wns_for_target_clock(self._call_vivado_tool),
                    timeout=600.0)
            except Exception:
                wns_out = None
            if wns_out is None:
                logger.warning("RECIPE-PASS: failed step=measure "
                               "reason=wns_unmeasurable (nothing banked)")
                return True
            store_dir = self.run_dir / "final_candidates"
            store_dir.mkdir(parents=True, exist_ok=True)
            store = store_dir / f"recipe_pass_{band}.dcp"
            try:
                res = await asyncio.wait_for(
                    self.call_tool("vivado_write_checkpoint", {
                        "dcp_path": str(store.resolve()),
                        "force": True}),
                    timeout=900.0)
            except Exception as e:
                res = f'{{"error": "write_checkpoint raised {type(e).__name__}"}}'
            if _looks_like_tool_error(res) or not (
                    store.exists() and store.stat().st_size > 0):
                logger.warning("RECIPE-PASS: failed step=store "
                               f"reason=write_checkpoint detail="
                               f"{str(res)[:120]} (nothing banked)")
                return True
            # In-memory state == the candidate on disk, so verify=True
            # re-runs the exact routed/hold/cell gates against it (the same
            # contract the presweep registration relies on).
            #
            # NOTE-1 fix (adversarial review aug04; pre-existing, LIVE
            # since the shallow arming 2a7b207): this call was the ONE
            # post-mutation operation outside any try — a raise here
            # propagated to the caller's except, which leaves `fired`
            # unset and therefore SKIPS _recipe_pass_reset_session, so
            # the LLM loop would start on the recipe-mutated session
            # (pristine-contract violation).  Mirror the step-exception
            # handling above: catch, log, return True — "mutated the
            # session" is TRUE regardless of registration, and the
            # caller's reset must run.
            #
            # MERGE RESOLUTION (staging/v30-rfd): NOTE-1 guard (5c6b9bd)
            # + the RFD banked-marker/RESULT block (cd2eaec lineage)
            # compose in THIS order deliberately — the exception path
            # returns BEFORE the marker, so a failed register can never
            # set _recipe_first_deep_banked and therefore never arms the
            # tail reduction (the reviewer's carry-over requirement).
            # Known minor, disclosed: a register RAISE on an RFD fire
            # emits no "RECIPE-FIRST-DEEP: RESULT" line — the greppable
            # record for that path is the "register FAILED" warning.
            try:
                registered = await self.register_final_candidate(
                    store, float(wns_out), f"recipe_pass_{band}", verify=True)
            except Exception as e:
                logger.warning(
                    f"RECIPE-PASS: register FAILED "
                    f"({type(e).__name__}: {e!r}); candidate dropped; "
                    f"session reset proceeds (pristine contract held)")
                return True
            if _rfd_ctx is not None and registered:
                # BANKED, not just fired: the reduced-tail step (caller)
                # keys on this — a fire that died pre-registration keeps
                # the full deterministic tail (fence-failure-mode guard).
                self._recipe_first_deep_banked = True
            if _rfd_ctx is not None:
                # GREPPABLE RESULT TELEMETRY (hardening (4)), ADDITIVE —
                # the RECIPE-PASS result line below is unchanged.
                logger.info(
                    f"RECIPE-FIRST-DEEP: RESULT "
                    f"recipe_wall={time.time() - t0:.0f}s "
                    f"wns_out={float(wns_out):.3f} "
                    f"registered={'T' if registered else 'F'} abort=NONE")
            logger.info(
                f"RECIPE-PASS: result recipe={band} wns_in={wns_in:.3f} "
                f"wns_out={float(wns_out):.3f} registered={registered} "
                f"dt={time.time() - t0:.0f}s (candidate competes ONLY at "
                f"the finalize MUX; pipeline enters PRISTINE)")
            # FPL26_VEX2_RETIME_CANDIDATE (aug05): SECOND shallow candidate,
            # MUX-additive.  Runs INSIDE the pass bracket (auto-bank still
            # suppressed) and AFTER the primary WLD candidate completed —
            # a primary abort above never reaches this call, so the primary
            # path is byte-identical to flag-off in every failure mode.
            # The caller's single reset covers both candidates.  Exception-
            # safe: a raise here must not void the ALREADY-REGISTERED
            # primary candidate.
            if band == "shallow":
                try:
                    await self._maybe_run_vex2_retime_candidate(
                        input_dcp, wns_in)
                except Exception as e:
                    logger.warning(
                        f"VEX2-RETIME: skipped reason=exception "
                        f"{type(e).__name__}: {e!r} (non-fatal; primary "
                        f"candidate already registered)")
                # FPL26_OWNFRONT_RETIME_CANDIDATE (aug05, v4.1 rev2):
                # the UNIFIED own-front retime candidate, MUX-additive.
                # ONE-CANDIDATE RULE: when this flag is armed the vex2
                # call above defers (reason=ownfront_supersedes), so
                # this is the single retime candidate of the pass; when
                # it is off/killed this call is a silent no-op and the
                # vex2 candidate above runs exactly as shipped v4.0.1.
                # Same bracket guarantees: auto-bank still suppressed, a
                # raise here voids neither the primary nor any earlier
                # registration, and the caller's single reset covers all
                # candidates.
                try:
                    await self._maybe_run_ownfront_retime_candidate(
                        input_dcp, wns_in)
                except Exception as e:
                    logger.warning(
                        f"OWNFRONT-RETIME: skipped reason=exception "
                        f"{type(e).__name__}: {e!r} (non-fatal; earlier "
                        f"candidates already registered)")
                # FPL26_SPAM_DETERMINIZER_CANDIDATE (aug06, v4.1.2):
                # THIRD shallow candidate, MUX-additive, band
                # [0.60, 0.90) — the exact window the ownfront v4.1.1
                # floor vacated.  SWAP, not stack (aug06 measurement):
                # in this band the vex2 candidate defers
                # (reason=spam_det_supersedes) — it is measured
                # MUX-discarded x3 on spam-class, and tonight's r1
                # refuted the c37f2c0 spend-timing theory; the freed
                # ~700 s makes the deterministic floor affordable.
                # Elsewhere the determinizer only ADDS a floor after
                # it.  On spam-class runs the sequence is: vex2 fires
                # (band overlap), ownfront skips out_of_band (0.90
                # floor), this one fires-or-defers on its own wall gate.
                # Same bracket guarantees as the two calls above.
                try:
                    await self._maybe_run_spam_determinizer_candidate(
                        input_dcp, wns_in)
                except Exception as e:
                    logger.warning(
                        f"SPAM-DET: skipped reason=exception "
                        f"{type(e).__name__}: {e!r} (non-fatal; earlier "
                        f"candidates already registered)")
            return True
        finally:
            self._tail_ctrl_suppress_autobank = prev_suppress

    async def _vex2_retime_ff_count(self, timeout_s: float,
                                    tag: str = "VEX2-RETIME"):
        """FF-count probe for the latency audit (VEX2_RETIME_FF_COUNT_TCL).
        Returns int or None (unmeasurable — the caller fails CLOSED).
        Parses ONLY the FFCOUNT= sentinel token (post-review ack): a bare
        first-parseable-token scan could bind to an unrelated number in
        interleaved Vivado chatter and silently pass a wrong audit.
        SHARED helper (v4.1): the WLD-retime candidate reuses this probe
        verbatim, passing tag="WLD-RETIME" so its log lines keep the
        stable per-candidate key; the default tag keeps the vex2 armed
        path's log bytes identical to v4.0."""
        try:
            res = await asyncio.wait_for(
                self.call_tool("vivado_run_tcl",
                               {"command": VEX2_RETIME_FF_COUNT_TCL,
                                "timeout": float(max(60.0, timeout_s))}),
                timeout=float(max(60.0, timeout_s)) + 60.0)
        except Exception as e:
            logger.warning(f"{tag}: ff-count probe raised "
                           f"{type(e).__name__}: {e!r}")
            return None
        if not isinstance(res, str) or _looks_like_tool_error(res):
            logger.warning(f"{tag}: ff-count probe errored "
                           f"({str(res)[:120]})")
            return None
        return vex2_retime_parse_ffcount(res)

    async def _maybe_run_vex2_retime_candidate(
            self, input_dcp: Path, wns_in: float) -> None:
        """FPL26_VEX2_RETIME_CANDIDATE (aug05, DEFAULT OFF): the q07 retime
        chain as a SECOND shallow-pass candidate.  See the VEX2_RETIME_*
        constants block for evidence, sub-band rationale, the latency-audit
        contract, and the recomputed wall arithmetic (need2 = 2330 s).

        Candidate contract (identical to the primary): pristine reopen ->
        frozen steps under a hard deadline -> FF latency audit -> measure ->
        private store -> register_final_candidate verify=True.  NEVER banks
        into best_valid (caller's auto-bank suppression bracket is still
        active); competes ONLY at the finalize MUX = never-worse by
        construction.  Every skip is fail-closed and logged.

        Stable log keys: "VEX2-RETIME: skipped reason=...",
        "VEX2-RETIME: fired", "VEX2-RETIME: ff-audit", "VEX2-RETIME: result".
        """
        if not vex2_retime_candidate_enabled():
            if v40_flag_env_present("FPL26_VEX2_RETIME_CANDIDATE",
                                    "FPL26_NO_VEX2_RETIME_CANDIDATE"):
                logger.info("VEX2-RETIME: skipped reason=disabled "
                            "(FPL26_VEX2_RETIME_CANDIDATE off or "
                            "FPL26_NO_VEX2_RETIME_CANDIDATE set)")
            return
        # v4.1 rev2 ONE-CANDIDATE RULE: when the unified own-front
        # candidate is armed, it OWNS the retime slot — this candidate
        # defers BEFORE spending any wall, so exactly ONE retime
        # candidate runs per pass (the v4.1-eggs A/B measured the
        # stacked shape self-defeating: vex2 fired, then the second
        # retime candidate skipped reason=wall 2195<2420).  When the
        # ownfront flag is off/killed this branch is dead and the vex2
        # candidate runs exactly as shipped in v4.0.1.
        if ownfront_retime_enabled() and ownfront_retime_front(wns_in) is not None:
            # v4.1.1 (parity-measured, aug05 spam +17.51 vs 29.19): the defer
            # applies ONLY when the ownfront candidate actually HANDLES this
            # design's band.  Out-of-band designs (spam-class after the 0.90
            # floor) fall through to THIS candidate = the exact v4.0.1
            # validated wall spend (spam's cycle-5 fork needs that tightness).
            logger.info("VEX2-RETIME: skipped reason=ownfront_supersedes "
                        "(FPL26_OWNFRONT_RETIME_CANDIDATE armed — the "
                        "unified own-front candidate owns the retime "
                        "slot; exactly ONE retime candidate spends wall "
                        "per run)")
            return
        if spam_determinizer_enabled() and spam_det_subband_match(wns_in):
            # v4.1.2 SWAP (aug06, measured): in [0.60, 0.90) the determinizer
            # REPLACES this candidate rather than stacking after it.  Evidence:
            # (a) this candidate on spam-class = fired -> -0.692 -> MUX-discarded
            # EVERY observed run (x3, zero value, ~700 s spent); (b) tonight's
            # r1 (byte-exact v4.0.1 spend) still drew +17.51 — the c37f2c0
            # "spam needs this spend's timing" theory is REFUTED by its own
            # follow-up measurement; (c) the stacked shape's need (2225 s)
            # does not fit after this candidate spends — the swap makes the
            # deterministic -0.543 floor affordable exactly where it matters.
            logger.info("VEX2-RETIME: skipped reason=spam_det_supersedes "
                        "(FPL26_SPAM_DETERMINIZER_CANDIDATE armed and "
                        "|wns_in| in [0.60, 0.90) — the deterministic "
                        "floor candidate owns this sub-band's wall; "
                        "this candidate is measured MUX-discarded x3 here)")
            return
        if not vex2_retime_subband_match(wns_in):
            logger.info(f"VEX2-RETIME: skipped reason=out_of_band "
                        f"wns_in={wns_in} (sub-band "
                        f"[{VEX2_RETIME_WNS_MAG_MIN_NS}, "
                        f"{VEX2_RETIME_WNS_MAG_MAX_NS}])")
            return
        # Recomputed second-candidate gate (constants block): the primary
        # shallow gate (2450 s) is UNTOUCHED; this one prices the second
        # candidate against what is left NOW, after the primary spent its
        # wall.  Fail-closed skip keeps the run byte-identical to flag-off.
        try:
            llm_floor = float(getattr(
                self, "phys_opt_preempt_budget_floor_s", 1100.0))
        except (TypeError, ValueError):
            llm_floor = 1100.0
        cap_s = RECIPE_PASS_TIMEOUT_FACTOR * VEX2_RETIME_EXPECTED_S  # 690
        need = cap_s + VEX2_RETIME_OVERHEAD_RESERVE_S + llm_floor    # 2330
        remaining = self._budget_remaining()
        if remaining < need:
            logger.info(
                f"VEX2-RETIME: skipped reason=wall "
                f"(remaining {remaining:.0f}s < cap {cap_s:.0f}s "
                f"(1.5x{VEX2_RETIME_EXPECTED_S:.0f}) + overheads "
                f"{VEX2_RETIME_OVERHEAD_RESERVE_S:.0f}s [measure "
                f"{RECIPE_PASS_MEASURE_RESERVE_S:.0f} + store "
                f"{RECIPE_PASS_STORE_RESERVE_S:.0f} + register "
                f"{RECIPE_PASS_REGISTER_RESERVE_S:.0f}; reset covered by "
                f"the caller's single post-pass reset] + LLM-loop floor "
                f"{llm_floor:.0f}s = {need:.0f}s — fail closed, primary "
                f"candidate unaffected)")
            return
        pass_budget = cap_s
        if remaining != float("inf"):
            pass_budget = min(pass_budget,
                              remaining - RECIPE_PASS_FINALIZE_RESERVE_S)
        if pass_budget < 60.0:
            logger.info(f"VEX2-RETIME: skipped reason=wall "
                        f"(pass budget {pass_budget:.0f}s < 60s floor)")
            return
        logger.info(f"VEX2-RETIME: fired wns_in={wns_in:.3f} "
                    f"(pass_budget={pass_budget:.0f}s, "
                    f"steps={len(VEX2_RETIME_TCL)}, MUX-additive second "
                    f"shallow candidate)")
        t0 = time.time()
        pass_deadline = t0 + pass_budget
        # The chain is verified RELATIVE TO THE PRISTINE INPUT (q07 ran
        # from the pristine DCP), and the primary recipe just mutated the
        # session — explicit pristine reopen first.
        if not await self._presweep_reopen(input_dcp):
            logger.warning("VEX2-RETIME: failed step=pristine_preopen "
                           "(chain not run; wall lost, nothing banked)")
            return
        ff_before = None
        ff_after = None
        for i, step in enumerate(VEX2_RETIME_TCL, 1):
            step_left = pass_deadline - time.time()
            if step_left < 30.0:
                logger.warning(
                    f"VEX2-RETIME: failed step={i}/{len(VEX2_RETIME_TCL)} "
                    f"reason=pass_timeout ({pass_budget:.0f}s budget "
                    f"exhausted before '{step}'; aborting — wall lost, "
                    f"nothing banked)")
                return
            try:
                res = await asyncio.wait_for(
                    self.call_tool("vivado_run_tcl",
                                   {"command": step,
                                    "timeout": float(step_left)}),
                    timeout=float(step_left) + 60.0)
            except Exception as e:
                logger.warning(
                    f"VEX2-RETIME: failed step={i}/{len(VEX2_RETIME_TCL)} "
                    f"reason=step_raised:{type(e).__name__} "
                    f"cmd='{step}' (aborting)")
                return
            if _looks_like_tool_error(res):
                logger.warning(
                    f"VEX2-RETIME: failed step={i}/{len(VEX2_RETIME_TCL)} "
                    f"reason=step_error cmd='{step}' "
                    f"detail={str(res)[:120]} (aborting)")
                return
            # LATENCY AUDIT probes: FF count after the place step (=before
            # retime) and after the retime step.  Cheap queries; bounded by
            # the step budget.
            if step == "place_design -directive ExtraTimingOpt":
                ff_before = await self._vex2_retime_ff_count(
                    min(300.0, max(60.0, pass_deadline - time.time())))
            elif step == "phys_opt_design -retime":
                ff_after = await self._vex2_retime_ff_count(
                    min(300.0, max(60.0, pass_deadline - time.time())))
        # ---- latency audit (DQ protection; fails CLOSED) ----
        if not vex2_retime_ff_drift_ok(ff_before, ff_after):
            logger.warning(
                f"VEX2-RETIME: ABORTED reason=latency_audit "
                f"ff_before={ff_before} ff_after={ff_after} "
                f"(drift beyond +-{VEX2_RETIME_FF_DRIFT_MAX_FRAC:.0%} or "
                f"unmeasured — protections fail ON; candidate NOT "
                f"registered, primary candidate unaffected)")
            return
        logger.info(f"VEX2-RETIME: ff-audit PASS ff_before={ff_before} "
                    f"ff_after={ff_after} "
                    f"(drift {abs(ff_after - ff_before) / float(ff_before):.4%}"
                    f" <= {VEX2_RETIME_FF_DRIFT_MAX_FRAC:.0%})")
        # ---- measure + private store + register (contract 1-3) ----
        try:
            wns_out = await asyncio.wait_for(
                self.get_wns_for_target_clock(self._call_vivado_tool),
                timeout=600.0)
        except Exception:
            wns_out = None
        if wns_out is None:
            logger.warning("VEX2-RETIME: failed step=measure "
                           "reason=wns_unmeasurable (nothing banked)")
            return
        store_dir = self.run_dir / "final_candidates"
        store_dir.mkdir(parents=True, exist_ok=True)
        store = store_dir / "recipe_pass_shallow_vex2retime.dcp"
        try:
            res = await asyncio.wait_for(
                self.call_tool("vivado_write_checkpoint", {
                    "dcp_path": str(store.resolve()),
                    "force": True}),
                timeout=900.0)
        except Exception as e:
            res = (f'{{"error": "write_checkpoint raised '
                   f'{type(e).__name__}"}}')
        if _looks_like_tool_error(res) or not (
                store.exists() and store.stat().st_size > 0):
            logger.warning("VEX2-RETIME: failed step=store "
                           f"reason=write_checkpoint detail="
                           f"{str(res)[:120]} (nothing banked)")
            return
        try:
            registered = await self.register_final_candidate(
                store, float(wns_out), "recipe_pass_shallow_vex2retime",
                verify=True)
        except Exception as e:
            logger.warning(
                f"VEX2-RETIME: register FAILED ({type(e).__name__}: "
                f"{e!r}); candidate dropped; caller's reset proceeds")
            return
        logger.info(
            f"VEX2-RETIME: result wns_in={wns_in:.3f} "
            f"wns_out={float(wns_out):.3f} registered={registered} "
            f"ff_before={ff_before} ff_after={ff_after} "
            f"dt={time.time() - t0:.0f}s (candidate competes ONLY at the "
            f"finalize MUX; caller resets to PRISTINE)")

    async def _maybe_run_ownfront_retime_candidate(
            self, input_dcp: Path, wns_in: float) -> None:
        """FPL26_OWNFRONT_RETIME_CANDIDATE (aug05, v4.1 rev2, DEFAULT
        OFF): the UNIFIED own-front retime candidate — ONE second
        shallow candidate whose place front is SELECTED per run from the
        measured |wns_in| ([0.60, 1.00) -> q07/ETO chain, vex2-class;
        [1.00, 1.05] -> WLD chain, digit-class).  See the
        OWNFRONT_RETIME_* constants block for the evidence (v4.1 A/B
        wall-stacking self-defeat; drill law: retime pays on the
        design's OWN winning front), the boundary rationale, and the
        single recomputed need constant (2420 s).  When this flag is
        armed the vex2 candidate DEFERS (reason=ownfront_supersedes) so
        exactly ONE retime candidate spends wall per run.

        Candidate contract (identical to the primary and vex2
        candidates): pristine reopen -> frozen steps under a hard
        deadline -> FF latency audit (SHARED helpers:
        _vex2_retime_ff_count sentinel probe + vex2_retime_ff_drift_ok
        +-1% gate; unmeasured = abort, protections fail ON) -> measure
        -> private store -> register_final_candidate verify=True.  NEVER
        banks into best_valid (caller's auto-bank suppression bracket is
        still active); competes ONLY at the finalize MUX = never-worse
        by construction.  Every skip is fail-closed and logged.

        Stable log keys (mirror VEX2-RETIME's): "OWNFRONT-RETIME:
        skipped reason=...", "OWNFRONT-RETIME: fired",
        "OWNFRONT-RETIME: ff-audit", "OWNFRONT-RETIME: result".
        """
        if not ownfront_retime_enabled():
            if v40_flag_env_present("FPL26_OWNFRONT_RETIME_CANDIDATE",
                                    "FPL26_NO_OWNFRONT_RETIME_CANDIDATE"):
                logger.info("OWNFRONT-RETIME: skipped reason=disabled "
                            "(FPL26_OWNFRONT_RETIME_CANDIDATE off or "
                            "FPL26_NO_OWNFRONT_RETIME_CANDIDATE set)")
            return
        front = ownfront_retime_front(wns_in)
        if front is None:
            logger.info(f"OWNFRONT-RETIME: skipped reason=out_of_band "
                        f"wns_in={wns_in} (band "
                        f"[{OWNFRONT_RETIME_WNS_MAG_MIN_NS}, "
                        f"{OWNFRONT_RETIME_WNS_MAG_MAX_NS}]; split "
                        f"{OWNFRONT_RETIME_SPLIT_NS} — eto below, wld at "
                        f"or above; logicnets-class <0.60 uncovered this "
                        f"round by design)")
            return
        chain = VEX2_RETIME_TCL if front == "eto" else WLD_RETIME_TCL
        place_step = chain[2]  # the selected front's place directive
        # SINGLE recomputed gate for the one-candidate shape (constants
        # block): the primary shallow gate (2450 s) is UNTOUCHED; this
        # prices the ONE retime candidate against what is left NOW,
        # after the primary spent its wall.  There is no earlier retime
        # candidate to stack against (the vex2 candidate defers).
        # Fail-closed skip keeps the run byte-identical from this point.
        try:
            llm_floor = float(getattr(
                self, "phys_opt_preempt_budget_floor_s", 1100.0))
        except (TypeError, ValueError):
            llm_floor = 1100.0
        cap_s = RECIPE_PASS_TIMEOUT_FACTOR * OWNFRONT_RETIME_EXPECTED_S  # 780
        need = cap_s + OWNFRONT_RETIME_OVERHEAD_RESERVE_S + llm_floor   # 2420
        remaining = self._budget_remaining()
        if remaining < need:
            logger.info(
                f"OWNFRONT-RETIME: skipped reason=wall "
                f"(remaining {remaining:.0f}s < cap {cap_s:.0f}s "
                f"(1.5x{OWNFRONT_RETIME_EXPECTED_S:.0f}) + overheads "
                f"{OWNFRONT_RETIME_OVERHEAD_RESERVE_S:.0f}s [measure "
                f"{RECIPE_PASS_MEASURE_RESERVE_S:.0f} + store "
                f"{RECIPE_PASS_STORE_RESERVE_S:.0f} + register "
                f"{RECIPE_PASS_REGISTER_RESERVE_S:.0f}; reset covered by "
                f"the caller's single post-pass reset] + LLM-loop floor "
                f"{llm_floor:.0f}s = {need:.0f}s — fail closed, primary "
                f"candidate unaffected)")
            return
        pass_budget = cap_s
        if remaining != float("inf"):
            pass_budget = min(pass_budget,
                              remaining - RECIPE_PASS_FINALIZE_RESERVE_S)
        if pass_budget < 60.0:
            logger.info(f"OWNFRONT-RETIME: skipped reason=wall "
                        f"(pass budget {pass_budget:.0f}s < 60s floor)")
            return
        logger.info(f"OWNFRONT-RETIME: fired wns_in={wns_in:.3f} "
                    f"front={front} (pass_budget={pass_budget:.0f}s, "
                    f"steps={len(chain)}, MUX-additive unified second "
                    f"shallow candidate — the ONE retime candidate on "
                    f"this run)")
        t0 = time.time()
        pass_deadline = t0 + pass_budget
        # Both sub-chains are verified RELATIVE TO THE PRISTINE INPUT
        # (q07 and the box3 drills ran from the pristine DCP), and the
        # primary recipe just mutated the session — explicit pristine
        # reopen first.
        if not await self._presweep_reopen(input_dcp):
            logger.warning("OWNFRONT-RETIME: failed step=pristine_preopen "
                           "(chain not run; wall lost, nothing banked)")
            return
        ff_before = None
        ff_after = None
        for i, step in enumerate(chain, 1):
            step_left = pass_deadline - time.time()
            if step_left < 30.0:
                logger.warning(
                    f"OWNFRONT-RETIME: failed step={i}/{len(chain)} "
                    f"reason=pass_timeout ({pass_budget:.0f}s budget "
                    f"exhausted before '{step}'; aborting — wall lost, "
                    f"nothing banked)")
                return
            try:
                res = await asyncio.wait_for(
                    self.call_tool("vivado_run_tcl",
                                   {"command": step,
                                    "timeout": float(step_left)}),
                    timeout=float(step_left) + 60.0)
            except Exception as e:
                logger.warning(
                    f"OWNFRONT-RETIME: failed step={i}/{len(chain)} "
                    f"reason=step_raised:{type(e).__name__} "
                    f"cmd='{step}' (aborting)")
                return
            if _looks_like_tool_error(res):
                logger.warning(
                    f"OWNFRONT-RETIME: failed step={i}/{len(chain)} "
                    f"reason=step_error cmd='{step}' "
                    f"detail={str(res)[:120]} (aborting)")
                return
            # LATENCY AUDIT probes (shared FFCOUNT= sentinel helper): FF
            # count after the SELECTED place step (=before retime) and
            # after the retime step.  Cheap queries; bounded by the step
            # budget.
            if step == place_step:
                ff_before = await self._vex2_retime_ff_count(
                    min(300.0, max(60.0, pass_deadline - time.time())),
                    tag="OWNFRONT-RETIME")
            elif step == "phys_opt_design -retime":
                ff_after = await self._vex2_retime_ff_count(
                    min(300.0, max(60.0, pass_deadline - time.time())),
                    tag="OWNFRONT-RETIME")
        # ---- latency audit (DQ protection; fails CLOSED) ----
        if not vex2_retime_ff_drift_ok(ff_before, ff_after):
            logger.warning(
                f"OWNFRONT-RETIME: ABORTED reason=latency_audit "
                f"front={front} ff_before={ff_before} ff_after={ff_after} "
                f"(drift beyond +-{VEX2_RETIME_FF_DRIFT_MAX_FRAC:.0%} or "
                f"unmeasured — protections fail ON; candidate NOT "
                f"registered, primary candidate unaffected)")
            return
        logger.info(f"OWNFRONT-RETIME: ff-audit PASS ff_before={ff_before} "
                    f"ff_after={ff_after} "
                    f"(drift {abs(ff_after - ff_before) / float(ff_before):.4%}"
                    f" <= {VEX2_RETIME_FF_DRIFT_MAX_FRAC:.0%})")
        # ---- measure + private store + register (contract 1-3) ----
        try:
            wns_out = await asyncio.wait_for(
                self.get_wns_for_target_clock(self._call_vivado_tool),
                timeout=600.0)
        except Exception:
            wns_out = None
        if wns_out is None:
            logger.warning("OWNFRONT-RETIME: failed step=measure "
                           "reason=wns_unmeasurable (nothing banked)")
            return
        store_dir = self.run_dir / "final_candidates"
        store_dir.mkdir(parents=True, exist_ok=True)
        store = store_dir / f"recipe_pass_shallow_ownfront_{front}.dcp"
        try:
            res = await asyncio.wait_for(
                self.call_tool("vivado_write_checkpoint", {
                    "dcp_path": str(store.resolve()),
                    "force": True}),
                timeout=900.0)
        except Exception as e:
            res = (f'{{"error": "write_checkpoint raised '
                   f'{type(e).__name__}"}}')
        if _looks_like_tool_error(res) or not (
                store.exists() and store.stat().st_size > 0):
            logger.warning("OWNFRONT-RETIME: failed step=store "
                           f"reason=write_checkpoint detail="
                           f"{str(res)[:120]} (nothing banked)")
            return
        try:
            registered = await self.register_final_candidate(
                store, float(wns_out),
                f"recipe_pass_shallow_ownfront_{front}", verify=True)
        except Exception as e:
            logger.warning(
                f"OWNFRONT-RETIME: register FAILED ({type(e).__name__}: "
                f"{e!r}); candidate dropped; caller's reset proceeds")
            return
        logger.info(
            f"OWNFRONT-RETIME: result wns_in={wns_in:.3f} front={front} "
            f"wns_out={float(wns_out):.3f} registered={registered} "
            f"ff_before={ff_before} ff_after={ff_after} "
            f"dt={time.time() - t0:.0f}s (candidate competes ONLY at the "
            f"finalize MUX; caller resets to PRISTINE)")

    async def _maybe_run_spam_determinizer_candidate(
            self, input_dcp: Path, wns_in: float) -> None:
        """FPL26_SPAM_DETERMINIZER_CANDIDATE (aug06, v4.1.2, DEFAULT
        OFF): the box2-drilled spam determinizer chain (place ASL_medium
        -> route Explore -> route AE incremental, NO unroute between ->
        phys_opt AFWR; wns -0.543/466.64 x3 bit-identical, ~390 s) as a
        THIRD shallow-pass candidate on the [0.60, 0.90) sub-band — the
        exact window the ownfront v4.1.1 floor vacated.  See the
        SPAM_DET_* constants block for the evidence (tonight's live
        29.19-vs-17.51x2 timing lottery), the slot rationale (runs AFTER
        the vex2 candidate, which is deliberately NOT deferred — spam's
        validated 29.19 path includes its exact spend), the recomputed
        need constant (2225 s) and its honest worked example (on the
        typical ship-wall draw post-swap the vex2 candidate defers in this band; THIS candidate fail-closed-skips only on wall),
        and the latency-audit disagreement note (audit ADDED, bracketing
        the AFWR step).

        Candidate contract (identical to the primary/vex2/ownfront
        candidates): pristine reopen -> frozen steps under a hard
        deadline -> FF latency audit (SHARED helpers, fail closed) ->
        measure -> private store -> register_final_candidate
        verify=True.  NEVER banks into best_valid (caller's auto-bank
        suppression bracket is still active); competes ONLY at the
        finalize MUX = never-worse by construction.  Every skip is
        fail-closed and logged.

        Stable log keys: "SPAM-DET: skipped reason=...",
        "SPAM-DET: fired", "SPAM-DET: ff-audit", "SPAM-DET: result".
        """
        if not spam_determinizer_enabled():
            if v40_flag_env_present("FPL26_SPAM_DETERMINIZER_CANDIDATE",
                                    "FPL26_NO_SPAM_DETERMINIZER_CANDIDATE"):
                logger.info("SPAM-DET: skipped reason=disabled "
                            "(FPL26_SPAM_DETERMINIZER_CANDIDATE off or "
                            "FPL26_NO_SPAM_DETERMINIZER_CANDIDATE set)")
            return
        if not spam_det_subband_match(wns_in):
            logger.info(f"SPAM-DET: skipped reason=out_of_band "
                        f"wns_in={wns_in} (sub-band "
                        f"[{SPAM_DET_WNS_MAG_MIN_NS}, "
                        f"{SPAM_DET_WNS_MAG_MAX_NS}) — high bound "
                        f"exclusive; [0.90, 1.05] is the ownfront "
                        f"candidate's)")
            return
        # Recomputed third-candidate gate (constants block): the primary
        # shallow gate (2450 s) and the vex2 gate (2330 s) are UNTOUCHED;
        # this one prices the determinizer against what is left NOW,
        # after the primary spent its wall (the vex2 candidate DEFERRED in this band per the a5dcddb swap).  On
        # the typical ship-wall draw that leaves < 2225 s and THIS skip
        # fires — the documented "which defers" answer: the determinizer
        # defers, the swap frees the old vex2 spend in this band (measured MUX-discarded x3).
        try:
            llm_floor = float(getattr(
                self, "phys_opt_preempt_budget_floor_s", 1100.0))
        except (TypeError, ValueError):
            llm_floor = 1100.0
        cap_s = RECIPE_PASS_TIMEOUT_FACTOR * SPAM_DET_EXPECTED_S  # 585
        need = cap_s + SPAM_DET_OVERHEAD_RESERVE_S + llm_floor    # 2225
        remaining = self._budget_remaining()
        if remaining < need:
            logger.info(
                f"SPAM-DET: skipped reason=wall "
                f"(remaining {remaining:.0f}s < cap {cap_s:.0f}s "
                f"(1.5x{SPAM_DET_EXPECTED_S:.0f}) + overheads "
                f"{SPAM_DET_OVERHEAD_RESERVE_S:.0f}s [measure "
                f"{RECIPE_PASS_MEASURE_RESERVE_S:.0f} + store "
                f"{RECIPE_PASS_STORE_RESERVE_S:.0f} + register "
                f"{RECIPE_PASS_REGISTER_RESERVE_S:.0f}; reset covered by "
                f"the caller's single post-pass reset] + LLM-loop floor "
                f"{llm_floor:.0f}s = {need:.0f}s — fail closed, earlier "
                f"candidates unaffected; NOTE post-swap this leaves the "
                f"band with NO retime candidate and a ~700s-larger tail "
                f"budget vs c37f2c0 — an uncovered cell, named in the "
                f"prereg amendment)")
            return
        pass_budget = cap_s
        if remaining != float("inf"):
            pass_budget = min(pass_budget,
                              remaining - RECIPE_PASS_FINALIZE_RESERVE_S)
        if pass_budget < 60.0:
            logger.info(f"SPAM-DET: skipped reason=wall "
                        f"(pass budget {pass_budget:.0f}s < 60s floor)")
            return
        logger.info(f"SPAM-DET: fired wns_in={wns_in:.3f} "
                    f"(pass_budget={pass_budget:.0f}s, "
                    f"steps={len(SPAM_DET_TCL)}, MUX-additive third "
                    f"shallow candidate — determinizer floor for the "
                    f"spam-class timing lottery)")
        t0 = time.time()
        pass_deadline = t0 + pass_budget
        # The chain is verified RELATIVE TO THE PRISTINE INPUT (the box2
        # drills ran from the pristine DCP), and the earlier candidates
        # just mutated the session — explicit pristine reopen first.
        if not await self._presweep_reopen(input_dcp):
            logger.warning("SPAM-DET: failed step=pristine_preopen "
                           "(chain not run; wall lost, nothing banked)")
            return
        ff_before = None
        ff_after = None
        for i, step in enumerate(SPAM_DET_TCL, 1):
            step_left = pass_deadline - time.time()
            if step_left < 30.0:
                logger.warning(
                    f"SPAM-DET: failed step={i}/{len(SPAM_DET_TCL)} "
                    f"reason=pass_timeout ({pass_budget:.0f}s budget "
                    f"exhausted before '{step}'; aborting — wall lost, "
                    f"nothing banked)")
                return
            try:
                res = await asyncio.wait_for(
                    self.call_tool("vivado_run_tcl",
                                   {"command": step,
                                    "timeout": float(step_left)}),
                    timeout=float(step_left) + 60.0)
            except Exception as e:
                logger.warning(
                    f"SPAM-DET: failed step={i}/{len(SPAM_DET_TCL)} "
                    f"reason=step_raised:{type(e).__name__} "
                    f"cmd='{step}' (aborting)")
                return
            if _looks_like_tool_error(res):
                logger.warning(
                    f"SPAM-DET: failed step={i}/{len(SPAM_DET_TCL)} "
                    f"reason=step_error cmd='{step}' "
                    f"detail={str(res)[:120]} (aborting)")
                return
            # LATENCY AUDIT probes (shared FFCOUNT= sentinel helper),
            # ADDED despite the no-bare-retime-step spec (see the
            # constants-block disagreement note: AlternateFlowWithRetiming
            # IS a retiming-enabled flow).  Brackets the AFWR step: FF
            # count after the route-AE step (= before AFWR) and after
            # AFWR.  Cheap queries; bounded by the step budget.
            if step == "route_design -directive AggressiveExplore":
                ff_before = await self._vex2_retime_ff_count(
                    min(300.0, max(60.0, pass_deadline - time.time())),
                    tag="SPAM-DET")
            elif step == "phys_opt_design -directive AlternateFlowWithRetiming":
                ff_after = await self._vex2_retime_ff_count(
                    min(300.0, max(60.0, pass_deadline - time.time())),
                    tag="SPAM-DET")
        # ---- latency audit (DQ protection; fails CLOSED) ----
        if not vex2_retime_ff_drift_ok(ff_before, ff_after):
            logger.warning(
                f"SPAM-DET: ABORTED reason=latency_audit "
                f"ff_before={ff_before} ff_after={ff_after} "
                f"(drift beyond +-{VEX2_RETIME_FF_DRIFT_MAX_FRAC:.0%} or "
                f"unmeasured — protections fail ON; candidate NOT "
                f"registered, earlier candidates unaffected)")
            return
        logger.info(f"SPAM-DET: ff-audit PASS ff_before={ff_before} "
                    f"ff_after={ff_after} "
                    f"(drift {abs(ff_after - ff_before) / float(ff_before):.4%}"
                    f" <= {VEX2_RETIME_FF_DRIFT_MAX_FRAC:.0%})")
        # ---- measure + private store + register (contract 1-3) ----
        try:
            wns_out = await asyncio.wait_for(
                self.get_wns_for_target_clock(self._call_vivado_tool),
                timeout=600.0)
        except Exception:
            wns_out = None
        if wns_out is None:
            logger.warning("SPAM-DET: failed step=measure "
                           "reason=wns_unmeasurable (nothing banked)")
            return
        store_dir = self.run_dir / "final_candidates"
        store_dir.mkdir(parents=True, exist_ok=True)
        store = store_dir / "recipe_pass_shallow_spamdet.dcp"
        try:
            res = await asyncio.wait_for(
                self.call_tool("vivado_write_checkpoint", {
                    "dcp_path": str(store.resolve()),
                    "force": True}),
                timeout=900.0)
        except Exception as e:
            res = (f'{{"error": "write_checkpoint raised '
                   f'{type(e).__name__}"}}')
        if _looks_like_tool_error(res) or not (
                store.exists() and store.stat().st_size > 0):
            logger.warning("SPAM-DET: failed step=store "
                           f"reason=write_checkpoint detail="
                           f"{str(res)[:120]} (nothing banked)")
            return
        try:
            registered = await self.register_final_candidate(
                store, float(wns_out), "recipe_pass_shallow_spamdet",
                verify=True)
        except Exception as e:
            logger.warning(
                f"SPAM-DET: register FAILED ({type(e).__name__}: "
                f"{e!r}); candidate dropped; caller's reset proceeds")
            return
        logger.info(
            f"SPAM-DET: result wns_in={wns_in:.3f} "
            f"wns_out={float(wns_out):.3f} registered={registered} "
            f"ff_before={ff_before} ff_after={ff_after} "
            f"dt={time.time() - t0:.0f}s (candidate competes ONLY at the "
            f"finalize MUX; caller resets to PRISTINE)")

    async def _recipe_pass_roundtrip(self, step_left: float,
                                     tag: str = "RECIPE-PASS") -> bool:
        """Deep-recipe session round-trip: write checkpoint -> restart
        Vivado -> reopen the checkpoint.  The restart is REQUIRED (the
        verified recipe's key ingredient is fresh session state; reusing the
        exact vivado_restart_vivado call + error-envelope check the
        candidate contract documents — the tool name trap and the error-
        STRING return are both real).  ``tag`` only prefixes the log lines
        (default keeps the pre-LLM slot's lines byte-identical; the
        post-loop slot passes "RECIPE-PASS[postloop]")."""
        mid = self.run_dir / "recipe_pass_midpoint.dcp"
        try:
            res = await asyncio.wait_for(
                self.call_tool("vivado_write_checkpoint", {
                    "dcp_path": str(mid.resolve()), "force": True}),
                timeout=max(60.0, step_left))
        except Exception as e:
            logger.warning(f"{tag}: roundtrip write raised "
                           f"{type(e).__name__}: {e!r}")
            return False
        if _looks_like_tool_error(res) or not (
                mid.exists() and mid.stat().st_size > 0):
            logger.warning(f"{tag}: roundtrip write failed "
                           f"({str(res)[:120]})")
            return False
        try:
            _r = await self.call_tool("vivado_restart_vivado", {})
            if isinstance(_r, str) and '"error"' in _r:
                logger.warning(f"{tag}: roundtrip restart returned "
                               f"error ({_r[:140]}) — aborting (the recipe "
                               f"is conditional on the fresh session)")
                return False
        except Exception as e:
            logger.warning(f"{tag}: roundtrip restart raised {e!r}")
            return False
        if not await self._presweep_reopen(mid):
            logger.warning(f"{tag}: roundtrip reopen failed")
            return False
        logger.info(f"{tag}: session round-trip complete "
                    f"(checkpoint -> fresh Vivado -> reopen)")
        return True

    async def _recipe_pass_reset_session(self, input_dcp: Path) -> None:
        """Contract steps 4-5 (presweep candidate mode, copied): restart
        Vivado BEFORE the LLM loop (M1: recipe place/route leaves process
        state that degrades every later place_design and open_checkpoint
        does NOT clear it), reopen the PRISTINE input, and do the lineage/
        allowance handling so downstream accounting starts clean."""
        try:
            _r = await self.call_tool("vivado_restart_vivado", {})
            if isinstance(_r, str) and '"error"' in _r:
                logger.warning(f"RECIPE-PASS: post-pass restart returned "
                               f"error ({_r[:140]}); staying in current "
                               f"session (pristine reopen still follows).")
            else:
                logger.info("RECIPE-PASS: restarted Vivado fresh before the "
                            "LLM loop (clears recipe session pollution).")
        except Exception as e:
            logger.warning(f"RECIPE-PASS: post-pass restart failed ({e!r}); "
                           "current session.")
        reopened = await self._presweep_reopen(input_dcp)
        if not reopened:
            logger.warning(
                "RECIPE-PASS: pristine re-open FAILED after the pass — the "
                "LLM loop will retry tool calls against whatever session "
                "state exists (finalize baseline-copy safety still holds).")
        # Lineage: the pass NEVER banks into best_valid (auto-bank
        # suppressed; candidate goes through register_final_candidate), so
        # unlike the presweep there is nothing to reset — assert the
        # invariant loudly instead of silently discarding a legitimate
        # pre-pass mirror (e.g. deep-replace[first] state).
        if self._pending_best_mirror:
            logger.warning("RECIPE-PASS: unexpected pending best-mirror "
                           "after the pass (invariant breach — leaving "
                           "lineage untouched).")
        # Improvement clock (contract parity with the presweep, so the
        # pass's elapsed wall is not read as pipeline stagnation; the
        # Phase-1 allowance shift happens in the caller over the FULL pass).
        self.last_improvement_iter = self.iteration
        self.last_improvement_time = time.time()
        logger.info(
            f"RECIPE-PASS: COMPLETE — pipeline enters "
            f"{'PRISTINE' if reopened else 'UNVERIFIED (reopen failed)'}; "
            f"{len(self._final_candidates)} non-pipeline candidate(s) "
            f"enrolled; remaining wall {self._budget_remaining():.0f}s.")

    def _recipe_first_deep_apply_reduced_tail(self) -> None:
        """FPL26_RECIPE_FIRST_DEEP reduced-tail step (aug04).

        Called ONLY from the flag-gated fire path (caller checks
        _recipe_first_deep_fired), AFTER the post-pass reset — so
        _budget_remaining() is the honest post-recipe figure.

        WHY: the fire gate replaced the 2400s deep-WNS tail reserve with
        the 1100s LLM floor; leaving the reserve itself at 2400s would
        contradict that arithmetic — on a size-gated design the loop's
        tail-reserve boundary (_tail_reserve_break_due: remaining <=
        effective reserve) would trip on the FIRST iteration and hand the
        LLM zero seconds, silently converting the variant into "recipe
        then straight to tail".  The reserve is therefore reduced so the
        loop keeps at least the LLM floor:
            new = min(current_effective, max(0, remaining - llm_floor))
        applied via _recipe_first_deep_tail_reserve_cap_s (consumed by
        _deep_wns_tail_reserve_effective_s; reduce-only by construction).
        The tail still gets whatever the loop leaves plus the reduced
        reserve — SHORTENED, which is the measured bet (constants block:
        recipe deterministic 5.15 vs n=13 tail/loop outcomes <= 4.14).

        Keyed on a BANKED candidate, never on fired alone: a fire that
        registered nothing has bought nothing, and shortening the
        deterministic tail on top of that loss would be exactly the
        "recipe miss eats the deep tail" fence failure mode REVIEW_V30
        MAJOR-1 candidate (b) was rejected over — the miss path keeps
        the full reserve.  Every branch logs; nothing here is silent."""
        cur = self._deep_wns_tail_reserve_effective_s()
        if not self._recipe_first_deep_banked:
            logger.info(
                f"RECIPE-FIRST-DEEP: tail reserve UNCHANGED at "
                f"{cur:.0f}s (recipe fired but banked no candidate — the "
                f"full deterministic tail is kept; reducing it on a miss "
                f"is the fence failure mode)")
            return
        if cur <= 0.0:
            logger.info(
                "RECIPE-FIRST-DEEP: tail reserve UNCHANGED (reserve not "
                "armed on this run — nothing to reduce; the loop already "
                "owns the remaining wall)")
            return
        try:
            llm_floor = float(getattr(
                self, "phys_opt_preempt_budget_floor_s", 1100.0))
        except (TypeError, ValueError):
            llm_floor = 1100.0
        # SCALED LLM FLOOR coherence (hardening (2), aug04 external
        # review): the fire gate reserved max(base, 0.35 x remaining_at_
        # gate) — the loop must keep THAT figure, not the smaller base.
        _gate_floor = self._recipe_first_deep_gate_llm_floor_s
        if _gate_floor is not None:
            llm_floor = max(llm_floor, float(_gate_floor))
        remaining = self._budget_remaining()
        if remaining == float("inf"):
            logger.info(
                f"RECIPE-FIRST-DEEP: tail reserve UNCHANGED at "
                f"{cur:.0f}s (no wall deadline — no boundary to reduce "
                f"against)")
            return
        new = max(0.0, min(cur, remaining - llm_floor))
        if new >= cur:
            logger.info(
                f"RECIPE-FIRST-DEEP: tail reserve UNCHANGED at "
                f"{cur:.0f}s (remaining {remaining:.0f}s already leaves "
                f"the loop >= the {llm_floor:.0f}s LLM floor above it)")
            return
        self._recipe_first_deep_tail_reserve_cap_s = new
        if new <= 0.0:
            # MINOR-1 fix (adversarial review aug04): when remaining <=
            # the floor the cap is ZERO — the deterministic tail window
            # is gone, not shortened, and the log must say so.
            logger.info(
                f"RECIPE-FIRST-DEEP: recipe-first: tail reserve reduced "
                f"{cur:.0f}s->0s because the recipe candidate is "
                f"banked (remaining {remaining:.0f}s; loop keeps the "
                f"{llm_floor:.0f}s LLM floor; tail ELIMINATED "
                f"(remaining <= floor) — the measured reduced-tail bet, "
                f"see RECIPE_FIRST_DEEP_* constants)")
        else:
            logger.info(
                f"RECIPE-FIRST-DEEP: recipe-first: tail reserve reduced "
                f"{cur:.0f}s->{new:.0f}s because the recipe candidate is "
                f"banked (remaining {remaining:.0f}s; loop keeps the "
                f"{llm_floor:.0f}s LLM floor; tail runs SHORTENED — the "
                f"measured reduced-tail bet, see RECIPE_FIRST_DEEP_* "
                f"constants)")

    async def _maybe_run_recipe_pass_postloop(self) -> None:
        """FPL26_RECIPE_PASS POST-LOOP slot (aug03, REVIEW_V30_DIFF_aug03.md
        MAJOR-1 redesign candidate (a)): the frozen-Tcl candidate pass, run
        from STRANDED wall at the single exit tail.

        WHY THIS SLOT EXISTS (MAJOR-1): the pre-LLM slot's deep gate needs
        pass budget 1350s + overheads 900s + deep-WNS tail reserve 2400s =
        4650s, but _budget_deadline = start + MAX_WALL - 300 caps remaining
        at 3200s on the ship wall (MAX_WALL 3500) — the deep band (the only
        SCORED recipe evidence, vtr_v2 +0.45) is UNARMABLE there.  HERE —
        after the LLM loop AND every polish stage (ILS / bare-reroute /
        deep-replace tail) have finished, immediately before
        _finalize_output_dcp — the remaining wall is wall NOTHING else will
        consume (750-1300s measured stranded per run), and two of the
        pre-LLM gate's reserve terms honestly VANISH:
          * deep-WNS tail reserve (2400s): it funds the tail stages that
            run AFTER the pre-LLM slot; at this point they have already
            run.  There is nothing downstream to protect but finalize,
            which _budget_deadline already reserves 300s for (optimize()
            deadline setup — do NOT re-subtract it here: the deep-replace
            gate's double-reserve defect, project_double_reserve_defect
            _jul30, was exactly that).
          * Vivado reset reserve (360s expected / 1800s ship-scale cap):
            there is no LLM loop left to hand a pristine session to — see
            RECIPE_PASS_POSTLOOP_OVERHEAD_RESERVE_S and the session-state
            audit in the inner.
        Nothing new decides shipping: the result enrolls via
        register_final_candidate (same routed/hold/cell gates) and competes
        at _maybe_ship_final_candidate_mux's argmax-by-WNS + structural
        validate — never-worse is enforced THERE, exactly like the pre-LLM
        slot and the deep-replace/replace_gamble candidates.

        Stable log keys (firing audit greps "RECIPE-PASS\\[postloop\\]: "):
          "RECIPE-PASS[postloop]: ARMED band=...",
          "RECIPE-PASS[postloop]: fired recipe=...",
          "RECIPE-PASS[postloop]: skipped reason=..."
            (reason= disabled / already_fired / band / no_pristine_input /
             wall / exception).
        """
        if not recipe_pass_enabled():
            # Reached-but-disabled must be distinguishable from
            # never-called (feedback_firing_check_must_key_on_treatment).
            # Flag-off ship cost: this ONE log line at the exit tail —
            # same disclosed class as the pre-LLM slot (REVIEW_V30 NOTE-1
            # precedent: deep-replace[first] "hook REACHED" logs before
            # its enable check).
            logger.info("RECIPE-PASS[postloop]: skipped reason=disabled "
                        "(FPL26_RECIPE_PASS off or FPL26_NO_RECIPE_PASS set)")
            return
        # LLM-INVISIBILITY tag — same contract as the pre-LLM slot
        # (aug04 exposure investigation): the slot's tool calls are
        # log-only machinery; tag their tool_call_details entries so no
        # prompt-side consumer ever renders them.  (Post-loop there is
        # no further LLM call in-run; the tag still matters for any
        # end-of-run prompt-adjacent consumer and keeps the invariant
        # uniform across ALL paths: fired, skipped, postloop.)
        _tc0 = len(self.tool_call_details)
        try:
            await self._run_recipe_pass_postloop_inner()
        except Exception as e:
            # Exception-safe by contract: finalize MUST still run.  The
            # session may be left mid-recipe; that is the same state class
            # a failed deep-replace tail leaves, and finalize is
            # disk-truth-driven (see the audit in the inner).
            logger.warning(f"RECIPE-PASS[postloop]: skipped reason=exception "
                           f"{type(e).__name__}: {e!r} (non-fatal; finalize "
                           f"proceeds on disk truth)")
        finally:
            for _d in self.tool_call_details[_tc0:]:
                try:
                    _d["recipe_pass_internal"] = True
                except Exception:
                    pass

    async def _run_recipe_pass_postloop_inner(self) -> None:
        """Post-loop gates + recipe execution + candidate registration.

        Execution is a faithful copy of _run_recipe_pass_inner's execution
        contract (pristine preopen -> frozen steps under a hard pass
        deadline -> measure -> private store -> register_final_candidate
        verify=True); ONLY the gate arithmetic and the post-pass session
        handling differ, and both differences are argued inline.

        SESSION STATE LEFT BEHIND (requirement: preserve the downstream
        contract EXACTLY): this slot deliberately does NOT restart/reopen
        after the recipe.  Audit of everything between this slot and
        process exit (all in this file):
          * the D3 wall-handback log block and _finalize_output_dcp are
            the only code after the slot in _exit_with_ils_polish;
          * MUX candidate-wins path: _structural_validate_dcp re-opens the
            candidate itself before trusting it, and the EDIF regen
            re-opens the shipped output first — both replace whatever
            session state exists;
          * pipeline fast path: pure disk copy of the best_valid mirror
            (_atomic_copy); fresh-EDIF-mirror branch is also a disk copy;
          * no-improvement path: baseline disk copy; its slow EDIF path
            re-opens output_dcp before write_edif;
          * finalize Step 3: re-opens output_dcp before writing EDIF (and
            refuses on an error envelope — jul20 review S4);
          * the ONE live-session reader is _finalize_refresh_edif (fast
            path with a STALE EDIF mirror), which writes EDIF from memory
            WITHOUT reopening — a documented pre-existing F1 risk
            ("trace, do not patch"), and the deep-replace tail already
            leaves ITS candidate/attempt state in-session at this exact
            point (registers verify=False, "no session re-open, shipping
            state undisturbed").  Exposure class is PARITY with the
            validated surface, not new — and HARDENED beyond it
            (MAJOR-2, postloop review aug03): once this slot mutates the
            session it sets _finalize_session_untrusted, and that branch
            now REFUSES the live-session regen (ships
            VALID_OPTIMIZED_NO_EDIF) instead of stamping a
            different-flow netlist EDIF onto the shipped DCP.
        Restoring the session would cost the ship-scale restart+reopen
        reserve (up to 1800s) that made the pre-LLM deep gate dead code —
        the arithmetic this redesign exists to fix.

        NEVER touches best_valid: auto-bank is suppressed for the whole
        pass (_tail_ctrl_suppress_autobank bracket, presweep pattern) AND
        the _in_ils_stage bracket bypasses the auto-bank hook as well;
        banking happens only via register_final_candidate -> finalize MUX.
        """
        wns_in = self.initial_wns  # measured once at open; NOT re-measured
        band = recipe_pass_band(wns_in)
        if band is None:
            logger.info("RECIPE-PASS[postloop]: skipped reason=band "
                        "(initial_wns unmeasured/non-negative — no honest "
                        "band key)")
            return
        logger.info(f"RECIPE-PASS[postloop]: ARMED band={band} "
                    f"wns_in={wns_in:.3f}")
        if self._recipe_pass_preloop_fired:
            # Double-fire guard (MINOR-1 fix, postloop review aug03: claim
            # only what the marker proves).  The marker is set at the
            # pre-LLM "fired" log — BEFORE its first mutation — so it
            # guarantees the pre-LLM pass STARTED this band's recipe; it
            # does NOT guarantee the pass completed or registered a
            # candidate (a pass that died pre-registration still sets it,
            # and re-running here would double-spend the same recipe).
            logger.info("RECIPE-PASS[postloop]: skipped reason=already_fired "
                        "(pre-LLM pass already mutated a session this "
                        "process; registration not implied)")
            return
        if band == "shallow":
            # The shallow recipe's home is the PRE-LLM slot: its gate
            # (450 + 900 + 1100 = 2450s) IS satisfiable on the ship wall,
            # so it fires there or was refused for wall — and post-loop
            # stranded wall is characteristically SMALLER than the
            # pre-loop remaining that refused it.  This slot exists for
            # the bands the pre-LLM gate can never arm (deep; mid stays
            # arithmetic-dormant below).
            logger.info("RECIPE-PASS[postloop]: skipped reason=band "
                        "(shallow is the pre-LLM slot's band; post-loop "
                        "targets pre-LLM-unarmable bands only)")
            return
        input_dcp = self.input_dcp_path
        if not (input_dcp and Path(input_dcp).exists()):
            logger.info("RECIPE-PASS[postloop]: skipped reason="
                        "no_pristine_input (input DCP missing on disk — "
                        "cannot honor the pristine-reopen contract, "
                        "EXPLORATION_PLAN FIND #2)")
            return
        if self._wall_handback_break_due():
            # MAJOR-1 fix (postloop review aug03): the first version of
            # this comment claimed the handback kill switch is OFF at
            # ship — FACTUALLY INVERTED, the two-layer Makefile trap
            # (project_ship_config_composition_jul30): Makefile:338/418
            # pass --wall-handback unless explicitly disabled
            # ($(if $(filter 0 false no off,$(WALL_HANDBACK)),,...)),
            # the wrapper forwards it per attempt
            # (scripts/multi_restart_optimize.py:590-591), and
            # dcp_optimizer.py:16179 arms _wall_handback_enabled — the
            # ship default is ON (8da68da).  So on saturation-armed runs
            # — exactly the early-saturating, high-stranded class this
            # slot targets — the remaining wall is NOT stranded: it is
            # spoken for by the PROVEN shipped lever (gamma handback).
            # The slot DEFERS rather than racing it for the same
            # seconds; the A/B measures the residual firing set only.
            # Checked BEFORE any session mutation, and evaluated ONLY on
            # the flag-ON branch (this inner is unreachable unless
            # recipe_pass_enabled()).
            logger.info(
                f"RECIPE-PASS[postloop]: skipped reason=handback_armed "
                f"band={band} remaining={self._budget_remaining():.0f}s "
                f"(wall-handback is the proven lever on this run class; "
                f"recipe defers — A/B the residual firing set only)")
            return
        steps = {"deep": RECIPE_PASS_DEEP_TCL,
                 "mid": RECIPE_PASS_MID_TCL}[band]
        expected_s = {"deep": RECIPE_PASS_DEEP_EXPECTED_S,
                      "mid": RECIPE_PASS_MID_EXPECTED_S}[band]
        remaining = self._budget_remaining()
        overhead = RECIPE_PASS_POSTLOOP_OVERHEAD_RESERVE_S
        _overhead_terms = (
            f"[measure {RECIPE_PASS_MEASURE_RESERVE_S:.0f} + store "
            f"{RECIPE_PASS_STORE_RESERVE_S:.0f} + register "
            f"{RECIPE_PASS_REGISTER_RESERVE_S:.0f}; NO reset term — "
            f"session left as-is, NO tail reserve — tail stages already "
            f"ran, NO LLM floor — loop is done]")
        if band == "deep":
            # remaining >= 1.5 x verified cost + post-loop overheads.
            # = 1350 + 540 = 1890s.  On MAX_WALL=3500 this is REACHABLE
            # (max remaining 3200s) whenever the loop+polish strand
            # >= 1890s — unlike the pre-LLM gate's 4650s (MAJOR-1).
            # The 750-1300s TYPICAL stranded band still skips honestly;
            # the slot fires on early-saturating runs only.
            need = RECIPE_PASS_TIMEOUT_FACTOR * expected_s + overhead
            if remaining < need:
                logger.info(
                    f"RECIPE-PASS[postloop]: skipped reason=wall band=deep "
                    f"(remaining {remaining:.0f}s < pass budget "
                    f"{RECIPE_PASS_TIMEOUT_FACTOR * expected_s:.0f}s "
                    f"(1.5x{expected_s:.0f}) + overheads {overhead:.0f}s "
                    f"{_overhead_terms} = {need:.0f}s — fail closed; "
                    f"stranded wall too small for the deep recipe)")
                return
        else:  # band == "mid"
            # Mid stays DORMANT-BY-ARITHMETIC here too (mirror of the
            # pre-LLM mid gate): the corescore recipe's MEASURED cross-box
            # cost is 2800s (un-margined on purpose — even that cannot
            # fit), + 540s overheads = 3340s, but post-loop stranded wall
            # measures 750-1300s and can never exceed the 3200s ship-wall
            # maximum remaining.  Present, fail-closed, honest skip; a
            # DEBUG-WALL run (MAX_WALL 8000-9000) CAN fund it, which is
            # exactly the behaviour-only validation channel.
            need = expected_s + overhead
            if remaining < need:
                logger.info(
                    f"RECIPE-PASS[postloop]: skipped reason=wall band=mid "
                    f"(remaining {remaining:.0f}s < measured recipe cost "
                    f"{expected_s:.0f}s (cross-box probe, boxes 4/5) + "
                    f"overheads {overhead:.0f}s {_overhead_terms} = "
                    f"{need:.0f}s.  Stranded wall (750-1300s measured) "
                    f"cannot fund 2800s — DORMANT-BY-ARITHMETIC on the "
                    f"ship wall, same honest-skip contract as the "
                    f"pre-LLM mid gate)")
                return
        # Hard per-pass deadline: 1.5x the verified cost, additionally
        # capped so the out-of-deadline overheads stay funded.  NOTE the
        # deliberate difference from the pre-LLM inner: we do NOT subtract
        # RECIPE_PASS_FINALIZE_RESERVE_S here — _budget_deadline already
        # holds back the 300s finalize reserve (optimize() setup;
        # _deadline_aware_timeout's own docstring: "We do not subtract
        # reserve again here"), and re-subtracting it is the
        # double-reserve defect class (project_double_reserve_defect
        # _jul30).  The pre-LLM inner's extra -300 is its own disclosed
        # convention (REVIEW_V30 NOTE-2, conservative direction).
        # MINOR-3 (postloop review aug03), honestly stated: the 540s
        # overhead reserve is a TYPICAL-cost estimate, NOT a bound — the
        # post-step ops may legally spend up to their deadline-fenced
        # caps (measure <=600s, store <=900s, register deadline-capped).
        # The deadline fencing is the hard guarantee; an overrun wastes
        # wall (gamma) but cannot DQ.
        pass_budget = RECIPE_PASS_TIMEOUT_FACTOR * expected_s
        if remaining != float("inf"):
            pass_budget = min(pass_budget, remaining - overhead)
        if pass_budget < 60.0:
            logger.info(f"RECIPE-PASS[postloop]: skipped reason=wall "
                        f"(pass budget {pass_budget:.0f}s < 60s floor)")
            return
        logger.info(f"RECIPE-PASS[postloop]: fired recipe={band} "
                    f"wns_in={wns_in:.3f} (pass_budget={pass_budget:.0f}s, "
                    f"steps={len(steps)}, remaining={remaining:.0f}s)")
        t0 = time.time()
        pass_deadline = t0 + pass_budget
        # The recipes are verified RELATIVE TO THE INPUT STATE
        # (EXPLORATION_PLAN aug03 FIND #2 — non-negotiable): the loop's
        # final session state is arbitrary, so start from an explicit
        # pristine reopen.
        prev_suppress = self._tail_ctrl_suppress_autobank
        self._tail_ctrl_suppress_autobank = True
        # SELF-CAPPED STAGE BYPASS — copied from the deep-replace tail's
        # audited pattern (save/restore, not assign-False): post-loop a
        # banked best almost always exists, so WITHOUT this bracket the
        # unroute gate / polish-reserve fence / router block would refuse
        # the recipe's own `route_design -unroute` (REVIEW_V30 MINOR-4 is
        # that exact abort on the pre-LLM slot) and the slot would be dead
        # code again.  The bypass is legitimate for the same reason the
        # deep-replace stage claims it: every step here is bounded by
        # pass_deadline, and call_tool's deadline-aware timeout still
        # fences the absolute wall (_in_ils_stage passes tool_name=None,
        # so timeout = full remaining, never past _budget_deadline).
        prev_ils_flag = self._in_ils_stage
        self._in_ils_stage = True
        try:
            # MAJOR-2 (postloop review aug03): from this point the live
            # session no longer matches the pipeline's best_valid state
            # (even a FAILED preopen may have disturbed it).  Mark it
            # untrusted so _finalize_refresh_edif's no-reopen branch (the
            # F1 risk) refuses instead of pairing a different flow's
            # netlist EDIF with the shipped DCP.  Never cleared.
            self._finalize_session_untrusted = True
            if not await self._presweep_reopen(input_dcp):
                logger.warning("RECIPE-PASS[postloop]: failed "
                               "step=pristine_preopen (recipe not run; "
                               "wall lost, nothing banked)")
                return
            for i, step in enumerate(steps, 1):
                step_left = pass_deadline - time.time()
                if step_left < 30.0:
                    logger.warning(
                        f"RECIPE-PASS[postloop]: failed step={i}/{len(steps)} "
                        f"reason=pass_timeout ({pass_budget:.0f}s budget "
                        f"exhausted before '{step}'; aborting — wall lost, "
                        f"nothing banked)")
                    return
                if step == RECIPE_PASS_SESSION_ROUNDTRIP:
                    ok = await self._recipe_pass_roundtrip(
                        step_left, tag="RECIPE-PASS[postloop]")
                    if not ok:
                        logger.warning(
                            f"RECIPE-PASS[postloop]: failed "
                            f"step={i}/{len(steps)} "
                            f"reason=session_roundtrip (aborting)")
                        return
                    continue
                try:
                    res = await asyncio.wait_for(
                        self.call_tool("vivado_run_tcl",
                                       {"command": step,
                                        "timeout": float(step_left)}),
                        timeout=float(step_left) + 60.0)
                except Exception as e:
                    logger.warning(
                        f"RECIPE-PASS[postloop]: failed step={i}/{len(steps)} "
                        f"reason=step_raised:{type(e).__name__} "
                        f"cmd='{step}' (aborting)")
                    return
                if _looks_like_tool_error(res):
                    logger.warning(
                        f"RECIPE-PASS[postloop]: failed step={i}/{len(steps)} "
                        f"reason=step_error cmd='{step}' "
                        f"detail={str(res)[:120]} (aborting)")
                    return
            # ---- measure + private store + register (contract 1-3, same
            # as the pre-LLM inner) ----
            try:
                wns_out = await asyncio.wait_for(
                    self.get_wns_for_target_clock(self._call_vivado_tool),
                    timeout=600.0)
            except Exception:
                wns_out = None
            if wns_out is None:
                logger.warning("RECIPE-PASS[postloop]: failed step=measure "
                               "reason=wns_unmeasurable (nothing banked)")
                return
            store_dir = self.run_dir / "final_candidates"
            store_dir.mkdir(parents=True, exist_ok=True)
            store = store_dir / f"recipe_pass_postloop_{band}.dcp"
            try:
                res = await asyncio.wait_for(
                    self.call_tool("vivado_write_checkpoint", {
                        "dcp_path": str(store.resolve()),
                        "force": True}),
                    timeout=900.0)
            except Exception as e:
                res = (f'{{"error": "write_checkpoint raised '
                       f'{type(e).__name__}"}}')
            if _looks_like_tool_error(res) or not (
                    store.exists() and store.stat().st_size > 0):
                logger.warning("RECIPE-PASS[postloop]: failed step=store "
                               f"reason=write_checkpoint detail="
                               f"{str(res)[:120]} (nothing banked)")
                return
            # In-memory state == the candidate on disk, so verify=True
            # re-runs the exact routed/hold/cell gates against it (the
            # same contract the presweep + pre-LLM registrations rely on).
            registered = await self.register_final_candidate(
                store, float(wns_out), f"recipe_pass_postloop_{band}",
                verify=True)
            logger.info(
                f"RECIPE-PASS[postloop]: result recipe={band} "
                f"wns_in={wns_in:.3f} wns_out={float(wns_out):.3f} "
                f"registered={registered} dt={time.time() - t0:.0f}s "
                f"(candidate competes ONLY at the finalize MUX; session "
                f"left on the recipe state — finalize is disk-truth-"
                f"driven, see the session audit in this method's "
                f"docstring)")
        finally:
            self._in_ils_stage = prev_ils_flag
            self._tail_ctrl_suppress_autobank = prev_suppress
            # NO session reset, NO phase-1 allowance shift (the shift
            # protects allowance-keyed gates DOWNSTREAM of the pre-LLM
            # slot; the only allowance consumer runs inside Phase 1,
            # long finished), NO improvement-clock touch (nothing after
            # this slot reads the stagnation clock).  Lineage invariant
            # (presweep-contract parity, same assert-loudly-not-reset
            # choice as _recipe_pass_reset_session): the pass never banks
            # into best_valid, so a pending mirror here is a breach.
            if self._pending_best_mirror:
                logger.warning("RECIPE-PASS[postloop]: unexpected pending "
                               "best-mirror after the pass (invariant "
                               "breach — leaving lineage untouched).")

    async def _maybe_run_corescore_route_rung_postloop(self) -> None:
        """FPL26_CORESCORE_ROUTE_RUNG (aug05; v4.1 rev2 BREAK redesign,
        DEFAULT OFF): the retime-BREAK chain as a POST-LOOP candidate
        step for MID-band designs, running from the BANKED BEST state
        and claiming its priced wall BEFORE the wall-handback exit
        decision.  See the CORESCORE_BREAK_RUNG_* constants block for
        the mechanism evidence (-0.612/438.79 deterministic x4 incl.
        in-session cs3 and cross-box; +7.76 MHz over the banked record)
        and the pricing (need = 810 + 540 = 1350 s, deadline 1215 s).

        v4.0 history: the route-Explore variant of this rung shipped
        INERT (0 fires x2 — handback claimed the wall first via this
        method's own reason=handback_armed defer).  The redesign REMOVES
        that defer: when the mid-band + banked-best gates pass, the rung
        claims its priced wall out of what handback would return, and
        handback still gets the remainder (this slot sits immediately
        before the exit tail's handback log + finalize).  Outside the
        gates — and with the flag off/killed — handback behavior is
        byte-identical to shipped v4.0.1.

        POST-LOOP ONLY (PODF lesson: a pre-loop stage pre-empts the
        LLM's better call).  Runs from the BANKED BEST state — the
        break evidence is unroute->retime->poAE->routeAE FROM the
        polished attractor state, not from pristine.  Bracket contract
        unchanged: auto-bank suppressed, _in_ils_stage set,
        _finalize_session_untrusted on first mutation, register via
        register_final_candidate verify=True -> finalize MUX argmax =
        never-worse; best_valid is READ (its mirror file is never
        written) and never re-banked.  The chain retimes, so the SHARED
        FF latency audit applies (fail closed).

        Stable log keys: "ROUTE-RUNG[postloop]: skipped reason=..."
        (disabled / band / no_banked_best / wall / exception),
        "ROUTE-RUNG[postloop]: claiming", "ROUTE-RUNG[postloop]: fired",
        "ROUTE-RUNG[postloop]: ff-audit", "ROUTE-RUNG[postloop]: result".
        """
        if not corescore_route_rung_enabled():
            if v40_flag_env_present("FPL26_CORESCORE_ROUTE_RUNG",
                                    "FPL26_NO_CORESCORE_ROUTE_RUNG"):
                logger.info("ROUTE-RUNG[postloop]: skipped reason=disabled "
                            "(FPL26_CORESCORE_ROUTE_RUNG off or "
                            "FPL26_NO_CORESCORE_ROUTE_RUNG set)")
            return
        wns_in = self.initial_wns
        band = recipe_pass_band(wns_in)
        if band != "mid":
            logger.info(f"ROUTE-RUNG[postloop]: skipped reason=band "
                        f"band={band} wns_in={wns_in} (mid-band-only "
                        f"scope, 1.05 < |wns_in| < 8.0)")
            return
        best = self._best_valid_dcp
        if best is None or not Path(best).exists():
            # The break's mechanism needs the polished attractor state; a
            # run that banked nothing has no evidence-bearing input.
            logger.info("ROUTE-RUNG[postloop]: skipped reason="
                        "no_banked_best (break is proven FROM the polished "
                        "state; pristine input is out of evidence)")
            return
        # v4.1 rev2: NO handback defer here (the v4.0 rung's INERT
        # cause).  The rung claims its priced wall ahead of the handback
        # exit decision; handback returns whatever remains after it.
        # Scope of the reallocation = corescore-mid + banked-best only
        # (the two gates above), pre-registered as the riskiest v4.1
        # piece.
        if self._wall_handback_break_due():
            logger.info(
                f"ROUTE-RUNG[postloop]: claiming priced wall AHEAD of "
                f"wall-handback (remaining={self._budget_remaining():.0f}s; "
                f"handback returns the remainder after the rung — "
                f"corescore-mid-only scope bounds the reallocation)")
        remaining = self._budget_remaining()
        overhead = RECIPE_PASS_POSTLOOP_OVERHEAD_RESERVE_S  # 540
        need = CORESCORE_BREAK_RUNG_EXPECTED_S + overhead   # 1350
        if remaining < need:
            logger.info(
                f"ROUTE-RUNG[postloop]: skipped reason=wall "
                f"(remaining {remaining:.0f}s < measured break cost "
                f"{CORESCORE_BREAK_RUNG_EXPECTED_S:.0f}s (un-margined, "
                f"measured-cost convention; cs3 in-session 806s) + "
                f"overheads {overhead:.0f}s "
                f"[measure {RECIPE_PASS_MEASURE_RESERVE_S:.0f} + store "
                f"{RECIPE_PASS_STORE_RESERVE_S:.0f} + register "
                f"{RECIPE_PASS_REGISTER_RESERVE_S:.0f}; no reset/tail/LLM "
                f"terms post-loop] = {need:.0f}s — fail closed; whatever "
                f"wall exists stays with handback)")
            return
        pass_budget = (RECIPE_PASS_TIMEOUT_FACTOR
                       * CORESCORE_BREAK_RUNG_EXPECTED_S)  # 1215
        if remaining != float("inf"):
            pass_budget = min(pass_budget, remaining - overhead)
        if pass_budget < 60.0:
            logger.info(f"ROUTE-RUNG[postloop]: skipped reason=wall "
                        f"(pass budget {pass_budget:.0f}s < 60s floor)")
            return
        logger.info(f"ROUTE-RUNG[postloop]: fired band=mid "
                    f"wns_in={wns_in:.3f} best_wns={self.best_wns} "
                    f"(pass_budget={pass_budget:.0f}s, break chain "
                    f"steps={len(CORESCORE_BREAK_RUNG_TCL)} from the "
                    f"banked best state)")
        t0 = time.time()
        pass_deadline = t0 + pass_budget
        _tc0 = len(self.tool_call_details)
        prev_suppress = self._tail_ctrl_suppress_autobank
        self._tail_ctrl_suppress_autobank = True
        prev_ils_flag = self._in_ils_stage
        self._in_ils_stage = True
        try:
            # Session diverges from the pipeline state from here on —
            # same MAJOR-2 contract as the postloop RECIPE_PASS slot.
            self._finalize_session_untrusted = True
            if not await self._presweep_reopen(Path(best)):
                logger.warning("ROUTE-RUNG[postloop]: failed "
                               "step=best_reopen (break not run; wall "
                               "lost, nothing banked)")
                return
            ff_before = None
            ff_after = None
            for i, step in enumerate(CORESCORE_BREAK_RUNG_TCL, 1):
                step_left = pass_deadline - time.time()
                if step_left < 30.0:
                    logger.warning(
                        f"ROUTE-RUNG[postloop]: failed step="
                        f"{i}/{len(CORESCORE_BREAK_RUNG_TCL)} "
                        f"reason=pass_timeout ({pass_budget:.0f}s budget "
                        f"exhausted before '{step}'; aborting — wall "
                        f"lost, nothing banked)")
                    return
                try:
                    res = await asyncio.wait_for(
                        self.call_tool("vivado_run_tcl",
                                       {"command": step,
                                        "timeout": float(step_left)}),
                        timeout=float(step_left) + 60.0)
                except Exception as e:
                    logger.warning(
                        f"ROUTE-RUNG[postloop]: failed step="
                        f"{i}/{len(CORESCORE_BREAK_RUNG_TCL)} "
                        f"reason=step_raised:{type(e).__name__} "
                        f"cmd='{step}' (aborting)")
                    return
                if _looks_like_tool_error(res):
                    logger.warning(
                        f"ROUTE-RUNG[postloop]: failed step="
                        f"{i}/{len(CORESCORE_BREAK_RUNG_TCL)} "
                        f"reason=step_error cmd='{step}' "
                        f"detail={str(res)[:120]} (aborting)")
                    return
                # LATENCY AUDIT probes (shared FFCOUNT= sentinel
                # helper): FF count after the unroute step (= before
                # retime) and after the retime step.
                if step == "route_design -unroute":
                    ff_before = await self._vex2_retime_ff_count(
                        min(300.0, max(60.0, pass_deadline - time.time())),
                        tag="ROUTE-RUNG[postloop]")
                elif step == "phys_opt_design -retime":
                    ff_after = await self._vex2_retime_ff_count(
                        min(300.0, max(60.0, pass_deadline - time.time())),
                        tag="ROUTE-RUNG[postloop]")
            # ---- latency audit (DQ protection; fails CLOSED) ----
            if not vex2_retime_ff_drift_ok(ff_before, ff_after):
                logger.warning(
                    f"ROUTE-RUNG[postloop]: ABORTED reason=latency_audit "
                    f"ff_before={ff_before} ff_after={ff_after} "
                    f"(drift beyond +-{VEX2_RETIME_FF_DRIFT_MAX_FRAC:.0%} "
                    f"or unmeasured — protections fail ON; candidate NOT "
                    f"registered)")
                return
            logger.info(
                f"ROUTE-RUNG[postloop]: ff-audit PASS "
                f"ff_before={ff_before} ff_after={ff_after} "
                f"(drift "
                f"{abs(ff_after - ff_before) / float(ff_before):.4%}"
                f" <= {VEX2_RETIME_FF_DRIFT_MAX_FRAC:.0%})")
            # ---- measure + private store + register ----
            try:
                wns_out = await asyncio.wait_for(
                    self.get_wns_for_target_clock(self._call_vivado_tool),
                    timeout=600.0)
            except Exception:
                wns_out = None
            if wns_out is None:
                logger.warning("ROUTE-RUNG[postloop]: failed step=measure "
                               "reason=wns_unmeasurable (nothing banked)")
                return
            store_dir = self.run_dir / "final_candidates"
            store_dir.mkdir(parents=True, exist_ok=True)
            store = store_dir / "route_rung_mid_break.dcp"
            try:
                res = await asyncio.wait_for(
                    self.call_tool("vivado_write_checkpoint", {
                        "dcp_path": str(store.resolve()),
                        "force": True}),
                    timeout=900.0)
            except Exception as e:
                res = (f'{{"error": "write_checkpoint raised '
                       f'{type(e).__name__}"}}')
            if _looks_like_tool_error(res) or not (
                    store.exists() and store.stat().st_size > 0):
                logger.warning("ROUTE-RUNG[postloop]: failed step=store "
                               f"reason=write_checkpoint detail="
                               f"{str(res)[:120]} (nothing banked)")
                return
            try:
                registered = await self.register_final_candidate(
                    store, float(wns_out), "route_rung_mid_break",
                    verify=True)
            except Exception as e:
                logger.warning(f"ROUTE-RUNG[postloop]: register FAILED "
                               f"({type(e).__name__}: {e!r}); candidate "
                               f"dropped (finalize proceeds on disk truth)")
                return
            logger.info(
                f"ROUTE-RUNG[postloop]: result wns_in={wns_in:.3f} "
                f"wns_out={float(wns_out):.3f} registered={registered} "
                f"ff_before={ff_before} ff_after={ff_after} "
                f"dt={time.time() - t0:.0f}s (candidate competes ONLY at "
                f"the finalize MUX; session left on the break state — "
                f"finalize is disk-truth-driven, postloop-slot contract)")
        finally:
            self._in_ils_stage = prev_ils_flag
            self._tail_ctrl_suppress_autobank = prev_suppress
            for _d in self.tool_call_details[_tc0:]:
                try:
                    _d["recipe_pass_internal"] = True
                except Exception:
                    pass
            if self._pending_best_mirror:
                logger.warning("ROUTE-RUNG[postloop]: unexpected pending "
                               "best-mirror after the rung (invariant "
                               "breach — leaving lineage untouched).")

    def _wns_tcl_for_stages(self) -> str:
        """Target-clock-aware WNS query, shared by terminal stages.

        Extracted jul25 so the deep-replace sibling can run from the single
        exit tail (_exit_with_ils_polish) rather than only from inside
        _run_ils_polish_stage, which is gated off for large designs
        ("ILS-polish loop-exit trigger NOT armed (too_large(cells=379048))"
        on boom_soc — the exact DEEP-extreme class the sibling targets)."""
        if self.target_clock:
            return (
                f"set clk_obj [get_clocks -quiet {{{self.target_clock}}}]; "
                f"if {{$clk_obj ne {{}}}} {{ set tp [get_timing_paths -max_paths 1 "
                f"-setup -to $clk_obj]; if {{[llength $tp] > 0}} {{get_property SLACK $tp}} "
                f"else {{puts 0.0}} }} else {{ set tp [get_timing_paths -max_paths 1 "
                f"-slack_lesser_than 999]; if {{[llength $tp] > 0}} {{get_property SLACK $tp}} "
                f"else {{puts 0.0}} }}")
        return ("set tp [get_timing_paths -max_paths 1 -slack_lesser_than 999]; "
                "if {[llength $tp] > 0} {get_property SLACK $tp} else {puts 0.0}")

    async def _deep_replace_sibling_after_polish(
        self, deadline: float, wns_tcl: str, *,
        stage_label: str = "tail",
        cost_basis_override: Optional[float] = None,
        basis_note: str = "",
    ) -> None:
        """DEEP-WNS full re-place from the PRISTINE input -> MUX candidate.

        Called from TWO places (jul25):
          * ``_exit_with_ils_polish`` — the original exit tail, where the cost
            anchor comes from this run's observed ILS cycle;
          * ``_maybe_run_recipe_first`` — BEFORE the LLM loop, where no heavy
            step has run yet, so the caller passes ``cost_basis_override`` from
            the size model. ``stage_label``/``basis_note`` only affect logging,
            so the two paths cannot diverge in gate behaviour.

        jul25 panel, grok-4.5 seat (the only Scale-1 killer, E[alpha hidden]
        +10). boom_soc's validated all-time best is +35.47; last night we got
        +13.32, a -22.15 gap -- the largest in the portfolio. The record run
        reopened the ORIGINAL benchmark DCP and did a full re-placement, which
        R1's DEEP-extreme branch never does ("retiming is the slow step").

        This deliberately does NOT touch the router. It adds a candidate to the
        insured-compare MUX, which picks by measured WNS -- never-worse by
        construction. Gate reuses the router's OWN published constants
        (R1_FAILING_ENDPOINTS_MIN, R1_ROUTE_FIRST_WNS_NS); no new cut is fitted.

        Strict no-op with the flag off (default)."""
        # Log REACHED before the enabled check. jul25: chain8 produced
        # deep_replace=0 and it was impossible to tell "never called" from
        # "called but disabled" — a null result you cannot interpret is worth
        # nothing (the M1-echo trap). Reachability is now always visible.
        cfg = self._ils_polish_cfg
        _en = bool(getattr(cfg, "deep_replace_enabled", False))
        logger.info(f"deep-replace[{stage_label}]: stage REACHED "
                    f"(enabled={_en})")
        if not _en:
            return
        from optimizer.deep_replace_sibling import (
            DEEP_REPLACE_COST_MARGIN, VERDICT_ADOPTED, VERDICT_ERROR,
            deep_replace_should_run, run_deep_replace_sibling)
        from optimizer.ils_polish import (_measure, _measure_hold, _tool_ok,
                                          derive_cost_anchors)
        from optimizer.replace_gamble import replace_gamble_cost_basis
        try:
            from optimizer.recipe_router import (R1_FAILING_ENDPOINTS_MIN,
                                                 R1_ROUTE_FIRST_WNS_NS)
        except Exception:
            logger.warning("deep-replace: router constants unavailable; "
                           "skipping (fail closed).")
            return

        pristine = (str(self.input_dcp_path)
                    if self.input_dcp_path and self.input_dcp_path.exists()
                    else None)
        if cost_basis_override and cost_basis_override > 0:
            basis = float(cost_basis_override)
            logger.info(f"deep-replace[{stage_label}]: cost basis from "
                        f"{basis_note or 'caller override'} = {basis:.0f}s")
        else:
            basis = replace_gamble_cost_basis(
                cfg, getattr(self, "_ils_observed_costs", None))
            # ---- SIZE-MODEL FALLBACK (jul28 night16c). ------------------------------
            #
            # A MEASURED anchor only exists once a heavy step has run. So when the FIRST
            # stage is skipped — for the band, or for the reserve — nothing publishes an
            # anchor, replace_gamble_cost_basis returns 0, and the TAIL then refuses with
            # "no measured cost anchor (fail closed)". The two skips are causally linked:
            # a first-stage skip GUARANTEES a tail-stage skip, so the stage runs at
            # NEITHER point. Seen on ispd16 tonight:
            #
            #   deep-replace[first]: skipped (insufficient terminal reserve ...)
            #   deep-replace[tail]:  skipped (no measured cost anchor (fail closed))
            #
            # That is a circular dependency, not a budget decision, and the asymmetry has
            # no justification: the FIRST stage already trusts predict_place_route_s at
            # t=0 for exactly this reason (see _deep_replace_first_stage's docstring —
            # "the size model supplies the basis"). An estimate good enough to START the
            # stage is good enough to SIZE it.
            #
            # Nothing becomes unbounded: the affordability check below still applies
            # basis x1.3 + reserve against the remaining window, so a design that cannot
            # afford the stage is still refused — it is now refused for the RIGHT reason,
            # with a number, instead of for a missing measurement.
            #
            # NOT the cause of ispd16's -4.14 tonight: its tail had ~960s against a
            # ~3310s need, so it would refuse either way, and 126.49 MHz sits inside that
            # design's documented bimodal cluster (124.7-131.8). This closes a latent
            # hole, it does not claim a design's number back.
            if basis <= 0:
                try:
                    from optimizer.deep_replace_sibling import predict_place_route_s
                    _est, _why = predict_place_route_s(
                        primitive_cells=getattr(self, "_input_cell_count", None))
                    if _est > 0:
                        basis = float(_est)
                        logger.info(
                            f"deep-replace[{stage_label}]: no measured anchor "
                            f"(first stage never ran) — falling back to the SAME size "
                            f"model the first stage trusts at t=0: {basis:.0f}s ({_why}). "
                            f"Affordability still gated below; without this the stage "
                            f"would be skipped for a missing measurement rather than "
                            f"for cost.")
                except Exception as e:
                    logger.warning(f"deep-replace[{stage_label}]: size-model fallback "
                                   f"raised {type(e).__name__} (non-fatal): {e!r}")
        _wns = self._phase1_wns_for_features()
        # UNBANDED mode (jul26, DEFAULT OFF): drop the DEEP-extreme band, which
        # is a benefit PREDICTION used as a VETO and is measurably mis-scoped
        # (logicnets: failing 1,529 / |WNS| 0.978, three orders of magnitude
        # outside the band, yet regen-from-pristine beats operate by +93.77).
        # Affordability, pristine-input and cost-anchor gates all still apply,
        # and the stage remains an insured-compare MUX candidate, so a losing
        # regeneration is discarded BY MEASUREMENT rather than pre-empted by a
        # guess. Enable: --deep-replace-unbanded or FPL26_DEEP_REPLACE_UNBANDED=1.
        _unbanded = bool(getattr(self, "_deep_replace_unbanded", False))
        # ---- DOUBLE-RESERVE FIX (jul30). DEFAULT OFF = byte-identical behaviour ----
        # The affordability gate re-subtracts the finalize reserve that
        # _budget_deadline has ALREADY removed, so it withholds 600s for a 300s
        # finalize. Corpus (59 agent.logs since jul26): 22 of 30 terminal-reserve
        # declines arm once corrected, while all 8 genuinely-infeasible ones stay
        # declined. Full rationale in optimizer/deep_replace_sibling.py.
        _no_double_reserve = (
            os.environ.get("FPL26_DEEP_REPLACE_NO_DOUBLE_RESERVE", "0")
            .strip().lower() in ("1", "true", "on", "yes"))
        # ---- B3 SMALL-FLOOR SIBLING (aug09). DEFAULT OFF = byte-identical ----
        # Armed by FPL26_DEEP_REPLACE_B3 (the Makefile ships it ON). Scoped to
        # the MID band — the od4/mg5 evidence class (rationale at the
        # DEEP_REPLACE_B3_* constant block in deep_replace_sibling.py) — and to
        # the FIRST stage only: the tail re-deriving a deterministic result it
        # already banked is pure wall. v5.5.3: what keeps this null on every
        # known design except mini-ISP is the affordability cap (550s: 3d
        # est 662s declines by arithmetic) PLUS the physics admission below —
        # on dev-speed boxes vexriscv/optical pass affordability and are
        # refused by the admission attestation (fabric, not floor-class).
        _b3_on = (
            os.environ.get("FPL26_DEEP_REPLACE_B3", "0")
            .strip().lower() in ("1", "true", "on", "yes")
            and recipe_pass_band(self.initial_wns) == "mid"
            and stage_label == "first")
        # ---- BAND-GATED *FIRST* (jul27). DEFAULT OFF = byte-identical behaviour ----
        #
        # FIRST and TAIL are not the same decision and must not share one setting:
        #
        #   TAIL  spends LEFTOVER budget. A benefit-prediction must NEVER refuse it —
        #         that is the house rule the UNBANDED flag restored, with logicnets as
        #         standing proof (3 orders of magnitude outside the band, regeneration
        #         still worth ~+94 MHz). TAIL therefore stays UNBANDED, untouched.
        #
        #   FIRST spends the LLM LOOP'S wall. That makes it a SCHEDULING decision, and
        #         the same house rule explicitly permits a prediction to SCHEDULE work.
        #         Nothing is refused: a design that misses the band still gets
        #         deep-replace at the tail if budget remains.
        #
        # Measured jul27 on corescore, single variable, control reproduced on BOTH
        # boxes to the digit:
        #     FIRST on   -> probe spends 813s, REJECTS its own output, alpha +17.56
        #     FIRST off  -> loop opens in 86s instead of 38 min,        alpha +80.94
        # while boom_soc runs -19.162 -> -9.583 with ZERO LLM calls and genuinely
        # needs FIRST. boom_soc/boom_v2 are the only two designs of 16 satisfying the
        # band, so it separates exactly the cases that matter.
        #
        # NO NEW NUMBER IS FITTED: this reuses R1_FAILING_ENDPOINTS_MIN /
        # R1_ROUTE_FIRST_WNS_NS already in the tree. Fitting a fresh boundary on 16
        # designs against a 3.5 MHz noise floor is what deep_replace_should_run's own
        # docstring forbids and a jul25 panel rejected 0/5.
        #
        # THAT RISK IS NOW RETIRED (jul29). The five designs that ADOPTED deep-replace but
        # miss the band all RE-LANDED at or above their same-config control in the jul28
        # night16d cohort (band gate ON, jul27 arm=banded as the one-variable control):
        #
        #   mini-ISP   102.71 vs 102.04    finn       65.24 vs 65.24
        #   vexriscv   149.81 vs 136.65    vtr_mcml   16.94 vs 15.74
        #   logicnets   98.96 vs  95.20  <- corrected; see the under-report note below
        #
        # All artifact-verified (ROUTE_CLEAN=1, 0 routing errors, manifest == artifact).
        # boom_soc reproducing 41.43 EXACTLY is the in-band counter-check: it sits inside
        # the DEEP-extreme band, so the gate KEEPS deep-replace at FIRST for it. The gate
        # discriminates by physics; it is not an off-switch.
        #
        # logicnets was recorded as this cohort's ONLY loss (-0.74) until jul29, when the
        # shipped DCP was re-opened and held 502.513 MHz against a logged 498.01: the
        # multi-restart winner-polish replaces the artifact AFTER the summary block prints,
        # so any run with POLISH_VERDICT=IMPROVED under-reports itself. Corrected, the
        # cohort is +23.91 with zero losses.
        #
        # HONEST LIMITS OF THIS EVIDENCE, kept here because arming a default deserves them:
        #   * n=1 per design. A jul29 five-model panel voted 4-1 to ship; the dissent
        #     (deepseek) was that "zero losses" is unfalsifiable at n=1, which is correct.
        #   * the +19.41/+23.91 cohort varies the ILS stack as well as the band, so it is
        #     not a clean causal estimate of THIS flag alone. The causal band evidence is
        #     really corescore/optical/logicnets/BOOM.
        #   * the DEEP-extreme failing-endpoint threshold is fitted on boom_soc and
        #     boom_soc_v2 — two versions of one netlist, so n~=1 independent observation.
        # DEFAULT ON (jul29, after measuring the deferral path on THIS tree).
        #
        # The objection that held this back was that "a band miss merely DEFERS to the
        # tail" did not hold: of the six band-ON designs that missed the band, FOUR got
        # NEITHER stage. Re-measured on the current tree, that objection does not survive,
        # for two different reasons depending on how expensive the stage is.
        #
        # CHEAP STAGE -> the jul28 affordability override arms FIRST anyway, so there is no
        # deferral at all. Measured jul29, band gate ON, current code:
        #   finn      anchor 684s: "band gate OVERRIDDEN by affordability" -> FIRST ARMED,
        #             B1 BANKED. alpha +63.90 vs 65.24 (-1.34, inside the noise floor).
        #   vexriscv  anchor  15s: FIRST ARMED and TAIL ARMED too. alpha +154.94 vs the
        #             old-code band-ON 149.81 — +5.13, ABOVE the noise floor.
        # Once FIRST runs it PUBLISHES a measured anchor, which is why 276abd4 makes
        # 7291a4d's "no measured cost anchor (fail closed)" circularity unreachable rather
        # than merely patched.
        #
        # EXPENSIVE STAGE -> the gate really does skip both stages. The one design where
        # that happens is corescore (anchor 724s x1.3 + 300s reserve = 1241s vs 316s left),
        # and there the skip is the CORRECT answer, because deep-replace at FIRST is
        # actively harmful on it:
        #   run2_jul27 C1              deep-replace FIRST RAN     alpha  +17.56
        #   run2_jul27 C1_nodeepfirst  disabled by hand           alpha  +80.94
        #   gate_ab_jul27 banded       band-gated -> skipped      alpha  +81.84
        #   night16d uni3b             band-gated -> skipped      alpha  +86.80
        #   bandcur2 (CURRENT CODE)    band-gated -> skipped      alpha  +80.03
        # Running the stage costs ~63 MHz. The gate is what prevents that, and on the
        # current tree it still prevents it (+80.03 is inside the noise floor of the
        # 80.94/81.84 same-arm family).
        #
        # RESIDUAL RISK, stated rather than hidden: a hidden design where the stage is
        # EXPENSIVE *and* would have HELPED gets neither stage. We have no example of that
        # class, and the only expensive-stage design we do have is one where running it
        # loses 63 MHz — so unconditional arming is the worse gamble. The DEEP-extreme
        # threshold is still fitted on boom_soc/boom_soc_v2, two versions of one netlist.
        #
        # Disarm with FPL26_DEEP_REPLACE_FIRST_BANDED=0.
        #
        # (Historical, for context — the cohort that FAILED to justify this, on the
        # superseded tree b8f856d31311. Of six band-ON designs missing the band, four got
        # neither stage:
        #
        #   corescore  first: band miss   -> tail: insufficient reserve (312s < 1260s)
        #   vexriscv   first: band miss   -> tail: insufficient reserve (397s <  474s)
        #   vtr_mcml   first: band miss   -> tail: insufficient reserve (786s < 1216s)
        #   finn       first: band miss   -> tail: NO MEASURED COST ANCHOR (fail closed)
        #
        # finn's is the circular failure 7291a4d exists to fix: FIRST is skipped, so no
        # heavy step runs, so nothing publishes an anchor, so the tail refuses for want of
        # a measurement that a skipped stage was never going to take.
        #
        # That cohort ran code_md5 b8f856d31311 (commit 35d2f23), which PREDATES both
        # 276abd4 (affordability override) and 7291a4d (tail falls back to the size model).
        # The current tree should therefore behave better — but "should" is exactly the
        # word that preceded every over-claim this project has had to retract, and
        # 7291a4d is recorded as NEVER HAVING TRIGGERED LIVE. Arming a default on a cohort
        # measured against superseded code, in the one code path that was superseded, is
        # the error we keep committing.
        #
        # That evidence was gathered on jul29 and is recorded above.)
        _band_first = (stage_label == "first"
                       and os.environ.get(
                           "FPL26_DEEP_REPLACE_FIRST_BANDED", "1"
                       ).strip().lower() in ("1", "true", "on", "yes"))
        # ---- FPL26_DEEP_FIRST_SIZEGATED (aug06, DEFAULT OFF) --------------
        # See the constants block at deep_first_sizegated_enabled(). Applies
        # ONLY at FIRST, ONLY to the ILS-size-gated class, and ONLY relaxes
        # two gates that are measurably mis-scoped for that class. Unknown
        # cell count or unknown max_cells -> not size-gated -> no change.
        _sg_first = False
        if stage_label == "first" and deep_first_sizegated_enabled():
            _sg_cells = getattr(self, "_input_cell_count", None)
            _sg_max = getattr(self._ils_polish_cfg, "max_cells", None)
            # BOTH conditions, and the second is NOT optional (adversarial
            # review aug06, BLOCKER). Size alone waives the band's |WNS| floor
            # for EVERY >=300k design, including a hidden LARGE-but-SHALLOW one
            # — which is corescore's exact physics (|WNS| 1.24), the single
            # design where this stage at FIRST is measured to cost ~63 MHz
            # (+80.94 without, +17.56 with). corescore is excluded here only by
            # cell count, i.e. by the wrong property; a 400k-cell near-met
            # hidden benchmark would have armed it. Because the stage runs at
            # FIRST, that loss is the whole downstream pipeline's alpha, not
            # just gamma.
            #
            # So keep the band's OWN failing-endpoint half as a floor. No new
            # constant: R1_FAILING_ENDPOINTS_MIN (100k) is the band's existing
            # threshold. Effect on the corpus:
            #   ispd16    242,906 failing -> still arms  (+91 preserved)
            #   boom_v1   217,988 failing -> unchanged
            #   boom_v2   220,131 failing -> unchanged
            #   corescore  39,008 failing -> refused twice over
            #   large + shallow (hidden)  -> refused on failing endpoints
            _sg_fail = self._phase1_failing_endpoints_for_features()
            if (_sg_cells and _sg_max and _sg_cells > _sg_max
                    and (_sg_fail or 0) >= R1_FAILING_ENDPOINTS_MIN):
                _sg_first = True
                logger.info(
                    f"deep-replace[first]: SIZE-GATED CLASS "
                    f"({_sg_cells:,} cells > ILS max_cells {_sg_max:,}, "
                    f"failing={_sg_fail:,} >= {R1_FAILING_ENDPOINTS_MIN:,}) — "
                    f"ILS never arms here and the design is broadly failing, so "
                    f"the DEEP-extreme |WNS| floor and the double-subtracted "
                    f"finalize reserve are waived for this stage (ispd16 "
                    f"measured +24.11 -> +115.37; boom_v1 unchanged +41.43).")
            else:
                logger.info(
                    f"deep-replace[first]: size-gate NOT applied "
                    f"(cells={_sg_cells} max_cells={_sg_max} "
                    f"failing={_sg_fail}) — needs BOTH cells > max_cells AND "
                    f"failing >= {R1_FAILING_ENDPOINTS_MIN:,}; behavior "
                    f"unchanged.")
        if _sg_first:
            _band_first = False
        # ---- AFFORDABILITY OVERRIDE (jul28 night16d). ----------------------------
        #
        # The comment above assumes "nothing is refused: a design that misses the band
        # still gets deep-replace at the tail". MEASURED FALSE tonight. Both deferred
        # designs DID run the stage at the tail and still lost, because FIRST and TAIL
        # are not the same work: at FIRST the stage reseeds the whole pipeline, at the
        # tail it is a closing polish.
        #
        #   design     cost basis   failing    tail ran it?   alpha vs control
        #   mini-ISP        37s      4,887     yes (75s)          -3.39
        #   logicnets      161s      1,529     yes (184s)        -10.64
        #   corescore     1099s     39,008     n/a (deferred)     +4.96
        #
        # The separator is COST, not the band: both CHEAP stages lose when deferred and
        # the EXPENSIVE one gains. Deferring a 161s stage to save loop wall trades
        # 10.64 MHz for 4.6% of the wall, which is a bad trade by two orders of
        # magnitude.
        #
        # So defer only when the stage is out-of-band AND genuinely unaffordable as a
        # first step. "Affordable" reuses the wave-2-proven tail reserve already in the
        # tree (TAIL_RESERVE_WALL_CLAMP_FRAC = 2400/3500): the recipe+loop are budgeted
        # that fraction of the wall, so a first stage may spend what is left over.
        # NO NEW CONSTANT IS FITTED — the same discipline the band gate itself claims.
        #
        #   budget = wall x (1 - 2400/3500) = 1100s on the 3500s eval wall
        #   mini-ISP    37 x 1.3 =   48s <= 1100  -> keep FIRST
        #   logicnets  161 x 1.3 =  209s <= 1100  -> keep FIRST
        #   corescore 1099 x 1.3 = 1429s >  1100  -> DEFER  (still gets +4.96)
        #
        # Unknown wall -> no budget to reason about -> leave the band decision alone.
        if _band_first:
            _wall = getattr(self, "max_wall_seconds", None)
            _first_budget = (float(_wall) * (1.0 - TAIL_RESERVE_WALL_CLAMP_FRAC)
                             if _wall else 0.0)
            _need = (basis or 0.0) * DEEP_REPLACE_COST_MARGIN
            if _first_budget > 0 and _need > 0 and _need <= _first_budget:
                _band_first = False
                logger.info(
                    f"deep-replace[first]: band gate OVERRIDDEN by affordability — "
                    f"stage needs {_need:.0f}s (basis {basis:.0f}s x"
                    f"{DEEP_REPLACE_COST_MARGIN}) which fits the "
                    f"{_first_budget:.0f}s left over the tail reserve, so FIRST costs "
                    f"the loop nothing it was budgeted. Deferring a cheap stage cost "
                    f"logicnets 10.64 MHz on jul28 even though the tail did run it.")
        if _band_first:
            logger.info("deep-replace[first]: BAND-GATED (jul27 opt-in) — FIRST "
                        "requires the DEEP-extreme band; a miss DEFERS the stage to "
                        "the tail rather than refusing it.")
        run, why = deep_replace_should_run(
            enabled=True,
            pristine_dcp=pristine,
            failing_endpoint_count=self._phase1_failing_endpoints_for_features(),
            wns_magnitude_ns=(abs(_wns) if _wns is not None else None),
            remaining_s=deadline - time.time(),
            cost_basis_s=basis,
            finalize_reserve_s=cfg.deep_replace_finalize_reserve_s,
            failing_endpoints_min=R1_FAILING_ENDPOINTS_MIN,
            wns_min_ns=R1_ROUTE_FIRST_WNS_NS,
            require_physics_band=((_band_first or (not _unbanded))
                                  and not _sg_first),
            # Both callers pass a deadline already reduced by
            # _finalize_reserve_seconds, so the gate must not subtract it again.
            # DEFAULT OFF: see the DOUBLE-RESERVE FIX note in the gate.
            # _sg_first waives it for the ILS-size-gated class only, where the
            # refusal was measured to be a margin artifact and not physics
            # (ispd16: predicted need 3309s vs a chain that took 1976s).
            reserve_already_in_deadline=(_no_double_reserve or _sg_first),
        )
        if not run:
            logger.info(f"deep-replace[{stage_label}]: skipped ({why})")
            return
        logger.info(f"deep-replace[{stage_label}]: {why}")
        out_dcp = str((self.run_dir or Path(".")) / "deep_replace_candidate.dcp")
        # SELF-CAPPED STAGE BYPASS (jul25, found by the first live E2E run).
        #
        # This stage is exactly what the unroute gate's own comment exempts:
        # "finalize writes and ILS's own self-capped unroute/reroute cycles
        # (ils_polish _heavy_to) are never gated". run_deep_replace_sibling
        # bounds every step by deadline_ts through _heavy_to()/_light_to(), so
        # it is self-capped in the same sense — but it was never added to the
        # bypass, and the gate refused its route_design:
        #
        #   unroute_gate_refused: "predicted re-route 2274.0s + banking reserve
        #   30s = 2304.0s exceeds effective budget 2094.8s ... by 209.3s"
        #   place=827s route=0s banked=none
        #
        # Two independent reasons that refusal was wrong here: (1) the gate
        # exists to protect a ROUTED state from destruction, and at this point
        # the recipe has deliberately unplaced — there is no routed state left
        # to protect; (2) its size-scaled estimate said 2274 s for a route that
        # MEASURES 746 s on this very design, a ~3x over-estimate, so it
        # refused something that fits with 1300 s to spare.
        #
        # We reuse the audited _in_ils_stage bypass rather than adding a new
        # flag, because that path is already threaded through all four gate
        # sites (budget skip, router block, unroute gate, auto-bank); a new
        # flag risks missing one. Save/restore rather than assign False: the
        # TAIL call site can already be inside a real ILS stage.
        #
        # NOT FIXED HERE: the route_gate over-estimate itself. It guards a real
        # failure (jul14 boom_v2 shipped alpha=0 after a budget-killed
        # re-route), and re-tuning a protective cost model on one observation is
        # how we get the next phantom. Logged as a separate finding.
        # v5.5.3 B3 physics admission (AWS eval-parity fix): a closure the
        # sibling calls AFTER affordability passes, with the banked WNS. It
        # runs the B1 floor-class attestation on the live session (~10-25s,
        # spent only on affordable mid-band candidates) — hard-macro-
        # dominated near-floor solves admit; re-place fabric refuses; any
        # tool/parse failure refuses (pre-v5.5.3 decline behavior).
        _b3_admit = None
        if _b3_on:
            async def _b3_admit(wns_banked, _out=out_dcp):
                # r1 finding 9: any setup error (e.g. clock_period None ->
                # TypeError) must refuse HERE with an admission-labeled
                # reason, not surface as a mislabeled B3-leg failure.
                try:
                    from optimizer.logic_floor import (
                        run_b1_admission_attestation)
                    v = await run_b1_admission_attestation(
                        self.call_tool,
                        clock_name="*fpl26contest*",
                        period_ns=float(self.clock_period),
                        wns_banked=wns_banked,
                        log=lambda m: logger.info(m),
                        recover_dcp=_out or None)
                except Exception as e:
                    return False, (f"B3 declined (physics admission): "
                                   f"attestor setup raised {e!r} "
                                   f"(fail closed)")
                return v.fire, (
                    ("B3 physics-admitted: " if v.fire
                     else "B3 declined (physics admission): ") + v.reason)
        _prev_ils_flag = self._in_ils_stage
        self._in_ils_stage = True
        try:
            res = await run_deep_replace_sibling(
                self.call_tool,
                pristine_dcp=pristine,
                chain_best_wns=self.best_wns,
                deadline_ts=deadline,
                wns_tcl=wns_tcl,
                out_dcp=out_dcp,
                log=lambda m: logger.info(m),
                measure=_measure,
                measure_hold=_measure_hold,
                tool_ok=_tool_ok,
                hold_slack_floor_ns=cfg.hold_slack_floor_ns,
                heavy_timeout_s=cfg.heavy_cmd_timeout_s,
                light_timeout_s=cfg.measure_cmd_timeout_s,
                adopt_margin_ns=cfg.deep_replace_adopt_margin_ns,
                # Funds the B2 (retiming-tail) gate, decided from the MEASURED
                # B1 elapsed time rather than the arm-time anchor.
                finalize_reserve_s=cfg.deep_replace_finalize_reserve_s,
                b3_enabled=_b3_on,
                b3_admission=_b3_admit,
            )
        finally:
            self._in_ils_stage = _prev_ils_flag
        # ---- RECOVER A WEDGED SESSION AFTER A FAILED STAGE (aug06) ---------
        # If the stage errored with NO candidate, the most likely cause is the
        # server-side per-command cap: _heavy_to() hands the MCP payload
        # min(heavy_cmd_timeout_s, ...) = 1800s, and ispd16's place leg alone
        # measured 1339s (74% of it). On that timeout the server raises
        # pexpect.TIMEOUT, returns "Error: Command timed out...", AND leaves
        # _command_pending set while Vivado keeps placing — so the LLM loop's
        # very next Tcl call blocks in sync_after_timeout (up to 3600s), the
        # client cancels at the budget deadline, and the run finalizes the
        # BASELINE at alpha 0. Restarting here clears _command_pending and
        # kills the stranded process, handing the loop its remaining wall on a
        # clean session: worst case becomes "the design's normal result"
        # instead of zero.
        #
        # Deliberately NARROW: only on VERDICT_ERROR with no candidate (a
        # successful or partially-successful stage is untouched), and entirely
        # best-effort. call_tool returns an error STRING rather than raising,
        # and the tool must be addressed as "vivado_restart_vivado" — the
        # prefix is how call_tool routes it (see the ILS restart at ~:10215).
        try:
            if (getattr(res, "verdict", None) == VERDICT_ERROR
                    and not getattr(res, "candidate_path", None)):
                logger.warning(
                    f"deep-replace[{stage_label}]: stage ERRORED with no "
                    f"candidate ({str(getattr(res, 'reason', ''))[:160]}); "
                    f"restarting Vivado so a wedged session cannot cost the "
                    f"remaining wall.")
                _rs = await self.call_tool("vivado_restart_vivado", {})
                if _looks_like_tool_error(_rs):
                    logger.warning(
                        f"deep-replace[{stage_label}]: restart_vivado returned "
                        f"an error envelope ({str(_rs)[:120]}) — continuing; "
                        f"the banked best is unaffected either way.")
                else:
                    logger.info(
                        f"deep-replace[{stage_label}]: Vivado restarted; the "
                        f"loop continues on a clean session.")
        except Exception as e:
            logger.warning(f"deep-replace[{stage_label}]: post-error restart "
                           f"raised (ignored): {e!r}")
        # PUBLISH THE MEASUREMENT (jul26). run_deep_replace_sibling has just
        # performed a REAL full place+route on THIS design and THIS box and
        # returns the elapsed times — but nothing consumed them, so every later
        # cost-gated stage fell back to replace_gamble_cost_basis()'s rung 3
        # (0.0 -> FAIL CLOSED). That is how chain15b produced
        #   deep-replace[tail]: skipped (no measured cost anchor (fail closed))
        # moments after B1 had measured place=817s route=736s on that very run.
        #
        # This is the same defect class as the B2 predictive gate (54d875e) and
        # the deep-replace ship gap (31fc835): the information exists, the
        # consumer cannot see it. Publishing it also OBEYS the cost-basis
        # ladder's own stated preference — "measured-on-THIS-design/box first"
        # — since a measurement strictly dominates the derived anchor.
        #
        # Never LOWER an existing anchor: a smaller basis makes affordability
        # gates more permissive, and this stage's cycle can be cheaper than a
        # full ILS combo. Raising-only keeps every gate at least as conservative
        # as it was, so this cannot turn a refusal into an unaffordable start.
        try:
            _measured_cycle_s = float(getattr(res, "place_s", 0.0) or 0.0) + \
                                float(getattr(res, "route_s", 0.0) or 0.0)
            if _measured_cycle_s > 0:
                _prev_anchor = float(getattr(cfg, "expected_heavy_cycle_s", 0.0) or 0.0)
                if _measured_cycle_s > _prev_anchor:
                    cfg.expected_heavy_cycle_s = _measured_cycle_s
                    logger.info(
                        f"deep-replace[{stage_label}]: published measured "
                        f"place+route anchor {_measured_cycle_s:.0f}s "
                        f"(place={float(getattr(res, 'place_s', 0.0)):.0f}s + "
                        f"route={float(getattr(res, 'route_s', 0.0)):.0f}s); "
                        f"previous anchor {_prev_anchor:.0f}s. Downstream "
                        f"cost gates now size from a measurement of THIS "
                        f"design on THIS box.")
                else:
                    logger.info(
                        f"deep-replace[{stage_label}]: measured cycle "
                        f"{_measured_cycle_s:.0f}s <= existing anchor "
                        f"{_prev_anchor:.0f}s; anchor left unchanged "
                        f"(raise-only).")
        except Exception as e:                                # pragma: no cover
            logger.warning(f"deep-replace[{stage_label}]: could not publish "
                           f"cost anchor ({type(e).__name__}: {e}) — "
                           f"non-fatal, downstream gates keep their basis.")
        # B3-FLOOR-EXIT sentinel input (v5.4): record the adopted small-floor
        # value so finalize can attest "this attempt's outcome is the
        # deterministic recipe floor" to the multi-restart wrapper. Recorded
        # regardless of later promotion — the MUX guarantees the shipped best
        # is never below it.
        if (getattr(res, "stage_banked", "") == "small_floor"
                and getattr(res, "post_wns", None) is not None):
            self._b3_floor_wns = float(res.post_wns)
            logger.info(f"deep-replace[{stage_label}]: B3 floor recorded "
                        f"({res.post_wns:.3f}) for the floor-exit sentinel.")
            # LOGIC-FLOOR ATTESTATION (v5.5, FPL26_LOGIC_FLOOR_EXIT, python
            # default OFF / Makefile ON): one ~25s Tcl round-trip on the LIVE
            # session (which holds B3's routed state — B3 is the last leg).
            # Fires => the LLM loop and the ILS/polish stages are skipped and
            # the run finalizes the floor; every guard failure is NO-FIRE and
            # the run proceeds exactly as v5.4.2. First-stage only (the tail
            # runs too late to matter and its session state is not B3's).
            _lf_on = (os.environ.get("FPL26_LOGIC_FLOOR_EXIT", "0").strip()
                      .lower() in ("1", "true", "on", "yes")
                      and stage_label == "first")
            if _lf_on:
                try:
                    from optimizer.logic_floor import (
                        run_logic_floor_attestation)
                    _lfv = await run_logic_floor_attestation(
                        self.call_tool,
                        clock_name="*fpl26contest*",
                        period_ns=float(self.clock_period),
                        wns_b1=getattr(res, "b1_wns", None),
                        wns_b3=float(res.post_wns),
                        log=lambda m: logger.info(m),
                        recover_dcp=str(getattr(res, "candidate_path", "")
                                        or "") or None)
                    if _lfv.fire:
                        self._logic_floor_terminate = _lfv.reason
                except Exception as e:
                    logger.warning(f"[logic-floor] attestation call raised "
                                   f"{e!r} — NO-FIRE (fail-safe).")
        # Enroll as a FINAL candidate. run_deep_replace_sibling already
        # measured routed (unrouted==0) and hold under the SAME gate logic
        # register_final_candidate applies, so verify=False (the "caller
        # already measured under identical gates" contract) -- no session
        # re-open, shipping state undisturbed. A full re-place never deletes
        # cells, so the cell-band guard is moot (cell_count None -> fail-open).
        if (res.candidate_path and res.post_wns is not None
                and Path(res.candidate_path).exists()
                and Path(res.candidate_path).stat().st_size > 0):
            try:
                res.registered = await self.register_final_candidate(
                    res.candidate_path, res.post_wns, "deep_replace",
                    whs=res.post_whs, verify=False)
            except Exception as e:
                logger.warning(
                    f"[mux] deep_replace registration raised "
                    f"{type(e).__name__} (non-fatal): {e}")

            # HAND THE STATE FORWARD (jul25, found in the first live E2E run).
            #
            # Registering with the MUX makes the result SHIPPABLE but leaves the
            # pipeline's own best pointing at the baseline, so every downstream
            # stage reopens the pristine design. Measured on chain12: the recipe
            # banked wns=-10.256 (84.57 MHz) at 18:09, and then --
            #   "running finalize with best_wns=-19.162"
            #   bare-reroute polish: opening best_valid...   <- the BASELINE
            #   [tail-ctrl] ARMED: entry wns=-19.162
            #   phys_opt -critical_pin_opt / -placement_opt  <- 925 s
            #   verdict=ERROR gain=+0.000ns
            # -- 925 s spent re-polishing a design we had already beaten by
            # 36 MHz. The MUX still shipped the right DCP, so the run LOOKED
            # fine; the waste is invisible unless you read the tail.
            #
            # This is the identical block replace_gamble (this stage's declared
            # sibling) has run since it landed; deep-replace simply never got
            # it. With the state handed forward, the tail's remaining wall
            # compounds ON the recipe's result instead of restarting from zero.
            #
            # Guarded by a strict improvement re-check: the adopt gate inside
            # the stage compared against chain_best_wns captured at CALL time,
            # and something else may have banked since.
            if (res.verdict == VERDICT_ADOPTED and res.candidate_path
                    and res.post_wns is not None
                    and (self.best_wns is None
                         or self.best_wns == float("-inf")
                         or res.post_wns > self.best_wns)):
                _prev_best = self.best_wns
                self.best_wns = res.post_wns
                self._best_valid_dcp = Path(res.candidate_path)
                self._best_valid_dcp_wns = res.post_wns
                # C1-T5 convention: keep the banked-size reference in sync.
                try:
                    self._best_valid_mirror_size = (
                        Path(res.candidate_path).stat().st_size)
                except OSError:
                    self._best_valid_mirror_size = None
                logger.info(
                    f"deep-replace[{stage_label}]: promoted to pipeline best "
                    f"{_prev_best} -> {res.post_wns} ({res.stage_banked}); "
                    f"downstream stages now continue FROM this state.")

    async def _run_bare_reroute_polish(self) -> None:
        """ITERATED undirected `route_design` on the routed banked best
        when ILS never ran (drill jul21 D1-null: +0.094 boom_v2
        deterministic; meta: undirected beats directed; plateau probe
        jul21: the re-roll COMPOUNDS while WNS is deep).

        Evidence: on boom_v2's banked route-first state (unroute +
        AggressiveExplore), a single bare `route_design` — no directive,
        no -unroute — gains +0.094 ns hold-neutral, deterministically
        (also reproduced as ~half of the v1 +0.190).  Every DIRECTED
        variant tried the same day LOST to it (skew-root move −0.120,
        per-net -delay re-route −0.139, AdvancedSkewModeling −0.910):
        the UG904 rip-up pass where the router picks its own victims is
        the only live route-pass lever from a banked AE state.

        THE GAP this closes: ILS's __ROUTE_ONLY__ combo already harvests
        this on designs where ILS runs, but boom-class designs are
        ILS-SIZE-GATED (379,380 cells > max_cells 300k) so they never
        capture it.  Gates (all must hold):
          (a) ILS never armed this run (_ils_preempt_requested False —
              size-gated or otherwise declined; the caller also guards),
          (b) a routed banked best EXISTS (_best_valid_dcp; the bank
              only ever holds validated routed states) and auto-bank is
              ON (the measurement/banking machinery this step rides),
          (c) the re-route fits the remaining wall per the PRESERVING
              cost basis (optimizer.route_gate.assess_preserving_
              reroute: this run's observed route_design sample ×
              PRESERVING_ROUTE_FACTOR 0.5 + 30s banking + 60s margin),
              after paying the observed open_checkpoint cost to
              re-open the banked best.  NOT the destructive K=2 basis:
              that doubling exists because a DESTROYED state must be
              fully rebuildable in-window (overrun = α:=0); here the
              banked mirror is untouched on disk and an overrun ships
              it via the emergency path, costing only tail-γ.  With
              K=2 the gate refused at DEBUG-WALL (predicted 7200s vs
              2375s remaining) AND on the leg-2 eval trace (2×1620=
              3240s vs ~1300s post-bank) — the lever would have been
              dead code everywhere.  Factor 0.5 ≈ 1.6× the MEASURED
              preserving ratio 0.31 (drill1 log: bare route 1199s vs
              full AE route 3871s, same design/box/session); see the
              constants block in optimizer/route_gate.py.

        Never-worse by construction: open_checkpoint + route_design go
        through the NORMAL call_tool path, so routed-state tracking,
        the phantom-best guard, and the R-D1-1 auto-bank hook all
        apply — an improved+routed result banks via the existing
        eager-mirror path; a worse result is measured but NOT banked.
        The re-route mutates in-memory state only; the banked disk
        mirror is untouched, and finalize ships disk truth.

        C1-T3 composition: this step counts as a POLISH stage.  A bare
        route on a routed design is state-PRESERVING per
        is_routed_state_destroying, so neither the reserve gate nor the
        fence cap applies — it may spend the reserved window — and its
        completion RELEASES the reserve (one-way, finalize still
        backstops).  ALL loop iterations run inside that one reserve
        window; release happens once, at step completion.

        ITERATION LOOP (plateau probe jul21): the mechanism is a
        route-lottery re-roll via rip-up, and it RE-BITES while WNS is
        deep — on boom the shipped single-pass state −11.177 gained
        ANOTHER +0.404 on a second iteration (hold neutral; cumulative
        +0.62 over two passes from −11.392) — while it decays near
        plateaus (fir plateau: +0.004).  So the single route pass is
        wrapped in a loop:
          - each iteration: wall-fit check with the SAME preserving
            cost basis (assess_preserving_reroute); from iteration 2 on
            the route sample is REFRESHED with the OBSERVED cost of the
            previous iteration (a bare-route pass is a direct sample of
            the next one — better predictor than the stale full-route
            sample — so the full→bare preserve_factor becomes 1.0),
            then the bare route_design via call_tool (auto-bank
            measures/banks exactly as the single pass did), then the
            measured WNS delta is read off best_wns.
          - continue while gain_this_iteration >=
            _bare_reroute_min_gain_ns (default 0.020 — well above
            measurement noise, below the observed +0.094/+0.215/+0.404
            band) AND the next iteration wall-fits AND iterations <
            _bare_reroute_max_iters (default 4, runaway guard).
          - stop reasons logged distinctly: gain_below_min / wall_unfit
            / max_iters / route_error.
        First-iteration semantics are IDENTICAL to the shipped one-shot
        behavior: a single non-improving pass measures, does not bank,
        stops (gain_below_min), and releases the reserve — same outcome
        as before; a first-pass route error returns without releasing
        (finalize backstops), exactly as shipped.

        Kill switches: --no-bare-reroute-polish / env
        FPL26_NO_BARE_REROUTE_POLISH=1 (default ON: evidence-backed,
        never-worse-insured).  Loop knobs: --bare-reroute-min-gain /
        --bare-reroute-max-iters (env FPL26_BARE_REROUTE_MIN_GAIN /
        FPL26_BARE_REROUTE_MAX_ITERS).
        """
        if not self._bare_reroute_polish_enabled:
            logger.info("bare-reroute polish: disabled (kill switch); skipped.")
            return
        if self._ils_preempt_requested:
            # ILS ran — its __ROUTE_ONLY__ combo already covers this lever.
            return
        banked = self._best_valid_dcp
        if (banked is None or not Path(banked).exists()
                or Path(banked).stat().st_size <= 0):
            logger.info("bare-reroute polish: no routed banked best; skipped.")
            return
        if not self._auto_bank_enabled:
            # Without auto-bank the re-route would mutate state with no
            # measurement/banking ride-along — pure wall waste.
            logger.info("bare-reroute polish: auto-bank disabled; skipped.")
            return
        # ---- Wall-fit gate: PRESERVING cost basis (docstring (c)) ----
        from optimizer.route_gate import assess_preserving_reroute
        # The banked best must be re-opened first (drill fidelity: the
        # +0.094 is measured FROM the banked state, and the live session
        # may have drifted since the last bank).  Charge the re-open at
        # the observed open_checkpoint cost this run (phase 1 always
        # records one); 0.0 when unknown — the assessment's safety
        # margin covers small designs.
        open_cost_s = 0.0
        for _tc in self.tool_call_details:
            if not isinstance(_tc, dict) or _tc.get("error"):
                continue
            if (_tc.get("tool_name") == "vivado_open_checkpoint"
                    or "open_checkpoint" in str(_tc.get("cmd_head", ""))):
                try:
                    open_cost_s = max(open_cost_s,
                                      float(_tc.get("elapsed_time") or 0.0))
                except (TypeError, ValueError):
                    pass
        remaining = self._budget_remaining()
        assessment = assess_preserving_reroute(
            remaining - open_cost_s,
            self.tool_call_details,
        )
        if not assessment.feasible:
            # Honest skip — includes the no-route-sample case (predicted
            # inf: the run's history carries no route_design sample to
            # size the op with — no data, no gamble).
            logger.info(
                f"bare-reroute polish: skipped (wall unfit after "
                f"{open_cost_s:.0f}s re-open charge): {assessment.reason}")
            return
        min_gain_ns = float(getattr(self, "_bare_reroute_min_gain_ns",
                                    BARE_REROUTE_MIN_GAIN_NS_DEFAULT))
        max_iters = int(getattr(self, "_bare_reroute_max_iters",
                                BARE_REROUTE_MAX_ITERS_DEFAULT))
        logger.info(
            f"bare-reroute polish: firing (drill jul21 D1-null: +0.094 "
            f"boom_v2 deterministic; meta: undirected beats directed; "
            f"plateau probe jul21: re-roll compounds while WNS deep) — "
            f"predicted route {assessment.predicted_reroute_s:.0f}s + "
            f"re-open {open_cost_s:.0f}s of {remaining:.0f}s remaining; "
            f"iterating while gain >= {min_gain_ns:.3f} ns, wall fits, "
            f"iters < {max_iters}.")
        # Dedicated open tool (same as the revert-to-best paths): its
        # success transition sets _design_routed_state=True, so the bare
        # route below is classified state-PRESERVING even if the tracker
        # had drifted (e.g. a late refused -unroute left it False).
        _r = await self.call_tool(
            "vivado_open_checkpoint",
            {"dcp_path": str(Path(banked).resolve())})
        if _looks_like_tool_error(_r):
            logger.info("bare-reroute polish: re-open of banked best failed; "
                        "keeping best (never-worse).")
            return
        # ---- Adaptive tail CONTROLLER dispatch (jul22, PLAN item 1) ----
        # Deep-WNS states get the measured-Δns/s portfolio policy over
        # the proven move menu (harvest-to-wall).  Shallow states keep
        # the shipped plain M1 loop below (plateau probe: the menu
        # decays to no-op near-met).  FAIL-CLOSED: any controller error
        # re-opens the banked best and falls through to the plain loop.
        if (self._tail_controller_enabled
                and self.best_wns is not None
                and self.best_wns != float("-inf")
                and self.best_wns <= self._tail_ctrl_deep_wns_ns):
            try:
                await self._run_tail_controller(min_gain_ns=min_gain_ns)
                return
            except Exception as e:
                logger.warning(
                    f"[tail-ctrl] controller failed ({e!r}); FAIL-CLOSED "
                    f"to plain bare-reroute loop (banked best intact).")
                try:
                    _r = await self.call_tool(
                        "vivado_open_checkpoint",
                        {"dcp_path": str(Path(banked).resolve())})
                    if _looks_like_tool_error(_r):
                        logger.info(
                            "bare-reroute polish: fail-closed re-open "
                            "failed; keeping best (never-worse).")
                        return
                except Exception:
                    return
        # Bare route_design ITERATION loop — undirected on purpose
        # (meta-finding: undirected rip-up beat every directed variant).
        # All iterations run inside the one C1-T3 reserve window; the
        # single release happens at step completion below.
        iters_done = 0
        stop_reason = "max_iters"
        observed_cost_s = 0.0  # measured cost of the previous iteration
        while True:
            if iters_done > 0:
                # Wall-fit re-check for the NEXT pass: SAME preserving
                # basis, route sample REFRESHED with the observed cost
                # of the previous iteration.  preserve_factor=1.0: the
                # observed sample IS already a bare-route pass — the 0.5
                # factor exists only to discount a FULL (directed) route
                # sample down to a bare rip-up, and applying it to an
                # observed bare pass would under-predict (gamble).  No
                # re-open charge: the design is already open in-session.
                remaining = self._budget_remaining()
                assessment = assess_preserving_reroute(
                    remaining,
                    [{"tool_name": "vivado_run_tcl",
                      "cmd_head": "route_design",
                      "elapsed_time": observed_cost_s}],
                    preserve_factor=1.0,
                )
                if not assessment.feasible:
                    stop_reason = "wall_unfit"
                    logger.info(
                        f"bare-reroute polish: stop (wall_unfit) before "
                        f"iteration {iters_done + 1}: {assessment.reason}")
                    break
            # Server-side timeout = 2× the current prediction (first
            # pass: ≈ the full-route sample at the default 0.5 factor —
            # a bare route on a routed state should never exceed the
            # full-route cost it was derived from); the outer deadline-
            # aware asyncio cap still fences the real wall, and an
            # overrun only costs tail-γ (banked mirror safe).
            _route_to = max(600.0, assessment.predicted_reroute_s * 2.0)
            if remaining != float("inf"):
                _route_to = min(_route_to, max(600.0, remaining))
            _pre_wns = self.best_wns
            _hist_mark = len(self.tool_call_details)
            _r = await self.call_tool(
                "vivado_run_tcl",
                {"command": "route_design", "timeout": _route_to})
            if isinstance(_r, str) and ('"error"' in _r or "TCL ERROR:" in _r):
                if iters_done == 0:
                    # Shipped single-pass semantics: a first-pass route
                    # failure returns WITHOUT releasing the reserve
                    # (finalize backstops).
                    logger.info(
                        "bare-reroute polish: route_design failed/skipped; "
                        "banked best intact (never-worse).")
                    return
                stop_reason = "route_error"
                logger.info(
                    f"bare-reroute polish: stop (route_error) on iteration "
                    f"{iters_done + 1}; banked best intact (never-worse).")
                break
            iters_done += 1
            # Measured WNS delta of THIS pass, read off best_wns: the
            # auto-bank hook inside call_tool measured and (improved +
            # routed) banked; a worse/neutral/phantom-rejected pass
            # leaves best_wns unchanged -> gain 0 -> honest stop.
            _gain_ns = (
                self.best_wns - _pre_wns
                if (_pre_wns is not None and _pre_wns != float("-inf")
                    and self.best_wns is not None
                    and self.best_wns != float("-inf"))
                else 0.0)
            # Observed cost of THIS pass -> next iteration's cost basis
            # (call_tool appended the route entry at _hist_mark; the
            # auto-bank measurement entries that follow don't match).
            _obs = 0.0
            for _tc in self.tool_call_details[_hist_mark:]:
                if (isinstance(_tc, dict) and not _tc.get("error")
                        and "route_design" in str(_tc.get("cmd_head", ""))):
                    try:
                        _obs = max(_obs, float(_tc.get("elapsed_time") or 0.0))
                    except (TypeError, ValueError):
                        pass
            # Fall back to the prediction we just routed under when the
            # history entry is missing/zero (prefer-refusing: never let
            # a 0s sample turn the next wall-fit into an inf-skip that
            # masks a real observation, nor a free pass).
            observed_cost_s = _obs if _obs > 0.0 else assessment.predicted_reroute_s
            if _gain_ns < min_gain_ns:
                stop_reason = "gain_below_min"
                logger.info(
                    f"bare-reroute polish: stop (gain_below_min) after "
                    f"iteration {iters_done}: gain {_gain_ns:+.3f} ns < "
                    f"min {min_gain_ns:.3f} ns (plateau-decay shape).")
                break
            if iters_done >= max_iters:
                stop_reason = "max_iters"
                logger.info(
                    f"bare-reroute polish: stop (max_iters) after iteration "
                    f"{iters_done}: gain {_gain_ns:+.3f} ns still >= min "
                    f"{min_gain_ns:.3f} ns but runaway guard reached.")
                break
            logger.info(
                f"bare-reroute polish: iteration {iters_done} gained "
                f"{_gain_ns:+.3f} ns >= min {min_gain_ns:.3f} ns — "
                f"re-rolling (observed pass cost {observed_cost_s:.0f}s "
                f"feeds the next wall-fit).")
        # Completion releases the C1-T3 reserve (this WAS the polish);
        # measurement + keep-best already happened inside call_tool's
        # auto-bank hook per iteration (improved+routed -> banked, else
        # no bank).  One release for the whole loop, all stop reasons.
        self._release_polish_reserve("bare_reroute_polish_done")
        logger.info(
            f"bare-reroute polish: complete after {iters_done} iteration(s), "
            f"stop={stop_reason} (best_wns={self.best_wns}); "
            f"auto-bank decided keep/no-keep (never-worse).")
        # jul23 INSURED-COMPARE wiring: the size-gated tail lineage (plain
        # bare-reroute loop, when the controller did not claim the state)
        # enrolls its harvested best_valid too, so BOTH tail lineages feed
        # the MUX. Same belt-and-suspenders / no-op-vs-pipeline semantics.
        await self._register_tail_final_candidate("bare_reroute")

    def _observed_open_cost_s(self) -> float:
        """Max successful open_checkpoint cost observed this run (0.0 when
        none — the affordability margins cover small designs)."""
        cost = 0.0
        for _tc in self.tool_call_details:
            if not isinstance(_tc, dict) or _tc.get("error"):
                continue
            if (_tc.get("tool_name") == "vivado_open_checkpoint"
                    or "open_checkpoint" in str(_tc.get("cmd_head", ""))):
                try:
                    cost = max(cost, float(_tc.get("elapsed_time") or 0.0))
                except (TypeError, ValueError):
                    pass
        return cost

    async def _run_tail_controller(self, min_gain_ns: float) -> None:
        """Adaptive banked tail controller (jul22, PLAN item 1 — the
        identified ceiling).  Caller: _run_bare_reroute_polish, AFTER its
        entry gates passed AND the banked best was re-opened in-session.

        Policy (optimizer/tail_controller.py, pure/unit-tested): pick
        argmax measured-Δns/s over the proven move menu among wall-
        affordable, non-retired moves; a move retires when its last gain
        < min_gain_ns; an ACCEPTED move un-retires the others (chain
        evidence M2→M1→M3 = +0.726: moves re-bite after state change);
        HARVEST-TO-WALL — the loop stops only on wall floor, plateau
        (nothing eligible), or the runaway caps (max_moves global,
        4 executions per move).

        Banking discipline per move class:
          - m1_route rides the normal call_tool auto-bank hook (identical
            op + path to the shipped M1 loop; hold-neutral in every probe
            cell and live run).
          - phys_opt moves (m2/m3/m4) run with the auto-bank hook
            SUPPRESSED and bank through the stage's own accept: WNS
            improved AND fully routed AND hold_accept() (h0-relative
            floor) — then the same mirror machinery the hook uses
            (_mirror_best_valid_now(eager=True), ship-integrity manifest
            included).  Reject/error/no-gain leaves the banked mirror
            untouched and forces a re-open of the banked best before the
            next move (probe fidelity: chains measure from banked
            states; drift never compounds).

        Never-worse by construction: the on-disk banked mirror only ever
        advances through the two gated paths above; an overrun ships the
        mirror via the emergency path, costing only tail-γ.

        POST-ACCEPT M1 ECHO (jul23 panel fantasy #2, terra; DEFAULT OFF
        via _tail_ctrl_m1_echo): when ON, every ADOPTED non-M1 move is
        immediately followed by ONE bare route_design echo — identical
        mechanics to a picked M1 (auto-bank hook, M1 cost prediction,
        observed cost from history), counts toward moves_done/max_moves,
        own affordability check (skip with a log line), and records into
        the m1_route MoveState (a below-min echo retires m1 exactly like
        a picked M1 would — intentional: the echo IS an M1 execution).
        Evidence: M1 re-bites +0.048/681s on already-harvested boom
        states (wave-2 probe); DW#2 run reached M1 only as move 3.
        """
        from optimizer.route_gate import assess_preserving_reroute
        from optimizer.tail_controller import (
            TAIL_CTRL_MAX_EXECS_PER_MOVE, TAIL_MENU, hold_accept,
            move_by_key, new_states, pick_next, predict_move_cost_s,
            record_result)
        from optimizer.ils_polish import _measure_hold

        _cfg = getattr(self, "_ils_polish_cfg", None)
        _measure_to = float(getattr(_cfg, "measure_cmd_timeout_s", 120.0)
                            if _cfg is not None else 120.0)
        states = new_states()
        max_moves = int(self._tail_ctrl_max_moves)
        moves_done = 0
        stop_reason = "max_moves"
        pending_reopen = False
        entry_wns = self.best_wns
        logger.info(
            f"[tail-ctrl] ARMED: entry wns={entry_wns:.3f} <= gate "
            f"{self._tail_ctrl_deep_wns_ns:.3f}; menu="
            f"{[m.key for m in TAIL_MENU]}; max_moves={max_moves}; "
            f"min_gain={min_gain_ns:.3f} ns; harvest-to-wall.")
        while moves_done < max_moves:
            remaining = self._budget_remaining()
            base_assess = assess_preserving_reroute(
                remaining, self.tool_call_details)
            route_pred = base_assess.predicted_reroute_s
            reopen_extra = (self._observed_open_cost_s()
                            if pending_reopen else 0.0)
            afford: dict = {}
            preds: dict = {}
            for m in TAIL_MENU:
                pred = predict_move_cost_s(m, states[m.key], route_pred)
                preds[m.key] = pred
                # Same margin stack as the preserving assessment: x1.3
                # cost slack + 30s banking + 120s safety, plus the
                # banked-best re-open when the session drifted.
                need = pred * 1.3 + 30.0 + 120.0 + reopen_extra
                afford[m.key] = (pred != float("inf")
                                 and remaining != float("inf")
                                 and remaining >= need) or (
                    pred != float("inf") and remaining == float("inf"))
            pick = pick_next(states, afford)
            if pick is None:
                _all_dead = all(
                    st.retired or st.executed >= TAIL_CTRL_MAX_EXECS_PER_MOVE
                    for st in states.values())
                stop_reason = ("plateau_all_retired" if _all_dead
                               else "wall_unfit")
                break
            move = move_by_key(pick)
            if pending_reopen:
                _banked = self._best_valid_dcp
                if _banked is None or not Path(_banked).exists():
                    stop_reason = "banked_best_missing"
                    break
                _r = await self.call_tool(
                    "vivado_open_checkpoint",
                    {"dcp_path": str(Path(_banked).resolve())})
                if _looks_like_tool_error(_r):
                    stop_reason = "reopen_failed"
                    break
                pending_reopen = False
            pre_wns = self.best_wns
            _hist_mark = len(self.tool_call_details)
            _move_to = max(600.0, preds[pick] * 2.0)
            if remaining != float("inf"):
                _move_to = min(_move_to, max(600.0, remaining))
            errored = False
            banked = False
            gain = 0.0
            whs = None
            verdict = "REJECTED_NO_GAIN"
            if move.rides_autobank:
                _r = await self.call_tool(
                    "vivado_run_tcl",
                    {"command": move.cmds[0], "timeout": _move_to})
                if isinstance(_r, str) and ('"error"' in _r
                                            or "TCL ERROR:" in _r):
                    errored = True
                    verdict = "ERROR"
                else:
                    gain = (
                        self.best_wns - pre_wns
                        if (pre_wns is not None
                            and pre_wns != float("-inf")
                            and self.best_wns is not None
                            and self.best_wns != float("-inf"))
                        else 0.0)
                    banked = gain > 0.0
                    verdict = "ADOPTED" if banked else "REJECTED_NO_GAIN"
            else:
                base_whs = await _measure_hold(self.call_tool,
                                               timeout_s=_measure_to)
                self._tail_ctrl_suppress_autobank = True
                try:
                    for _cmd in move.cmds:
                        _r = await self.call_tool(
                            "vivado_run_tcl",
                            {"command": _cmd, "timeout": _move_to})
                        if isinstance(_r, str) and ('"error"' in _r
                                                    or "TCL ERROR:" in _r):
                            errored = True
                            verdict = "ERROR"
                            break
                finally:
                    self._tail_ctrl_suppress_autobank = False
                if not errored:
                    try:
                        w = await asyncio.wait_for(
                            self.get_wns_for_target_clock(
                                self._call_vivado_tool),
                            timeout=600.0)
                    except Exception:
                        w = None
                    if (w is not None and pre_wns is not None
                            and pre_wns != float("-inf") and w > pre_wns):
                        if not await self._routed_ok_for_best():
                            verdict = "REJECTED_UNROUTED"
                        else:
                            whs = await _measure_hold(self.call_tool,
                                                      timeout_s=_measure_to)
                            if hold_accept(whs, base_whs):
                                old_best = self.best_wns
                                self.best_wns = w
                                self.last_improvement_iter = self.iteration
                                self.last_improvement_time = time.time()
                                self.regression_warning_sent = False
                                self._pending_best_mirror = True
                                self._pending_best_mirror_epoch = (
                                    self._mutation_epoch)
                                await self._mirror_best_valid_now(eager=True)
                                banked = True
                                gain = w - (old_best if old_best is not None
                                            else w)
                                verdict = "ADOPTED"
                            else:
                                verdict = "REJECTED_HOLD"
                    else:
                        verdict = "REJECTED_NO_GAIN"
            # Observed cost of THIS move from the history slice (sum of
            # the move's own heavy ops; measurement entries don't match).
            _obs = 0.0
            for _tc in self.tool_call_details[_hist_mark:]:
                if (isinstance(_tc, dict) and not _tc.get("error")
                        and any(str(_tc.get("cmd_head", "")).startswith(
                            _c.split()[0]) for _c in move.cmds)):
                    try:
                        _obs += float(_tc.get("elapsed_time") or 0.0)
                    except (TypeError, ValueError):
                        pass
            cost_s = _obs if _obs > 0.0 else preds[pick]
            moves_done += 1
            record_result(states, pick, gain if not errored else 0.0,
                          cost_s, min_gain_ns, errored=errored)
            if not banked:
                pending_reopen = True
            logger.info(
                f"[tail-ctrl] move={pick} exec#{states[pick].executed} "
                f"verdict={verdict} gain={gain:+.3f}ns cost={cost_s:.0f}s "
                f"wns={self.best_wns} whs={whs} "
                f"remaining={self._budget_remaining():.0f}s")
            # POST-ACCEPT M1 ECHO (jul23 panel fantasy #2, terra) —
            # gated by the DEFAULT-OFF flag: after every ADOPTED non-M1
            # move, run ONE bare route_design from the fresh banked
            # state (M1 re-bite evidence +0.048/681s on harvested boom).
            # Identical mechanics to a picked M1: rides the auto-bank
            # hook, M1 cost prediction for the timeout, observed cost
            # from the history slice.  NO FREE LUNCH: counts toward
            # moves_done/max_moves and needs its own affordability
            # check (same margin stack; no reopen extra — the parent
            # just banked, so the session IS the banked state).
            if self._tail_ctrl_m1_echo and banked and pick != "m1_route":
                _m1 = move_by_key("m1_route")
                _m1_st = states["m1_route"]
                _rem = self._budget_remaining()
                _echo_pred = predict_move_cost_s(
                    _m1, _m1_st,
                    assess_preserving_reroute(
                        _rem, self.tool_call_details).predicted_reroute_s)
                _echo_need = _echo_pred * 1.3 + 30.0 + 120.0
                _echo_ok = (_echo_pred != float("inf")
                            and (_rem == float("inf") or _rem >= _echo_need))
                if moves_done >= max_moves:
                    logger.info(
                        f"[tail-ctrl] echo after {pick} SKIPPED "
                        f"(max_moves cap {max_moves} reached).")
                elif _m1_st.executed >= TAIL_CTRL_MAX_EXECS_PER_MOVE:
                    logger.info(
                        f"[tail-ctrl] echo after {pick} SKIPPED (m1_route "
                        f"exec cap {TAIL_CTRL_MAX_EXECS_PER_MOVE} reached).")
                elif not _echo_ok:
                    logger.info(
                        f"[tail-ctrl] echo after {pick} SKIPPED "
                        f"(unaffordable: need {_echo_need:.0f}s vs "
                        f"remaining {_rem:.0f}s).")
                else:
                    _e_pre = self.best_wns
                    _e_mark = len(self.tool_call_details)
                    _e_to = max(600.0, _echo_pred * 2.0)
                    if _rem != float("inf"):
                        _e_to = min(_e_to, max(600.0, _rem))
                    _e_errored = False
                    _e_banked = False
                    _e_gain = 0.0
                    _r = await self.call_tool(
                        "vivado_run_tcl",
                        {"command": _m1.cmds[0], "timeout": _e_to})
                    if isinstance(_r, str) and ('"error"' in _r
                                                or "TCL ERROR:" in _r):
                        _e_errored = True
                        _e_verdict = "ERROR"
                    else:
                        _e_gain = (
                            self.best_wns - _e_pre
                            if (_e_pre is not None
                                and _e_pre != float("-inf")
                                and self.best_wns is not None
                                and self.best_wns != float("-inf"))
                            else 0.0)
                        _e_banked = _e_gain > 0.0
                        _e_verdict = ("ADOPTED" if _e_banked
                                      else "REJECTED_NO_GAIN")
                    _e_obs = 0.0
                    for _tc in self.tool_call_details[_e_mark:]:
                        if (isinstance(_tc, dict) and not _tc.get("error")
                                and any(str(_tc.get("cmd_head", "")
                                            ).startswith(_c.split()[0])
                                        for _c in _m1.cmds)):
                            try:
                                _e_obs += float(
                                    _tc.get("elapsed_time") or 0.0)
                            except (TypeError, ValueError):
                                pass
                    _e_cost = _e_obs if _e_obs > 0.0 else _echo_pred
                    moves_done += 1
                    # Records into the m1_route MoveState so the rate
                    # policy sees the observation; a below-min echo
                    # retires m1 EXACTLY like a picked M1 would —
                    # INTENTIONAL: the echo IS an M1 execution, and a
                    # no-gain echo is the same plateau evidence.
                    record_result(states, "m1_route",
                                  _e_gain if not _e_errored else 0.0,
                                  _e_cost, min_gain_ns,
                                  errored=_e_errored)
                    if not _e_banked:
                        pending_reopen = True
                    logger.info(
                        f"[tail-ctrl] echo after {pick} move=m1_route "
                        f"exec#{_m1_st.executed} verdict={_e_verdict} "
                        f"gain={_e_gain:+.3f}ns cost={_e_cost:.0f}s "
                        f"wns={self.best_wns} whs=None "
                        f"remaining={self._budget_remaining():.0f}s")
        self._release_polish_reserve("tail_controller_done")
        logger.info(
            f"[tail-ctrl] COMPLETE moves={moves_done} stop={stop_reason} "
            f"wns {entry_wns} -> {self.best_wns} (banked mirror is disk "
            f"truth; never-worse).")
        # jul23 INSURED-COMPARE wiring (RESERVE/controller -> final-candidate
        # MUX): enroll the harvested best_valid as a FINAL candidate.
        await self._register_tail_final_candidate("tail_controller")

    async def _register_tail_final_candidate(self, source_label: str) -> bool:
        """Enroll a tail lineage's harvested best_valid into the finalize MUX.

        BELT-AND-SUSPENDERS TODAY: the tail advances best_valid via
        _mirror_best_valid_now(eager=True), so the DCP registered here is
        USUALLY byte-identical to the implicit pipeline candidate #0
        (source="pipeline"). A candidate equal to pipeline can NEVER win the
        MUX (FINAL_CANDIDATE_MUX_MIN_GAIN_NS + tie->pipeline), so the
        default (controller-ON) SHIPPED artifact stays byte-identical. This
        is the hook the panel's RESERVE fork-compare will use later to
        enroll a DIVERGENT tail DCP (which the MUX would then legitimately
        pick if it beats the pipeline).

        verify=True re-runs the full never-worse gate stack (tracker-routed +
        hold + cell-band) against the CURRENT in-memory state. The tail loop
        may have left a rejected draw loaded (pending_reopen), so re-open the
        banked best FIRST — exactly the pre-sweep's verify-mode discipline —
        so in-memory == the registered candidate. Never raises into the
        caller (a registration hiccup must never break a run)."""
        try:
            bv = self._best_valid_dcp
            if (bv is None or not Path(bv).exists()
                    or self.best_wns is None
                    or self.best_wns == float("-inf")):
                return False
            _ro = await self.call_tool(
                "vivado_open_checkpoint",
                {"dcp_path": str(Path(bv).resolve())})
            if _looks_like_tool_error(_ro):
                logger.info(
                    f"[mux] {source_label}: banked-best re-open failed; "
                    "SKIPPING registration (never-worse).")
                return False
            store_dir = (self.run_dir or Path(".")) / "final_candidates"
            store_dir.mkdir(parents=True, exist_ok=True)
            store = store_dir / f"{source_label}.dcp"
            _atomic_copy(str(bv), str(store))
            src_edif = Path(bv).with_suffix(".edf")
            if src_edif.exists() and src_edif.stat().st_size > 0:
                try:
                    _atomic_copy(str(src_edif),
                                 str(store.with_suffix(".edf")))
                except Exception:
                    pass
            return await self.register_final_candidate(
                store, self.best_wns, source_label, verify=True)
        except Exception as e:
            logger.warning(
                f"[mux] {source_label} registration raised "
                f"{type(e).__name__} (non-fatal): {e}")
            return False

    async def _finalize_logic_floor(self, output_dcp: Path,
                                    max_iterations_reached: bool) -> None:
        """v5.5 short exit: finalize + summary for a logic-floor-attested run.
        Lives OUTSIDE _exit_with_ils_polish so the stage-ordering contract of
        that function's source (recipe -> rung -> handback -> finalize, pinned
        by test_v41_levers) stays literally true."""
        await self._finalize_output_dcp(output_dcp)
        self.end_time = time.time()
        self._print_optimization_summary(
            max_iterations_reached=max_iterations_reached)

    async def _exit_with_ils_polish(self, output_dcp: Path, *,
                                    max_iterations_reached: bool = False) -> None:
        """Shared loop-exit tail. Arms the ILS-polish loop-exit trigger (if the
        loop ended with timing still unmet + leftover budget + viable size), runs
        the ILS stage if armed (or if a mid-loop stagnation preempt already armed
        it), then finalizes + prints the summary.

        MUST be the single exit tail for EVERY loop-exit path. Before this, the
        early-stop returns (timing-met / plateau / empty-spin ceiling guard)
        called _finalize_output_dcp directly and bypassed the trigger entirely —
        so ceiling designs like vexriscv_v2 that early-exit at wns<0 with budget
        to spare (the exact ILS target) never ran ILS. keep-best => never-worse."""
        # LOGIC-FLOOR TERMINATION (v5.5, FPL26_LOGIC_FLOOR_EXIT): the physics
        # attestation fired post-B3-adopt — the worst paths are measurably at
        # the unbreakable logic floor (bound <= 10 MHz over 32 paths at a
        # 45ps/hop net floor, logic >= 80%, hard-macro >= 50%, two solves
        # agree), so ILS/polish/fixpoint stages cannot pay for their wall.
        # Finalize the attested floor immediately; the B3-FLOOR-EXIT token
        # then ends the multi-restart run. Everything skipped here is
        # measured-zero from this state (ILS beyond floor: +0.003 forfeited
        # by design — the wall+beta it costs prices higher; census aug09).
        if getattr(self, "_logic_floor_terminate", None):
            logger.info(
                f"[logic-floor] exit tail: skipping fixpoint/ILS/polish "
                f"stages ({self._logic_floor_terminate}); finalizing the "
                f"attested floor now.")
            await self._finalize_logic_floor(output_dcp, max_iterations_reached)
            return
        # PHYSOPT_DEFAULT_FIXPOINT v2 (jul31 night, DEFAULT OFF). Runs HERE — after
        # the LLM loop has finished — and NOT before it. v1 ran pre-loop and was
        # killed by its own A/B: on digit it banked +0.110 with `-directive
        # Default` where the LLM's own next call would have banked +0.204, the
        # loop then found nothing, and the run shipped 59.65 against a 72.50 mode.
        # The action was never the defect; the ORDERING was. Post-loop it cannot
        # pre-empt a call the LLM was going to make, because the LLM is done.
        # It still improves the ILS entry baseline, which is the whole reason fir
        # gains from it. See PHYSOPT_ARG_DROP_jul31.md §11.
        await self._physopt_default_fixpoint()

        # ILS-polish LOOP-EXIT trigger (generalizable): catches early LLM/loop
        # exits the mid-loop stagnation preempt misses.
        if (not self._ils_preempt_requested and self._ils_polish_cfg.enabled
                and self.best_wns > float("-inf")):
            from optimizer.ils_polish import should_trigger_at_exit as _ils_exit
            if self._design_cells is None:
                try:
                    _cr = await self.call_tool("vivado_run_tcl", {
                        "command": "llength [get_cells -hierarchical "
                                   "-filter {IS_PRIMITIVE==1}]"})
                    _cm = re.search(r"(\d+)", _cr or "")
                    self._design_cells = int(_cm.group(1)) if _cm else -1
                except Exception:
                    self._design_cells = -1
            _et, _ew = _ils_exit(cells=self._design_cells,
                                 remaining_s=self._budget_remaining(),
                                 best_wns=self.best_wns, cfg=self._ils_polish_cfg)
            if _et:
                self._ils_preempt_requested = True
                logger.info(f"ILS-polish loop-exit trigger ({_ew}); using "
                            f"remaining {self._budget_remaining():.0f}s.")
            else:
                logger.info(f"ILS-polish loop-exit trigger NOT armed ({_ew}).")
        # ILS-polish stage: runs if the loop preempted (stagnation) OR the
        # loop-exit trigger fired. Exception-safe — failure leaves best intact.
        if self._ils_preempt_requested:
            try:
                await self._run_ils_polish_stage()
            except Exception as e:
                logger.warning(f"ILS-polish stage failed (ignored): {e!r}")
        else:
            # Bare re-route polish (drill jul21 D1-null: +0.094 boom_v2
            # deterministic; meta: undirected beats directed): when ILS
            # never armed (boom-class designs are ILS-SIZE-GATED at
            # 379k cells > max_cells 300k, so the __ROUTE_ONLY__ combo
            # never harvests the undirected rip-up for them), run ONE
            # bare route_design on the routed banked best.  All gates
            # (banked best exists, auto-bank on, wall fits per the
            # route_gate predictor) live in the method; exception-safe —
            # failure leaves the banked best intact (never-worse).
            try:
                await self._run_bare_reroute_polish()
            except Exception as e:
                logger.warning(f"bare-reroute polish failed (ignored, "
                               f"banked best intact): {e!r}")
        # jul25 DEEP-REPLACE sibling — moved here from _run_ils_polish_stage.
        # WHY: that stage is gated off for large designs ("ILS-polish loop-exit
        # trigger NOT armed (too_large(cells=379048))" on boom_soc), so the
        # sibling was UNREACHABLE on exactly the DEEP-extreme class it targets.
        # This is the single exit tail every loop-exit path takes, so the gate
        # now always gets to decide. Strict no-op with the flag off.
        try:
            await self._deep_replace_sibling_after_polish(
                self._budget_deadline
                if self._budget_deadline is not None else time.time(),
                self._wns_tcl_for_stages())
        except Exception as e:
            logger.warning(f"deep-replace stage failed (ignored, banked best "
                           f"intact): {e!r}")
        # RECIPE-PASS POST-LOOP slot (aug03, REVIEW_V30_DIFF_aug03.md
        # MAJOR-1 redesign candidate (a)): runs AFTER every polish stage —
        # so the remaining wall is genuinely stranded, nothing else will
        # consume it — and BEFORE _finalize_output_dcp, so the result
        # competes at the finalize MUX like every other candidate.  Deep
        # band (vtr-class, |wns_in| >= 8.0) is the target: it is unarmable
        # at the pre-LLM slot on the ship wall.  Strict near-no-op with
        # the flag off (one skipped-reason=disabled audit line, the
        # disclosed NOTE-1 class).  Exception-safe twice over (the method
        # catches internally; this bracket is the belt — MINOR-3 lesson:
        # an await outside a try in this tail can kill optimize()).
        try:
            await self._maybe_run_recipe_pass_postloop()
        except Exception as e:
            logger.warning(f"RECIPE-PASS[postloop]: skipped reason=exception "
                           f"{type(e).__name__}: {e!r} (non-fatal)")
        # ROUTE-RUNG POST-LOOP slot (aug05, FPL26_CORESCORE_ROUTE_RUNG;
        # v4.1 rev2 BREAK redesign, DEFAULT OFF): mid-band retime-break
        # candidate from the banked best state.  AFTER the recipe
        # postloop slot (band-disjoint at ship: that slot's residual
        # firing set is deep-band, this one is mid-band-only) and —
        # deliberately — BEFORE the wall-handback exit decision below
        # AND before _finalize_output_dcp: the v4.0 rung shipped INERT
        # because its own handback defer let handback claim the wall
        # first (0 fires x2); rev2 removes the defer, so the rung
        # claims its PRICED wall (need 1350 s) out of what handback
        # would return, and the handback log + finalize right below
        # still hand back whatever remains.  Corescore-mid + banked-
        # best gates bound the reallocation; the candidate competes at
        # the finalize MUX.  Exception-safe twice over, same MINOR-3
        # belt as the slot above.
        try:
            await self._maybe_run_corescore_route_rung_postloop()
        except Exception as e:
            logger.warning(f"ROUTE-RUNG[postloop]: skipped reason=exception "
                           f"{type(e).__name__}: {e!r} (non-fatal)")
        # D3 (04-01): checked AFTER the polish stages, BEFORE finalize — the
        # saturation signal must SURVIVE one polish pass (locked OQ1: polish
        # stages run once and never clear/reset _exit_early_reason).
        if self._exit_early_reason is not None:
            logger.info(
                f"wall-handback: exit-early reason "
                f"'{self._exit_early_reason}' survived the polish stages; "
                + ("finalizing now returns the remaining wall to the "
                   "wrapper." if self._wall_handback_enabled
                   else "kill switch OFF — observational only.")
            )
        await self._finalize_output_dcp(output_dcp)
        self.end_time = time.time()
        # Reporting only — _print_optimization_summary never raises (aug06:
        # a KeyError here discarded a completed artifact; see its docstring).
        self._print_optimization_summary(
            max_iterations_reached=max_iterations_reached)

    # Flags whose state changes what the optimizer DOES, as opposed to tuning
    # knobs. Recorded explicitly (resolved, not just "present in environ") so a
    # banked row can be read back years later without guessing.
